import{b as A,u as x,a as S,r as o,j as e}from"./index-Crha1dSC.js";import{B as I,P as Y}from"./PageLayout-5tJ8VNHW.js";import{R as C,a as j}from"./ResultBlockWithSettings-Drd8RFVW.js";import{M as E}from"./Marks-CUl88-sS.js";const B="1.0.1",_="2026-04-10",R=JSON.parse(`[{"id":"outcomes-001","code":"001","description":{"en":"<p>Your society has constructed a solid outpost that it can occupy seasonally, and has begun to form a culture around its particular location. Over the years, this outpost becomes a thriving hold, with some occupants residing there all year.</p>\\n<p>Illustrate the saga of the steadfast dwellers on the primal cave wall, including the hold mark (i) and the mark of one region where you have an outpost (e.g. the Verdant Vale [ii] or Skyreach Plateau [iii]). The full-time inhabitants of your outposts can provide you with additional assistance. Gain the Holds (KN10) Knowledge card.</p>","ru":"<p><strong><i>Ваша община возвела надёжное поселение, служившее убежищем в холодное время года, и заложила основу для формирования местной культуры. С годами поселение разрослось, и некоторые жители стали оставаться в нём круглый год.</i></strong></p><p>На стене первобытной пещеры изобразите историю о неустрашимых поселенцах, включив в неё отметку укрытия [i] и отметку одного из регионов, где у вас есть поселение (например, Дивная долина [ii] или Поднебесная равнина [iii]). Постоянные обитатели ваших поселений могут оказать вам поддержку. Получите карту знаний «Укрепления» (ЗБ10).</p>"},"repeatable":false,"marks":[{"label":"i","image":"<hold>"},{"label":"i","image":"<verdantvale>"},{"label":"iii","image":"<skyreachplateau>"}]},{"id":"outcomes-002","code":"002","description":{"en":"<p>Cold rays of sunlight linger on rattling leaves, but you have completed the outpost to shelter your people from the deep frosts. Uncertainty remains your constant companion. When the moon shines bright overhead, something vast and inscrutable stalks toward the valley...</p>\\n\\"At the end of any day, you may end this challenge. When you do, add <population><population>.\\n\\nAs your people grow more accustomed to the valley, you have developed new skills for survival. Your society gains the following mantle powers: Prey-Stalker (MA01), Secret-Finder (MA02), Friend-Guide (MA03), Safe-Keeper (MA04). Record these in the Mantle Powers section on the Culture page of the Journal. At the start of each subsequent challenge, players will select one mantle power for each character based on their mantle, as described in Mantle Powers on Rulebook p.65.\\n\\nThen, as a group, the players must choose one of the following paths for your society:\\n\\n<b>A) Counsel your people to focus on tangible improvements, not vague uncertainties:</b> Add <population> and add <unrest><unrest>. Illustrate the saga of the shining sun on the primal cave wall, including the <sun> mark and the mark for a region where you built an outpost (e.g. the Verdant Vale [i] or Skyreach Plateau [ii]). At the start of the next challenge, add A Peaceful Season (CZ01) to your looming challenges. Add the following to your goals: Gather Stores (GA03), Seek the Omens (GA07), Stoke the Flame (GA08), A Trail of Mysteries (GA11).\\n\\n<b>B) Rally your people to meet the mysterious threat head-on:</b> Illustrate the saga of the moonlit vigil on the primal cave wall, including the <moon> mark and the mark for a region where you built an outpost (e.g. the Verdant Vale [i] or Skyreach Plateau [ii]). Add Arrival (CA04) to your looming challenges. At the start of the next challenge, add the following to your goals: Gather Stores (GA03), Seek the Omens (GA07), Stoke the Flame (GA08).\\"","ru":"<p><strong><i>Холодные солнечные лучи скользили по дрожащим листьям, но поселение уже было достроено и готово укрыть ваш народ от суровых морозов. И всё же беспокойство не покидало вас. В час, когда луна царила на небосводе, нечто огромное и непостижимое устремлялось к долине...</i></strong></p><p>В конце любого дня можете завершить текущее испытание. Затем добавьте <population><population>.<br>Освоившись в долине, ваш народ приобрёл новые навыки выживания. Ваша община получает следующие силы мантий: «Следопыт» (МА01), «Знаток секретов» (МА02), «Друг-наставник» (МА03), «Хранитель» (МА04). Запишите их в раздел «Силы мантий» на странице «Культура» в журнале. В начале каждого следующего испытания выбирайте по одной силе для каждого персонажа в соответствии с их мантиями, как описано в разделе «Силы мантий» на с. 65 правил игры. Затем совместно выберите один из следующих путей развития общины:<br><strong>А. Направьте свой народ на путь созидания, избавив его от страха перед неизвестностью.</strong> Добавьте <population> и <unrest><unrest>. На стене первобытной пещеры изобразите историю о сияющем солнце, включив в неё отметку <sun> и отметку региона, где вы построили поселение (например, Дивная долина [i] или Поднебесная равнина [ii]). Добавьте карту «Период затишья» (ИЯ01) к грядущим испытаниям. В начале следующего испытания добавьте к целям следующие карты: «Соберите припасы» (ЦА03), «Отыщите знамения» (ЦА07), «Разведите огонь» (ЦА08), «Пройдите по следам тайн» (ЦА11).<br><strong>Б. Объедините народ, чтобы противостоять таинственной угрозе.</strong> На стене первобытной пещеры изобразите историю о лунном дозоре, включив в неё отметку <moon> и отметку региона, где вы построили поселение (например, Дивная долина [i] или Поднебесная равнина [ii]). Добавьте карту «Вторжение» (ИА04) к грядущим испытаниям. В начале следующего испытания добавьте к целям следующие карты: «Соберите припасы» (ЦА03), «Отыщите знамения» (ЦА07), «Разведите огонь» (ЦА08).</p>"},"repeatable":false,"marks":[{"label":"i","image":"<verdantvale>"},{"label":"ii","image":"<skyreachplateau>"}]},{"id":"outcomes-003","code":"003","description":{"en":"<p>You see patterns in the cycles of season and age...</p>\\n<p>Look at the top three cards of the Event deck (beneath this one). You may put any number of them on the bottom, shuffle the Event deck, then place the rest on top of the deck (beneath this card) in any order.</p>","ru":"<p><strong><i>Вы начали видеть закономерности в смене времён года и чередовании эпох…</i></strong></p><p>Посмотрите три верхние карты колоды событий (находящиеся под этой картой). Вы можете положить любое количество из них под низ колоды. Затем перемешайте колоду и положите оставшиеся карты на верх колоды (под эту карту) в любом порядке.</p>"},"repeatable":false},{"id":"outcomes-006","code":"006","description":{"en":"<p>\\"Sliding past the deadly antlers, you vault onto the behemoth's head. Atop its bony brow, you stare into the amber pits of its eyes...\\"</p>\\n\\"Choose one of the following and resolve it:\\n\\n<b>A) Match your will with the behemoth:</b> Contest <conviction> versus the behemoth's <conviction>. Add +2 if you are <i>indomitable</i> and +4 if you have another behemoth's mark.\\nWin: <i>You overcome the behemoth.</i> Aggravate the behemoth's demeanor by 1. It flees. \\nLose: <i>You feel your life-force draining away.</i> Check 1 age box on your Character card. Add this behemoth's mark to the Legend side of your Character card. \\n\\n<b>B) Seek the behemoth's truth:</b> Contest <awareness> versus the behemoth's <might>. Add +2 if you are <i>attuned</i> and +4 if you have this behemoth's mark.\\nWin: <i>You see the cycles of life and death spin eternally, the moon chasing the sun across seasons and eons.</i> Discard all your <boost>. The behemoth flees. Placate its demeanor by 3. \\nLose: <i>You gaze into the eye of eternity and are overwhelmed.</i> Check 1 age box on your character card. Add this behemoth's mark to the Legend side of your Character card. Gain the <i>attuned</i> trait.\\n\\nThen end the encounter.\\"","ru":"<p><strong><i>Увернувшись от смертоносных рогов, вы взобрались на голову чудища и всмотрелись в янтарные омуты его глаз...</i></strong></p><p>Выберите и разыграйте одно:</p><p><strong>А. Померяйтесь выдержкой с чудищем.</strong>Проведите состязание: ваша <conviction> против <conviction> чудища. +2, если вы неукротимый, и +4, если у вас есть отметка другого чудища.<br><strong>Успех.</strong> Вы одержали верх. Разозлите чудище на 1. Оно сбегает.<br><strong>Провал.</strong> Вы почувствовали, как ваша жизненная сила начинает угасать. Отметьте одну клетку возраста на карте своего персонажа. Добавьте отметку этого чудища на сторону легенды карты своего персонажа.</p><p><strong>Б. Постарайтесь по-настоящему понять чудище.</strong>Проведите состязание: ваше <awareness> против <might> чудища. +2, если вы сосредоточенный, и +4, если у вас есть отметка этого чудища.<br><strong>Успех.</strong> Вы увидели вечный круговорот жизни и смерти — луна бесконечно догоняет солнце сквозь времена и эпохи. Сбросьте все свои <boost>. Чудище сбегает. Успокойте чудище на 3.<br><strong>Провал.</strong> Вы заглянули в око вечности и были ошеломлены увиденным. Отметьте одну клетку возраста на карте своего персонажа. Добавьте отметку этого чудища на сторону легенды карты своего персонажа. Получите черту «сосредоточенный».</p><br>Затем завершите встречу."},"repeatable":false},{"id":"outcomes-009","code":"009","description":{"en":"<p>You drop past the shattered stones and roll to a spot beneath the behemoth, praying that you are too close for its senses. For several minutes the creature rumbles past while you crouch, hands over your head. As you stare into the dirt, you see an object embedded there, and once the behemoth has passed, you pry it loose.</p>\\n<p>\\"End the encounter. Gain 1 of the behemoth's curio.\\"</p>","ru":"<p><i><b>Вы скатились по каменной крошке и затаились под чудищем в надежде, что здесь оно вас не почует. Несколько томительных минут, пока чудище грохотало над вами, вы не смели поднять головы. Именно тогда, глядя в землю, вы заметили застрявший в ней предмет. Дождавшись, пока чудище уйдёт, вы вытащили находку. </b></i></p><p>Завершите встречу. Получите 1 сокровище этого чудища.</p>"},"repeatable":false},{"id":"outcomes-011","code":"011","description":{"en":"<p>\\"The inscrutable, furry behemoth's shell seems to be invulnerable, and frosts swirl about its tread. Yet even such a collossus might have a secret. By observing its behaviors, you have come to believe that it is not so unstoppable as you first believed.\\"</p>\\n\\"Resolve the first you are able:\\n\\n<b>A) Observing the great herald of the cycle gives you new insights into its nature:</b> If the behemoth has an unrevealed Secret card assigned to it, reveal this behemoth's currently assigned Secret card, then record it under the Secrets for that behemoth in the Journal.\\n\\n<b>B) You know from your stories that the ponderous orb moves across the landscape, leaving crystalline pools in places of interest:</b> Gain 1 of this behemoth's curio.\\"","ru":"<p><i><b>Таинственное мохнатое чудище казалось непобедимым, а его следы покрывал иней. Однако даже у такого колосса могли быть свои секреты. Наблюдая за его поведением, вы поняли, что существо уязвимее, чем можно было подумать. </b></i></p><p>Разыграйте первое, что можете:</p> <p><b>А. Наблюдая за исполинским вестником цикла, вы постигали новые истины о его природе.</b> Если у чудища есть назначенная неоткрытая карта секрета, откройте её. Затем запишите её в раздел секретов этого чудища в журнале. <b><br>Б. Согласно преданиям, гигантское существо ступает по земле, оставляя за собой хрустальные озёра — следы его непостижимой воли. </b>Получите 1 сокровище этого чудища.</p>"},"repeatable":false},{"id":"outcomes-012","code":"012","description":{"en":"<p>You take your first small step onto a strange, beautiful landscape...</p>\\n<p>Illustrate the saga of the distant steps on the primal cave wall, including the discovery mark (i), the Starlit Sea mark (ii), and the underworld mark (iii).</p>","ru":"<p><strong><i>Вы сделали первый робкий шаг по незнакомым прекрасным землям...</i></strong></p><p>На стене первобытной пещеры изобразите историю о шагах в неизвестность, включив в неё отметку открытия [i], отметку Звёздного моря [ii] и отметку подземного мира [iii].</p>"},"repeatable":false,"marks":[{"label":"i","image":"<discovery>"},{"label":"ii","image":"<starlitsea>"},{"label":"iii","image":"<underworld>"}]},{"id":"outcomes-015","code":"015","description":{"en":"<p>\\"Holding on to the fur at the behemoth's great chin, you present a great offering to it. You hope its mood is receptive and its generosity equivalent to your own...\\"</p>\\n\\"Choose one and resolve it:\\n\\n<b>A) You put forth a sizeable tribute:</b> If the behemoth's demeanor is 4 or lower and you have at least 3 materials in your inventory, discard three materials. Placate the behemoth's demeanor by 1. Then, if all three materials you discarded correspond to a current omen (as listed below), gain 1 of the behemoth's curio.\\n\\n<cloud>: Mineral materials\\n<comet>: Small materials\\n<moon>: Animal materials\\n<star>: Large materials\\n<sun>: Plant materials\\n\\n<b>B) Offer a placating tribute:</b> If the behemoth's demeanor is 5 or higher and you have at least 3 materials in your inventory, discard three materials. If you do, placate the behemoth's demeanor by 2.\\n\\n<b>C) Offer nothing, risking the behemoth's wrath:</b> Aggravate the behemoth's demeanor by 1. Then, if its demeanor is 5 or higher, suffer <minor_injury> and flee.\\n\\nThen, end the encounter.\\"","ru":"<p><strong>Уцепившись за густой мех на громадном подбородке чудища, вы протянули ему щедрый дар и затаили дыхание, в надежде, что чудище в благосклонном настроении — и что его великодушие окажется равным вашему...</strong></p><p>Выберите и разыграйте одно:</p><p><strong>А. Вы преподнесли весомый дар.</strong>Если значение нрава чудища не более 4, а в вашем инвентаре есть хотя бы 3 материала, сбросьте 3 из них. Если сделали это, успокойте чудище на 1. Затем, если все 3 сброшенных материала соответствуют текущим знамениям (см. ниже), получите 1 сокровище этого чудища:<br><cloud>— минеральные материалы<br><comet>— жетоны материалов меньшего размера.<br><moon>— животные материалы.<br><star>— жетоны материалов большего размера. <br><sun>— растительные материалы.<br></p><p><strong>Б. Вы преподнесли умиротворяющий дар.</strong> Если значение нрава чудища равно хотя бы 5, а в вашем инвентаре есть хотя бы 3 материала, сбросьте 3 из них. Если сделали это, успокойте чудище на 2.<br><strong>В. Вы не преподнесли ничего, рискуя разгневать чудище.</strong> Разозлите чудище на 1. Затем, если значение нрава чудища равно хотя бы 5, получите <minor_injury> и сбегите.</p><p>Затем завершите встречу.</p>"},"repeatable":false},{"id":"outcomes-016","code":"016","description":{"en":"<p>\\"The walking spire's tread grinds forests to dust, yet you have seen something that it seems to fear, something that makes you wonder. What heart beats beneath its stony skin?\\"</p>\\n\\"Resolve the first you are able:\\n\\n<b>A) Your observation reveals something about this great creature:</b> If the behemoth has an unrevealed Secret card assigned to it, reveal this behemoth's currently assigned Secret card, then record it under the Secrets for that behemoth in the Journal.\\n\\n<b>B) You know from your sagas that the behemoth leaves great broken tracts of earth, in which you can easily harvest stones:</b> Gain 2 of the behemoth's curio.\\"","ru":"<p><strong><i>Поступь ходячего шпиля стирала леса в пыль, но всё же вы видели нечто, что, казалось, внушает чудищу страх. Это заставило вас задуматься: что за сердце бьётся под каменной кожей?</i></strong></p><p>Разыграйте первое, что можете:</p><p><strong>А. Немного понаблюдав, вы раскрыли одну из тайн этого величественного существа.</strong>Если у чудища есть назначенная неоткрытая карта секрета, откройте её. Затем запишите её в раздел секретов этого чудища в журнале.<br><strong>Б. Истории вашего народа гласили, что чудище оставляет за собой огромные разломы в земле и в них легко добывать камень.</strong> Получите 2 сокровища этого чудища.</p>"},"repeatable":false},{"id":"outcomes-017","code":"017","description":{"en":"<p>\\"As you stand atop the behemoth's head, a shadow falls over you. You spin instinctively to see the behemoth's massive hand blotting out the sky. It descends with a rush of air, and darkness overtakes you.\\"</p>\\n\\"Suffer <major_injury><major_injury><major_injury>. If this fills your character's health track, they perish. If your character didn't perish, place your character in a randomly selected adjacent hex as the behemoth hurls you away.\\"","ru":"<p><strong><i>Вы стояли на голове чудища, когда тень накрыла вас. Обернувшись, вы увидели исполинскую лапу, заслонившую небо. Со свистом рассекая воздух, она обрушилась на вас — и стало темно.</i></strong></p><p>Получите <minor_injury><minor_injury><minor_injury>. Если это заполняет всю шкалу здоровья персонажа, он умирает.<br>Если персонаж не умер, переместите его на случайный соседний участок местности — чудище отшвырнуло его.</p>"},"repeatable":false},{"id":"outcomes-018","code":"018","description":{"en":"<p>By confronting the would-be raiders, you have managed to deescalate the situation without resorting to bloodshed. Your forbearance this day will be remembered.</p>\\nSubtract <unrest><unrest>. Illustrate the saga of the bloodless victory on the primal cave wall, including the mediator mark.","ru":"<p><strong><i>Встав на пути у возможных захватчиков, вы укротили чужую ярость и сумели разрешить конфликт миром. Терпение, проявленное в этот день, не будет забыто.</i></strong></p><p>Уберите <unrest><unrest>. На стене первобытной пещеры изобразите историю о бескровной победе, включив в неё отметку посредника.</p>"},"repeatable":false,"marks":[{"label":"","image":"<mediator>"}]},{"id":"outcomes-019","code":"019","description":{"en":"<p>Approaching the corpse, you smell an odor that turns your stomach sour, the aroma only death wears. You must be cautious to avoid the vileness of this place.</p>\\n\\"Test <awareness> to resist disease. Add +2 if you are <i>lucky</i> and +4 if you have the harrowing mark (i) or the plague mark (ii). You can discard 1 water to add +4 to this test.\\n11+: You manage to avoid the infectious material. No effect.\\n6–10: You notice a tickle in your throat. Suffer <minor_disease>.\\n1–5: You begin to cough. Suffer <major_disease>, then add Pestilence (CZ03) to your looming challenges unless the plague mark is on the primal cave wall.\\"","ru":"<p><strong><i>Приближаясь к туше, вы ощутили смрад, от которого скрутило желудок, — дыхание самой смерти. Нужно быть осторожным, чтобы скверна этого места не коснулась вас.</i></strong></p><p>Проведите проверку <awareness>, чтобы сопротивляться болезни. +2, если вы удачливый, и +4, если у вас есть отметка ужаса [i] или отметка чумы [ii]. +4 к результату этой проверки, если сбросите 1 воду.<br><strong>11≥</strong>: Вам удалось избежать инфекции. Без эффекта.<br><strong>6-10</strong>: У вас запершило в горле. Получите <minor_disease>.<br><strong>1-5</strong>: Вас разобрал кашель. Получите <major_disease>, затем добавьте карту «Мор» (ИЯ03) к грядущим испытаниям, если только на стене первобытной пещеры не изображена отметка чумы.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<harrowing>"},{"label":"ii","image":"<plague>"}]},{"id":"outcomes-021","code":"021","description":{"en":"<p>The vast creature of vegetation rises above the treeline, but in your observations of it, you have come to believe that it is not invulnerable. In fact, you think your discovery might let you stand on even footing with this mighy behemoth.</p>\\n\\"Resolve the first you are able:\\n\\n<b>A) Observing the great herald of the cycle gives you new insights into its nature:</b> If the behemoth has an unrevealed Secret card assigned to it, reveal this behemoth's currently assigned Secret card, then record it under the Secrets for that behemoth in the Journal.\\n\\n<b>B) The behemoth's ways are well-known to your people, and as it moves, it sheds rootlike tendrils filled with sticky pitch that you can harvest:</b> Gain 2 of this behemoth's curio.\\"","ru":"<p><strong><i>Над деревьями возвышалось существо, словно сама долина ожила и обрела форму. Но, наблюдая за ним, вы поняли: даже оно не безупречно в своей силе. И, быть может, ваше открытие позволит сразиться с могучим чудищем на равных.</i></strong></p><p>Разыграйте первое, что можете:</p><p><strong>А. Наблюдая за исполинским вестником цикла, вы постигали новые истины о его природе.</strong> Если у чудища есть назначенная неоткрытая карта секрета, откройте её. Затем запишите её в раздел секретов этого чудища в журнале.<br><strong>Б. Пути чудища были хорошо известны вашему народу. Двигаясь, оно сбрасывало похожие на корни щупальца, наполненные липкой смолой, которую вы могли собрать.</strong> Получите 2 сокровища этого чудища.</p>"},"repeatable":false},{"id":"outcomes-022","code":"022","description":{"en":"<p>The behemoth strides toward the seed with the certainty of a gale. It makes contact with the seed, and the color drains from the green tendrils.</p>\\n\\"Resolve the first you are able:\\n\\n<b>A) Watch the seed grow dim and ashy:</b> If you have the goal Nurture the Seedling, automatically complete it.\\n\\n<b>B) Try to retrieve the seed:</b> Place the seed on one of the behemoth's apex nodes of your choice. While the seed is on the behemoth board, Nurture the Seedling cannot be completed. After a character encounters the behemoth and reaches that node, they may place the seed in a hex of their choice adjacent to the behemoth's hex.\\n\\nThen, remove this behemoth's aim and all of its trace tokens. Assign it the Return to Slumber (BT20) instinct (replacing its previous instinct).\\"","ru":"<p><strong><i>Чудище настигло семя с неумолимостью урагана. Оно коснулось семени и начало вытягивать краски из зелёных побегов.</i></strong></p><p>Разыграйте первое, что можете:</p><p><strong>А. Наблюдайте, как семя тускнеет и покрывается пеплом.</strong> Если у вас есть цель «Взрастите саженец», немедленно достигните её. <br><strong>Б. Попробуйте вернуть семя.</strong> Поместите семя рядом с любой из главных развилок чудища. Пока семя находится на планшете чудища, вы не можете достигнуть цели «Взрастите саженец». После того как персонаж доберётся до этой развилки, он может поместить семя на любой участок местности, соседний с участком чудища.</p><p>Затем уберите жетон направления и все жетоны следов этого чудища. Замените его текущий инстинкт на «Вернуться в забытьё» (ЧК20).</p>"},"repeatable":false},{"id":"outcomes-023","code":"023","description":{"en":"<p>Between the harsh peaks, your people have struggled to find the necessary resources to thrive in the vale. Now, as frosts begin to deepen autumn into winter, your society comes to a hard decision.</p>\\n\\"End this challenge.\\n\\nAdd Putting Down Roots (CA02) to your looming challenges. Then, as a group, the players must choose one of the following paths for your society:\\n\\n<b>A) Return through the caverns before they are sealed by snows:</b> Add <unrest><unrest>. Follows the steps on Rulebook p.69 to illustrate the saga of the patient wayfarers on the primal cave wall, including the arrival mark, the caution mark, and the mark of your starting region (e.g. the Verdant Vale [i] or Skyreach Plateau [ii]). Finally, each character gains one of the following traits of their player's choice: <i>patient</i> or <i>wary</i>.\\n\\n<b>B) Hunker down for a hard winter:</b> Subtract <population><population>. Follows the steps on Rulebook p.69 to illustrate the saga of the stubborn skies on the primal cave wall, including the arrival mark, the ice mark, and the mark of your starting region (e.g. the Verdant Vale [i] or Skyreach Plateau [ii]). Finally, each character gains one of the following traits of their player's choice: <i>inquisitive</i> or <i>vengeful</i>.\\"","ru":"<p><strong><i>Меж суровых горных вершин вашему народу было непросто добыть всё необходимое, чтобы выжить в долине. Теперь, когда дыхание зимы всё сильнее ощущалось в осеннем воздухе, ваши люди столкнулись с трудным выбором.</i></strong></p><p>Завершите текущее испытание.<br>Добавьте карту «Пуская корни» (ИА02) к грядущим испытаниям.<br>Затем совместно выберите один из следующих путей развития общины:</p><p><strong>А. Вернитесь через пещеры до того, как их занесёт снегом.</strong> Добавьте <unrest><unrest>. Следуйте инструкциям на с. 69 правил игры, чтобы изобразить на стене первобытной пещеры историю о терпеливых путниках. Включите в неё отметку прибытия [i], отметку осторожности [ii] и отметку своего начального региона (например, Дивная долина [iii] или Поднебесная равнина [iv]). Затем каждый персонаж получает одну из двух черт на выбор игрока: «терпеливый» или «осторожный». <br><strong>Б. Останьтесь, чтобы пережить суровую зиму.</strong> Уберите <population><population>. Следуйте инструкциям на с. 69 правил игры, чтобы изобразить на стене первобытной пещеры историю о неумолимых небесах, включив в неё отметку прибытия [i], отметку льда [v] и отметку своего начального региона (например, Дивная долина [iii] или Поднебесная равнина [iv]). Затем каждый персонаж получает одну из двух черт на выбор игрока: «любознательный» или «мстительный».</p>"},"repeatable":false,"marks":[{"label":"i","image":"<arrival>"},{"label":"ii","image":"<caution>"},{"label":"iii","image":"<verdantvale>"},{"label":"iv","image":"<skyreachplateau>"},{"label":"v","image":"<ice>"}]},{"id":"outcomes-024","code":"024","description":{"en":"<p>A dreadful scene fills your mind: great jaws of smoke close about your people. The trees of the valley burn, and the beasts flee from the terror of flame. Your vision swirls and rises, and now you overlook a vast and silent valley, covered in deathly ash.</p>\\n<p>Illustrate the saga of the sky swallowed by ash on the primal cave wall, including the doom mark (i) enclosing the blaze mark (ii).</p>","ru":"<p><strong><i>В вашем сознании вспыхнула жуткая картина: огромные дымные челюсти сомкнулись вокруг вашего народа. Деревья в долине пылали, звери в страхе бежали от ужасающего пламени. Видение закружилось, подняло вас над землёй — теперь вы взирали на безмолвную долину, укрытую мёртвым пеплом.</i></strong></p><p>На стене первобытной пещеры изобразите историю о долине, покрытой пеплом, включив в неё отметку пламени [i], заключённую в отметку погибели[ii].</p>"},"repeatable":false,"marks":[{"label":"i","image":"<doom>"},{"label":"ii","image":"<blaze>"}]},{"id":"outcomes-025","code":"025","description":{"en":"<p>Small shoots of green push up through the ashy soil where the behemoth has tread. You wonder...</p>\\n\\"Resolve the first you are able:\\n\\n<b>A) ....where could it hail from?:</b> If the Volcanic Wastes mark is not on the primal cave wall, <outcome> 990.\\n\\n<b>B). ..how its tread brings both death and flourishing?:</b> If the behemoth has an unrevealed Secret card assigned to it, reveal this behemoth's currently assigned Secret card, then record it under the Secrets for that behemoth in the Journal.\\n\\n<b>C) ...what brought it here?:</b> Place a mystery token in an adjacent hex without a character, if able.\\n\\"","ru":"<p><strong>Маленькие зелёные побеги пробивались сквозь усыпанную пеплом почву, по которой прошло чудище. Вы задумались…</strong></p><p>Разыграйте первое, что можете:</p><p><strong>А. ...откуда оно пришло?</strong> Если на стене первобытной пещеры нет отметки Вулканических пустошей, то <outcome> 990.<br><strong>Б. ...как его поступь приносит и смерть, и возрождение?</strong> Если у чудища есть назначенная неоткрытая карта секрета, откройте её. Затем запишите её в раздел секретов этого чудища в журнале.<br><strong>В. ...что привело его сюда?</strong> Поместите жетон тайны на соседний участок местности без персонажа, если возможно.</p>"},"repeatable":false,"marks":[{"label":"","image":"volcanic_wastes"}]},{"id":"outcomes-028","code":"028","description":{"en":"<p>\\"You hurl yourself toward the behemoth's craggy brow to deliver a precise, stunning blow to its forehead. The behemoth shudders and stumbles, its head brushing close to the ground. You leap off safely.\\"</p>\\n<p>\\"End the encounter. Aggravate the behemoth's demeanor once. Degrade all of its boosts.\\"</p>","ru":"<p><i><b>Вы бросились к щербатому лбу чудища, чтобы нанести точный оглушающий удар. Чудище содрогнулось и оступилось, его голова почти коснулась земли. Вы успели соскочить и остались в живых.</b></i></p> <p>Завершите встречу. Разозлите чудище на 1. Уменьшите все его <boost>.</p>"},"repeatable":false},{"id":"outcomes-029","code":"029","description":{"en":"<p>The seed of the Tangle lies deep in the root-tunnels. Once again, you stride into the depths to save the Tangle, this time with a certainty of purpose.</p>\\n\\"Embark on the venture below (see Ventures on Rulebook p.60).\\n\\n<bi>Within the root-tunnels, the earth seems to press down upon you from all sides and the darkness is oppressive.</bi>\\n<b>Group, Hazard:</b> Everyone must test <conviction> to press on. A character adds +2 if they have an item with a <fire> token on it and +2 if they are <i>indomitable</i>.\\n12+: You march on resolutely. The venture continues.\\n7–11: Fear sets your eyes twitching at every shadow. Lose <energy>. The venture continues.\\n1–6: You panic and retreat out of the tunnel. Leave the venture. If all characters resolve this result, the venture fails.\\n\\n<bi>You reach the seed-chamber once again and find the colossal orb before you. Its sides are smooth, but you can feel a warmth from within. You will have to be very careful in excavating it.</bi>\\n<b>Champion:</b> Someone must test <dexterity> to free the seed. Add +2 if you have <dig>, +2 if you have <stoneworking>, and +2 if you are <i>wise</i>.\\n11+: You manage to loosen the seed without harming it. The venture continues.\\n1–10: The seed stays firmly stuck. The venture fails unless a character spends <energy><energy> or <lore> to attempt this test again.\\n\\n<bi>Now that the seed is free, you must move the massive object out of the tunnels.</bi>\\n<b>Group:</b> Everyone must test <might> to move the seed. Add +2 if you have Rope and +2 if you are <i>resourceful</i>.\\n14+: Together, painstakingly, you move the seed from the tunnels. Complete this venture and the associated goal.\\n1–13: You are unable to make any progress. If all characters resolve this result, the venture fails unless a character spends <energy><energy> or <lore> to attempt this test again.\\"","ru":"<p><strong><i>Семя покоилось глубоко в корневых туннелях. Вы вновь ступили в их темноту, чтобы спасти Сплетение, — на сей раз с ясным пониманием цели.</i></strong></p><p>Отправьтесь в поход (см. раздел «Походы» в правилах игры на с. 60).</p><p><strong><i>Внутри корневых туннелей земля будто давила на вас со всех сторон, а тьма казалась невыносимой.</i></strong></p><p><strong>Группа, угроза.</strong> Все персонажи в походе должны провести проверку <conviction>, чтобы продолжить путь. +2, если персонаж неукротимый, и +2, если у него есть предмет с <fire>.<br><b>≥12:</b> Вы уверенно продвигались вперёд. Продолжите поход.<br><b>7-11:</b> Страх заставил вас вздрагивать от каждого движения тени. Потеряйте <energy>. Продолжите поход.<br><b>1-6:</b> Вы поддались панике. Покиньте поход. Если все персонажи покинули поход, он окончился неудачно.</p><p><strong><i>Вы вновь оказались в полости с семенем и увидели перед собой гигантскую сферу. Её поверхность была гладкой, и вы чувствовали, как изнутри исходит тепло. Вам пришлось действовать крайне осторожно, чтобы извлечь её.</i></strong></p><p><strong>Защитник.</strong> Один из персонажей в походе должен провести проверку <dexterity>, чтобы высвободить семя. +2, если у него есть <dig>, +2, если у него есть <stoneworking>, и +2, если он <i>мудрый</i>.<br><b>≥11:</b> Вам удалось вытащить семя, не повредив его. Продолжите поход.<br><b>1-10:</b> Семя не поддалось — оно слишком крепко вросло. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy> или <lore>, чтобы провести проверку ещё раз.</p><p><b><i>Теперь, когда семя было у вас, предстояло вынести эту громадину из туннелей.</b></i></p><p><b>Группа.</b> Все персонажи в походе должны провести проверку <might>, чтобы переместить семя. +2, если у персонажа есть «Верёвка», и +2, если он <i>изобретательный</i>.<br><b>≥14:</b> Все вместе, с огромным трудом, вы вынесли семя из туннелей. Завершите этот поход и достигните соответствующей цели.<br><b>1-13:</b> Вам не удалось сдвинуть семя с места. Если все персонажи получили этот результат, поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy> или <lore>, чтобы провести проверку ещё раз.</p>"},"repeatable":false},{"id":"outcomes-030","code":"030","description":{"en":"<p>Your outpost is unfinished as great clouds sweep across the sky, harbingers of suffering to come. The trail of stars that lights up the sky seems pale and distant...</p>\\n\\"End this challenge. Subtract <population> and add <unrest>. \\n\\nHowever, all hope is not lost. Through hard experience, your people have developed new skills that will facilitate surviving in the valley. Your society gains the following mantle powers: Prey-Stalker (MA01), Secret-Finder (MA02), Friend-Guide (MA03), Safe-Keeper (MA04). Record these in the Mantle Powers section on the Culture page of the Journal. At the start of each subsequent challenge, players will select one mantle power for each character based on their mantle, as described in Mantle Powers on Rulebook p.65.\\n\\nThen, as a group, the players must choose one of the following paths for your society:\\n\\n<b>A) Continue building as the frosts descend:</b> Subtract <population><population> and add <unrest>, then build an outpost (without paying costs) in a zone with no building requirements (if no such zone exists, you cannot select this option). Illustrate the saga of frigid resolve on the primal cave wall, including <cloud> mark and the harrowing mark (i). Add Festival of Remebrance (CA07) to your looming challenges. At the start of the next challenge, add the following to your goals: Gather Stores (GA03), Seek the Omens (GA07), Stoke the Flame (GA08), A Trail of Mysteries (GA11).\\n\\n<b>B) Abandon the unfinished outpost to follow the starlit path to a new home:</b> Your outpost becomes a ruin (flip the overlay to it to its inactive side and note on its card that it is a ruin). Illustrate the saga of the horizon's promise on the primal cave wall, including the arrival mark (ii) and the <star> mark. Add A Place of Solace (CA03) to your looming challenges. At the start of the next challenge, add the following goals: Gather Stores (GA03), Seek the Omens (GA07), Stoke the Flame (GA08), A Trail of Mysteries (GA11).\\"","ru":"<p><strong><i>Ваше поселение оставалось недостроенным, а по небу уже проносились тяжёлые тучи — предвестники грядущих страданий. Свет звёздных троп в вышине над вами потускнел и казался таким далёким...</i></strong></p><p>Завершите текущее испытание. Уберите <population> и добавьте <unrest>.</p><p><strong><i>Однако не всё было потеряно. Преодолев немало трудностей, ваш народ обрёл новые умения, которые помогут выжить.</i></strong></p><p>Ваша община получает следующие силы мантий: «Следопыт» (МА01), «Знаток секретов» (МА02), «Друг-наставник» (МА03), «Хранитель» (МА04). Запишите их в раздел «Силы мантий» на странице «Культура» в журнале. В начале каждого следующего испытания выбирайте по одной силе для каждого персонажа в соответствии с их мантиями, как описано в разделе «Силы мантий» на с. 65 правил игры.<br>Затем совместно выберите один из следующих путей развития общины:<br><strong>А. Продолжите строительство, несмотря на подступающие морозы.</strong> Уберите <population><population> и добавьте <unrest>, затем постройте поселение (не оплачивая его стоимость) в районе без требований для строительства (если таких районов нет, выбрать этот вариант нельзя). На стене первобытной пещеры изобразите историю о ледяной стойкости, включив в неё отметку и <cloud> отметку ужаса [i]. Добавьте карту «Праздник памяти» (ИА07) к грядущим испытаниям. В начале следующего испытания добавьте к целям следующие карты: «Соберите припасы» (ЦА03), «Отыщите знамения» (ЦА07), «Разведите огонь» (ЦА08), «Пройдите по следам тайн» (ЦА11).<br><strong>Б. Бросьте недостроенное поселение и отправьтесь по звёздной тропе к новому дому.</strong> Ваше поселение становится руинами (переверните накладку неактивной стороной вверх и укажите на карте поселения, что теперь это руины). На стене первобытной пещеры изобразите историю о надежде, что сулит горизонт, включив в неё отметку прибытия [ii] и отметку <star>. Добавьте карту «Прибежище» (ИА03) к грядущим испытаниям. В начале следующего испытания добавьте к целям следующие карты: «Соберите припасы» (ЦА03), «Отыщите знамения» (ЦА07), «Разведите огонь» (ЦА08), «Пройдите по следам тайн» (ЦА11).</p>"},"repeatable":false,"marks":[{"label":"i","image":"<harrowing>"},{"label":"ii","image":"<arrival>"}]},{"id":"outcomes-031","code":"031","description":{"en":"<p>The behemoth looks at you expectantly for an offering, and you find yourself rifling through your pack for an adequate gift...</p>\\n\\"Choose one and resolve it:\\n\\n<b>A) Give the behemoth an offering:</b> If you have 2 or more resources in your inventory, discard any 2 resources to placate the behemoth's demeanor by 1. Then continue the encounter. \\n\\n<b>B) Offer nothing:</b> Aggravate the behemoth's demeanor by 1. Then continue the encounter.\\"","ru":"<p><strong><i>Чудище смотрело на вас, ожидая подношения, и вы начали рыться в своём мешке в поисках подходящего подарка...</i></strong></p><p>Выберите и разыграйте одно:</p><p> <strong>А. Сделайте подношение.</strong> Если в вашем инвентаре есть хотя бы 2 ресурса, сбросьте любые 2 из них, чтобы успокоить чудище на 1. Затем продолжите встречу.<br><strong>Б. Не давайте ничего.</strong> Разозлите чудище на 1. Затем продолжите встречу.</p>"},"repeatable":false},{"id":"outcomes-034","code":"034","description":{"en":"<p>The glowing mushroom spores fill your vision with dancing images of the moon, waxing and waning at a fever pitch. You remember stumbling in darkness and a fall. When you come to your senses, the moon greets you in the afternoon sky above, and your head throbs in tune with the last vestiges the vanishing omen.</p>\\nEnd this delve action. Gain 1 of the rewards you claimed during your delve, then return the rest to the supply. Add <lore><lore>. Then, place your character in a randomly selected hex in the region where you started delving, selecting an unexplored hex if able. Unless you discard 1 water, lose <energy> from dehydration and the pounding in your head.","ru":"<p><strong><i>Светящиеся споры грибов вспыхнули перед глазами, и в их пляске вы узрели луну — то растущую, то убывающую в исступлённом ритме. Вы вспомнили, как оступились во тьме и рухнули вниз. Очнувшись, вы увидели луну уже в полуденном небе, а голова пульсировала в такт последним отблескам исчезающего знамения.</i></strong></p><p>Завершите это действие спуска. Получите одну из присвоенных во время спуска наград, остальные верните в запас. Добавьте <lore><lore>.Затем поместите своего персонажа на случайный участок местности в регионе, где вы начали спуск. Выберите неисследованный участок, если возможно. Персонаж теряет <energy> из-за обезвоживания и пульсации в голове, если только не сбросит 1 воду.</p>"},"repeatable":false},{"id":"outcomes-035","code":"035","description":{"en":"<p>Brushing aside the white dust, you find an ancient, fossilized bank of what you believe to be coral.</p>\\n<p>If all coral overgrowth overlays have been placed, remove one of your choice from the valley. Then place an inactive coral overgrowth in your current hex. Add Meeting the Ineffable Mind (GC11) to your goals.</p>","ru":"<p><strong><i>Смахивая белую пыль, вы наткнулись на древний окаменевший риф, по вашему мнению бывший когда‑то кораллом.</i></strong></p><p>Если все накладки коралловых зарослей находятся в долине, уберите одну из них на ваш выбор. Затем поместите неактивные коралловые заросли на ваш текущий участок местности. Добавьте карту «Встретьтесь с высшим разумом» (ЦВ11) к целям.</p>"},"repeatable":false},{"id":"outcomes-037","code":"037","description":{"en":"<p>\\"The prophet's words bubble up through back channels and reach you: their adherents say the prophet is marked by the sky wanderer. The comet, the adherents whisper reverently, will arrive in a great column of glorious light, and will create a new world in the image the prophet has foreseen. To prepare, groups of adherents seek rare treasures to entreat the wanderer to arrive with greatest haste!\\"</p>\\n<p>\\"Add Seek the Comet's Sign (GC03) to your goals.\\"</p>","ru":"<p><strong><i>Слова пророка просачивались по тайным тропам и достигали ваших ушей: его последователи говорили, что пророк отмечен небесным Скитальцем. Комета — благоговейно шептали последователи — явится в великом столпе чудесного света и создаст новый мир таким, как предсказывал пророк. Готовясь к великому дню, адепты искали редкие сокровища, чтобы умилостивить Скитальца и ускорить его пришествие.</i></strong></p><p>Добавьте карту «Отыщите знаки кометы» (ЦВ03) к целям.</p>"},"repeatable":false},{"id":"outcomes-039","code":"039","description":{"en":"<p>It begins with a roar as the heavens ignite above you. The air shudders and the sky breaks.</p>\\n<p>Add The Sky Descends (CC04) to your looming challenges.</p>","ru":"<p><strong><i>Раздался рёв, и небеса воспылали над вами. Воздух вздрогнул, и небо разверзлось.</i></strong></p><p>Добавьте карту «Падение небес» (ИВ04) к грядущим испытаниям.</p>"},"repeatable":false},{"id":"outcomes-045","code":"045","description":{"en":"<p>Your people sweat blood and break their backs to reshape the land, but the land refuses to be molded. Where you clear trees, seedlings sprout resolutely. Your stores of seeds rot waiting for places to plant them. Eventually, your people abandon the project, returning to surer ways of surviving.</p>\\nAdd <unrest><unrest><unrest>. Illustrate the saga of the wilted harvest on the primal cave wall, including the broken earth mark (i) and the herbalism mark (ii).","ru":"<p><strong><i>Ваши люди трудились до изнеможения в попытках перекроить землю, но она отказывалась поддаваться. Там, где вы выкорчёвывали деревья, прорастали новые побеги. Ваши запасы семян загнивали, не дождавшись посадки. В конце концов, ваш народ оставил эту затею, вернувшись к более надёжным способам выживания.</i></strong></p><p>Завершите текущее испытание.<br>Добавьте <unrest><unrest><unrest>. На стене первобытной пещеры изобразите историю об увядшем урожае, включив в неё отметку расколотой земли [i] и отметку травничества [ii].</p>"},"repeatable":false,"marks":[{"label":"i","image":"<brokenearth>"},{"label":"ii","image":"<herbalism>"}]},{"id":"outcomes-046","code":"046","description":{"en":"<p>The behemoth rumbles toward the seed with a strange curiosity. Slowly, gently, it picks up the seed, with a delicacy belied by its rocky hands. You feel a thrill set your hair on end, and then the seed glistens for a moment. The behemoth turns to look at you with a stony gaze of what might be... understanding? It points to the horizon, indicating a direction.</p>\\n\\"Resolve the first you are able:\\n\\n<b>A) Look on in awe as the seed becomes stony:</b> If the goal Halt the Cycle is in play and is incomplete, add one moonblood to it.\\n\\n<b>B) Follow the behemoth's outstretched arm:</b> Each character gains <major_boost> to <awareness>.\\n\\nThen, remove this behemoth's aim and all of its trace tokens. Assign it the Return to Slumber (BT20) instinct (replacing its previous instinct).\\"","ru":"<p><strong><i>Чудище потянулось к семени с каким‑то необъяснимым любопытством. Медленно, с нежностью оно подняло семя, что не вязалось с громадными каменными лапами. Вас пробрала дрожь. Семя на миг озарилось блеском. Чудище обернулось к вам, и в его холодном взоре скользнуло... понимание? Оно указало вдаль, обозначая путь.</i></strong></p><p>Разыграйте первое, что можете:<br><strong>А. Смотрите в изумлении, как семя каменеет.</strong> Если цель «Разомкните круг» в игре и ещё не достигнута, добавьте 1 лунную кровь на её карту.<br><strong>Б. Последуйте туда, куда указало чудище.</strong> Каждый персонаж получает <major_boost> к <awareness>.</p><p>Затем уберите жетон направления и все жетоны следов этого чудища. Замените его текущий инстинкт на «Вернуться в забытьё» (ЧК20).</p>"},"repeatable":false},{"id":"outcomes-048","code":"048","description":{"en":"<p>Underground, the seeds of your society are cradled in the deeps. Someday, they flourish again on the surface.</p>\\nEnd this challenge. Illustrate the saga of the underground escape on the primal cave wall, including the underworld mark. All of your outposts become ruins. Then, if there are no outpost overlays available, remove one ruin of your choice from the valley. Build a new outpost with the type Underground (without spending <energy>), and place it in a hex of your choice, choosing a hex with a cave or chasm, if able. Add Scorn of the Earth (CC06) to your looming challenges. When you begin Scorn of the Earth, automatically complete Control the Outposts.","ru":"<p><strong><i>В подземных глубинах бережно хранились семена вашей общины. Однажды они снова прорастут.</i></strong></p><p>Завершите текущее испытание.</p><p>На стене первобытной пещеры изобразите историю о побеге в подземелье, включив в неё отметку подземного мира. Все ваши поселения становятся руинами. Затем, если не осталось накладок поселений, уберите из долины одну из них по вашему выбору. Постройте новое поселение, не тратя <energy> . Поместите его на любой участок, выбрав участок местности с пещерой или пропастью, если возможно. В строке «Категория» на карте этого поселения напишите «Подземное». Добавьте карту «Презрение земли» (ИВ06) к грядущим испытаниям. Когда начнёте испытание «Презрение земли», сразу же достигните цели «Укротите мятеж».</p>"},"repeatable":false,"marks":[{"label":"","image":"<underworld>"}]},{"id":"outcomes-049","code":"049","description":{"en":"<p>\\"You vault up the behemoth's great visage, carefully avoiding the swirling stones.You could deliver a blow to the behemoth's thick mask.\\"</p>\\n\\"Choose one and resolve it:\\n\\n<b>A) Strike the behemoth:</b> End the encounter. Aggravate the behemoth's demeanor by 2. The behemoth flees. \\n\\n<b>B) Commune with the behemoth</b>: Gain 2 of the behemoth's curio, then continue the encounter.\\"","ru":"<p><strong><i>Вы взобрались на исполинское лицо чудища, стараясь не попасть под вихрь камней. У вас появился шанс нанести удар по его крепкой маске.</i></strong></p><p>Выберите и разыграйте одно:<br><strong>А. Ударьте чудище.</strong> Завершите встречу. Разозлите чудище на 2. Чудище сбегает.<br><strong>Б. Установите контакт с чудищем.</strong> Получите 2 сокровища этого чудища, затем продолжите встречу.</p>"},"repeatable":false},{"id":"outcomes-052","code":"052","description":{"en":"<p>One day, the strain of past disagreements grows too great to bear, and a group of people depart, vanishing into legend...</p>\\n\\"Illustrate the saga of the vanished ones on the primal cave wall, including the schism mark. Subtract <population><population>. Then, as a group, the players must choose one of the following paths for your society:\\n\\n<b>A) Warn future generations against the threat of outsiders:</b> Add \\\\\\"resting in a hex adjacent to one or more hexes with mystery tokens\\\\\\" to the Taboos section of the Culture page of the Journal. Gain the Taboos (KN18) Knowledge card if you do not already have it. Add <unrest><unrest>. Illustrate the saga of the dire warning on the primal cave wall, including the schism mark (i) and the taboo mark (ii).\\n\\n<b>B) Speak to the possibility of reunion:</b> Add <unrest><unrest><unrest>. Illustrate the saga of the promised return on the primal cave wall, including the mediator mark (iii).\\"","ru":"<p><strong><i>Когда напряжение от старых распрей достигло предела, некоторые решили уйти, оставив после себя лишь сказания…</i> </strong></p><p>    На стене первобытной пещеры изобразите историю об исчезнувших, включив в неё отметку раскола [i]. Уберите <population><population>. Затем совместно выберите один из следующих путей развития общины:<br><strong>А. Предупредите будущие поколения об угрозе извне.</strong> Запишите «Отдыхать на участке местности, соседнем хотя бы с одним участком с жетоном тайны» в раздел «Табу» на странице «Культура» в журнале. Получите карту знаний «Табу» (ЗБ18), если у общины её нет. Добавьте <unrest><unrest>. На стене первобытной пещеры  изобразите историю о мрачном предостережении, включв в неё отметку раскола [i] и отметку табу [ii].<br><strong>Б. Сохраните надежду на воссоединение.</strong> Добавьте <unrest><unrest><unrest>. На стене первобытной пещеры изобразите историю о заветном возвращении, включив в неё отметку посредника [iii].</p>"},"repeatable":false,"marks":[{"label":"i","image":"<schism>"},{"label":"ii","image":"<taboo>"},{"label":"iii","image":"<mediator>"}]},{"id":"outcomes-059","code":"059","description":{"en":"<p>As you pick your way through the dark, your hand comes to rest on what you believe to be a bone. It is dry and ancient, but still sturdy.</p>\\n\\"Test <might> to wrench the bones free. Add +2 if you are <i>wise</i>, +2 if you have <grind>, and +2 if you have a Walking Stick.\\n14+: You wrench the strange bones free and study them, noticing the way they resemble certain creatures of the valley. Gain 2 bone. Add <lore><lore>.\\n9–13: The bones splinter and crack as you extract them. Add <lore>.\\n1–8: The bones break apart, and you are puzzled. No effect.\\"","ru":"<p><strong><i>Пробираясь во тьме, вы наткнулись на нечто похожее на высохшую кость. Она казалась древней, но по‑прежнему крепкой</i>.</strong></p><p>Проведите проверку <might>, чтобы попытаться вырвать кости из земли. +2, если вы <i>мудрый</i>, +2, если у вас есть <grind>, и +2, если у вас есть «Трость».</p><p><b>≥14:</b> Вам удалось вытащить странные кости и изучить их. Они напомнили вам кости существ из долины. Получите 2 кости. Добавьте <lore><lore>.<br><b>9-13:</b> Кости ломались и трещали, когда вы пытались их извлечь. Добавьте <lore>. <br><b>1-8:</b> Кости просто рассыʼпались, оставив вас в недоумении. Без эффекта.</p>"},"repeatable":false},{"id":"outcomes-061","code":"061","description":{"en":"<p>\\"Clouds swirl around your feet as you look down from the spire atop the behemoth's head. From this vantage, you can see all the way to the high walls of the valley.\\"</p>\\n\\"Look at the top two cards of the Journey deck. Place any number of them on the bottom. You and this behemoth each gain <minor_boost> to <awareness>. Then, if this behemoth's demeanor is 4 or lower end the encounter as it tips its horn for you to depart. Otherwise, lose <energy><energy> unless you have Rope.\\"","ru":"<p><strong><i>Облака клубились у ваших стоп, когда вы смотрели вниз со шпиля на голове чудища . Отсюда взору открывалась вся долина до самых её скалистых стен.</i></strong></p><p>Посмотрите 2 верхние карты колоды пути. Можете положить любые из них под низ колоды. Вы и это чудище получаете по <minor_boost> к <awareness>. Затем, если значение нрава этого чудища не более 4, завершите встречу: оно наклоняет рог, приглашая вас спуститься. В противном случае потеряйте <energy><energy>, если только у вас нет «Верёвки».</p>"},"repeatable":false},{"id":"outcomes-065","code":"065","description":{"en":"<p>You wind your way deep into the root-tunnels, uncertain of what horrors you may face in this strange reflection of the Tangle...</p>\\n\\"Embark on the venture below (see Ventures on Rulebook p.60).\\n\\n<bi>The weight of the roots and earth above you is palpable in the tunnels.</bi>\\n<b>Group, Hazard:</b> Everyone must test <conviction> to press on. A character adds +2 if they have an item with a <fire> token on it and +2 if they are <i>indomitable</i>.\\n12+: You march on resolutely. If any character resolves this result, the venture continues.\\n7–11: Fear sets your eyes twitching at every shadow. Lose <energy>. If any character resolves this result, the venture continues.\\n1–6: You panic and flee out of the tunnel. Leave the venture. If all characters on the venture resolve this result, the venture fails.\\n\\n<bi>As you round a bend, you find yourself within a nest of venomous underground hunters. You must fight for your lives!</bi>\\n<b>Group, Hazard:</b> Everyone must test <might> or <dexterity> to fight. A character adds +2 if they are <i>vengeful</i> and +4 if they have a <i>compound</i> item.\\n11+: You cut your way through the creatures, their ichor slick upon the ground. If any character resolves this result, the venture continues.\\n1–10: You are bitten and stung, and painful welts well up on your flesh. Suffer <minor_injury><major_disease>. If all characters on the venture resolve this result, the venture fails unless a character spends <energy><energy> to attempt this test again.\\n\\n<bi>Deep in the darkness, you come to a blockage. From behind it, you can smell the rot you encountered at the surface, far more pungent and dire. You'll have to break through the barrier to find the source of the rot.</bi>\\n<b>Champion, Hazard:</b> Someone must test <awareness> to find the correct place to dig. Add +4 if you have <dig>, +4 if you have <stoneworking>, and +2 if you are <i>resourceful</i>.\\n12+: You strike the right spot, bringing down the earthen barricade. Complete the venture and the associated goal.\\n6–11: The tunnel shudders ominously. The venture fails unless a character spends <energy> to attempt this test again.\\n1–5: The tunnel collapses! The venture fails, and each character on the venture suffers <major_injury><major_injury><major_injury>.\\n\\"","ru":"<p><strong><i>Вы спускались по корневым туннелям, не догадываясь, какие ужасы поджидают вас в этом странном отражении Сплетения...</i></strong></p><p>Отправьтесь в поход (см. раздел «Походы» в правилах игры на с. 60).</p><p><b><i>В туннелях ощущалась вся тяжесть земли и корней, нависающих сверху.</b></i><br><b>Группа, угроза.</b> Все персонажи в походе должны провести проверку <conviction>, чтобы продолжить путь. +2, если у персонажа есть предмет с <fire>, и +2, если он <i>неукротимый</i>.<br><b>≥12:</b> Вы уверенно продвигались вперёд. Если хотя бы один персонаж получил этот результат, продолжите поход.<br><b>7-11:</b> Страх заставил вас вздрагивать от каждого движения тени. Потеряйте <energy>. Если хотя бы один персонаж получил этот результат, продолжите поход.<br><b>1-6:</b> Вы поддались панике и сбежали из туннеля. Покиньте поход. Если все персонажи получили этот результат, поход окончился неудачно.</p><p><b><i>Повернув за угол, вы оказались в гнезде ядовитых подземных хищников. Вам предстояло бороться за свою жизнь!</i></b><br><b>Группа, угроза.</b> Все персонажи в походе должны провести проверку <might> или <dexterity>, чтобы сразиться. +2, если персонаж мстительный, и +4, если у него есть смесь.<br><b>≥11:</b> Вы сумели пробиться. Если хотя бы один персонаж получил этот результат, продолжите поход.<br><b>1-10:</b> Изжаленная кожа начала болезненно опухать. Получите <minor_injury> и <major_disease>. Если все персонажи получили этот результат, поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy>, чтобы провести проверку ещё раз.<br></p><p><b><i>В непроглядной мгле вы наткнулись на преграду. Из‑за толщи грунта доносился знакомый смрад гнили, куда более резкий и зловещий, чем тот, что ощущался на поверхности. Чтобы добраться до источника разложения, предстояло прорваться сквозь барьер.</i></b><br><b>Защитник, угроза.</b> Один из персонажей в походе должен провести проверку <awareness>, чтобы найти правильное место для раскопок. +4, если у него есть <dig>, +4, если у него есть <resourceful>, и +2, если он <i>изобретательный</i>.<br><b>≥12:</b> Вы нашли нужное место и разрушили земляной барьер. Завершите поход и достигните соответствующей цели.<br><b>6-11:</b> Туннель содрогнулся, предвещая беду. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy>, чтобы провести проверку ещё раз.<br><b>1-5:</b> Туннель обрушился! Поход окончился неудачно, и каждый персонаж в походе получает <major_injury><major_injury><major_injury>."},"repeatable":false},{"id":"outcomes-068","code":"068","description":{"en":"<p>\\"Your observations tell you that the comet is closely linked to the coral, its passage predicting the ebbs and flows of the coral's growth. Stranger still, you have observed that the creatures of the valley's underworld are unaffected by the coral despite its presence in the depths. You feel as if you hold a piece of the truth, but its full form eludes you.\\"</p>\\n\\"Illustrate the saga of the coral and the comet on the primal cave wall, including the <comet> mark, the coral mark, the blackened sky mark. Your society gains the Coral-Tender (MA17) mantle power. \\n\\nThen, if it is Epoch 3, add Suppress the Overgrowths (GC02) to your goals.\\"","ru":"<p><b><i>Вы заметили, что комета тесно связана с кораллом: её движение по небу предвещало подъёмы и спады кораллового  роста. Удивительнее всего было то, что коралл, похоже, не мог повлиять на обитателей подземного мира, хотя он пронизывал самые его глубины. Вы чувствовали, что держите в руках ключ к разгадке, но полная картина ускользала от вас.</i></b></p><p>На стене первобытной пещеры изобразите историю о коралле и комете, включив в неё  отметку <comet>, отметку коралла [i] и отметку почерневшего неба [ii]. Ваша община получает  силу мантии «Сторож коралла» (МА17).<br>Если сейчас эра 3, добавьте карту «Остановите заросли» (ЦВ02) к целям.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<coral>"},{"label":"ii","image":"<blackenedsky>"}]},{"id":"outcomes-072","code":"072","description":{"en":"<p>You dream of a stone that smashes its way through the great bowl of the sky. In your vision, shattered chunks of pottery descend, tearing furrows from the earth and casting clouds of dust into the sky. Plants wither and rot, and animals collapse into piles of tattered flesh and bleached bone.</p>\\nAt the end of any day, you may end this challenge. Then, add <unrest>. Illustrate the saga of ruinous vision on the primal cave wall, including the <comet> mark and the misfortune mark. Add A Time to Prepare (CC03) to your looming challenges.","ru":"<p><b><i>Вам снился камень, проламывающий великую чашу небес. В видении глиняные осколки обрушивались вниз, оставляя борозды в земле и поднимая тучи пыли. Растения чернели и увядали, а животные оседали грудами выбеленных костей.</i></b></p><p>В конце любого дня можете завершить текущее испытание. Затем добавьте <unrest>.<br>На стене первобытной пещеры изобразите историю о разрушительном видении, включив в неё отметку <comet> и отметку несчастья. Добавьте карту «Час приготовлений» (ИВ03) к грядущим испытаниям.</p>"},"repeatable":false,"marks":[{"label":"","image":"<misfortune>"}]},{"id":"outcomes-073","code":"073","description":{"en":"<p>\\"You vault onto the behemoth's neck, which rises like a great bridge to the clouds. Teetering like a leaf caught in a great wind, you cling to the rocky skin as the creature sets forth.\\"</p>\\n\\"Choose one and resolve it:\\n\\n<b>A) Hurl a lure:</b> Discard 1 of the behemoth's curio and spend <lore> to end the encounter. Then place the behemoth and your character in any hex within the same region (without drawing a Journey card).\\n\\n<b>B) Hang on for dear life:</b> End the encounter. The behemoth flees. Place your character in the hex it fled to (without drawing a Journey card).\\n\\n<b>C) Your destination lies higher atop the behemoth:</b> Continue the encounter.\\"","ru":"<p><i><b>Вы взобрались на шею чудища — она тянулась к облакам, как громадный мост. Вас бросало, словно лист на ветру, но вы удержались, вцепившись в каменистую кожу, когда существо пришло в движение.</b></i></p><p>Выберите и разыграйте одно:</p><p><b>А. Бросьте приманку. </b>Сбросьте 1 сокровище чудища и потратьте <lore>, чтобы завершить встречу. Затем переместите чудище и своего персонажа на любой участок местности в этом же регионе (не берите карту пути).<br><b>Б. Держитесь изо всех сил.</b> Завершите встречу. Чудище сбегает. Поместите своего персонажа на участок местности, куда сбежало чудище (не берите карту пути).<br><b>В. Легко соскользните.</b> Если на стене первобытной пещеры есть отметка этого чудища, получите одно сокровище этого чудища и завершите встречу. Чудище сбегает.</p>"},"repeatable":false},{"id":"outcomes-074","code":"074","description":{"en":"<p>\\"Many heed the strange prophet's words, and your efforts to refute them are in vain. Following this figure's vision of dread, their followers make their way into a distant part of the valley, vanishing from your saga as the snows of winter erase their tracks. By spring, their fate is uncertain, and fear spreads throughout your diminished populace...\\"</p>\\nEnd this challenge. Subtract <population><population><population>. Add <unrest><unrest><unrest>. Illustrate the saga of the vanished faith on the primal cave wall, including the mystery mark (i) and the schism mark (ii). Add the Buried Coals May Yet Burn (CZ05) to looming challenges (even if previously completed).","ru":"<p><i><b>Многие внимали речам странного пророка, и ваши усилия опровергнуть их были тщетны. Влекомые его мрачным видением, они ушли в дальние пределы долины и исчезли из вашей истории, когда зимний снег укрыл их следы. К весне судьба этих людей оставалась неведомой, и страх проникал в сердца вашего поредевшего народа…</b></i></p><p>Завершите текущее испытание.<br>Уберите <population><population><population> и добавьте <unrest><unrest><unrest>. На стене первобытной пещеры изобразите историю об утерянной вере, включив в неё отметку тайны [i] и отметку раскола [ii]. Добавьте карту «Тлеющие угли» (ИЯ05) к грядущим испытаниям (даже если это испытание было завершено ранее).</p>"},"repeatable":false,"marks":[{"label":"i","image":"<mystery>"},{"label":"ii","image":"<schism>"}]},{"id":"outcomes-076","code":"076","description":{"en":"<p>Beheath the blackened sky, your people see no hope of survival. The only option is escape from this valley before it is consumed completely by the coral...</p>\\nSubtract <population><population><population><population><population>. Flip each inactive coral overgrowth overlay to its active side. Then place each unplaced coral overgrowths on its active side in a hex of your choice, choosing a hex without an overlay, if able. You must choose a hex adjacent to another coral overgrowth, if able. To determine the zone, roll <1d6> and place it in the corresponding zone: (1–2): A, (3–4), B, (5–6) C. Then add Exodus (CZ09) to your looming challenges.","ru":"<p><i><b>Под чёрным небом ваш народ не видел надежды на выживание. Единственный выход — покинуть эту долину, прежде чем она будет полностью поглощена кораллом...</b></i></p><p>Завершите текущее испытание.<br>Уберите 5 <population>. Переверните все неактивные коралловые заросли активной стороной вверх. Затем поместите все неразмещённые коралловые заросли активной стороной вверх на любые участки местности, выбирая участки без накладок, если возможно. Вы должны выбрать участок, соседний с другими коралловыми зарослями, если это возможно. Для каждых зарослей бросьте <1d6>, чтобы поместить их в соответствующий район: [1-2] А, [3-4] Б, [5-6] В. Затем добавьте карту «Исход» (ИЯ09) к грядущим испытаниям.</p>"},"repeatable":false},{"id":"outcomes-080","code":"080","description":{"en":"<p>\\"The behemoth slumps, stunned. You coat your weapon in the acidic substance, then bring it down down again and again and again, until only the cracked haft remains. The behemoth's shattered skull turns soft as clay, and slowly, the rest of its body does the same. The shapeless form oozes into the earth. Within hours, a great shuddering begins, shaking the mountains and chasms. But soon it abates, and the behemoth's presence in the valley is reduced to the scars of its passage and the memory of its power.\\"</p>\\n\\"End this challenge.\\n\\nIllustrate the saga of the felled ancient on the primal cave wall, including the battle mark (i) and the alert behemoth's mark adorned by the behemoth's blood mark (ii). Add the behemoth's blood mark (ii) to the Legend side of the card of each character who participated in the venture. One character who participated in the venture must discard a <i>weapon</i> item, if able.\\n\\nPlace the alert behemoth's lair in its current hex in its inactive state. Then, if there are any unplaced shattered wake overlays, place them in randomly selected hexes adjacent to that behemoth's inactive lair. For each wake placed this way, roll <1d6> and place it in the corresponding zone: 1–2: A, 3–4: B, 5–6: C. If a wake would be placed in a zone with an overlay this way, remove the overlay and replace it with the shattered wake. \\n\\nThen end the Epoch. See Codex p.204 to begin Epoch 3.\\"","ru":"<p><i><b>Чудище осело. Вы окунули своё оружие в едкую жижу, а затем стали наносить удары — снова и снова, пока не поняли, что сжимаете только треснувшую рукоять. Разбитый череп чудища стал мягким, как глина. Постепенно всё его тело размягчилось и растеклось бесформенной массой, просачиваясь в почву. Спустя несколько часов твердь начала содрогаться, сотрясая горы и пропасти. Но вскоре всё затихло — чудище вернулось в утробу земли, оставив на ней шрамы разломов как напоминание о его мощи.</b></i></p><p>Завершите текущее испытание.</p><p>На стене первобытной пещеры изобразите историю о поверженном древнем существе, включив в неё отметку боя [i] и отметку бодрствующего чудища, украшенную отметкой крови чудища [ii]. Добавьте отметку крови чудища [ii] на сторону легенды карты каждого персонажа, который участвовал в походе. Один из персонажей, участвовавших в походе, должен сбросить оружие, если возможно.<br>Поместите логово бодрствующего чудища неактивной стороной вверх на участок местности с чудищем. Затем, если остались неразмещённые накладки расколотых отпечатков, поместите их на случайные участки местности, соседние с неактивным логовом чудища. Для каждого отпечатка бросьте <1d6>, чтобы поместить отпечаток в соответствующий район: [1-2] А, [3-4] Б, [5-6] В. Если при этом вы должны поместить отпечаток в район с другой накладкой, замените её на расколотый отпечаток.<br>Затем завершите эру. См. с. 204, чтобы начать эру 3.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<battle>"},{"label":"ii","image":"<behemothsblood>"}]},{"id":"outcomes-083","code":"083","description":{"en":"<p>The behemoth lurches toward the seed, touching it with a claw. A frozen shell begins to form around the seed before your very eyes, and then the behemoth lifts it and places it atop its back.</p>\\n\\"Resolve the first you are able:\\n\\n<b>A) Let the behemoth take the seed:</b> If the goal Halt the Cycle is in play and incomplete, complete it immediately.\\n\\n<b>B) Try to retrieve the seed:</b> Place the seed next to one of the behemoth's apex nodes of your choice. While the seed is on the behemoth board, Nurture the Seedling cannot be completed. After a character encounters the behemoth and reaches that node, they may place the seed in a hex of their choice adjacent to the behemoth's hex.\\n\\nThen, remove this behemoth's aim and all of its trace tokens. Assign it the Return to Slumber (BT20) instinct (replacing its previous instinct).\\"","ru":"<p><i><b>Чудище наклонилось к семени и коснулось его когтем. Ледяная корочка покрыла оболочку прямо на ваших глазах. Чудище подняло замёрзшее семя и положило к себе на спину.</b></i></p><p>Разыграйте первое, что можете:<br><b>А. Позвольте чудищу унести семя.</b> Если цель «Разомкните круг» в игре и ещё не достигнута, достигните её немедленно.<br><b>Б. Попробуйте забрать семя.</b> Поместите семя рядом с любой из главных развилок чудища. Пока семя находится на планшете чудища, вы не можете достигнуть цели «Взрастите саженец». После того как персонаж доберётся до этой развилки, он может поместить семя на любой участок местности, соседний с участком чудища.</p><p>Затем уберите жетон направления и все жетоны следов этого чудища. Замените его текущий инстинкт на «Вернуться в забытьё» (ЧК20).</p>"},"repeatable":false},{"id":"outcomes-084","code":"084","description":{"en":"<p>\\"You clamber onto the behemoth's great, granite brow. You feel a gentle hum from within the creature as the two of you share a quiet moment.\\"</p>\\n\\"You may discard 1 of the behemoth's curio to placate its demeanor once. If you do, resolve an effect of your choice below that corresponds to a current omen: \\n\\n<cloud>: Gain <minor_boost> to <might>.\\n<comet>: Degrade one of your maladies once.\\n<moon>: Gain <minor_boost> to <awareness>.\\n<star>: Gain <minor_boost> to <dexterity>.\\n<sun>: Gain <minor_boost> to <conviction>.\\n\\nThen end the encounter.\\"","ru":"<p><i><b>Вы вскарабкались на высокое гранитное чело чудища. Из его глубин доносился тихий гул, и вы ощутили, как на миг вас с исполином связало безмолвное единение.</b></i></p><p>Вы можете сбросить 1 сокровище чудища, чтобы успокоить его на 1. Если сделали это, выберите один из эффектов ниже, соответствующий текущему знамению:<br><cloud>— получите <minor_boost> к <might>.<br><moon>— получите <minor_boost> к <awareness><br><comet>— уменьшите любой недуг своего персонажа 1 раз.<br><star>— получите <minor_boost> к <dexterity>.<br><sun>— получите <minor_boost> к <conviction>.</p><p>Затем завершите встречу.</p>"},"repeatable":false},{"id":"outcomes-085","code":"085","description":{"en":"<p>By turning the fractious parties to unified cause, you have healed the rift in your people.</p>\\nAdd <lore><lore><lore> and add <population>. Illustrate the saga of the mediator on the primal cave wall, including the mediator mark.","ru":"<p><i><b>Сплотив враждующие стороны общей целью, вы положили конец расколу среди своего народа.</b></i></p><p>Добавьте <lore><lore><lore> и <population>. На стене первобытной пещеры изобразите историю о посреднике, включив в неё отметку посредника.</p>"},"repeatable":false,"marks":[{"label":"","image":"<mediator>"}]},{"id":"outcomes-086","code":"086","description":{"en":"<p>\\"As you clamber to the top of the behemoth's masklike visage, you can see almost across the horizon. Shadows twist and dance at the edge of where you can see, perhaps portending things to come. Your mind touches that of the behemoth.\\"</p>\\n\\"Choose one and resolve it:\\n\\n<b>A) Confront the behemoth's mind with your full will, driving it off:</b> If <comet> or <sun> is a current omen, aggravate the behemoth's demeanor by 1. The behemoth flees.\\n\\n<b>B) Seek knowledge in the behemoth's mind:</b> If <star> is a current omen, look at the top of 3 cards of the Night or Journey deck and put any number on the bottom.\\n\\n<b>C) Follow the behemoth's gaze to something in the distance:</b> If <cloud> or <moon> is a current omen, place a mystery token in a hex of your choice without a character.\\n\\nThen, end the encounter.\\"","ru":"<p><i><b>С вершины громадного, похожего на маску лица чудища был виден почти весь горизонт. Краем глаза вы заметили танцующие тени — они будто предрекали то, что ещё только грядёт. Ваш разум соприкоснулся с разумом чудища.</b></i></p><p>Выберите и разыграйте одно:<br><b>А. Попробуйте противостоять разуму чудища всей своей волей, заставив чудище отступить. </b>Если <comet> или <sun> — текущее знамение, разозлите чудище на 1. Чудище сбегает.<br><b>Б. Поищите знания в разуме чудища. </b>Если <star> — текущее знамение, посмотрите 3 верхние карты колоды ночи или пути и положите любое количество из них под низ колоды.<br><b>В. Проследите за устремлённым вдаль взглядом чудища. </b>Если <cloud> или <moon> — текущее знамение, поместите жетон тайны на любой участок местности без персонажа.</p><p>Затем завершите встречу.</p>"},"repeatable":false},{"id":"outcomes-087","code":"087","description":{"en":"<p>Through encounters with the behemoths, you lead your people to unity on the issue of these massive creatures.</p>\\n\\"Subtract <unrest><unrest><unrest>. Then resolve the first you are able:\\n\\n<b>A): Your people decide that conflict is inevitable, and incite the behemoths:</b> If all behemoths' demeanors are 6 or higher, add Vendetta (CB03) to your looming challenges. Illustrate the saga of the coming clash on the primal cave wall, including the mark of a behemoth with the highest demeanor and an active lair in the valley adorned with the wrath mark (i) (see Adorning Marks on Rulebook p.70).\\n\\n<b>B): Your people conclude that coexistence is possible:</b> If any behemoth has a demeanor of 5 or lower and <unrest> is 14 or lower, Add Vision of One (CB07) to your looming challenges. Illustrate the saga of the unifying path on the primal cave wall, including the mark of a behemoth with an active lair in the valley and the lowest demeanor and the mediator mark (ii).\\"","ru":"<p><i><b>Встречи с чудищами помогли вашему народу обрести единство в отношении этих гигантов.</b></i></p><p>Уберите <unrest><unrest><unrest>. Затем разыграйте первое, что можете:<br><b>А. Ваш народ решил, что конфликт неизбежен, и начал провоцировать чудищ.</b> Если значения нрава всех чудищ равны хотя бы 6, добавьте карту «Непримиримая вражда» (ИБ03) к грядущим испытаниям. На стене первобытной пещеры изобразите историю о грядущем столкновении, включив в неё отметку чудища с активным логовом в долине и с самым высоким значением нрава, украшенную отметкой гнева [i] (см. раздел «Украшающие отметки» в правилах игры на с. 70).<br><b>Б. Ваш народ понял, что можно мирно сосуществовать с чудищами. </b>Если значение нрава любого чудища не более 5 и значение <unrest> не более 14, добавьте карту «Единое видение» (ИБ07) к грядущим испытаниям. На стене первобытной пещеры изобразите историю о пути единения, включив в неё отметку чудища с активным логовом в долине и с самым низким значением нрава, а также отметку посредника [ii].</p>"},"repeatable":false,"marks":[{"label":"i","image":"<wrath>"},{"label":"ii","image":"<mediator>"}]},{"id":"outcomes-089","code":"089","description":{"en":"<p>You make your way back to the seed deep in the root-tunnels. Uncertainty grips your heart with cold hands as you approach.</p>\\n\\"Embark on the venture below (see Ventures on Rulebook p.60).\\n\\n<bi>The shadows of the tunnel seem colder than usual. Your purpose weighs on you.</bi>\\n<b>Group, Hazard:</b> Everyone must test <conviction> to press on. A character adds +2 if they have an item with a <fire> token on it, +2 if they are <i>indomitable</i>, and +4 if they have the plenty mark.\\n12+: You forge ahead with conviction. If any character resolves this result, the venture continues.\\n7–11: You slog on, painfully conscious of the weight of the Tangle hanging above your head. Lose <energy>. If any character resolves this result, the venture continues.\\n1–6: Uncertainty overwhelms you, and you turn back. Leave the venture. If all characters recieve this result, the venture fails.\\n\\n<bi>You creep into the seed-chamber. The thick shell protects the seed from meddling like your own, but you have come prepared to do what is necessary.</bi>\\n<b>Champion:</b> Someone must test <dexterity> to open a hole into the heart of the seed. Add +2 if you have <drill> and +2 if you are <i>cunning</i>.\\n11+: You crack through the shell without difficulty. The venture continues.\\n1–10: The shell refuses to crack. The venture fails unless a character spends <energy><energy> or <lore> to attempt this test again.\\n\\n<bi>One of the materials you have brought might enable you to affect the seed.</bi>\\n<b>Champion:</b> Someone must discard a rare material, then test <awareness> to apply a substance to the seed. Add +2 if you are <i>attuned</i> and +6 if you discarded moonblood.\\n14+: A shudder reverberates through the tunnels. Complete this venture and the associated goal.\\n1–13: You are unable to make any progress. The venture fails unless a character spends <energy><energy> or  to attempt this test again.\\"","ru":"<p><i><b>Вы вернулись к семени, сокрытому в глубине корневых туннелей. Сомнения ледяными пальцами сжимали ваше сердце, пока вы приближались.</b></i></p><p>Отправьтесь в поход (см. раздел «Походы» в правилах игры на с. 60).</p><p><i><b>Тени в туннеле казались холоднее обычного. Вас тяготила ваша же цель.</b></i><br><b>Группа, угроза.</b> Все персонажи в походе должны провести проверку <conviction>, чтобы продолжить путь. +2, если у персонажа есть предмет с <fire> , +2, если персонаж <i>неукротимый</i>, и +4, если у него есть отметка изобилия.<br><b>≥12:</b>  Вы уверенно продвигались вперёд. Если хотя бы один персонаж получил этот результат, продолжите поход.<br><b>7-11:</b>  Вы с трудом двигались вперёд, остро ощущая тяжесть Сплетения над головой. Потеряйте <energy>. Если хотя бы один персонаж получил этот результат, продолжите поход.<br><b>1-6:</b>  Вас одолели сомнения, и вы повернули назад. Покиньте поход. Если все персонажи покинули поход, он окончился неудачно.</p><p><i><b>Вы пробрались в полость с семенем. Плотная оболочка защищала семя от чужого вмешательства, но вы были готовы идти до конца.</b></i><br><b>Защитник.</b> Один из персонажей в походе должен провести проверку <dexterity>, чтобы пробить отверстие к сердцевине семени. +2, если у этого персонажа есть <drill>, и +2, если он <i>хитрый</i>.<br><b>≥11:</b>  Вы раскололи оболочку без особого труда. Продолжите поход.<br>1-10  Оболочка не поддалась. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy> или <lore>, что бы провести проверку ещё раз.</p><p><i><b>Один из принесённых вами материалов мог повлиять на семя.</b></i><br><b>Защитник.</b> Один из персонажей в походе должен сбросить редкий материал, а затем провести проверку <awareness>, чтобы нанести вещество на семя. +2, если персонаж <i>сосредоточенный</i>, и +6, если он сбросил лунную кровь.<br><b>≥14:</b>  По туннелям прошла дрожь. Завершите этот поход и достигните соответствующей цели.<br><b>1-13:</b>  Вам не удалось добиться успеха. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy> или <lore>, чтобы провести проверку ещё раз. </p>"},"repeatable":false,"marks":[{"label":"","image":"<plenty>"}]},{"id":"outcomes-090","code":"090","description":{"en":"<p>\\"You stand on the behemoth's back. Its bony spine pulses with an unexpected warmth.\\"</p>\\n\\"Choose one of the following and resolve it:\\n\\nA) Strike between the vertebrae with a weapon, watching as it rots away from contact with the behemoth: If you have a <i>weapon</i> item in your inventory, discard 1 <i>weapon</i> item to end the encounter. Aggravate the behemoth's demeanor by 2. The behemoth flees.\\n\\nB) Strike between the vertrebrae with your fist, feeling the life sap from you: Check 1 age box on your Character card. End the encounter. Aggravate the behemoth's demeanor by 2. The behemoth flees. Add this behemoth's mark to the Legend side of your Character card.\\n\\nC) Place your hand on the spine to guide the behemoth's stride: Discard all your <boost>; if you have none to discard, check 1 age box on your Character card. The behemoth flees. Placate its demeanor once. Add this behemoth's mark to the Legend side of your Character card.\\"","ru":"<p><i><b>Вы стояли на спине чудища. Его костистый хребет пульсировал неожиданным теплом.</b></i></p><p>Выберите и разыграйте одно:<br><b>А. Вонзите своё оружие меж позвонков и узрите, как оно рассыпается от соприкосновения с чудищем. </b>Если в вашем инвентаре есть оружие, сбросьте 1 оружие. Завершите встречу. Разозлите чудище на 2. Чудище сбегает.<br><b>Б. Ударьте между позвонками кулаком и ощутите, как из вас уходит жизненная сила.</b> Отметьте одну клетку возраста на карте персонажа. Завершите встречу. Разозлите чудище на 2. Чудище сбегает. Добавьте отметку этого чудища на сторону легенды карты своего персонажа.<br><b>В. Коснитесь хребта, чтобы направить чудище.</b>Сбросьте все свои <boost>. Завершите встречу. Чудище сбегает. Успокойте чудище на 1. Добавьте отметку этого чудища на сторону легенды карты своего персонажа.</p>"},"repeatable":false},{"id":"outcomes-092","code":"092","description":{"en":"<p>\\"Thunderous footfalls rock the valley, and you turn your head to see a terrifying sight: a creature of unfathomable scale smashing its way across the landscape. The behemoth's trail leads from where your elders entered the valley, and a great cloud of dust kicks up into the sky as the passageway is sealed forever. Whatever the future holds for your people, this behemoth will have a role in it.\\"</p>\\n<p>Return A Trail of Mysteries to the game box. Add Arrival (CA04) to your looming challenges.</p>","ru":"<p><i><b>Оглушительные шаги сотрясали долину. Вы обернулись и увидели ужасающее существо невообразимых размеров. Оно сминало всё на своём пути, и след его вёл от того места, где ваши старейшины вошли в долину. Огромное облако пыли клубилось над запечатанным навсегда проходом. Какой бы ни была дальнейшая судьба вашего народа, это чудище должно было сыграть в ней свою роль.</b></i></p><p>Верните в коробку карту цели «Пройдите по следам тайн» (ЦА11). Добавьте карту «Вторжение» (ИА04) к грядущим испытаниям.</p>"},"repeatable":false},{"id":"outcomes-093","code":"093","description":{"en":"<p>\\"You call back to your people's history of turmoil and mediation, and relate a story of flaring tempers that were soothed. Unity and peace spread across the valley as this story propagates.\\"</p>\\nSubtract <unrest><unrest><unrest>. If <unrest> would be reduced below 0 this way, add <lore> per point by which it would be reduced below 0.","ru":"<p><i><b>Вы воззвали к прошлому своего народа, полному волнений и примирений, и рассказали о вспышках гнева, которые удалось погасить. Ваша история передавалась из уст в уста, принося с собой мир и единство.</b></i></p><p>Уберите <unrest><unrest><unrest>. Если значение <unrest> должно опуститься ниже 0, добавьте <lore> за каждое , которое не может быть убрано.</p>"},"repeatable":false},{"id":"outcomes-094","code":"094","description":{"en":"<p>Could the coral spores originate from the wanderer? Your mind spins at the possibility. As you watch, a chunk of the comet detatches, vanishing beyond the horizon point. Certainty and fear swell in you. The wanderer is coming, and you have little time to prepare.</p>\\n<p>Add A Time to Prepare (CC03) to your looming challenges.</p>","ru":"<p><i><b>Неужели споры коралла в долину принёс Скиталец? Ваша голова шла кругом от этой мысли. Пока вы наблюдали, кусок кометы откололся и исчез за горизонтом. Осознание происходящего привело вас в ужас. Скиталец приближался, и времени на подготовку почти не осталось.</b></i></p><p>Добавьте карту «Час приготовлений» (ИВ03) к грядущим испытаниям.</p>"},"repeatable":false},{"id":"outcomes-095","code":"095","description":{"en":"<p>The behemoth shakes as it plods along, and the razor-sharp ridges on its back swing perilously even as you attempt to climb amidst them. Your brush with danger sets alight the fire of your heart.</p>\\nGain <minor_boost> to <conviction>.","ru":"<p><i><b>Спина чудища сотрясалась при ходьбе, и острые гребни на его спине опасно раскачивались, пока вы пробирались между ними. Риск раззадорил вас, наполнив храбростью.</b></i></p><p>Добавьте <minor_boost> к <conviction>.</p>"},"repeatable":false},{"id":"outcomes-096","code":"096","description":{"en":"<p>The behemoth makes its way to the foot of the blazing mountainside, as if to lead you along the last safe path past through the blistering clouds and crackling lightning that crown the spire.</p>\\n<p>\\"End this challenge.\\n\\nIllustrate the saga of the desolate guide on the primal cave wall, including the conclusion mark enclosing the BH4 mark. Add Ashfall (CY05) to your looming challenges. Add An Unlikely Alliance (GY06) to your goals at the start of Ashfall.\\"</p>","ru":"<p><i><b>Чудище направилось к подножию пылающего горного склона, будто указывая вам единственный безопасный путь сквозь обжигающие облака и трескучие молнии, венчающие вершину.</b></i></p><p>Завершите текущее испытание.<br>На стене первобытной пещеры изобразите историю об одиноком проводнике, включив в неё отметку ЧД4 [ii], заключённую в отметку окончания [i]. Добавьте карту «Пеплопад» (ИЕ05) к грядущим испытаниям. Когда выберете его, добавьте карту «Заключите необычный союз» (ЦЕ06) к целям.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<conclusion>"},{"label":"ii","image":"<bh4>"}]},{"id":"outcomes-097","code":"097","description":{"en":"<p>\\"The chaos spills over into violence, distracting from your current goals and leaving your people in a state of disarray. Pitched battles threaten to harm the innocent, destroy structures, and disturb all of the valley's inhabitants.\\"</p>\\n\\"Aggravate each behemoth's demeanor by 2. For each outpost, roll <1d6>. Add +1 to the result for each mystery token in that outpost's hex and each adjacent hex and +1 for each trace marker or behemoth in that outpost's hex and each adjacent hex. Then resolve the corresponding effect below for each outpost:\\n9+: During a brawl, hot embers are spilled, and flames spread throughout in the outpost. It becomes a ruin. Add <unrest><unrest> and subtract <population><population>.\\n5–8: A structure is razed in the chaos. Randomly select 1 structure and destroy it unless a character in that hex suffers <major_injury><major_injury><minor_injury>. Add <unrest>.\\n3–4: The situation simmers, but cooler heads ultimately prevail within the outpost. Add <unrest>.\\n1–2: Nothing catastrophic occurs in this outpost, and tensions ease slightly. Subtract <unrest>.\\"","ru":"<p><i><b>Хаос перерастал в насилие, отвлекал от важных целей и приводил ваш народ в замешательство. Ожесточённые сражения задели невинных жителей, разрушили здания и побеспокоили всех обитателей долины.</b></i></p><p>Разозлите каждое чудище на 2. Для каждого поселения бросьте <1d6>. +1 к результату за каждый жетон тайны на участке с поселением и на соседних участках, а также за каждый жетон следов или чудище на участке с поселением и на соседних участках. Затем разыграйте эффект для каждого поселения в зависимости от результата:<br><b>≥9:</b>  Во время очередной потасовки разлетелись горячие угли, и пламя охватило поселение. Поселение становится руинами. Добавьте <unrest><unrest>  и уберите <population><population>.<br><b>5-8:</b>  Одна из построек рухнула во время беспорядков. Разрушьте одно случайное сооружение в этом поселении, если только персонаж на этом участке местности не получит <major_injury><minor_injury><minor_injury>. Добавьте <unrest>.<br><b>3-4:</b>  Обстановка опасно накалилась, но в конце концов здравый смысл победил. Добавьте <unrest>.<br><b>1-2:</b>  В этом поселении беды не случилось, и напряжение немного ослабло. Уберите <unrest>.</p>"},"repeatable":false},{"id":"outcomes-098","code":"098","description":{"en":"<p>\\"You have investigated the scar in spite of your people's trepidation. Within the great, smouldering crater, one among your number communed with the coral and stilled its growth with their sacrifice. However, you may find that your people are not so receptive to this knowledge in light of your defiance...\\"</p>\\n<p>\\"End this challenge, then resolve the first you are able: \\n\\nA) Your people accept your decision, too exhausted by the crisis to raise strenuous objections, so an uneasy peace descends: If unrest is 8 or lower, add A Peaceful Season (CZ01) (even if previously completed) and Scorn of the Earth (CC04).\\n\\nB) Your people are enraged by your actions, and you are cast out from your society even as a great doom threatens your world: If unrest is 9 or higher, add Scorn of Humanity (CC05) to your looming challenges.\\"</p>","ru":"<p><i><b>Вы исследовали место падения, несмотря на беспокойство народа. В огромном тлеющем кратере один из вас бросил вызов кораллу и остановил его рост ценой собственной жизни. Однако могло оказаться, что люди не примут этого.</b></i></p><p>Завершите текущее испытание.</p><p>Затем разыграйте первое, что можете:<br><b>A. Ваш народ, слишком измученный бесконечными тяготами, чтобы протестовать, принял ваше решение — и так наступил хрупкий мир.</b> Если значение <unrest> не более 8, добавьте к грядущим испытаниям карту «Период затишья» (ИЯ01), даже если это испытание было завершено ранее, и карту «Презрение земли» (ИВ06).<br><b>Б. Ваш народ был разгневан вашими поступками. Вас изгнали из общины, несмотря на великое бедствие, угрожавшее миру. </b>Если значение <unrest> равно хотя бы 9, добавьте карту «Презрение человечества» (ИВ05) к грядущим испытаниям.</p>"},"repeatable":false},{"id":"outcomes-099","code":"099","description":{"en":"<p>\\"Atop the behemoth's head, you pull back your arm to deliver the final blow, then hesitate. To kill such a creature, who strode into the valley alongside your ancestors... you slump, and in that instant, the behemoth shudders. You topple to the ground. The behemoth looms over you, great gouts of sap flowing from its wounds. It regards you with a new recognition. You feel as if your place in the valley has changed in its eyes.\\"</p>\\n\\"End this challenge.\\n\\nAdd <unrest><unrest><unrest><unrest>. Set the alert behemoth's demeanor to \\\\\\"2.\\\\\\" Illustrate the saga of the broken cycle on the primal cave wall, including the alert behemoth's mark, the caution mark (i), and the growth mark (ii). Permanently raise the conviction and <awareness> of each character that was on the venture when it was completed by 1 (to a maximum of 7). Add the alert behemoth's mark and the growth mark (ii) to the Legend side of each of those Character cards.\\n\\nThen end the Epoch. See Codex p.204 to begin Epoch 3.\\"","ru":"<p><i><b>Стоя на голове чудища, вы занесли руку для последнего удара, но замерли в нерешительности. Убить великое существо, что пришло в долину вместе с вашими предками?.. Вы обмякли, и в этот момент чудище вздрогнуло. Вы упали на землю. Чудище нависло над вами, его раны сочились. Оно смотрело на вас по‑новому, словно признав ваше место в долине.</b></i></p><p>Завершите текущее испытание.</p><p>Добавьте <unrest><unrest><unrest><unrest>. Установите значение нрава бодрствующего чудища на 2. На стене первобытной пещеры изобразите историю о разомкнутом круге, включив в неё отметку бодрствующего чудища, отметку осторожности [i] и отметку становления [ii]. Навсегда увеличьте <conviction> и <awareness> на 1 (не более чем до 7) каждого персонажа, оставшегося в походе на момент его завершения. Добавьте отметку чудища и отметку становления на сторону легенды карты каждого из этих персонажей.</p><p>Затем завершите эру. См. с. 204, чтобы начать эру 3.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<caution>"},{"label":"ii","image":"<growth>"}]},{"id":"outcomes-101","code":"101","description":{"en":"<p>\\"The behemoth's secret has given you a means of subduing it. This unexpected discovery gives you a way to keep the behemoth's incredible power in check. In generations to come, this mythic discovery will grant your descendents a means to forge a new relationship with this creature. But will they wield this power responsibly? Or will power over the behemoth sow the seeds of hubris, and cause your successors to forget to respect their place in the vast and powerful natural world around them?\\"</p>\\n<p>\\"At the end of any day, you may end this challenge.\\n\\nIllustrate the saga of the behemoth's secret on the primal cave wall, including the alert behemoth's mark and the discovery mark.\\n\\nAdd Festival of Remembrance (CA07) and The Behemoth's Warning (CA10) to your looming challenges.\\n\\"</p>","ru":"<p><i><b>Вы раскрыли секрет укрощения чудища. Это неожиданное открытие позволило вам сдержать невероятную мощь исполинского существа, а позже позволит грядущим поколениям выстроить с чудищем новые отношения. Но будут ли потомки распоряжаться мудро этим знанием? Или власть над гигантом посеет семена высокомерия и заставит ваших преемников забыть об уважении к своему месту в этом огромном мире?</b></i></p><p>В конце любого дня можете завершить текущее испытание.</p><p>На стене первобытной пещеры изобразите историю о секрете чудища, включив в неё отметку бодрствующего чудища и отметку открытия.<br>Добавьте карты «Праздник памяти» (ИА07) и «Предостережение чудища» (ИА10) к грядущим испытаниям.</p>"},"repeatable":false,"marks":[{"label":"","image":"<discovery>"}]},{"id":"outcomes-107","code":"107","description":{"en":"<p>You sit atop the pile within your society, yet now you find yourself facing the very problems that led to your exile...</p>\\n\\"End this challenge.\\n\\nSubtract <unrest><unrest><unrest><unrest>. Illustrate the saga of the ascendant on the primal cave wall, including the harrowing mark (i) and the rebellion (ii) mark. Add Scorn of the Earth (CC06) to your looming challenges.\\"","ru":"<p><i><b>Вы занимали высокое положение среди своего народа, но проблемы, с которыми вам довелось столкнуться, привели к вашему изгнанию... </b></i></p><p>Завершите текущее испытание.</p><p>Уберите <unrest><unrest><unrest><unrest>. На стене первобытной пещеры изобразите историю о восхождении к власти, включив в неё отметку ужаса [i] и отметку мятежа [ii]. Добавьте карту «Презрение земли» (ИВ06) к грядущим испытаниям.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<harrowing>"},{"label":"ii","image":"<rebellion>"}]},{"id":"outcomes-108","code":"108","description":{"en":"<p>You have created a lasting monument to past generations. The maintenance of the place of reverence you have created becomes an important task to your people.</p>\\n<p>\\"Illustrate the saga of the inscriptions on the primal cave wall, including the scribe mark. Gain the Legends (KN15) Knowledge card and the Symbols (KN17) Knowledge card.\\n\\nYour society gains the Legend-Speaker (MA11) mantle power.\\"</p>","ru":"<p><i><b>Вы создали вечный памятник прошлым поколениям. Уход за этим местом стал важной задачей для вашего народа.</b></i></p><p>На стене первобытной пещеры изобразите историю о письменах, включив в неё отметку летописца. Получите карту знаний «Легенды» (ЗБ15) и карту знаний «Символы» (ЗБ17). Ваша община получает силу мантии «Глашатай легенд» (МА11).</p>"},"repeatable":false,"marks":[{"label":"","image":"<scribe>"}]},{"id":"outcomes-109","code":"109","description":{"en":"<p>\\"Your people's history remains preserved in oral tradition. The effort to remember past figures is considerable, but each generation works to maintain a connection to the past. Still, some lessons are inevitably lost to time, vanishing through the cracks of collective memory.\\"</p>\\n<p>\\"Illustrate the saga of the distant days on the primal cave wall, including the mystery mark. Gain the Legends (KN15) Knowledge card. \\n\\nYour society gains the Legend-Speaker (MA11) mantle power.\\n\\nPut all Legend cards in the draw bag, then draw 2 at random. These legends are forgotten. Return them to the game box. They cannot be used by your society any longer.\\"</p>","ru":"<p><i><b>История вашего народа по‑прежнему передавалась из уст в уста. Вы делали всё возможное, чтобы помнить деяния предков, и каждое поколение стремилось сохранить связь с прошлым. И всё же какие‑то истины неизбежно терялись, ускользая сквозь трещины человеческой памяти.</b></i></p><p>Завершите текущее испытание.</p><p>На стене первобытной пещеры изобразите историю о далёких днях, включив в неё отметку тайны. Получите карту знаний «Легенды» (ЗБ15). Ваша община получает силу мантии «Глашатай легенд» (МА11).<br>Возьмите 2 случайные карты из колоды легенд. Эти легенды забыты. Верните их в коробку — ваша община больше не может их использовать.</p>"},"repeatable":false,"marks":[{"label":"","image":"<mystery>"}]},{"id":"outcomes-111","code":"111","description":{"en":"<p>As you excavate, you find a pearlescent shard. It is unlike any stone you have seen, lighter and more porous than most rocks of its size. It crumbles at your touch, but perhaps there is a proper way to handle it...</p>\\n\\"You may test <might> to pull the shard from the wall. Add +2 if you are <i>indomitable</i>, +2 if you have <dig>, and +4 if you have the <comet> or the coral mark.\\n12+: Gain 2 dead coral.\\n8–11: Gain 1 dead coral.\\n1–7: The shard refuses to come loose. No effect.\\"","ru":"<p><i><b>Во время раскопок вы нашли перламутровый осколок, совсем не похожий на камни, с которыми вам приходилось работать. Он был легче и пористее, чем обычно, и крошился под кончиками пальцев. Но вдруг был способ извлечь его, не повредив?</b></i></p><p>Вы можете провести проверку <might>, чтобы вытащить осколок из стены. +2, если вы <i>неукротимый</i>, +2, если у вас есть <comet>, и +4, если у вас есть отметка  или отметка коралла.<br><b>≥12:</b>  Получите 2 мёртвых коралла.<br><b>8-11:</b>  Получите 1 мёртвый коралл.<br><b>1-7:</b>  Осколок не поддался. Без эффекта.</p>"},"repeatable":false,"marks":[{"label":"","image":"<coral>"}]},{"id":"outcomes-112","code":"112","description":{"en":"<p>The stories grow more consistent day by day: a flattened glade here, a massive rent in the land there. Something powerful and unpredictable stalks the outskirts of this isolated place, likely arriving at the same time you did. Your society drifts toward a branch in the river.</p>\\n\\"As a group, the players must choose one of the following paths for your society:\\n\\nA) Prepare defenses for a coming conflict: Add <population>. Design the Palisade (ST11) structure (without spending <lore>).\\n\\nB) Seek refuge deeper in the valley: Add Across the Ice (GA06) to your goals.\\"","ru":"<p><i><b>Слухи из разных уголков долины начали складываться в единую картину: тут — примятая поляна, там — зияющий разлом в земле. Что‑то могущественное и опасное обитало на окраинах этого уединённого места. Казалось, оно пришло одновременно с вами. Ваша община встала перед выбором.</b></i></p><p>Совместно выберите один из следующих путей развития общины:<br><b>А. Подготовьтесь к возможной угрозе. </b>Добавьте <population>. Спроектируйте частокол (СР11), не тратя <lore>.<br><b>Б. Уйдите вглубь долины в поисках укрытия. </b>Добавьте карту «Пройдите по ледяному покрову» (ЦА06) к целям.</p>"},"repeatable":false},{"id":"outcomes-113","code":"113","description":{"en":"<p>\\"Over many generations, the old Tangle withers and dies, the ground growing dusty and dry as the floral jungle succumbs to the blight. However, the Tangle's seed will one day grow to surpass its parent, creating a new Tangle in which your people's society can flourish for untold generations to come.\\"</p>\\n\\"Add <population><population><population> and subtract <unrest><unrest><unrest>.\\n\\nIllustrate the saga of the Tangle reborn on the primal cave wall, including the mystery and Tangle marks.Your society persists.\\n\\nCongratulations! You have completed Stonesaga's campaign! To immortalize a photo of your primal cave wall and see other people's works of art, we invite you to share your saga with our community! \\n\\n@[Insert Link]@\\n\\nTo continue playing Stonesaga, see Playing Endless Mode After a Campaign on Rulebook p.97, or Beginning Subsequent Campaigns on Rulebook p.97.\\"","ru":"<p><i><b>За многие поколения старое Сплетение увяло и умерло. Земля стала сухой и пыльной, когда цветущие джунгли уступили губительному заболеванию. Однако семя однажды даст всходы и превзойдёт своего родителя, создав новое Сплетение, в котором ваша община сможет процветать на протяжении бесчисленных поколений.</b></i></p><p>Добавьте <population><population><population> и уберите <unrest><unrest><unrest>.<br></p><p>На стене первобытной пещеры изобразите историю о возрождении Сплетения, включив в неё отметку Сплетения [i] и отметку тайны [ii]. Ваша община <b>выжила</b>.<br></p> <p>Поздравляем! Вы завершили кампанию «Наскальной истории»! Чтобы увековечить фотографию своей стены первобытной пещеры и увидеть произведения искусства других игроков, мы приглашаем вас поделиться своей историей с нашим сообществом!<br>Чтобы продолжить играть в «Наскальную историю», см. в правилах игры раздел «Начало следующих кампаний» на с. 97 или раздел «Бесконечный режим» на с. 102.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<tangle>"},{"label":"ii","image":"<mystery>"},{"label":"","image":"<qrcode>"}]},{"id":"outcomes-114","code":"114","description":{"en":"<p>Having fullfilled its instincts and returned to its lair, the behemoth rests.</p>\\n\\"The alert behemoth that completed Return to Slumber becomes dormant. Remove its miniature from the valley. Then resolve the first you are able:\\n\\n<b>A) If there are 1 or more other behemoths with active lairs in the valley,</b> randomly select one of them to become alert. Place its miniature in the hex with its lair and assign it an Instinct (see Behemoth States on Rulebook p.75).\\n\\n<b>B) If there are no other behemoths with active lairs in the valley,</b> place 4 trace marker's on lair of the behemoth that became dormant. Remove 1 at the end of each day. When there are no trace markers left on the dormant behemoth's lair, that behemoth becomes alert again. Place it in the hex with its lair and assign it an Instinct (see Behemoth States on Rulebook p.75).\\"","ru":"<p><i><b>Ведомое своими инстинктами, чудище завершило путь, вернулось в логово и погрузилось в покой.</b></i></p><p>Это чудище становится спящим. Затем разыграйте первое, что можете:<br><b>А. Если в долине есть одно или несколько других чудищ с активными логовами,</b> выберите случайное из них — оно становится бодрствующим. Поместите фигурку этого чудища на участок местности с его логовом и назначьте ему инстинкт (см. в правилах игры на с. 75).<br><b>Б. Если в долине нет других чудищ с активными логовами,</b> положите 4 жетона следов на логово чудища, которое стало спящим. В конце каждого дня убирайте по 1 жетону. Когда на логове не останется жетонов следов, это чудище снова становится бодрствующим. В этом случае поместите фигурку этого чудища на участок местности с его логовом и назначьте ему инстинкт (см. в правилах игры на с. 75).</p>"},"repeatable":false},{"id":"outcomes-116","code":"116","description":{"en":"<p>As the season passes, the conflicting sides grow ever-more intractable. When the dissident group departs, they take many able bodies with them, splitting your population and leaving both groups vulnerable.</p>\\nSubtract <population><population><population><population>. Illustrate the saga of broken bonds on the primal cave wall, including the schism mark.","ru":"<p><i><b>Сменялись времена года, а разногласия только сильнее разделяли ваших людей, превращая их в непримиримых врагов. Когда недовольные ушли, забрав с собой сильных членов общины, обе стороны остались ослабленными и разобщёнными.</b></i></p><p>Завершите текущее испытание.</p><p>Уберите <population><population><population><population>. На стене первобытной пещеры изобразите историю о разрыве связей, включив в неё отметку раскола.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<schism>"}]},{"id":"outcomes-117","code":"117","description":{"en":"<p>Your instincts tell you that some entity is sending some message through this, and you think you can interpret it...</p>\\nAdd <lore> and gain <minor_boost> to an attribute of your choice. If you have a behemoth mark, add <lore><lore><lore> and gain <major_boost> to an attribute of your choice, instead.","ru":"<p><i><b>Ваше чутьё подсказывало, что некая сущность намеренно оставила это странное послание, — и вам казалось, что вы способны понять его…</b></i></p><p>Добавьте <lore> и получите <minor_boost> к любой характеристике. Если у вас есть отметка чудища, вместо этого добавьте <lore><lore><lore> и получите <major_boost> к любой характеристике.</p>"},"repeatable":false},{"id":"outcomes-119","code":"119","description":{"en":"<p>The blast of lightning starts a small fire that threatens to spread...</p>\\n<p>Add Suppress the Flames (GZ20) to your goals.</p>","ru":"<p><i><b>Сухая трава занялась от вспышки молнии — и огонь уже грозился выйти из‑под контроля...</b></i></p><p>Добавьте карту «Остановите огонь» (ЦЯ20) к целям.</p>"},"repeatable":false},{"id":"outcomes-121","code":"121","description":{"en":"<p>The outpost you have built is lightly developed, comprised primarily of structures that can easily be torn down and relocated. Over the years, your people become adroit at relocating their lodgings, allowing them to follow the game herds as they move or harvest the most abundant regions of the valley year-to-year.</p>\\n<p>\\"Illustrate the saga of untethered paths on the primal cave wall, including the caravan mark. Your people's outposts can be relocated during and between challenges. Gain the Caravans (KN09) Knowledge card.\\"</p>","ru":"<p><i><b>Возведённое вами поселение едва ли можно было назвать основательным, ведь оно состояло в основном из лёгких построек, которые несложно разобрать и перенести. Со временем ваши люди так приноровились к кочевому укладу, что теперь они могли следовать за дикими животными и собирать урожай в самых плодородных уголках долины, переходя от места к месту из года в год.</b></i></p><p>На стене первобытной пещеры изобразите историю о безграничных путях, включив в неё отметку каравана. Поселения вашего народа могут быть перемещены как в процессе испытаний, так и между ними. Получите карту знаний «Караваны» (ЗБ09).</p>"},"repeatable":false,"marks":[{"label":"","image":"<caravan>"}]},{"id":"outcomes-126","code":"126","description":{"en":"<p>The mystery unsolved, your people cannot help but what lies just beyond the grasp of their insight.</p>\\n\\"End this challenge.\\n\\nThen, as a group, the players must choose one of the following paths for your society:\\n\\n<b>A) Accept that some things exceed human understanding:</b> Subtract <unrest><unrest>. Add the mystery mark (i) to the legend side of each of your Character cards. Illustrate the saga of the question unswered on the primal cave wall, including the alert behemoth's mark and the mystery mark (i).\\n\\n<b>B) Never give up the search for answers:</b> Permanently raise each characters' <awareness> by 2 (to a maximum of 7). Add the growth mark (ii) to the Legend side of each of your Character cards. Add \\\\\\"ending a challenge with 1 or more mystery tokens in the valley\\\\\\" to the Taboos section of the Culture page of the Journal. Gain the Taboos Knowledge card (KN18). Illustrate the saga of the unending quest on the primal cave wall, including the alert behemoth's mark and the growth mark (ii).\\n\\nThen end the current epoch. Refer to Codex p.196 to continue your campaign into Epoch 2.\\"","ru":"<p><i><b>Загадка оставалась неразгаданной, и ваши люди невольно задумывались, что же кроется за пределами их восприятия.</b></i></p><p>Завершите текущее испытание.</p><p>Затем совместно выберите один из следующих путей развития общины:<br><b>А. Примите, что есть вещи, непостижимые для человеческого разума. </b>Уберите  <unrest><unrest>. Добавьте отметку тайны [i] на сторону легенды карты каждого персонажа. На стене первобытной пещеры изобразите историю о непостижимом вопросе, включив в неё отметку бодрствующего чудища и отметку тайны [i].<br><b>Б. Никогда не прекращайте поиски ответов.</b>Навсегда увеличьте <awareness> каждого персонажа на 2 (не более чем до 7). Добавьте отметку становления [ii] на сторону легенды карты каждого персонажа. Запишите «Завершение испытания хотя бы с 1 жетоном тайны в долине» в раздел «Табу» на странице «Культура» в журнале. Получите карту знаний «Табу» (ЗБ18), если у вас её нет. На стене первобытной пещеры изобразите историю о бесконечном поиске, включив в неё отметку бодрствующего чудища и отметку становления [ii].</p><p>Завершите текущую эру. См. с. 196, чтобы начать эру 2.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<mystery>"},{"label":"ii","image":"<growth>"}]},{"id":"outcomes-129","code":"129","description":{"en":"<p>\\"You make your way toward a place where shadow and fear cling to every surface. In the quiet outside the behemoth's unattended lair, none dare to speak. Within, who knows what you will find?\\"</p>\\n\\"Embark on venture below (see Ventures on Rulebook p.60).\\n\\n<bi>The behemoth must enter and exit this lair somehow, but its means of egress are mysterous. You have to find your own way in.</bi>\\n<b>Group, Wonder:</b> Everyone must test <awareness> to find an entrance. Each character add +2 for each <i>exploration</i>item they have and +2 if they are <i>inquisitive</i> or <i>intrepid</i>.\\n12+: You observe something of interest about the behemoth. Add <lore>. If any character resolves this result, the venture continues.\\n1–11: You are unable to make progress. If all characters on the venture resolve this result, the venture fails unless a character spends <energy><energy> or <lore> to attempt this test again.\\n\\n<bi>Within the lair, you are reminded of its colossal inhabitant at every turn. The traces of its passage, the tracks, the smell: even the echoes of this massive beast have a terrible power. You must rally your spirits to continue!</bi>\\n<b>Group, Hazard:</b> Everyone must test <conviction> to carry on through fear. Each character adds +2 if they have a <i>talisman</i> item and +2 if they are <i>indomitable</i> or <i>vengeful</i>.\\n10+: You push through this continous assault on your sense of place in the world. If any character resolves this result, the venture continues.\\n1–9: You founder at such proof of your cosmic insignificance. Leave the venture, then flee. If all characters on the venture resolve this result, the venture fails.\\n\\n<bi>Within the lair, you approach a small chamber carved from the earth. The behemoth must have created this hollow with intention. What could be inside?</bi>\\n<b>Champion, Wonder:</b> Someone must test <dexterity> to sneak into the lair. Add +2 if you have a <i>cloak</i> item and +2 if you are <i>cunning</i>.\\n13+: You slide inisde. Complete this venture and the associated goal.\\n1–12: You scrabble at the entrance, unable to reach within, and the noise seems to echo painfully throughout the lair. Aggravate the behemoth's demeanor by 1. The venture fails unless a character spends <energy><energy> or <lore> to attempt this test again.\\n\\"","ru":"<p><i><b>Вы отправились туда, где ужас вместе с тенями скользил по каждой поверхности. В звенящей тишине у пустующего логова чудища никто не осмеливался нарушить молчание. Что же ждало вас внутри? Оставалось только гадать…</b></i></p><p>Отправьтесь в поход (см. раздел «Походы» в правилах игры на с. 60).</p><p><b>Чудище должно было как‑то входить и выходить из этого логова, но его путь был покрыт тайной. Вам пришлось искать способ попасть внутрь.</b></p><p><b>Группа, чудо. </b>Все персонажи в походе должны провести проверку <awareness>, чтобы найти вход. +2 за каждый имеющийся у персонажа предмет для <i>исследования</i>, и +2, если персонаж <i>любознательный </i>или <i>отважный</i>.</p><p><b>≥12:</b>  Вы узнали о чудище нечто интересное. Добавьте <lore>. Если хотя бы один персонаж получил этот результат, продолжите поход.<br><b>1-11:</b>  Вы не преуспели. Если все персонажи получили этот результат, поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy> или <lore>, чтобы провести проверку ещё раз.</p><p><i><b>В логове на каждом шагу вы натыкались на напоминания об исполинском обитателе сего места. Следы, отметины, запах — даже отголоски этого чудища устрашали. Вы должны были собраться с духом, чтобы продолжить!</b></i></p><p><b>Группа, угроза.</b> Все персонажи в походе должны провести проверку <conviction>, чтобы преодолеть страх. +2, если у персонажа есть <i>талисман</i>, и +2, если персонаж <i>неукротимый </i>или <i>мстительный</i>.</p><p><b>≥10:</b>  Вы преодолели невыносимое давление, искажающее ваше ощущение реальности. Если хотя бы один персонаж получил этот результат, продолжите поход.<br><b>1-9:</b>  Вы растерялись перед доказательствами своей ничтожности в масштабах вселенной. Покиньте поход, затем сбегите. Если все персонажи получили этот результат, поход окончился неудачно.</p><p><i><b>Внутри логова вы нашли небольшую вырытую в земле полость. Чудище, несомненно, создало это укрытие намеренно. Что оно могло прятать там?</b></i></p><p><b>Защитник, чудо.</b> Один из персонажей в походе должен провести проверку <dexterity>, чтобы прокрасться в логово. +2, если у него есть <i>накидка</i>, и +2, если этот персонаж <i>хитрый</i>.</p><p><b>≥13:</b>  Вы проскользнули внутрь. Завершите этот поход и достигните соответствующей цели.<br><b>1-12:</b>  Вы не смогли попасть внутрь и наделали много шума. Разозлите чудище на 1. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy> или <lore>, чтобы провести проверку ещё раз.</p>"},"repeatable":false},{"id":"outcomes-130","code":"130","description":{"en":"<p>As a cold autumn deepens into the prelude to an icy winter. Without lodgings, even the early frosts take a particularly harsh toll. Clouds darken the horizon, blotting out the starlight above.</p>\\n\\"End this challenge. Subtract <population>. \\n\\nHowever, some hope remains. In their time in the valley, your people have developed new survival skills. Your society gains the following mantle powers: Prey-Stalker (MA01), Secret-Finder (MA02), Friend-Guide (MA03), Safe-Keeper (MA04). Record these in the Mantle Powers section on the Culture page of the Journal. At the start of each subsequent challenge, players will select one mantle power for each character based on their mantle, as described in Mantle Powers on Rulebook p.65.\\n\\nThen, as a group, the players must choose one of the following paths for your society:\\n\\n<b>A) Urge your people to complete the outpost at any cost, heedless of stormclouds on the horizon:</b> Subtract <population> and add <unrest>, then build 1 designed structure in one of your outposts without paying its resource or <energy> costs. You may repeat this process up to 2 times. Illustrate the saga of frigid resolve on the primal cave wall, including the <cloud> mark and the harrowing mark (i). Add Festival of Remebrance (CA07) to your looming challenges. Add the following to your goals: Gather Stores (GA03), Seek the Omens (GA07), Stoke the Flame (GA08), A Trail of Mysteries (GA11).\\n\\n<b>B) Tell your people that you will follow the river of starlight above to a more suitable home:</b> Your outpost becomes a ruin (flip the overlay to it to its inactive side and note on its card that it is a ruin). Illustrate the saga of the horizon's promise on the primal cave wall, including the arrival mark (ii) and the <star> mark. Add A Place of Solace (CA03) to your looming challenges. Add the following to your goals: Gather Stores (GA03), Seek the Omens (GA07), Stoke the Flame (GA08), A Trail of Mysteries (GA11).\\"","ru":"<p><i><b>Осенний холод крепчал, предвещая наступление ледяной зимы. Без надёжного крова над головой даже ранние заморозки ощущались особенно суровыми. Облака темнели на горизонте, скрывая высокое звёздное небо.</b></i></p><p>Завершите текущее испытание.</p><p>Уберите <population>. За время, проведённое в долине, ваш народ развил новые навыки выживания. Ваша община получает следующие силы мантий: «Следопыт» (МА01), «Знаток секретов» (МА02), «Друг-наставник» (МА03), «Хранитель» (МА04). Запишите их в раздел «Силы мантий» на странице «Культура» в журнале. В начале каждого следующего испытания выбирайте по одной силе для каждого персонажа в соответствии с их мантиями, как описано в разделе «Силы мантий» на с. 65 правил.</p><p>Затем совместно выберите один из следующих путей развития общины:<br><b>A. Призовите свой народ завершить начатые постройки любой ценой, несмотря на надвигающиеся штормовые облака. </b>Уберите <population> и добавьте <unrest>, затем постройте одно спроектированное сооружение в одном из своих поселений, не оплачивая его стоимость. Можете повторить это действие ещё 2 раза или меньше. На стене первобытной пещеры изобразите историю о закалённой решимости, включив в неё отметку <cloud> и отметку ужаса [i]. Добавьте карту «Праздник памяти» (ИА07) к грядущим испытаниям. Добавьте к целям следующие карты: «Соберите припасы» (ЦА03), «Отыщите знамения» (ЦА07), «Разведите огонь» (ЦА08), «Пройдите по следам тайн» (ЦА11).<br><b>Б. Сообщите своему народу, что вы отправитесь вслед за рекой звёздного света в лучшее пристанище.</b>Построенное вами поселение становится руинами (переверните накладку стороной руин вверх и укажите на карте поселения, что теперь это руины). На стене первобытной пещеры изобразите историю о надежде, что сулит горизонт, включив в неё отметку прибытия [ii] и отметку <star>. Добавьте карту «Прибежище» (ИА03) к грядущим испытаниям. Добавьте к целям следующие карты: «Соберите припасы» (ЦА03), «Отыщите знамения» (ЦА07), «Разведите огонь» (ЦА08), «Пройдите по следам тайн» (ЦА11).</p>"},"repeatable":false,"marks":[{"label":"i","image":"<harrowing>"},{"label":"ii","image":"<arrival>"}]},{"id":"outcomes-132","code":"132","description":{"en":"<p>Your people know the wanderer will soon return reborn, and exalt in its miraculous journey into the sun. The revels grow raucous as people celebrate this cosmic marvel.</p>\\nEach character gains <minor_boost> to an attribute of their choice. If they have a <i>coral</i> item, they may degrade a malady twice or gain <major_boost> to an attribute of choice instead.","ru":"<p><i><b>Ваш народ знал, что Скиталец вскоре вернётся перерождённым, и восхищался его чудесным путешествием к солнцу. С нарастающим шумом и весельем люди радовались этому запредельному чуду.</b></i></p><p>Каждый персонаж получает <minor_boost> к любой характеристике. Вместо этого, если у персонажа есть предмет <i>коралла</i>, он может 2 раза уменьшить недуг или получить <major_boost> к любой характеристике.</p>"},"repeatable":false},{"id":"outcomes-134","code":"134","description":{"en":"<p>Within this newly discovered part of the valley, you find a twisting expanse of ravines and pits. Steam issues from the fissures, driving back the cold even on the harshest of nights.</p>\\n\\"If there are 1 or fewer geothermal vents overlays in the valley, place a geothermal vents overlay in a hex in the the newly added terrain tray, choosing an unexplored hex without an overlay, if able. Roll <1d6> and place it in the corresponding zone: (1–2): A, (3–4), B, (5–6) C.\\n\\nSee geothermal vents on Codex p.210.\\"","ru":"<p><i><b>В этой недавно обнаруженной части долины вы нашли лабиринт из каньонов и ям. Из трещин выходил пар, сохраняя тепло даже в самые холодные ночи.</b></i></p><p>Если в долине не более 1 накладки геотермального источника, поместите накладку геотермального источника на участок в последней добавленной основе местности, выбрав неисследованный участок без накладок, если возможно. Бросьте <1d6>, чтобы поместить геотермальный источник в соответствующий район: [1-2]  A, [3-4] Б, [5-6] В. Подробнее о геотермальных источниках см. на с. 210.</p>"},"repeatable":false},{"id":"outcomes-136","code":"136","description":{"en":"<p>Your people have become accustomed to living in and around the Tangle, striding the vines beneath the flickering shadows of vast blooms. This land of eternal verdance and explosive cycles of growth provides for your people in the years to come, and your population expands as a result. Your relationship with the land deepens...</p>\\n\\"At the end of any day, you may end this challenge. Then, add <population><population>. Then, as a group, the players must choose one of the following paths for your society:\\n\\n<b>A) Begin to build within the Tangle:</b> Add <population><population><population><population>. You may place up to 1 outpost in a Tangle hex (without spending energy or resources). Illustrate the saga of the Tangle's gift on the primal cave wall, including the Tangle mark (i) and the plenty mark (ii).\\n\\n<b>B) Forbid building in the Tangle:</b> Add \\\\\\"building outposts in the Tangle\\\\\\" to the Taboos section of the Culture page of the Journal. Gain the Taboos (KN19) Knowledge card. Illustrate the saga of the reverent harvesters on the primal cave wall, including the taboo mark (iii) and the Tangle mark (i).\\"","ru":"<p><i><b>Ваш народ привык жить в Сплетении и рядом с ним, шагая по лианам под мерцающими тенями гигантских цветков. Эта земля, полная буйной растительности и неукротимого роста, давала вашему народу всё необходимое, и ваша община начала разрастаться. Вы ощущали всё более тесную связь с этим местом...</b></i></p><p>В конце любого дня можете завершить текущее испытание.</p><p>Добавьте <population><population>. Затем совместно выберите один из следующих путей развития общины:<br><b>А. Начните строить внутри Сплетения.</b>  Добавьте <population><population><population><population>. Вы можете поместить 1 поселение на участок Сплетения (не тратя энергию и ресурсы). На стене первобытной пещеры изобразите историю о даре Сплетения, включив в неё отметку Сплетения [i] и отметку изобилия [ii].<br><b>Б. Запретите строительство в Сплетении. </b>Запишите «Строительство поселений в Сплетении» в раздел «Табу» на странице «Культура» в журнале. Получите карту знаний «Табу» (ЗБ18), если у вас её нет. На стене первобытной пещеры изобразите историю о благоговейных жнецах, включив в неё отметку табу [iii] и отметку Сплетения [i].</p>"},"repeatable":false,"marks":[{"label":"i","image":"<tangle>"},{"label":"ii","image":"<plenty>"},{"label":"iii","image":"<taboo>"}]},{"id":"outcomes-143","code":"143","description":{"en":"<p>In the innermost chamber, you discover a polished stone which reflects an image like a still pond. At first, you believe the stone is reflecting yourself. However, as you examine the image, you notice that it is merely a person who resembles you, with the subtle differences of a branching family tree. You meet the tired eyes of this familiar stranger, and a vision floods into your mind. You awaken to the mirror stone shattered into tiny cubes of glass and your head throbbing with impossible knowledge.</p>\\n\\"Resolve the first you are able:\\n\\n<b>A) Even as the vision fades, the wanderer's blazing trail leaves an afterimage in your mind.</b> If <comet> is a current omen, find Goal card GC05. The player who completed the final <i>champion</i> test may look at that card for no more than 1 minute, then returns it to the Goal deck and describes it to the other players for any amount of time. Then illustrate the saga of vibrant scar on the primal cave wall, including BH1's mark (i) and the prophecy mark (ii) enclosing the <comet> mark. \\n\\n<b>B) You remember bleached bones rattling in a dry wind.</b> If <sun> is a current omen, find Goal card GZ08. The player who completed the final <i>champion</i> test may look at that card for no more than 1 minute, then returns it to the Goal deck and describes it to the other players for any amount of time. Then illustrate the saga of the sweeping death on the primal cave wall, including BH1's mark (i), the harrowing mark (iii) and the prophecy mark (ii) enclosing the <sun> mark. \\n\\n<b>C) The image of a stranger's warm smile lingers in your mind.</b> If <star> is a current omen, find Goal card GZ10. The player who completed the final <i>champion</i> test may look at that card for no more than 1 minute, then returns it to the Goal deck and describes it to the other players for any amount of time. Then illustrate the saga of foretold meeting unshed on the primal cave wall, including BH1's mark (i) and the prophecy mark (ii) enclosing the <star> mark.\\n\\n<b>D) Your entire body reverberates with the force of the vision.</b> If <cloud> or <moon> is a current omen, find Goal card GZ16. The player who completed the final <i>champion</i> test may look at that card for no more than 1 minute, then returns it to the Goal deck and describes it to the other players for any amount of time. Then illustrate the saga of ruinous clash on the primal cave wall, including BH1's mark (i) and the prophecy mark (ii) enclosing the <moon> mark.\\n\\nAt the end of this challenge, end the current epoch. Refer to Codex p.196 to continue your campaign into Epoch 2.\\"","ru":"<p><i><b>В глубине пещеры вы нашли отполированный камень, отражающий всё, словно озёрная гладь. Сначала вам показалось, что в отражении вы видите себя. Однако, присмотревшись, вы заметили, что это был человек, лишь похожий на вас, с едва уловимыми отличиями. Вы встретились взглядом с усталыми глазами незнакомца — и ваш разум захлестнуло видение. Вы пришли в себя рядом с осколками зеркального камня, а ваша голова гудела от немыслимого знания.</b></i></p><p>Разыграйте первое, что можете:<br><b>А. Даже когда видение угасло, пылающий след Странника остался в вашем сознании. </b>Если <comet> — текущее знамение, найдите карту цели ЦВ05. Игрок, прошедший последнюю проверку защитника, может изучать эту карту не более 1 минуты, после чего должен вернуть её в колоду целей и описывать её другим игрокам в течение любого времени. Затем на стене первобытной пещеры изобразите историю о живом кратере, включив в неё отметку ЧД1 [i] и отметку <comet>, заключённую в отметку пророчества [ii].<br><b>Б. Вы вспомнили побелевшие кости, гремящие на иссушающем ветре. </b>Если <sun> — текущее знамение, найдите карту цели ЦЯ08. Игрок, прошедший последнюю проверку защитника, может изучать эту карту не более 1 минуты, после чего должен вернуть её в колоду целей и описывать её другим игрокам в течение любого времени. Затем на стене первобытной пещеры изобразите историю о стремительной смерти, включив в неё отметку ЧД1 [i], отметку ужаса [iii] и отметку <sun>, заключённую в отметку пророчества [ii].<br><b>В. В сознании остался образ тёплой улыбки незнакомца. </b> Если  <star>— текущее знамение, найдите карту цели ЦЯ10. Игрок, прошедший последнюю проверку защитника, может изучать эту карту не более 1 минуты, после чего должен вернуть её в колоду целей и описывать её другим игрокам в течение любого времени. Затем на стене первобытной пещеры изобразите историю о ещё не случившейся, но предсказанной встрече, включив в неё отметку ЧД1 [i] и отметку <star>, заключённую в отметку пророчества [ii].<br><b>Г. Всё ваше тело содрогнулось от силы видения. </b>Если <cloud> или <moon> — текущее знамение, найдите карту цели ЦЯ16. Игрок, прошедший последнюю проверку защитника, может изучать эту карту не более 1 минуты, после чего должен вернуть её в колоду целей и описывать её другим игрокам в течение любого времени. Затем на стене первобытной пещеры изобразите историю о роковом столкновении, включив в неё отметку ЧД1 [i] и отметку <moon>, заключённую в отметку пророчества [ii].</p><p>В конце этого испытания завершите текущую эру. См. с. 196, чтобы начать эру 2.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<bh1>"},{"label":"ii","image":"<prophecy>"},{"label":"iii","image":"<harrowing>"}]},{"id":"outcomes-147","code":"147","description":{"en":"<p>\\"Through strength, guile, or sheer tenacity, you have overcome the behemoth on three occasions. As dawn breaks the darkness, you see the behemoth near the outskirts of the wilds. Despite its vast, inscrutable countenance, you get the impression that it is regarding you with uncertainty. It withdraws to its den, and you can't help but wonder how your conflicts with the behemoth will shape the lives of future generations.\\"</p>\\n\\"At the end of any day, you may end this challenge.\\nSubtract <unrest>. Illustrate the saga of the great battle, including the battle mark (i) and the alert behemoth's mark adorned with the wrath mark (ii). See Adorning Marks on Rulebook p.70.\\n\\nAdd Festival of Remembrance (CA07) and Night of Storms (CA09) to your looming challenges. \\n\\"","ru":"<p><i><b>Силой, хитростью или упорством — вы одолели чудище трижды. Когда рассвет прорезал тьму, вы увидели его у окраин диких земель. Оно было всё ещё необъятно и непостижимо, но теперь в его взгляде будто бы сквозила неуверенность. Чудище отступило к своему логову, а вы невольно задумались, как ваши столкновения с ним отзовутся в судьбе грядущих поколений.</b></i></p><p>В конце любого дня можете завершить текущее испытание.</p><p>Уберите <unrest>. На стене первобытной пещеры изобразите историю о великой битве, включив в неё отметку битвы [i] и отметку бодрствующего чудища, украшенную отметкой гнева [ii]. См. раздел «Украшающие отметки» в правилах игры на с. 70.</p><p>Добавьте карты «Праздник памяти» (ИА07) и «Ночь бурь» (ИА09) к грядущим испытаниям.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<battle>"},{"label":"ii","image":"<wrath>"}]},{"id":"outcomes-149","code":"149","description":{"en":"<p>The walls begin to feel clammy as you slog ever deeper into the darkness, and you slowly realize that the moisture is dripping from your body. A fever overtakes you.</p>\\n\\"Test <might> to resist disease. Add +2 if you are <i>wary</i> and add +4 if you have the plague mark.\\n12+: You shake off the worst of the effects. Suffer <minor_disease>.\\n6–11: You become ill. Suffer <major_disease>.\\n1–5: Resolve 6–11, then add Pestilence (CZ03) to your looming challenges unless the plague mark is on the primal cave wall.\\"","ru":"<p><i><b>Погружаясь глубже во тьму, вы ощущали, как стены становятся всё более липкими и влажными. Спустя какое‑то время вы поняли, что липким и влажным стало и ваше тело. Вас охватила лихорадка.</b></i></p><p>Проведите проверку <might>, чтобы сопротивляться болезни. +2, если вы <i>осторожный</i>, и +4, если у вас есть отметка чумы.<br><b>≥12:</b>  Вам удалось справиться с самыми тяжёлыми последствиями. Получите <minor_disease>.<br><b>6-11:</b>  Вы заболели. Получите <major_disease>.<br><b>1-5:</b>  Разыграйте исход как при 6-11, затем добавьте карту «Мор» (ИЯ03) к грядущим испытаниям, если на стене первобытной пещеры нет отметки чумы.</p>"},"repeatable":false,"marks":[{"label":"","image":"<plague>"}]},{"id":"outcomes-154","code":"154","description":{"en":"<p>\\"At the top of the mountain, flames and smoke belch forth from the great caldera. Lightning flashes in the clouds above the mountain. You will have to act quickly to seal the great maw before your people's future is buried in ash.\\"</p>\\n\\"Embark on the venture below (see Ventures on Rulebook p.60).\\n\\n<bi>Thunder shakes the sky as lightning cracks around the lip of the caldera. You must find cover swiftly!</bi>\\n<b>Group, Weather:</b> Everyone must test <awareness> to find cover. A character adds +2 if they are <i>wary</i>, and +6 if the behemoth is aiding the venture.\\n10+: You spot an overhang and duck beneath it just as a flash of lightning sears the ground above. If any character resolves this result, the venture continues.\\n1–9: You are thrown from your feet by the crack of lightning. Suffer <major_injury>. If all characters on the venture resolve this result, the venture fails unless a character spends <energy><energy> or <lore><lore> to attempt this test again.\\n\\n<bi>Choking smoke bellows forth from the maw of fire, and you must push through the curtains of ash.</bi>\\n<b>Group, Weather:</b> Everyone must test <might> to persevere. A character adds +2 if they are <i>intrepid</i> and +6 if the behemoth is aiding the venture. You may discard 1 water to add +4 to the result.\\n12+: You keep the smoke from your lungs. If any character resolve this result, the venture continues.\\n8–11: You push forward, but inhale a blazing lungful of smoke. Suffer <major_disease>. If any character resolves this result, the venture continues.\\n1–7: You wander in the smoke, but are unable to push your way through. Suffer <major_disease><minor_disease> and leave the venture. If all characters leave the venture, the venture fails.\\n\\n<bi>At the heart of the caldera, magma bubbles angrily, but perhaps the right offering can quench its fury.</bi>\\n<b>Champion:</b> Someone must discard a rare material or a <i>coral</i>, <i>moonblood</i>, <i>silk</i>, or <i>trophy</i> item, then test <dexterity> to hurl an offering into the bubbling pool. Add +2 if you discarded a <i>coral</i>, <i>moonblood</i>, or <i>silk</i> item, +4 if you discarded a <i>trophy</i> item, +2 if you are <i>resourceful</i>, and +6 if the behemoth is aiding the venture.\\n14+: With a flash of light, the object embeds into the magma, and the mountain rumbles as stone begins to solidify over the top of the caldera. Complete this venture and the associated goal.\\n1–13: As the object immolates, the molten stone churns ever-more fiercely. Each character on the venture suffers <minor_injury>, then the venture fails unless a character spends <energy><energy> or <lore> to attempt this test again.\\n\\"","ru":"<p><i><b>Пламя и дым извергались из огромного кратера на вершине горы. Молнии вспыхивали в тучах над вершиной. Вам нужно было спешить, чтобы запечатать гигантскую пасть, пока будущее вашего народа не оказалось погребено под пеплом.</b></i></p><p>Отправьтесь в поход (см. раздел «Походы» в правилах игры на с. 60).</p><p><b><i>Гром сотрясал небо, а молнии рассекали воздух над краем кратера. Вам нужно было срочно найти укрытие!</i></b></p><p><b>Группа, погода. </b>Все персонажи в походе должны провести проверку <awareness>, чтобы найти укрытие. +2, если персонаж <i>осторожный</i>, и +6, если чудище помогает в походе.<br><b>≥10:</b>  Вы заметили выступ и успели укрыться под ним как раз в тот момент, когда молния обожгла землю выше по склону. Если хотя бы один персонаж получил этот результат, продолжите поход.<br><b>1-9 : </b>Вас сбило с ног ударом молнии. Получите <major_injury>. Если все персонажи получили этот результат, поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy> или <lore><lore>, чтобы провести проверку ещё раз.</p><p><i><b>Из огненной пасти валил едкий дым, и вам предстояло пробиваться сквозь пелену пепла.</b></i></p><p><b>Группа, погода. </b>Все персонажи в походе должны провести проверку <might>. +2, если персонаж <i>отважный</i>, и +6, если чудище помогает в походе. Персонаж может сбросить 1 воду, чтобы добавить 4 к результату.<br><b>≥12:</b>  Вы не дали дыму проникнуть в лёгкие. Если хотя бы один персонаж получил этот результат, продолжите поход.<br><b>8-11:</b>  Вы продолжили путь, но вдохнули обжигающий дым. Получите <major_disease>. Если хотя бы один персонаж получил этот результат, продолжите поход.<br><b>1-7:</b>  Вы потерялись в дыму. Получите <major_disease> и <minor_disease>, затем покиньте поход. Если все персонажи получили этот результат, поход окончился неудачно.</p><p><b><i>В самом сердце кратера кипела грозная магма — но, быть может, правильная жертва усмирила бы её гнев.</i></b></p><p><b>Защитник. </b>Один из персонажей в походе должен сбросить редкий материал либо предмет с ключевым словом «коралл», «лунная кровь», «шёлк» или «трофей», а затем провести проверку <dexterity>, чтобы бросить подношение в кипящее жерло. +2, если был сброшен предмет с ключевым словом «коралл», «лунная кровь» или «шёлк», +4, если был сброшен предмет с ключевым словом «трофей», +2, если персонаж <i>изобретательный</i>, и +6, если чудище помогает в походе.<br><b>≥14:</b>  Сверкнув, подношение погрузилось в магму, и гора начала дрожать, когда камень затвердел над кратером. Завершите этот поход и достигните соответствующей цели.<br><b>1-13:</b>  Брошенный предмет воспламенился, и расплавленный камень начал бурлить ещё яростнее. Каждый персонаж в походе получает <minor_injury>. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy> или <lore>, чтобы провести</p>"},"repeatable":false},{"id":"outcomes-155","code":"155","description":{"en":"<p>Your familiarity with fire has grown, and with tenacity, you can create a flame through friction reliably. Still, you cannot help but wonder if there are quicker ways to make sparks.</p>\\n\\"Gain the Firemaking (KN06) Knowledge card. Illustrate the saga of the tended coals on the primal cave wall, including the blaze mark.\\n\\nDesign the Fire Pit (ST02) structure (without spending <lore>). See Structure Designs on Rulebook p.34.\\n\\nYour society gains the Hearth-Tender (MA15) mantle power. Add The Secret Ways (GA09) to your goals.\\"","ru":"<p><i><b>Вы стали лучше управляться с огнём и теперь, приложив усилия, научились высекать искры трением. Однако вы не переставали задумываться, как разжечь пламя ещё быстрее.</b></i></p><p>Получите карту знаний «Разведение огня» (ЗБ06). На стене первобытной пещеры изобразите историю о заботливо поддерживаемых углях, включив в неё отметку пламени. Спроектируйте костровую яму (СР02), не тратя <lore>. См. раздел «Проектирование сооружения» в правилах игры на с. 34. Ваша община получает силу мантии «Сторож очага» (МА15). Добавьте карту «Изучите тайные тропы» (ЦА09) к целям.</p>"},"repeatable":false,"marks":[{"label":"","image":"<blaze>"}]},{"id":"outcomes-165","code":"165","description":{"en":"<p>\\"The behemoth's mighty foot comes down, crushing the meteor that contains the heart of the coral. A great chiming echoes across the valley as stalks of coral deaden to ashy grey.\\nThe valley may still be scarred by the impact, but a sense of normalcy slowly returns in the coming days. Under the watch of the behemoth, your people begin to flourish once again.\\"</p>\\n\\"Add <population><population><population> and subtract <unrest><unrest><unrest>. Remove the impact site overlay. Flip each coral overgrowth to its inactive side.\\n\\nIllustrate the saga of mighty vanquisher beyond time on the primal cave wall, including the coral mark (i) and the conclusion mark (i) enclosing that behemoth's mark. Your society <b>persists.</b>\\n\\nCongratulations! You have completed <i>Stonesaga<i>'s campaign! To immortalize a photo of your primal cave wall and see other people's works of art, we invite you to share your saga with our community! \\n\\n@[Insert Link]@\\n\\nTo continue playing <i>Stonesaga<i>, see Playing Endless Mode After a Campaign on Rulebook p.97, or Beginning Subsequent Campaigns on Rulebook p.97.\\"","ru":"<p><i><b>Могучая лапа чудища обрушилась, сокрушая метеорит, в котором покоилось сердце коралла. Гулкий звон катился по долине, пока коралловые стебли не обесцветились, став пепельно‑серыми. Долина ещё не залечила шрамы от удара, но с каждым днём жизнь возвращалась в прежнее русло. Под присмотром чудища ваша община снова начала расцветать.</b></i></p><p>Добавьте <population><population><population> и уберите <unrest><unrest><unrest>. Уберите накладку места падения. Переверните все коралловые заросли неактивной стороной вверх.</p><p>На стене первобытной пещеры изобразите историю о могучем победителе вне времени, включив в неё отметку коралла [i] и отметку этого чудища, заключённую в отметку окончания [ii]. Ваша община <b>выжила</b>.</p><p>Поздравляем! Вы завершили кампанию «Наскальной истории»! Чтобы увековечить фотографию своей стены первобытной пещеры и увидеть произведения искусства других игроков, мы приглашаем вас поделиться своей историей с нашим сообществом!</p><p>Чтобы продолжить играть в «Наскальную историю», см. в правилах игры раздел «Начало следующих кампаний» на с. 97 или раздел «Бесконечный режим» на с. 102.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<coral>"},{"label":"ii","image":"<conclusion>"},{"label":"","image":"<qrcode>"}]},{"id":"outcomes-168","code":"168","description":{"en":"<p>\\"The figure explains themself, telling you of their joy, their grief, their loss.You find yourself filled with a desire to return their story to your people's living memory.\\"</p>\\n\\"Add <lore><lore><lore>. You may randomly select a Legend card that has been forgotten by your society (set-aside in the game box). It becomes one of your society's legends.\\"","ru":"<p><i><b>Человек рассказал о себе, делясь своей радостью, горем и утратами. В вашем сердце зародилось стремление возродить его историю в памяти вашего народа.</b></i></p><p>Добавьте  <lore><lore><lore>. Вы можете случайным образом выбрать карту легенды, забытую вашей общиной (которую вы вернули в коробку). Она снова становится одной из легенд вашей общины.</p>"},"repeatable":false},{"id":"outcomes-175","code":"175","description":{"en":"<p>You pull a creature you have not seen before from the slick ocean. Its has a bulbous head and several arms, which squirm as you hold it in your hands. Its large eyes stare up at you questioningly.</p>\\n\\"Choose one and resolve it:\\n\\n<b>A) Take pity on the creature and return it to the sea:</b> The creature slides back into the water. Add <lore><lore>.\\n\\n<b>B) See whether it's good to eat:</b> You find it stringy, but full of life-giving water despite living in the mercurial, toxic sea. Gain 2 game and 4 water.\\"","ru":"<p><i><b>Вы вытащили из ртутного моря создание, которое прежде не встречали. У него была вздутая голова и несколько щупалец, которые извивались у вас в руках. Его большие глаза вопрошающе смотрели на вас.</b></i></p><p>Выберите и разыграйте одно:<br><b>А. Пожалейте существо и верните его в море.</b> Существо скользнуло обратно в воду. Добавьте <lore><lore>.<br><b>Б. Проверьте, пригодно ли оно в пищу. </b> Мясо оказалось жилистым, но насыщенным живительной влагой, хотя существо обитало в переменчивом и ядовитом море. Получите 2 дичи и 4 воды.</p>"},"repeatable":false},{"id":"outcomes-186","code":"186","description":{"en":"<p>Throughout the days of darkness, you work hard to distribute food to the needy. However, your ability to distribute food is often disrupted by those who panic and hoard supplies. Still, you and your people persevere.</p>\\n\\"End this challenge.\\n\\nAdd <unrest><unrest><unrest><unrest>. Add Dangerous Raids (GZ26) to your goals. Illustrate the saga of the days of darkness on the primal cave wall, including the blackened sky mark (i) and the rebellion mark (ii). Then, as a group, the players must choose one of the following paths for your society:\\n\\n<b>A) Seek the coral's origins in a strange and icy land:</b> If the Starlit Sea mark (iii) is on the primal cave wall, add To Speak Beyond the Sky (CC07) to your looming challenges.\\n\\n<b>B) Face a champion of old who now serves the coral:</b> If the coral mark is enclosed in the conclusion mark (iv) on the primal cave wall, add The Comet's Chosen (CC08) to your looming challenges.\\n\\n<b>C) Seek out the lair of your ancient nemesis:</b> If the behemoth's blood mark (v) adorns the mark of a behemoth with an inactive lair on the primal cave wall, add Behemoth of the Comet (CC09) to your looming challenges.\\n\\n<b>D) Turn to a behemoth's bond of ancient days:</b> If a behemoth's mark is enclosed in the bond mark (vi) on the primal cave wall and that behemoth has an active lair in the valley, add Bond of the Behemoth (CC10) to your looming challenges.\\n\\n<b>E) Flee the valley once and for all:</b> Add Exodus (CZ09) to your looming challenges.\\"","ru":"<p><i><b>Когда тьма окутала землю, вы старались поддерживать нуждающихся пищей. Вам часто мешали люди, что в панике собирали ресурсы, даже когда те им были не нужны. Но всё же вам и вашему народу удалось справиться.</b></i></p><p>Завершите текущее испытание.</p><p>Добавьте <unrest><unrest><unrest><unrest>. Добавьте карту «Переживите опасные налёты» (ЦЯ26) к целям. На стене первобытной пещеры изобразите историю о тёмных днях, включив в неё отметку почерневшего неба [i] и отметку мятежа [ii]. Затем совместно выберите один из следующих путей развития общины:<br><b>A. Поищите происхождение коралла в незнакомой ледяной земле. </b> Если на стене первобытной пещеры есть отметка Звёздного моря [iii], добавьте карту «Разговор со звёздами» (ИВ07) к гряду щим испытаниям.<br><b>Б. Сразитесь с защитником древности, который теперь служит кораллу. </b>Если на стене первобытной пещеры есть отметка коралла, заключённая в отметку окончания [iv], добавьте карту «Избранник кометы» (ИВ08) к грядущим испытаниям.<br><b>В. Отправьтесь на поиски логова своего древнего врага. </b>Если на стене первобытной пещеры есть отметка чудища с неактивным логовом, украшенная отметкой крови чудища [v], добавьте карту «Чудище кометы» (ИВ09) к грядущим испытаниям.<br><b>Г. Обратитесь к связи чудища с прошлым. </b>Если на стене первобытной пещеры есть отметка чудища, заключённая в отметку связи [vi], добавьте карту «Узы чудища» (ИВ10) к грядущим испытаниям. <br><b>Д. Сбегите из долины раз и навсегда. </b>Добавьте карту «Исход» (ИЯ09) к грядущим испытаниям.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<blackenedsky>"},{"label":"ii","image":"<rebellion>"},{"label":"iii","image":"<starlitsea>"},{"label":"iv","image":"<behemothsblood>"},{"label":"v","image":"<bond>"}]},{"id":"outcomes-188","code":"188","description":{"en":"<p>You put your hand into something wet as you delve into the earth and find a pool of strange, silvery liquid. There must be a trick to capturing this strange liquid...</p>\\n\\"You may test <awareness> to capture the slippery substance. Add +2 if you are <i>resourceful</i>, +2 if you have a Waterskin, and +4 if you have the moonblood mark.\\n12+: Gain 2 moonblood.\\n8–11: Gain 1 moonblood.\\n1–7: The substance slips through your fingers. No effect.\\"","ru":"<p><i><b>Спускаясь под землю, вы зацепили рукой что‑то влажное и обнаружили лужу странной серебристой жидкости. Как бы ухитриться собрать это необычное вещество?</b></i></p><p>Можете провести проверку <awareness>, чтобы попытаться собрать скользкое вещество. +2, если вы <i>изобретательный</i>, +2, если у вас есть «Бурдюк», и +4, если у вас есть отметка лунной крови.<br><b>≥12:</b> Получите 2 лунные крови. <br><b>8-11:</b>  Получите 1 лунную кровь.<br><b>1-7 :</b> Вещество выскользнуло у вас из пальцев. Без эффекта. </p>"},"repeatable":false,"marks":[{"label":"","image":"<moonblood>"}]},{"id":"outcomes-193","code":"193","description":{"en":"<p>You put your hand into something wet as you delve into the earth and find a pool of strange, silvery liquid. There must be a trick to capturing this strange liquid...</p>\\n\\"Place an inactive coral overgrowth overlay in a hex of your choice. Choose a hex with no overlays, if able. Roll <1d6> and place it in the corresponding zone: (1–2): A, (3–4), B, (5–6) C. If an overlay would be placed over another overlay this way, reroll the result.\\n\\nRepeat this process once for each challenge you have played this epoch (prior to this one), to a maximum of placing 3 overgrowths this way. \\n \\nAdd Uncover the Coral's Secrets (GB08) to your goals (if not previously completed).\\n\\nThen, resolve as many of the following as possible:\\n\\n<b>A) The forests are twisted by the coral's presence:<b> If there are 1 or more Verdant Vale hexes in the valley, add CF01-CF04 to the Forest Foraging deck.\\n\\n<b>B) The prairies teem with odd new life:</b> If there are 1 or more Skyreach Plateau hexes in the valley, add CP01-CP04 to the Prairie Foraging deck.\\n\\n<b>C) The Tangle becomes even stranger than usual:</b> If there are 1 or more Tangle hexes in the valley, add CT01-CT04 to the Glade Foraging deck (if available).\\n\\n<b>D) Ominous things stalk the night:</b> Add NR01-NR02 to the Night deck.:\\n\\n<b>E) The land itself is transformed:</b> Add JR01-03 to the Journey deck.\\n\\nLiving coral appears as a bonus object on these new Foraging cards.\\"","ru":"<p><i><b>По всей долине с пугающей скоростью начали разрастаться кораллы.</b></i></p><p>Поместите неактивные коралловые заросли на любой участок, выбрав участок без накладок, если возможно (поместите столько зарослей, сколько испытаний завершили в текущей эре до этого момента, но не более 3). Для каждых зарослей бросьте <1d6>, чтобы поместить их в соответствующий район: [1-2] А, [3-4] Б, [5-6] В. Если заросли должны быть помещены поверх другой накладки, перебросьте <1d6>.</p><p>Добавьте карту «Раскройте тайну коралла» (ЦБ08) к целям (если вы не достигли её ранее).<br>Затем разыграйте как можно больше из следующего:<br><b>А. Леса изменились из-за воздействия кораллов. </b>Если в долине есть хотя бы 1 участок Дивной долины, добавьте карты КЛ01–КЛ04 в колоду добычи припасов в лесу.<br><b>Б. В степи закипела странная новая жизнь. </b>Если в долине есть хотя бы 1 участок Поднебесной равнины, добавьте карты КС01–КС04 в колоду добычи припасов в степи.<br><b>В. Сплетение стало ещё более странным, чем прежде. </b> Если в долине есть хотя бы 1 участок Сплетения, добавьте карты КП01–КП04 в колоду добычи припасов на полянах (если возможно).<br><b>Г. Зловещие создания рыскали в ночи. </b>Добавьте карты НК01–НК02 в колоду ночи.<br><b>Д. Сама земля изменилась. </b>Добавьте карты ПК01–ПК03 в колоду пути.</p><p>На новых картах добычи припасов появляется новый бонусный ресурс — живой коралл.</p>"},"repeatable":false},{"id":"outcomes-194","code":"194","description":{"en":"<p>A dark swirl moves under the water and you lash out to seize it. To your shock, something grabs back, and the water rushes up to meet you. You struggle to the surface, your would-be quarry vanishing into the depths.</p>\\n\\"Test <conviction> to hold on! Add +2 if you are <i>intrepid</i>, +4 if you have a <i>fishing<i> item, and +2 if you have the <star> mark.\\n13+: You stay on the creature, pulling it from the depths. It is a great fish, and its scales sparkle in the light. Gain 4 fish. Your society gains the River-Chaser (MA06) mantle power.\\n1–12: You lose your nerve. Discard any items you were using to fish.\\"","ru":"<p><i><b>Что‑то тёмное мелькнуло в толще воды, и вы метнулись, чтобы схватить это. К вашему ужасу, нечто схватило вас в ответ и утащило под воду. С трудом вынырнув, вы увидели, как добыча уходит на глубину.</b></i></p><p>Проведите проверку <conviction>, чтобы схватить и удержать существо. +2, если вы <i>отважный</i>, +4, если у вас есть предмет для <i>рыбалки</i>, и +2, если у вас есть отметка <star>.</p><p><b>≥13:</b>  Вы удержали добычу и вытащили её из воды. Это была огромная рыба со сверкающей чешуёй. Получите 4 рыбы. Ваша община получает силу мантии «Речной охотник» (МА06).<br><b>1-12:</b>  Вы утратили решимость. Сбросьте все предметы, которые вы использовали для рыбалки.</p>"},"repeatable":false},{"id":"outcomes-195","code":"195","description":{"en":"<p>\\"Your spires fall and your walls are shattered. Coral fronds wave gently in the ruins of your once-prosperous villages, and bleached bones peak out from the rubble of flattened homes. The wrath of the risen behemoth has tested your people's resilience and found it wanting.\\"</p>\\n\\"Illustrate the saga of the ancient vengeance on the primal cave wall, including the coral mark (i) and the alert behemoth's mark adorned with the wrath mark (ii). Then, as a group, the players must choose one of the following paths for your society:\\n\\nA) Accept that your saga ends with that of your people: Your campaign ends and your society <b>vanishes</b>. See Ending a Campaign on Rulebook p.97.\\n\\nThis end may not be a happy one, but it can still be instructive to future peoples who inhabit the valley. To immortalize a photo of your primal cave wall and see other people's works of art, we invite you to share your saga with our community!\\n\\n@[Insert Link]@\\n\\nTo continue playing <i>Stonesaga</i>, see Beginning Subsequent Campaigns on Rulebook p.97. Or you could switch to Endless Mode, as described on Rulebook p.97.\\n\\nB) Strike out on your own to escape this doom: Add Exodus (CZ09) to your looming challenges.\\"","ru":"<p><i><b>Возведённые вами шпили пали, а стены разрушились. Коралловые побеги мягко колыхались среди руин некогда процветавших поселений, а выбеленные кости торчали из‑под обломков рухнувших домов. Гнев пробудившегося чудища подверг испытанию ваш народ — и тот не выдержал.</b></i></p><p>Завершите текущее испытание.</p><p>На стене первобытной пещеры изобразите историю о древней мести, включив в неё отметку коралла [i] и отметку бодрствующего чудища, украшенную отметкой гнева [ii]. Затем совместно выберите один из следующих путей развития общины:<br><b>А. Смиритесь с тем, что ваша история будет погребена вместе с народом. </b>Ваша кампания завершилась, а община <b>исчезла</b>. См. раздел «Конец кампании» на с. 97 правил игры. <br>Такой конец хоть и далёк от счастливого, но он всё же может послужить уроком для народов, которые заселят эту долину в будущем. Чтобы увековечить фотографию своей стены первобытной пещеры и увидеть произведения искусства других игроков, мы приглашаем вас поделиться своей историей с нашим сообществом!<br>Чтобы продолжить играть в «Наскальную историю», см. в правилах игры раздел «Начало следующих кампаний» на с. 97 или раздел «Бесконечный режим» на с. 102.<br><b>Б. Отправьтесь в путь, чтобы избежать гибели. </b>Добавьте карту «Исход» (ИЯ09) к грядущим испытаниям.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<coral>"},{"label":"ii","image":"<wrath>"}]},{"id":"outcomes-196","code":"196","description":{"en":"<p>By force of arms and shedding of blood, you force the ringleaders of this dissident group to renounce their plans, flee, or perish. Without these figures to rally them, the rest of your people abandon their efforts to leave. Your harsh actions leave scars across the saga of your people, and the consequences may bubble up for generations to come.</p>\\nSubtract <population><population><population><population>, add <unrest><unrest><unrest><unrest>. Illustrate the saga of the harsh judgment, including the battle mark and the schism mark.","ru":"<p><i><b>Силой оружия и ценой пролитой крови вы заставили предводителей мятежа отказаться от своих планов, вынудили их выбрать — бежать или погибнуть. Без своих вождей недовольные люди бросили попытки покинуть свои земли. Ваши жестокие действия оставили след в истории вашего народа, и последствия могут отразиться на будущих поколениях.</b></i></p><p>Уберите <population><population><population><population>. Добавьте <unrest><unrest><unrest><unrest>. На стене первобытной пещеры изобразите историю о суровом суде, включив в неё отметку битвы [i] и отметку раскола [ii].</p>"},"repeatable":false,"marks":[{"label":"i","image":"<battle>"},{"label":"ii","image":"<schism>"}]},{"id":"outcomes-197","code":"197","description":{"en":"<p>Even in the face of your aggression, the behemoth remains inscrutable...</p>\\n\\"Embark on the venture below (see Ventures on Rulebook p.60).\\n\\n<bi>What does it know that you do not? You start casting about, looking for incoming danger...</bi>\\n<b>Behemoth, Champion:</b> Someone must contest <awareness> versus the behemoth's <dexterity> to find the safe path. Add +2 if you are <i>indomitable</i>.\\nWin (Equal or higher): You lead the others, keeping your group out of the behemoth's line of sight as you approach. The venture continues.\\nLose (Lower): The behemoth's gaze falls upon you, and your will saps. Degrade all of your <boost>. The venture fails unless a character spends <energy> to attempt this test again.\\n\\n<bi>A frozen storm sweeps in as you approach the behemoth. Hands freeze to the weapons they clench, and ice tears at your lungs.</bi>\\n<b>Behemoth, Group, Weather:</b> Everyone must contest <might> or <conviction> versus the behemoth's <conviction> to avoid harm. A character adds +2 if they have a <i>clothing</i> item, +2 if they have an item with a <fire> token on it, and +2 if they are <i>wary</i>.\\nWin (Equal or higher): You press on despite the hardship. If any character resolves this result, the venture continues.\\nLose (Lower): The cold saps your strength, and you suffer <major_disease><minor_disease> and degrade all of your boosts unless you leave the venture. If all characters on the venture resolve this result, the venture fails.\\n\\n<bi>As you approach close enough to touch the behemoth, it shifts subtly, watching you. You believe the symbol you found could undo the creature, but getting onto its shell to paint it will be no easy feat!</bi>\\n<b>Behemoth, Champion:</b> Someone must contest <dexterity> versus the behemoth's <awareness> to fight. Add +2 if you have a <i>weapon</i> item, and +4 if you have a <i>trophy</i> item.\\nWin (Equal or higher): Using your weapon, you etch the symbol into the shell. Complete this venture and the associated goal.\\nLose (Lower): Rime begins to encase you, and your weapon shatters. Discard one <i>weapon</i> item, if able. The venture fails unless a character suffers <major_disease><major_disease> or spends <lore> to attempt this test again.\\"","ru":"<p><i><b>Даже представляя угрозу для чудища, вы не могли постичь природу этого существа…</b></i></p><p>Отправьтесь в поход (см. раздел «Походы» в правилах игры на с. 60).</p><p><b><i>Какие неведомые вам тайны знало чудище? Вы принялись оглядываться, пытаясь заметить приближающуюся опасность...</i></b></p><p><b>Чудище, защитник. </b>Один из персонажей в походе должен провести состязание, чтобы найти безопасный путь: его <awareness> против <dexterity> чудища. +2, если персонаж <i>неукротимый</i>.<br><b>Успех. </b>Вы вели остальных, скрывая приближающуюся группу от взгляда чудища. Продолжите поход.<br><b>Провал.</b> Взгляд чудища упал на вас, и ваша воля ослабла. Уменьшите все свои <boost>. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy>, чтобы провести состязание ещё раз.</p><p><i><b>Снежная буря накрыла вас, когда вы приблизились к чудищу. Руки примёрзли к оружию, а ледяной воздух разрывал ваши лёгкие.</b></i></p><p><b>Чудище, группа,</b> погода. Все персонажи в походе должны провести состязание, чтобы не пострадать: <might> или <conviction> против <conviction> чудища. +2, если у персонажа есть <i>одежда</i>, +2, если у него есть предмет с  <fire>, и +2, если он <i>осторожный</i>.<br><b>Успех. </b>Вы продолжили двигаться вперёд, несмотря на трудности. Если хотя бы один персонаж получил этот результат, продолжите поход.<br><b>Провал.</b> Холод отнимал у вас силы. Покиньте поход или получите <major_disease> и <minor_disease>, а также уменьшите все свои <boost>. Если все персонажи получили этот результат, поход окончился неудачно.</p><p><b><i>Когда вы оказались достаточно близко к чудищу, чтобы прикоснуться, оно слегка отодвинулось, следя за вами. Вы надеялись, что найденный символ поможет победить это чудище, но добраться до его панциря, чтобы нарисовать там символ, будет непросто!</i></b></p><p><b>Чудище, защитник. </b>Один из персонажей в походе должен провести состязание, чтобы сразиться: его <dexterity> против <awareness> чудища. +2, если у персонажа есть <i>оружие</i>, и +4, если у персонажа есть <i>трофей</i>.<br><b>Успех. </b>Оружием вы вырезали символ на панцире. Завершите этот поход и достигните соответствующей цели.<br><b>Провал. </b>Вы покрылись снегом и льдом, и ваше оружие сломалось. Сбросьте 1 оружие, если возможно. Поход окончился неудачно, если только любой персонаж в походе не получит <major_disease><major_disease> или не потратит <lore>, чтобы провести состязание ещё раз. </p>"},"repeatable":false},{"id":"outcomes-199","code":"199","description":{"en":"<p>\\"In the chaos of preparing and serving such a great meal, you barely have a moment to gauge people's reactions to the food. But as the fire dims and the conversations slow, you find people scraping the bottoms of the cooking pots for the last dregs. Come the morning, the bounteous feast is all anyone can discuss.\\"</p>\\n\\"At the end of any day, you may end this challenge. Then, add <population><population><population>. Subtract <unrest><unrest><unrest>.\\n\\nIllustrate the saga of the lavish banquet on the primal cave wall, including the feast mark (i) and the plenty mark (ii).\\"","ru":"<p><i><b>В суете подготовки и подачи такого богатого угощения у вас едва ли было время оценить реакцию людей на еду. Но когда огонь начал затухать, а разговоры умолкли, вы заметили, что люди скребут дно котелков, чтобы достать остатки. К утру все только и говорили, что об изобильном пиршестве.</b></i></p><p>В конце любого дня можете завершить текущее испытание.</p><p>Затем добавьте <population><population><population> и уберите <unrest><unrest><unrest>. На стене первобытной пещеры изобразите историю о роскошном пиршестве, включив в неё отметку пира [i] и отметку изобилия [ii].</p>"},"repeatable":false,"marks":[{"label":"i","image":"<feast>"},{"label":"ii","image":"<plenty>"}]},{"id":"outcomes-200","code":"200","description":{"en":"<p>By finding vital resources, creating tools, and preparing to build a shelter, your people have created a solid foothold in the vale. But rumors spread: a shadow that swallows the moon, clouds of disturbed dust, and howls that echo off the high mountains.</p>\\n\\"At the end of any day, you may end this challenge.\\n\\nAdd Putting Down Roots (CA02) to your looming challenges. Then, as a group, the players must choose one of the following paths for your society:\\n\\n<b>A) Prioritize exploring the valley:</b> Illustrate the saga new horizons on the primal cave wall as described on Rulebook p.69, including the arrival mark (i), the mystery mark (ii), and the mark of your starting region (e.g. the Verdant Vale [iii] or Skyreach Plateau [iv]). Each character gains one of the following traits of their player's choice: <i>inquisitive</i> or <i>wary</i>. At the start of the next challenge, after setup, place a mystery token in two unexplored hexes of your choice (see Mystery Tokens on Rulebook p.60).\\n\\n<b>B) Focus your energies on stockpiling for winter:</b> Add <population><population>. Illustrate the saga of the hardy wayfarers on the primal cave wall as described on Rulebook p.69, including the arrival mark (i), the plenty mark (v), and the mark of your starting region (e.g. the Verdant Vale [iii] or Skyreach Plateau [iv]). Each character gains one of the following traits of their player's choice: <i>lucky</i> or <i>patient</i>.\\n\\n<b>After making this choice, end the challenge by following the instructions in Ending a Challenge on Rulebook p.95.</b>\\"","ru":"<p><i><b>Найдя жизненно важные ресурсы, создав инструменты и подготовив место для укрытия, ваш народ обосновался в долине. Но до вас долетали слухи о тени, что поглощает луну, облаках кружащейся пыли вдали и о странных завываниях, что разносятся эхом в высоких горах.</b></i></p><p>В конце любого дня можете завершить текущее испытание.</p><p>Добавьте карту «Пуская корни» (ИА02) к грядущим испытаниям. Затем совместно выберите один из следующих путей развития общины:<br><b>А. Сосредоточьтесь на исследовании долины. </b>Как описано на с. 69 правил игры, на стене первобытной пещеры изобразите историю о новых горизонтах, включив в неё отметку прибытия [i], отметку тайны [ii] и отметку своего начального региона (например, Дивная долина [iii] или Поднебесная равнина [iv]). Затем каждый персонаж получает одну из следующих черт по выбору игрока: «любознательный» или «осторожный». В начале следующего испытания, после подготовки, поместите по 1 жетону тайны на любые два неисследованных участка местности (см. раздел «Жетоны тайн» в правилах игры на с. 60).<br><b>Б. Приложите усилия, чтобы накопить припасы на зиму. </b>Добавьте <population><population>. Как описано на с. 69 правил игры, на стене первобытной пещеры изобразите историю о стойких путниках, включив в неё отметку прибытия [i], отметку изобилия [v] и отметку своего начального региона (например, Дивная долина [iii] или Поднебесная равнина [iv]). Затем каждый персонаж получает одну из следующих черт по выбору игрока: «удачливый» или «терпеливый».</p><p>Сделав выбор, завершите это испытание, следуя инструкциям раздела «Завершение испытания» в правилах игры на с. 95.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<arrival>"},{"label":"ii","image":"<mystery>"},{"label":"iii","image":"<verdantvale>"},{"label":"iv","image":"<skyreachplateau>"},{"label":"v","image":"<plenty>"}]},{"id":"outcomes-202","code":"202","description":{"en":"<p>\\"The great hunt's success gives your people confidence for the coming season, allowing your people to flourish as they grow to know the game-trails of the valley.\\"</p>\\n\\"At the end of any day, you may end this challenge. Then, as a group, the players must choose one of the following paths for your society:\\n\\n<b>A) Focus on the forests:</b> If there is at least 1 Verdant Vale hex in the valley, subtract <unrest><unrest><unrest>, add <population>. Then illustrate the saga of the leaf-stalker on the primal cave wall, including the following marks: hunter (i), plenty (ii), Verdant Vale (iii). Add FF14 to the forest Foraging deck, if able.\\n\\n<b>B) Focus on the prairies:</b> If there is at least 1 Skyreach Plateau hex in the valley, subtract <unrest><unrest><unrest>, add <population>. Then illustrate the saga of the golden grass hunter on the primal cave wall, including the following marks: hunter (i), plenty (ii), Skyreach Plateau (iv). Add FP14 to the prairie Foraging deck, if able.\\n\\n<b>C) Focus on the Tangle:</b> If there is at least 1 Tangle hex in the valley (and this region is available), subtract <unrest><unrest><unrest> and add <population>. Then illustrate the saga of the shadow-dappled hunter on the primal cave wall, including the following marks: hunter (i), plenty (ii), Tangle (v). Add FT14 to the Tangle Foraging deck.\\n\\n<b>D) A true hunter shuns eating clods of dirt:</b> Add <population><population><population>. Illustrate the saga of the hunter's glory on the primal cave wall, including the following marks: hunter (i), plenty (ii), taboo (vi). Add \\\\\\"One or more characters eat roots at night\\\\\\" to the Taboos section of the Culture page of the Journal. Gain the Taboos (KN18) Knowledge card. Add the hunter mark to the Legend side of each Character card. Then resolve as many of the following as you are able: \\n\\n1) If there is at least 1 Verdant Vale hex in the valley, add FF14 to the Forest Foraging deck\\n\\n2) If there is at least 1 Skyreach Plateau hex in the valley, add FP14 to the Prairie Foraging deck. \\n\\n3) If there is at least 1 Tangle hex in the valley (and this region is available), add FT14 to the Glade Foraging deck.\\"","ru":"<p><i><b>Успех великой охоты подарил вашим людям уверенность в завтрашнем дне, позволив им процветать, осваивая охотничьи тропы долины.</b></i></p><p>В конце любого дня можете завершить текущее испытание.</p><p>Затем совместно выберите один из следующих путей развития общины:<br><b>А. Сосредоточьтесь на лесах. </b>Если в долине есть хотя бы 1 участок Дивной долины, уберите <unrest><unrest><unrest> и добавьте <population>. Затем на стене первобытной пещеры изобразите историю о лесном следопыте, включив в неё отметку охотника [i], отметку изобилия [ii] и отметку Дивной долины [iii]. Добавьте карту ДЛ14 в колоду добычи припасов в лесу, если возможно.<br><b>Б. Сосредоточьтесь на степи. </b>Если в долине есть хотя бы 1 участок Поднебесной равнины, уберите <unrest><unrest><unrest> и добавьте <population>. Затем на стене первобытной пещеры изобразите историю об охотнике на золотую траву,  включив в неё отметку охотника [i], отметку изобилия [ii] и отметку Поднебесной равнины [iv]. Добавьте карту ДС14 в колоду добычи припасов в степи, если возможно.<br><b>В. Сосредоточьтесь на Сплетении. </b>Если в долине есть хотя бы 1 участок Сплетения (и этот регион доступен), уберите <unrest><unrest><unrest> и добавьте <population>. Затем на стене первобытной пещеры изобразите историю об охотнике в тенях, включив в неё отметку охотника [i], отметку изобилия [ii] и отметку Сплетения [v]. Добавьте карту ДП14 в колоду добычи припасов на полянах.<br><b>Г. Кто зовёт себя охотником — пусть ест мясо, а не землю. </b>Добавьте <population><population><population>. На стене первобытной пещеры изобразите историю о славе охотника, включив в неё отметку охотника [i], отметку изобилия [ii] и отметку табу [vi]. Запишите «Есть коренья ночью» в раздел «Табу» на странице «Культура» в журнале. Получите карту знаний «Табу» (ЗБ18), если у вас её нет. Добавьте отметку охотника на сторону легенды карты каждого персонажа. Затем разыграйте как можно больше из следующего:<br><b>1.</b> Если в долине есть хотя бы 1 участок Дивной долины, добавьте карту ДЛ14 в колоду добычи припасов в лесу.<br><b>2.</b> Если в долине есть хотя бы 1 участок Поднебесной равнины, добавьте карту ДС14 в колоду добычи припасов в степи.<br><b>3.</b> Если в долине есть хотя бы 1 участок Сплетения (и этот регион доступен), добавьте карту ДП14 в колоду добычи припасов на полянах.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<hunter>"},{"label":"ii","image":"<plenty>"},{"label":"iii","image":"<verdantvale>"},{"label":"iv","image":"<skyreachplateau>"},{"label":"v","image":"<tangle>"}]},{"id":"outcomes-209","code":"209","description":{"en":"<p>A land emerges from the shifting cloudscape of the high peaks...</p>\\n\\"Resolve the first you are able:\\n\\n<b>A) You gaze upon a familiar biome from a new perspective:</b> If the Skyreach Plateau mark (i) is on the primal cave wall or you have 0 unplaced terrain trays, add <lore><lore><lore>.\\n\\n<b>B) You arrive in a land of wonders:</b> If the Skyreach Plateau (i) mark is not on the primal cave wall and you have 1 or more unplaced terrain trays, you discover this region. Illustrate the saga of the cloud-touched lands on the primal cave wall, including the Skyreach Plateau mark (i) and the discovery (ii) mark. Then expand your valley by following the steps below:\\n\\nStep 1: Add a new terrain tray to your valley. Place it adjacent to your hex, if able. The tray must be placed such that its edges are adjacent to as many edges of placed trays as possible. If multiple valid positions exist, select one at random.\\n\\nStep 2: Place all Skyreach Plateaus hexes into the draw bag (except for the starting hex). Shuffle the hexes in the draw bag. Then, one at a time, draw three of those hexes and place them unexplored in the slots of the tray you just placed, filling empty slots from north to south and east to west.\\n\\nStep 3 (Epoch 1 and Endless Mode Only): If it is Epoch 1 (or you are playing Endless Mode) and there are 1 or more unplaced glacier overlays, roll <1d6> and place glaciers as follows:\\n1–2: 1 glacier in Zone \\\\\\"A\\\\\\" of one of the hexes without an overlay.\\n[diagram]\\n3–4: 1 glacier in Zone \\\\\\"B\\\\\\" of one of the hexes without an overlay.\\n[diagram]\\n5: Resolve both 1–2 and 3–4.\\n[diagram]\\n6: Roll <1d6> again and read the corresponding outcome instead.\\n1–3: <outcome> 846\\n4–5: <outcome> 134\\n6: <outcome> 446\\"","ru":"<p><i><b>Сквозь клубы облаков, в вышине над горами, проступила земля.</b></i></p><p>Разыграйте первое, что можете:<br><b>А. Вам открылся совершенно новый вид на знакомые земли. </b>Если на стене первобытной пещеры есть отметка Поднебесной равнины [i] или у вас нет ещё не помещённых основ местности, добавьте <lore><lore><lore>.<br><b>Б. Вы попали на землю, полную чудес. </b>Если на стене первобытной пещеры нет отметки Поднебесной равнины [i] и у вас есть хотя бы 1 ещё не помещённая основа местности, откройте этот регион. На стене первобытной пещеры изобразите историю о земле, касающейся облаков, включив в неё отметку Поднебесной равнины [i] и отметку открытия [ii]. Затем расширьте долину, пройдя описанные ниже этапы.</p><p><b>Этап 1. </b>Добавьте новую основу местности в долину. Поместите её по соседству с участком местности с вашим персонажем, если возможно. Границы основы должны соседствовать с как можно большим количеством границ уже размещённых основ. Если есть несколько возможных позиций, выберите одну случайным образом.<br><b>Этап 2. </b>Положите в мешочек все неразмещённые участки Поднебесной равнины, кроме начального, и перемешайте. Затем по одному вытащите 3 участка и поместите их неисследованной стороной вверх в ячейки новой основы по направлению с севера на юг и с востока на запад.<br><b>Этап 3 (только для эры 1 и бесконечного режима).</b> Если в запасе есть хотя бы 1 непомещённая накладка ледника, бросьте <1d6> и поместите ледники по результату броска: [1-2] один ледник в район А одного из участков местности без накладки, [3-4] один ледник в район Б одного из участков местности без накладки, [5] разыграйте результаты 1-2 и 3-4, [6] бросьте <1d6> ещё раз и прочитайте один из исходов ниже, соответствующий результату броска. <br>[1-3] <outcome> 846, [4-5] <outcome> 134, [6] <outcome> 446.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<skyreachplateau>"},{"label":"ii","image":"<discovery>"}]},{"id":"outcomes-210","code":"210","description":{"en":"<p>The creature crashes into you and you struggle with heroic might for what might be a moment or an hour. Then...</p>\\n\\"Resolve the first you are able:\\n\\n<b>A) Remember a time of triumph over a beast:</b> If you are <i>vengeful</i> or have the beastslayer mark (i), you fell the creature, and it lies still. Add 3 game, 1 shell, and 1 tooth to your rewards. Continue this delve.\\n\\n<b>B) Think to a path within the tunnels:</b> If you are <i>cunning</i>, have the underworld mark (ii), or have a Map, after a brief struggle, you slip into a familiar tunnel and escape. You may <exit> or continue this delve.\\n\\n<b>C) Struggle and throw the creature off:</b> After a desperate battle, the creature withdraws to slink off into the darkness. Lose <energy> and suffer <major_injury>. Continue this delve.\\"","ru":"<p><i><b>Существо обрушилось на вас, и бой вспыхнул с неистовой силой — трудно было понять, сколько длилась эта схватка…</b></i></p><p>Разыграйте первое, что можете:<br><b>А. Вспомните время триумфа над зверем. </b>Если вы <i>мстительный </i>или у вас есть отметка зверобоя [i], вы одолели подземное существо и оно пало. Добавьте 3 дичи, 1 ракушку и 1 клык к своим наградам. Продолжите это действие спуска.<br><b>Б. Вспомните путь в подземелье. </b>Если вы <i>хитрый</i>, и у вас есть отметка подземного мира [ii] или «Карта», после недолгой борьбы вы скользнули в знакомый туннель и сбежали. Вы можете <exit> или продолжить это действие спуска.<br><b>В. Прогоните зверя. </b>После ожесточённой битвы существо отступило и скрылось в темноте. Потеряйте <energy> и получите <major_injury>. Продолжите это действие спуска.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<beastslayer>"},{"label":"ii","image":"<underworld>"}]},{"id":"outcomes-211","code":"211","description":{"en":"<p>You return to the surface cradling the fragile fungus in your hands. Over the coming days, you distribute it across your outposts, and the grip of the sickness upon your people breaks.</p>\\n<p>\\"End this challenge.\\n\\nIllustrate the saga of the cavern's mercy on the primal cave wall, including the plague mark (i) and the underworld mark (ii). Your society gains the Cure-Bearer (MA14) mantle power.\\"</p>","ru":"<p><i><b>Вы вернулись на поверхность, бережно прижимая к груди хрупкий гриб. В последующие дни вы доставили его во все свои поселения — и недуг, терзавший ваш народ, постепенно отступил.</b></i></p><p>Завершите текущее испытание.</p><p>На стене первобытной пещеры изобразите историю о милосердии грота, включив в неё отметку чумы [i] и отметку подземного мира [ii]. Ваша община получает силу мантии «Лекарь» (МА14).</p>"},"repeatable":false,"marks":[{"label":"i","image":"<plague>"},{"label":"ii","image":"<underworld>"}]},{"id":"outcomes-212","code":"212","description":{"en":"<p>\\"You take another step and plunge into water far deeper than you expected. A current takes hold of you, pulling you through earthen flumes that must criss-cross the valley's underworld. From the tumult, a rock appears before your eyes, then all goes dark. When you awaken, it is growing dark and your head throbs, but you can see the sky above.\\"</p>\\nSuffer <major_injury> and lose <energy><energy>. End this delve action and lose all rewards you claimed. Place your character in a hex of your choice, choosing a hex with a lake, river, or wetland, if able.","ru":"<p><i><b>Вы сделали ещё один шаг и неожиданно погрузились на глубину. Течение подхватило вас, унося по подземным потокам, которые, должно быть, пролегали под долиной. Из бурной воды перед вами появился камень, затем всё потемнело. Когда вы очнулись, начало смеркаться, голова болела, но над вами простиралось небо.</b></i></p><p>Получите <major_injury> и потеряйте <energy><energy>. Завершите это действие спуска и потеряйте все полученные награды. Поместите своего персонажа на любой участок местности, выбрав участок с озером, рекой или болотом, если возможно.</p>"},"repeatable":false},{"id":"outcomes-214","code":"214","description":{"en":"<p>The route to the scar may not be an easy one...</p>\\n\\"Resolve the first you are able:\\n\\n<b>A) Slink toward the scar unseen:</b> If there is a taboo that would trigger if you enter the impact site, <outcome> 502.\\n\\n<b>B) Approach the scar openly:</b> <outcome> 622.\\"","ru":"<p><i><b>Путь к кратеру просто не мог быть лёгким...</b></i></p><p>Разыграйте первое, что можете:<br><b>А. Подкрадитесь к кратеру незаметно. </b>Если у общины есть табу, которое активируется в месте падения, то <outcome> 502. <br><b>Б. Подойдите к кратеру открыто. </b> <outcome> 622.</p>"},"repeatable":false},{"id":"outcomes-218","code":"218","description":{"en":"<p>As you pass the carcass, the stench overwhelms you and you put down your hand to steady yourself. It comes away slick with some viscous fluid that leaked from the corpse.</p>\\nSuffer <major_disease><minor_disease>. If the plague mark is on the primal cave wall, add <lore>. Otherwise, add Pestilence (CZ03) to your looming challenges.","ru":"<p><i><b>От туши исходила такая невыносимая вонь, что у вас закружилась голова и вам пришлось опереться на останки, чтобы устоять на ногах. Но рука скользнула по вязкой жидкости, которая сочилась из трупа. </b></i></p>Получите <major_disease><minor_disease>. Если на стене первобытной пещеры есть отметка чумы, добавьте <lore>. В противном случае добавьте карту «Мор» (ИЯ03) к грядущим испытаниям.<p></p>"},"repeatable":false,"marks":[{"label":"","image":"<plague>"}]},{"id":"outcomes-219","code":"219","description":{"en":"<p>The shimmering mists that cover the vale sometimes spin strange deceptions of the senses. You peer through the swirling fog to see...</p>\\n\\"Resolve the first you are able:\\n\\n<b>A) An unusual biome border:</b> If the hex you were exploring borders another region and that region also has at least 1 unexplored hex, exchange the positions of the hex you were exploring and an unexplored hex of your choice from the other region. If this is true for multiple regions, choose one for which to resolve the exchange.\\n\\n<b>B) A set of features you had misidentified:</b> If there are at least 2 unplaced hexes from the same region as the hex you are exploring (other than the starting hex), randomly select one of those hexes. Remove the hex you were exploring and replace it with the hex you randomly selected.\\n\\n<b>C) A mysterious occurence:</b> Place a mystery token in the hex you were exploring and resolve it immediately.\\"","ru":"<p><i><b>Мерцающие туманы, покрывающие долину, порой обманывали ваши чувства. Вы всмотрелись в туман и увидели...</b></i></p><p>Разыграйте первое, что можете:<br><b>А. …необычную границу местности. </b>Если исследуемый вами участок местности граничит с другим регионом, в котором есть хотя бы один неисследованный участок местности, поменяйте местами участок, который вы исследуете, и любой неисследованный участок из того региона. Если это условие возможно для нескольких регионов, выберите один из них.<br><b>Б. …изменившийся ландшафт. </b>Если есть хотя бы 2 ещё не помещённых участка местности (кроме начального), принадлежащих тому же региону, что и исследуемый вами участок, выберите случайный участок из непомещённых и замените им участок местности, который вы исследуете.<br><b>В. …загадочное происшествие. </b>Поместите жетон тайны на исследуемый вами участок местности и немедленно разгадайте тайну.</p>"},"repeatable":false},{"id":"outcomes-222","code":"222","description":{"en":"<p>At the bottom of the pool, you reach your hand for the liquid. Despite being in water, it remains separated, as if held down by some invisible hand.</p>\\n\\"Test <conviction> to reach out for the liquid. Add +2 if you are <i>attuned</i> and +4 you have the moonblood mark.\\n11+: You cup your hand decisively and manage to gather some of the liquid. Gain 2 moonblood.\\n8–10: The liquid slips through your tentative grasp, and you feel your fingers grow numb. Gain 1 moonblood and suffer <minor_injury>.\\n1–7: You flinch as the liquid coalesces around you, pulling you deeper and deeper. <outcome> 899.\\"","ru":"<p><i><b>На дне озера вы потянулись к странной жидкости. Несмотря на воду вокруг, она оставалась отделённой, словно её удерживала невидимая рука.</b></i></p><p>Проведите проверку <conviction>, чтобы дотянуться до жидкости. +2, если вы <i>сосредоточенный</i>, и +4, если у вас есть отметка лунной крови.<br><b>≥11:</b>  Вы решительно зачерпнули жидкость рукой и собрали её. Получите 2 лунные крови.<br><b>8-10:</b>  Жидкость ускользала, и вы ощутили, как пальцы начинают неметь. Получите 1 лунную кровь. Получите <minor_injury>. <br><b>1-7:</b>  Вы вздрогнули, когда жидкость сомкнулась вокруг вас, утаскивая всё глубже и глубже. <outcome> 899.</p>"},"repeatable":false,"marks":[{"label":"","image":"<moonblood>"}]},{"id":"outcomes-223","code":"223","description":{"en":"<p>In the underground pool, something catches hold of your foot and pulls you deep beneath the water.</p>\\n\\"Test <might> to break free. Add +2 if you are <i>cunning</i> and +4 if you have the beastslayer mark.\\n12+: You break away from the creature and continue this delve. Add <lore><lore>.\\n6–11: You are dragged into an underground current, and eventually wash up on a river bank nearby. End this delve action. Then, place your character in a randomly selected hex in the region where you started delving, selecting a hex with a lake, river, or wetland feature, if able.\\n1–5: Resolve 6–11, then suffer <major_injury>.\\"","ru":"<p><i><b>В подземном озере нечто схватило вас за ногу и потянуло на глубину.</b></i></p><p>Проведите проверку <might>, чтобы вырваться. +2, если вы <i>хитрый</i>, и +4, если у вас есть отметка зверобоя.<br><b>≥12:</b>  Вы вырвались из лап существа. Продолжите это действие спуска. Добавьте <lore><lore>.<br><b>6-11:</b>  Вас унесло подземным течением, и в конце концов вы выбрались на берег реки неподалёку. Завершите это действие спуска. Поместите своего персонажа на случайный участок местности в регионе, где вы начали спуск. Выберите участок с озером, рекой или болотом, если возможно.<br><b>1-5:</b>  Разыграйте исход как при [6-11], затем получите <major_injury>.</p>"},"repeatable":false,"marks":[{"label":"","image":"<beastslayer>"}]},{"id":"outcomes-224","code":"224","description":{"en":"<p>Over the coming years, the symbol you have taken to represent your people becomes synonymous with your presence, a friendly sign in the lands you commonly traverse and a symbol that means \\\\\\"home is near\\\\\\" in the wilds. Under this lucky mark, you feel a sense of safety and good fortune.</p>\\nSubtract <unrest><unrest><unrest>. Illustrate the saga of the symbol found on the primal cave wall, including the omen mark depicted on the mystery token on Spinner of Myth. Your society gains the <i>Fable-Weaver</i> (MA12) mantle power.","ru":"<p><i><b>Шли годы, и символ, что вы избрали для своего народа, стал неотделим от вашего имени. Он был зна́ком дружелюбия на землях, где вы часто бывали, и приметой того, что дом близко, среди диких просторов. Под этим счастливым знаком вы ощущали покой и благосклонность судьбы.</b></i></p><p>Уберите <unrest><unrest><unrest>. На стене первобытной пещеры изобразите историю о найденном символе, включив в неё отметку знамения, изображённую на жетоне тайны на карте цели «Сотворите миф» (ЦБ10). Ваша община получает силу мантии «Ткач преданий» (МА12).</p>"},"repeatable":false},{"id":"outcomes-227","code":"227","description":{"en":"<p>Following the shimmering star, you find your way into a yet-undiscovered corner of the valley.</p>\\n\\"Illustrate the saga of starcut path on the primal cave wall, including the mark of your current region, the discovery mark, and the <star> mark. Then expand your valley by following the steps below:\\n\\nStep 1: Add a new tray to your valley. Place it adjacent to your hex, if able. The tray must be placed such that its edges are adjacent to as many edges of placed trays as possible. If multiple valid positions exist, select one at random.\\n\\nStep 2: Place all unplaced hexes from your current region into the draw bag (except for the starting hex). Shuffle the hexes in the draw bag. Then, one at a time, draw three of those hexes. and place them unexplored in the slots of the tray you just placed, filling empty slots from north to south and east to west.\\n\\nStep 3 (Epoch 1 and Endless Mode Only): If it is Epoch 1 (or you are playing Endless Mode) and there are 1 or more unplaced glacier overlays, roll <1d6> and place glaciers as follows:\\n1–2: 1 glacier in Zone \\\\\\"A\\\\\\" of one of the hexes without an overlay.\\n[diagram]\\n3–4: 1 glacier in Zone \\\\\\"B\\\\\\" of one of the hexes without an overlay.\\n[diagram]\\n5: Resolve both 1–2 and 3–4.\\n[diagram]\\n6: Roll <1d6> again and read the corresponding outcome instead.\\n1–2: <outcome> 846\\n3–5: <outcome> 134\\n6: <outcome> 446\\n\\nFinally, return Brightest of Sparks (JU03) to the game box.\\"","ru":"<p><i><b>Следуя за мерцающей звездой, вы нашли путь в ещё не исследованный уголок долины.</b></i></p><p>На стене первобытной пещеры изобразите историю о пути, проложенном звёздами, включив в неё отметку своего текущего региона, отметку открытия и отметку <star>. Затем расширьте долину, пройдя описанные ниже этапы.</p><p><b>Этап 1. </b>Добавьте новую основу местности в долину. Поместите её по соседству с участком местности с вашим персонажем, если возможно. Границы основы должны соседствовать с как можно большим количеством границ уже размещённых основ. Если есть несколько возможных позиций, выберите одну случайным образом. <br><b>Этап 2. </b>Положите в мешочек все неразмещённые участки местности региона, в котором вы находитесь, кроме начального, и перемешайте. Затем по одному вытащите 3 участка и поместите их неисследованной стороной вверх в ячейки новой основы по направлению с севера на юг и с востока на запад.<br><b>Этап 3 (только для эры 1 и бесконечного режима).</b> Если в запасе есть хотя бы 1 непомещённая накладка ледника, бросьте <1d6> и поместите ледники по результату броска: [1-2] один ледник в район А одного из участков местности без накладки, [3-4] один ледник в район Б одного из участков местности без накладки, [5] разыграйте результаты [1-2] и [3-4], [6] бросьте <1d6> ещё раз и прочитайте один из исходов ниже, соответствующий результату броска.<br>[1-3] <outcome> 846, [4-5] <outcome> 134, [6] <outcome> 446.</p><p>Наконец, верните в коробку карту «Ярчайшая из искр» (ПН03).</p>"},"repeatable":false,"marks":[{"label":"","image":"<discovery>"}]},{"id":"outcomes-228","code":"228","description":{"en":"<p>You trudge across the icy ground to uncover...</p>\\n\\"Embark on the venture below (see Ventures on Rulebook p.60).\\n\\n<bi>The behemoth's lair is a sheer-lipped pit, descending deep into icy earth. You must descend, cutting a path as you go.</bi>\\n<b>Champion, Hazard:</b> Someone must test <dexterity> to cut a path. Add +2 if you have <stoneworking> and +2 for each <i>exploration</i> item you have.\\n10+: You cut a safe path for others to follow. The venture continues.\\n1–9: Waiting on the edge of the abyss, a chill pervades everyone. Each character degrades one of their boosts, then the venture fails unless a character spends <energy><energy> to attempt this test again.\\n\\n<bi>Pale blue mists swirl around you. The icy descent grows colder and colder as you go, until the air feels like gravel in your lungs.</bi>\\n<b>Group, Weather:</b> Everyone must test <might> or <conviction> to withstand the cold. A character adds +2 if they have an item with a <fire> token on it and +2 if they have a <i>clothing</i> item.\\n10+: You withstand the frigid mists. If any character resolves this result, the venture continues.\\n1–9: You begin to freeze. Suffer <major_injury><major_injury> unless you degrade all of your boosts. If all characters on the venture resolve this result, the venture fails.\\n\\n<bi>At the bottom of the pit, you find a strange glyph. It shifts and melds, and you come to understand: this is the essence of the behemoth. With it, this glyph, the creature can be undone, provided someone can reproduce it.</bi>\\n<b>Behemoth, Champion:</b> Someone must test <awareness> to study the glyph. Add +4 if one or more Secrets have been recorded in the Journal for this behemoth.\\n10+: You manage to hold the shifting shape in your mind, even as it dances like shadows in the firelight. Complete this venture and the associated goal.\\n1–9: Your eye twitches, and you notice a stream of blood from your nostrils. The mark twists and struggles, tearing out of your mind before you can seize it. Suffer <major_injury> unless you degrade a boost. The venture fails unless a character spends <energy><energy> to attempt this test again.\\"","ru":"<p><i><b>Вы пробрались через ледяную землю, чтобы обнаружить... </b></i></p><p>Отправьтесь в поход (см. раздел «Походы» в правилах игры на с. 60).</p><p><i><b>Логово чудища было обрывом с крутыми краями и уходило глубоко в ледяную землю. Вам нужно было спуститься, расчищая себе путь.</b></i></p><p><b>Защитник, угроза. </b>Один из персонажей в походе должен провести проверку <dexterity>, чтобы расчистить путь. +2, если у персонажа есть <stoneworking>, и +2 за каждый предмет для <i>исследования </i>у этого персонажа.<br><b>≥10:</b>  Вы проложили безопасный путь для других. Продолжите поход.<br><b>1-9:</b>  Ожидая на краю бездны, все замёрзли. Каждый персонаж уменьшает одно из своих усилений. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy>, чтобы провести проверку ещё раз.</p><p><b><i>Тусклые синие туманы вились вокруг вас. Ледяной спуск становился всё холоднее, и воздух казался камнями в лёгких. </i></b></p><p><b>Группа, погода. </b>Все персонажи в походе должны провести проверку <might> или <conviction>, чтобы выдержать холод. +2, если у персонажа есть предмет с <fire>, и +2, если у него есть <i>одежда</i>.<br><b>≥10:</b>  Вы справились с холодом тумана. Если хотя бы один персонаж получил этот результат, продолжите поход.<br><b>1-9: </b> Вы начали замерзать. Получите <major_injury><major_injury>, если не уменьшите все свои усиления. Если все персонажи получили этот результат, поход окончился неудачно.</p><p><i><b>На дне расселины вы нашли странный знак. Он мерцал и менялся, перетекая из одной формы в другую — и тогда вы поняли: перед вами сама сущность чудища. В этом знаке была заключена сила, способная обратить чудище в прах… если найдётся тот, кто сумеет его воспроизвести.</b></i></p><p><b>Чудище, защитник. </b>Один из персонажей в походе должен провести проверку <awareness>, чтобы изучить знак. +4, если в журнале записан хотя бы один секрет этого чудища.<br><b>≥10:</b>  Изменчивость линий была подобна танцу теней в свете костра, однако вы сумели удержать символ в своём сознании. Завершите этот поход и достигните соответствующей цели.<br><b>1-9:</b>  У вас задёргался глаз, и вы заметили струйку крови, стекающую из носа. Знак, извиваясь, с боем вырвался из вашего разума, прежде чем вы успели его запомнить. Получите <major_injury>, если только не уменьшите усиление. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy>, чтобы провести проверку ещё раз.</p>"},"repeatable":false},{"id":"outcomes-229","code":"229","description":{"en":"<p>The coral remains a thing beyond understanding. Whether you fear it, hate it, or resent it, your mind cannot encompass it. It spreads through the valley as a tide, sweeping your people from the lands of their ancestors without regard for your fleeting existences.</p>\\n\\"Illustrate the saga of the unfathomable on the primal cave wall, including the <comet> mark, the misfortune mark, and the Starlit Sea mark. Then, as a group, the players must choose one of the following paths for your society:\\n\\n<b>A) Accept that you will vanish with your civilization:</b> Your campaign ends and your society <b>vanishes</b>. See Ending a Campaign on Rulebook p.97.\\n\\nThis end may not be a happy one, but it can still be instructive to future peoples who inhabit the valley. To immortalize a photo of your primal cave wall and see other people's works of art, we invite you to share your saga with our community!\\n\\n@[Insert Link]@\\n\\nTo continue playing Stonesaga, see Beginning Subsequent Campaigns on Rulebook p.97. Or you could switch to Endless Mode, as described on Rulebook p.97.\\n\\n<b>B) Fight for your survival with every scrap of your tattered resolve:</b> Add Exodus (CZ09) to your looming challenges.\\"","ru":"<p><i><b>Коралл оставался чем‑то непостижимым. Боялись ли вы его, ненавидели или презирали — ваш разум был не в силах его воспринять. Он распространился по долине подобно приливу, унося ваших людей с земель их предков, не заботясь о вашем мимолётном существовании.</b></i></p><p>Завершите текущее испытание.</p><p>На стене первобытной пещеры изобразите историю о непостижимом знаке, включив в неё отметку <comet>, отметку несчастья [i] и отметку Звёздного моря [ii].<br>Затем совместно выберите один из следующих путей развития общины:<br><b>А. Смиритесь с тем, что ваша цивилизация исчезнет, и вы вместе с ней.</b> Завершите кампанию. Ваша община <b>исчезла</b>. См. раздел «Конец кампании» в правилах игры на с. 97. Такой конец хоть и далёк от счастливого, но он всё же может послужить уроком для народов, которые заселят эту долину в будущем. Чтобы увековечить фотографию своей стены первобытной пещеры и увидеть произведения искусства других игроков, мы приглашаем вас поделиться своей историей с нашим сообществом!<br>Чтобы продолжить играть в  «Наскальную историю», см.  в  правилах игры раздел «Начало следующих кампаний» на с. 97 или раздел «Бесконечный режим» на с. 102.<br><b>Б. Сражайтесь за выживание из последних сил.</b> Добавьте карту «Исход» (ИЯ09) к грядущим испытаниям.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<misfortune>"},{"label":"ii","image":"<starlitsea>"},{"label":"","image":"<qrcode>"}]},{"id":"outcomes-231","code":"231","description":{"en":"<p>\\"Over the years, the Tangle's great flowers wither, its waterways become choked with silt, and its massive vines moulder. At the heart of this jungle, some rot has set in, taking its vitality season by season.\\"</p>\\n\\"Each outpost in the Tangle region becomes a ruin. Subtract <population><population> for each outpost that became a ruin this way. Then, as a group, the players must choose one of the following paths for your society:\\n\\n<b>A) Forbid lingering in the Tangle:</b> Add \\\\\\"Resting in a hex in the Tangle\\\\\\" to the Taboos section of the Culture page of the Journal. Gain the Taboos (KN18) Knowledge card. Add <unrest><unrest>. Illustrate the saga of the forbidden vale on the primal cave wall, including the taboo (i) mark and the Tangle mark (ii).\\n\\n<b>B) Risk the dangers of the spreading rot:</b> Lose <population><population><population>. Illustrate the saga of the spreading decay on the primal cave wall, including the plague mark (iii) and the Tangle mark (ii).\\"","ru":"<p><i><b>С годами величественные растения Сплетения увяли, его водные пути заросли илом, а могучие лианы стали разлагаться. В самом сердце этих джунглей поселилась гниль, постепенно поглощая их жизненную силу. </b></i></p><p>Каждое поселение в регионе Сплетения становится руинами. Уберите <population><population> за каждое поселение, которое стало руинами таким образом. Затем совместно выберите один из следующих путей развития общины:<br><b>А. Запретите надолго оставаться в Сплетении. </b>Запишите «Отдых на участке местности в Сплетении» в  раздел «Табу» на странице «Культура» в  журнале. Получите карту знаний «Табу» (ЗБ18), если у вас её нет. Добавьте <unrest><unrest>. На стене первобытной пещеры изобразите историю о запретной долине, включив в неё отметку табу [i] и отметку Сплетения [ii].<br><b>Б. Осмельтесь столкнуться с расползающейся гнилью. </b>Уберите <population><population><population>. На стене первобытной пещеры изобразите историю о распространяющемся разложении, включив в неё от метку чумы [iii] и отметку Сплетения [ii].</p>"},"repeatable":false,"marks":[{"label":"i","image":"<taboo>"},{"label":"ii","image":"<tangle>"},{"label":"iii","image":"<plague>"}]},{"id":"outcomes-234","code":"234","description":{"en":"<p>\\"At the outskirts of an outpost, you hear shouts of terror and see villagers fleeing. The comet's champion strides toward the settlement. None but you can stand before them.\\"</p>\\n\\"Resolve a contest of your <conviction> versus the coral champion's <dexterity> to fight. Add +2 to your result if you have a <i>moonblood</i> item. Add +4 to the coral champion's result for each adjacent hex with an active coral overgrowth.\\n<b>Win:</b> You grapple with the coral champion, pushing them back from your outpost. As you hurl them back, a thicket of coral fronds folds around them, pulling them to safety. Add <major_boost> to <awareness>.\\n<b>Lose:</b> Where your skin presses up against the coral champion it burns and bubbles, seared by the spores that surround their flesh. Suffer <major_disease><major_injury><minor_injury>.\\"","ru":"<p><i><b>На окраине одного из поселений вы услышали крики ужаса и увидели, как жители спасаются бегством. Коралловый защитник шагал к деревне. Только вы могли преградить ему путь.</b></i></p><p>Проведите состязание, чтобы сразиться: ваша <conviction> против <dexterity> кораллового защитника. +2 к вашему результату, если у вас есть предмет <i>лунной крови</i>. +4 к результату кораллового защитника за каждый соседний участок местности с активными коралловыми зарослями.<br><b>Успех. </b>Вы сцепились с коралловым защитником, уводя его подальше от поселения. Когда вы швырнули его обратно в заросли, коралловые ветви обвили его, утаскивая в безопасное место. Добавьте <major_boost> к <awareness>.<br><b>Провал. </b>Ваша кожа, сожжённая спорами, которые окружали плоть кораллового защитника, начала гореть и пузыриться. Получите <major_disease>,<major_injury>  и <minor_injury>.</p>"},"repeatable":false},{"id":"outcomes-235","code":"235","description":{"en":"<p>You know that the chittering comes from small insects, though their cries can be mistaken for voices at a distance. These shelled creatures are good to eat, but you also know that they often bury interesting objects amidst the roots of shrubs.</p>\\n\\"You must choose one of the following: \\n\\n<b>A) You find a large hunk of meat. Seems like it's still edible.</b> Gain 2 game.\\n\\n<b>B) You find a snarl of plant fibers in a ball.</b> Gain 2 fiber.\\n\\n<b>C) You find a chipped predator's tooth.</b> Gain 1 tooth.\\"","ru":"<p><i><b>Вы увидели мелких насекомых — это их стрекотание издалека можно было принять за речь. Эти покрытые панцирями существа были хороши на вкус, но вы также знали, что они часто прячут среди корней кустарников занятные вещицы.</b></i></p><p>Разыграйте одно:<br><b>А. Вы нашли большой кусок мяса, который, казалось, всё ещё был съедобен.</b> Получите 2 дичи. <br><b>Б. Вы нашли клубок растительных волокон.</b> Получите 2 волокна.<br><b>В. Вы нашли осколок зуба хищника.</b> Получите 1 клык.</p>"},"repeatable":false},{"id":"outcomes-236","code":"236","description":{"en":"<p>Within the dark, the air grows foul and your senses begin to numb. You shake your head and feel a sharp pain. You cannot remain here.</p>\\n\\"Test <awareness> to find a path to safety! Add +2 if you are <i>lucky</i> and +2 if you have the underworld mark.\\n12+: You escape the cave unharmed. Add <lore>.\\n8–11:You manage to stumble out of the cave, coughing and choking. Suffer <minor_disease>.\\n1–7: You become lost, and eventually the darkness of the cave overtakes you. Later, you awaken far from the cave, with strange footprints in the dust around you. Suffer <major_disease><minor_disease> and flee. Place a mystery token in the hex you fled.\\"","ru":"<p><i><b>В темноте воздух становился удушающим, и ваши чувства начали затуманиваться. Вы тряхнули головой и ощутили острую боль. Вы не могли оставаться здесь.</b></i></p><p>Проведите проверку <awareness>, чтобы найти путь в безопасное место. +2, если вы <i>удачливый</i>, и +2, если у вас есть отметка подземного мира.<br><b>≥12:</b>  Вам удалось благополучно покинуть пещеру. Получите <lore>.<br><b>8-11:</b>  Кашляя и задыхаясь, вы всё же смогли выбраться из пещеры. Получите <minor_disease>.<br><b>1-7:</b>  Вы заблудились, и в конце концов тьма пещеры завладела вами. Вы пришли в себя вдалеке от пещеры, в окружении странных следов на песке. Получите <major_disease> и <minor_disease>. Сбегите. Поместите жетон тайны на участок местности, с которого вы сбежали.</p>"},"repeatable":false,"marks":[{"label":"","image":"<underworld>"}]},{"id":"outcomes-237","code":"237","description":{"en":"<p>\\"As you investigate the conflict, you uncover the inciting incident: after one of your village's inhabitants was slain by one of the valley's beasts, some have come to believe that these creatures must be exterminated. Others see them as sacred, for they test your people's resolve to remain in this harsh place.\\"</p>\\n\\"As a group, the players must choose one of the following paths for your society:\\n\\n<b>A) Accept the plan to reduce the population of predators:</b> Add <population><population>. Illustrate the saga of the cull on the primal cave wall, including the beastslayer mark (i). Resolve as many of the following as you are able:\\n\\n1) If there is at least 1 Verdant Vale hex in the valley, add FF14 to the Forest Foraging deck.\\n2) If there is at least 1 Skyreach Plateau hex in the valley, add FP14 to the Prairie Foraging deck.\\n3) If there is at least 1 Tangle hex in the valley (and this region is available), add FT14 to the Glade Foraging deck.\\n\\n<b>B) Speak to the importance of these creatures to your culture:</b> Add <unrest><unrest>. Illustrate the saga of the sacred beasts on the primal cave wall, including the caution mark (ii) and the hunter mark (iii). Add a \\\\\\"<i>Fighting</i> a predator in a hex without an outpost\\\\\\" to the Taboos section of the Culture page of the Journal. Gain the Taboos (KN18) Knowledge card.\\"","ru":"<p><i><b>Разбираясь в причинах конфликта, вы выяснили, с чего всё началось. Хищник убил жителя вашей деревни. Одни пришли к выводу, что этих существ необходимо истребить. Другие сочли их священными — ведь звери испытывали на прочность решимость вашего народа остаться в этом суровом краю.</b></i></p><p>Совместно выберите один из следующих путей развития общины:<br><b>А. Объявите охоту на хищников. </b>Добавьте <population><population>. На стене первобытной пещеры изобразите историю об истреблении, включив в неё отметку зверобоя [i]. Разыграйте как можно больше из следующего:<br>1. Если в долине есть хотя бы 1 участок местности Дивной долины, добавьте карту ДЛ14 в колоду добычи припасов в лесу.<br>2. Если в долине есть хотя бы 1 участок местности Поднебесной равнины, добавьте карту ДС14 в колоду добычи припасов в степи.<br>3. Если в долине есть хотя бы 1 участок местности Сплетения (и этот регион доступен), добавьте карту ДП14 в колоду добычи припасов на полянах.<br><b>Б. Подчеркните значимость этих существ для вашей культуры.</b> Добавьте <unrest><unrest>. На стене первобытной пещеры изобразите историю о священных зверях, включив в неё отметку осторожности [ii] и отметку охотника [iii]. Запишите «Сражение с хищником на участке без поселения» в раздел «Табу» на странице «Культура» в журнале. Получите карту знаний «Табу» (ЗБ18).</p>"},"repeatable":false,"marks":[{"label":"i","image":"<beastslayer>"},{"label":"ii","image":"<caution>"},{"label":"iii","image":"<hunter>"}]},{"id":"outcomes-238","code":"238","description":{"en":"<p>\\"Your advances in the study of the coral have uncovered an important means of protecting your people. While the coral's spores sting the lungs of those who breath them, moonblood crystals provide a measure of protection. Clouds of spores part as you approach.\\"</p>\\nAt the end of any day, you may end this challenge. Then, add <unrest><unrest><unrest><unrest><unrest>. Illustrate the saga of the strange cure on the primal cave wall, including the coral mark and the moonblood mark. Add The Sky Descends (CC04) to your looming challenges.","ru":"<p><i><b>Изучив коралл, вы сделали важное открытие, которое помогло бы защитить ваш народ. Споры коралла обжигали лёгкие тех, кто их вдыхал, но кристаллы лунной крови обеспечивали какую‑никакую защиту. Облака спор расступились, когда вы приблизились.</b></i></p><p>В конце любого дня можете завершить текущее испытание.</p><p>Затем добавьте 5 <unrest>. На стене первобытной пещеры изобразите историю о странном целебном средстве, включив в неё отметку коралла [i] и отметку лунной крови [ii]. Добавьте карту «Падение небес» (ИВ04) к грядущим испытаниям.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<coral>"},{"label":"ii","image":"<moonblood>"}]},{"id":"outcomes-239","code":"239","description":{"en":"<p>The ice breaks beneath you and you plummet into a cold, shining pool. As you sink into eternity, you remark that the liquid shimmers like moonlight...</p>\\n<p>Add the moonblood mark to the Legend side of your Character card, then return your character card to the game box. Create a new character as if your character had perished. Then return Mouth of the Underworld (JU10) to the game box and add Face in the Deep (JQ02) to the Journey deck.</p>","ru":"<p><i><b>Лёд проломился, и вы рухнули в сияющую холодную воду. Погружаясь в бездну, вы успели заметить, что жидкость мерцает, словно лунный свет...</b></i></p><p>Добавьте отметку лунной крови на сторону легенды своего персонажа, затем верните в коробку карту своего персонажа. Создайте нового персонажа, как если бы прежний умер. Верните в коробку карту «Проход в подземелье» (ПН10) и добавьте карту «Облик на глубине» (ПЗ02) в колоду пути.</p>"},"repeatable":false,"marks":[{"label":"","image":"<moonblood>"}]},{"id":"outcomes-244","code":"244","description":{"en":"<p>As the teeth of winter slice through the valley, your desperate flight through the pass is successful. Where this passage it will take your people, you cannot say. But your descendents will survive, and their saga will continue in this land beyond the valley of your ancestors. Perhaps they might even someday return to the vale to test themselves against its trials.</p>\\n\\"Illustrate the saga of the exodus on the primal cave wall, including the exodus mark. Your campaign ends and your society <b>vanishes</b>. See Ending a Campaign on Rulebook p.97.\\n\\nHowever, not all hope is lost, as your people's hard-won knowledge is passed down to new generations! To continue playing <i>Stonesaga</i>, see Beginning Subsequent Campaigns on Rulebook p.97. When you begin your new campaign, you may add any number of forgotten Legend cards to your new society as Legends. You may also copy any information from the Culture and Recipes pages from your old Journal into the new one when you begin your new campaign.\\"","ru":"<p><i><b>Ваш отчаянный побег через перевал увенчался успехом как раз, когда зубы зимы вгрызлись в долину. Нельзя было сказать, куда этот путь приведёт ваш народ. Но ваши потомки выживут, и их история продолжится на этой земле, за пределами долины ваших предков. Возможно, когда‑нибудь они вернутся в долину, чтобы попытать свои силы в её испытаниях.</b></i></p><p>На стене первобытной пещеры изобразите историю об исходе, включив в неё отметку исхода. Завершите кампанию. Ваша община <b>исчезла</b>. См. раздел «Конец кампании» в правилах игры на с. 97.<br>Однако не вся надежда утрачена, поскольку знания, добытые вашим народом, передаются новым поколениям! Чтобы продолжить играть в «Наскальную историю», см. в правилах игры раздел «Начало следующих кампаний» на с. 97 или раздел «Бесконечный режим» на с. 102.<br>Когда вы начнёте новую кампанию, можете добавить любое количество забытых карт легенд в свою новую общину в качестве легенд. Вы также можете перенести любые сведения со страниц «Культура» и «Рецепты» из старого журнала в новый.</p>"},"repeatable":false,"marks":[{"label":"","image":"<exodus>"}]},{"id":"outcomes-245","code":"245","description":{"en":"<p>Some among your people have come to rever the behemoth as a harbinger of cosmic forces that shape the world. Whether this takes the form of ancestral spirits, creator deities, or celestial balance, they believe the behemoth is a conduit of this power and must be appeased as such. You must decide your own thoughts on the matter.</p>\\n\\"At the end of any day, you may end this challenge.\\n\\nThen, as a group, the players must choose one of the following paths for your society:\\n\\n<b>A) Join the growing movement:</b> Subtract <unrest><unrest>. Illustrate the saga of the cosmic guide on the primal cave wall, including the bond mark (i) enclosing the alert behemoth's mark. Your society gains the Behemoth-Speaker (MA18) mantle power.\\n\\n<b>B) Speak for tolerance of many ways:</b> Add <unrest><unrest>. Illustrate the saga of the many paths on the primal cave wall, including the alert behemoth's mark, the mediator mark (ii), and the scribe mark (iii).\\n\\n<b>C) Expel the behemoth-worshippers:</b> Add <unrest><unrest><unrest>, subtract <population><population><population><population>. Illustrate the saga of the banished faith on the primal cave wall, including the alert behemoth's mark, the schism mark (iv), and the wrath mark (v).\\n\\nAt the end of this challenge, end the current epoch. Refer to Codex p.196 to continue your campaign into Epoch 2.\\"","ru":"<p><i><b>Среди вашего народа зародился культ почитателей чудища как вестника космических сил, лежащих в основе мироздания. Кто‑то видел в нём голос предков, кто‑то — дыхание творца, кто‑то — равновесие звёзд. Ваши люди стали считать чудище проводником этой силы и верили, что умиротворить его значит сохранить порядок вещей. Вам предстояло принять собственное решение по этому поводу.</b></i></p><p>Завершите текущее испытание.</p><p>Затем совместно выберите один из следующих путей развития общины:<br><b>А. Присоединитесь к растущему движению.</b> Уберите <unrest><unrest>. На стене первобытной пещеры изобразите историю о космическом проводнике, включив в неё отметку бодрствующего чудища, заключённую в отметку связи [i]. Ваша община получает силу мантии «Говорящий с чудищами» (MA18).<br><b>Б. Выступите за свободный выбор пути. </b>Добавьте <unrest><unrest>. На стене первобытной пещеры изобразите историю о множестве путей, включив в неё отметку бодрствующего чудища, отметку посредника [ii] и отметку летописца [iii].<br><b>В. Изгоните последователей чудища. </b>Добавьте <unrest><unrest><unrest> и уберите <population><population><population><population>. На стене первобытной пещеры изобразите историю о вере, преданной забвению, включив в неё отметку бодрствующего чудища, отметку раскола [iv] и отметку гнева [v].</p><p>Завершите текущую эру. См. с. 196, чтобы начать эру 2.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<bond>"},{"label":"ii","image":"<mediator>"},{"label":"iii","image":"<scribe>"},{"label":"iv","image":"<schism>"},{"label":"v","image":"<wrath>"}]},{"id":"outcomes-248","code":"248","description":{"en":"<p>With a fury born of many small wounds, the behemoth descends upon your outposts. It smashes wood and stone as easily as twigs and sand. Its vengeance complete, it returns, leaving your society in shambles.</p>\\n\\"Illustrate the saga of vengeance on the primal cave wall, including the alert behemoth's mark adorned with the wrath mark (i). Subtract <population><population><population><population><population>. For each of your outposts, randomly select two structures and destroy them.\\n\\nThen, as a group, the players must choose one of the following paths for your society:\\n\\n<b>A) Swear vengeance:</b> Each character gains the <i>vengeful</i> trait. Add To Surpass Eternity (CB08) to your looming challenges.\\n\\n<b>B) Accept the behemoth's judgment:</b> Each character gains the <i>patient</i> trait. Add Vision of One (CB07) to your looming challenges.\\n\\n<b>C) Seek refuge in the dark below the behemoth's mighty footfalls:</b> If the underworld mark (ii) is on the primal cave wall, add Tunnel Riders (CB09) to your looming challenges.\\"","ru":"<p><i><b>С яростью, рождённой множеством мелких ран, чудище обрушилось на ваши поселения. Оно растоптало деревянные и каменные постройки, будто они были из хвороста и песка. Отомстив, оно ушло, оставив вашу общину в руинах.</b></i></p><p>Завершите текущее испытание. На стене первобытной пещеры изобразите историю о мести, включив в неё отметку бодрствующего чудища, украшенную отметкой гнева [i]. Уберите 5 <population>. В каждом из своих поселений случайным образом выберите два сооружения и разрушьте их.</p><p>Затем совместно выберите один из следующих путей развития общины:<br><b>А. Поклянитесь отомстить. </b>Каждый персонаж получает черту «мстительный». Добавьте карту «Преодоление вечности» (ИБ08) к грядущим испытаниям.<br><b>Б. Смиритесь с наказанием чудища. </b>Каждый персонаж получает черту «терпеливый». Добавьте карту «Единое видение» (ИБ07) к грядущим испытаниям.<br><b>В. Найдите укрытие в тёмных недрах под могучей поступью чудища. </b>Если на стене первобытной пещеры есть отметка подземного мира [ii], добавьте карту «Странники подземелий» (ИБ09) к грядущим испытаниям.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<wrath>"},{"label":"ii","image":"<underworld>"}]},{"id":"outcomes-249","code":"249","description":{"en":"<p>\\"Your muscles burn and your body strains, but you cast the coral champion down. They struggle to stand, but you summon the last of your strength and lunge, cutting them down. The coral heart beating in their chest beats weakly, then shatters. As it breaks, a tone ripples across the valley. The coral glades resonate with the chime, then fall silent as they turn to deadened stalks of grey. The coral champion's body suffers a similar fate, petrifying into a strange monument to the day.\\n\\nThe following years are good to your people, and you expand to fill the valley. Yet the wanderer burns overhead, and your descendents cannot help but wonder what horrors it still carries...\\"</p>\\n\\"Add <population><population><population> and subtract <unrest><unrest><unrest>. Flip each coral overgrowth overlay to its inactive side.\\n\\nIllustrate the saga of coral champion's fall on the primal cave wall, including the <comet> mark, the battle mark (i), and the conclusion mark enclosing the coral mark (ii). Your society <b>persists.</b>\\n\\nCongratulations! You have completed <i>Stonesaga</i>'s campaign! To immortalize a photo of your primal cave wall and see other people's works of art, we invite you to share your saga with our community!\\n\\n@[Insert Link]@\\n\\nTo continue playing <i>Stonesaga</i>, see Playing Endless Mode After a Campaign on Rulebook p.97, or Beginning Subsequent Campaigns on Rulebook p.97.\\"","ru":"<p><i><b>Ваши мышцы горели, тело разрывалось — но вы повалили кораллового защитника. Он попытался подняться, но вы собрали остаток сил и метнулись вперёд, нанося последний удар. Коралловое сердце в его груди затрепетало — и раскололось. По долине прокатился звон. Коралловые поля отозвались на этот звук — и затихли, превращаясь в мёртвые серые стебли. Тело кораллового защитника постигла та же участь: оно окаменело, став странным памятником этому дню.</b></i></p><p><b><i>Следующие годы были благоприятны для вашего народа, и вы смогли заселить всю долину. Однако Скиталец по‑прежнему пылал над головами, и ваши потомки всё чаще задумывались, какие ужасы он всё ещё может принести...</i></b></p><p>Добавьте <population><population><population> и уберите <unrest><unrest><unrest>. Переверните все коралловые заросли неактивной стороной вверх.</p><p>На стене первобытной пещеры изобразите историю о падении кораллового защитника, включив в неё отметку <comet>, отметку битвы [i] и отметку коралла, заключённую в отметку окончания [ii]. Ваша община <b>выжила</b>.<br>Поздравляем! Вы завершили кампанию «Наскальной истории»! Чтобы увековечить фотографию своей стены первобытной пещеры и увидеть произведения искусства других игроков, мы приглашаем вас поделиться своей историей с нашим сообществом!</p><p>Чтобы продолжить играть в «Наскальную историю», см. в правилах игры раздел «Начало следующих кампаний» на с. 97 или раздел «Бесконечный режим» на с. 102.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<battle>"},{"label":"ii","image":"<conclusion>EncCoral"},{"label":"","image":"<qrcode>"}]},{"id":"outcomes-255","code":"255","description":{"en":"<p>You and the doppelganger grapple for what feels like hours, neither of you able to gain the upper hand. Finally, grabbing a rock you strike it unconscious. Blacking out from exhaustion, you awake alone. What was that creature? What are you?…Which are you?</p>\\nLose <energy><energy>. One at a time, for each of your attributes, roll <1d6>, then permanently change the value of that attribute to the result. Once while doing this, after rolling a <1d6>, you may turn the <1d6> to the opposite face of the die before recording the new attribute value. Illustrate the saga of the unknown on the primal cave wall, including the mystery mark. Then return The Other (JU08) to the game box.","ru":"<p><i><b>Вы сражались с двойником не один час, и никто не мог одержать верх. Наконец, схватив камень, вы ударили им своего противника и отправили в беспамятство. Потеряв сознание от изнеможения, вы очнулись в одиночестве. Что это было за существо? Кто вы?.. Который из вас?</b></i></p><p>Потеряйте <energy><energy>. По очереди, для каждой из характеристик своего персонажа, бросьте <1d6>, затем навсегда измените значение этой характеристики на результат броска. После одного из таких бросков можете перевернуть <1d6> на противоположную грань перед тем, как записать новое значение характеристики. На стене первобытной пещеры изобразите историю о неизвестном, включив в неё отметку тайны. Затем верните в коробку карту «Иной» (ПН08).</p>"},"repeatable":false,"marks":[{"label":"","image":"<mystery>"}]},{"id":"outcomes-268","code":"268","description":{"en":"<p>What initially seemed like a brawl is in fact an organized attack, and the target is you! You must fight for your life!</p>\\n\\"Test <might> or <dexterity> to fight. Add +2 for each <i>weapon</i> item you have in a <hand> slot and +2 if you are <i>vengeful</i>.\\n10+: You fight your way free! Flee to an adjacent hex.\\n6–9: You struggle to escape. Suffer <major_injury>.\\n1–5: You are badly wounded in the fighting. Suffer <major_injury><major_injury><minor_injury>..\\n\\nThen add Dangerous Raids (GZ26) to your goals.\\"","ru":"<p><i><b>То, что поначалу выглядело как обычная драка, оказалось организованным нападением — и целью были вы! Вам предстояло сразиться за свою жизнь. </b></i></p><p>Проведите проверку <might> или <dexterity>, чтобы сразиться. +2 за каждое <i>оружие</i>, находящееся в вашей <hand>, и +2, если вы <i>мстительный</i>. <br><b>≥10:</b>  Вы вырвались! Сбегите на соседний участок местности.<br><b>6-9:</b>  Вам с трудом удалось вырваться. Получите <major_injury>.<br><b>1-5:</b>  Вы получили тяжёлые раны в бою. Получите <major_injury><major_injury><minor_injury>.</p><p>Затем добавьте карту «Переживите опасные налёты» (ЦЯ26) к целям.</p>"},"repeatable":false},{"id":"outcomes-274","code":"274","description":{"en":"<p>Your hunt was ill-omened, and this inauspicious turn leaves your people anxious for the season to come. However, this misstep can still be corrected as ritual of the great hunt continues.</p>\\nAdd <unrest><unrest>. Each character degrades all of their <boost> once. Illustrate the saga of the ill-omened rite on the primal cave wall, including hunter mark and the misfortune mark.","ru":"<p><i><b>Охота обернулась дурным знамением, и эта неудача тревожила сердца вашего народа. Однако эту оплошность ещё можно было исправить — обряд великой охоты продолжался.</b></i></p><p>Добавьте <unrest><unrest>. Каждый персонаж уменьшает все свои <boost> один раз. На стене первобытной пещеры изобразите историю о недобром обряде, включив в неё отметку охотника [i] и отметку несчастья [ii].</p>"},"repeatable":false,"marks":[{"label":"i","image":"<hunter>"},{"label":"ii","image":"<misfortune>"}]},{"id":"outcomes-276","code":"276","description":{"en":"<p>Your people fail to establish an edge over the hunters of the north, and they continue to pressure you in the years to come.</p>\\n\\"Subtract <population>, add <unrest><unrest>. Illustrate the saga of the icy fangs on the primal cave wall, including the harrowing mark. Add Predator's Reign (JU06) to the Journey deck, if able.\\"","ru":"<p><i><b>Вашему народу не удалось превзойти охотников с севера, и в последующие годы эти хищники продолжали теснить вас.</b></i></p><p>Завершите текущее испытание.</p><p>Уберите <population> и добавьте <unrest><unrest>. На стене первобытной пещеры изобразите историю о ледяных клыках, включив в неё отметку ужаса. Добавьте карту «Царство хищника» (ПН06) в колоду пути, если возможно.</p>"},"repeatable":false,"marks":[{"label":"","image":"<harrowing>"}]},{"id":"outcomes-279","code":"279","description":{"en":"<p>Whatever the secrets of this behemoth, they sleep soundly in its grave. You find only a strange token of its ancient power.</p>\\n<p>\\"End this challenge. \\n\\nGain 1 of this behemoth's curio. Illustrate the saga of the ancient's mystique on the primal cave wall, including that behemoth's mark adorned by the mystery mark.\\"</p>","ru":"<p><i><b>Какие бы секреты ни хранило это чудище, они мирно покоились в его могиле. Вы нашли артефакт его былой мощи.</b></i></p><p>Завершите текущее испытание.</p><p>Получите 1 сокровище этого чудища. На стене первобытной пещеры изобразите историю о древней мистической силе, включив в неё отметку этого чудища, украшенную отметкой тайны.</p>"},"repeatable":false,"marks":[{"label":"","image":"<mystery>"}]},{"id":"outcomes-283","code":"283","description":{"en":"<p>You finally pull yourself from the river in a place where your people have never tread...</p>\\n\\"Illustrate the saga of the river's embrace on the primal cave wall, including the mark of your current region and the <star> mark. Then expand your valley by following the steps below:\\n\\n<b>Step 1:</b> Add a new tray to your valley. Place it adjacent to your hex, if able. The tray must be placed such that its edges are adjacent to as many edges of placed trays as posslble. If multiple valid positions exist, select one at random.\\n\\n<b>Step 2:</b> Place all hexes from your current region into the draw bag (except the starting hex). Shuffle the hexes in the draw bag. Then, one at a time, draw three of those hexes. and place them unexplored in the slots of the tray you just placed, filling empty slots from north to south and east to west.\\n\\n<b>Step 3 (Epoch 1 and Endless Mode Only):</b> If it is Epoch 1 (or you are playing Endless Mode) and there are 1 or more unplaced glacier overlays, roll <1d6> and place glaciers as follows:\\n1–2: 1 glacier in Zone \\\\\\"A\\\\\\" of one of the hexes without an overlay.\\n[diagram]\\n3–4: 1 glacier in Zone \\\\\\"B\\\\\\" of one of the hexes without an overlay.\\n[diagram]\\n5: Resolve both 1–2 and 3–4.\\n[diagram]\\n6: Roll <1d6> again and read the corresponding outcome instead.\\n1–2: <outcome> 846\\n3–5: <outcome> 134\\n6: <outcome> 446\\n\\nThen, randomly select a hex in the newly placed tray, explore it, then place your character there.\\"","ru":"<p><i><b>Вы наконец‑то выбрались из реки в месте, где ваш народ никогда прежде не бывал…</b></i></p><p>На стене первобытной пещеры изобразите историю об объятиях реки, включив в неё отметку текущего региона и отметку <star>. Затем расширьте долину, пройдя описанные ниже этапы.<br><b>Этап 1. </b>Добавьте новую основу местности в долину. Поместите её по соседству с участком местности со своим персонажем, если возможно. Границы основы должны соседствовать с как можно большим количеством границ уже размещённых основ. Если есть несколько возможных позиций, выберите одну случайным образом.<br><b>Этап 2. </b>Положите в мешочек все неразмещённые участки местности региона, в котором вы находитесь, и перемешайте. Затем по одному вытащите 3 участка и поместите их неисследованной стороной вверх в ячейки новой основы по направлению с севера на юг и с востока на запад.<br><b>Этап 3 (только для эры 1 и бесконечного режима). </b> Если в запасе есть хотя бы 1 непомещённая накладка ледника,  бросьте <1d6> и поместите ледники по результату броска: [1-2] один ледник в район А одного из участков местности без накладки, [3-4] один ледник в район Б одного из участков местности без накладки, [5] разыграйте результаты 1-2 и 3-4, [6] бросьте <1d6> ещё раз и прочитайте один из исходов ниже, соответствующий результату броска.<br>[1-3] <outcome> 846, [4-5] <outcome> 134, [6] <outcome> 446.</p><p>Затем поместите своего персонажа на случайный участок в только что помещённой основе и исследуйте его.</p>"},"repeatable":false},{"id":"outcomes-287","code":"287","description":{"en":"<p>These days of security give you a chance to prepare for harsh winters that will surely fall again.</p>\\n\\"As a group, the players must choose one of the following paths for your society:\\n\\n<b>A) Build up resources:</b> Add Gather Stores (GA03) to your goals.\\n\\n<b>B) Propagate your staple crops:</b> Add Shape the Land (GA16) to your goals. When you complete it, illustrate the saga of cultivation on the primal cave wall, including the cultivation (ii) mark.\\n\\n<b>C) Sow seeds for the future:</b> If the cultivation mark (iii) is on the primal cave wall, add Prepare Farmlands (GB06) to your goals.\\n\\n<b>D) Cultivate a shared culture:</b> If the songweaver mark (i) or scribe mark (ii) is on the primal cave wall, add Seek a Symbol (GB09) to your goals.\\n\\n<b>E) Build a grand citadel:</b> If the cultivation mark (iii) is on the primal cave wall, add Level the Land (GB14) to your goals. \\n\\n<b>F) Seek passage to the starlit sea:</b> If the Starlit Sea mark (iv) is on the primal cave wall, add Research the Moon's Mystery (GZ13) to your goals. \\n\\n<b>G) Chart the shrouded world:</b> If the underworld mark (v) is on the primal cave wall, add Journeys in Shadow (GZ23) to your goals. \\n\\nThen, you may spend 6<lore> to choose another effect from this list and resolve it. You may do this any number of times.\\"","ru":"<p><i><b>Эти спокойные дни дали вам возможность подготовиться к суровым зимам, что непременно наступят вновь.</b></i></p><p>Совместно выберите один из следующих путей развития общины:<br><b>А. Накопите ресурсы.</b> Добавьте карту «Соберите припасы» (ЦА03) к целям.<br><b>Б. Вырастите злаки. </b>Добавьте карту «Измените ландшафт» (ЦА16) к целям. Достигнув её, на стене первобытной пещеры изобразите историю о возделывании, включив в неё отметку возделывания [i].<br><b>В. Посейте семена грядущего урожая. </b>Если на стене первобытной пещеры есть отметка возделывания [i], добавьте карту «Вспашите поле» (ЦБ06) к целям.<br><b>Г. Взрастите общую культуру. </b>Если на стене первобытной пещеры есть отметка песнопевца [ii] или летописца [iii], добавьте карту «Отыщите символ» (ЦБ09) к целям.<br><b>Д. Возведите великую цитадель. </b>Если на стене первобытной пещеры есть отметка возделывания [i], добавьте карту «Разровняйте землю» (ЦБ14) к целям.<br><b>Е. Отправьтесь на поиски пути к Звёздному морю. </b>Если на стене первобытной пещеры есть отметка Звёздного моря [iv], добавьте карту «Исследуйте тайну луны» (ЦЯ13) к целям. <br><b>Ж. Исследуйте скрытый мир. </b>Если на стене первобытной пещеры есть отметка подземного мира [v], добавьте карту «Отправьтесь в путешествие к теням» (ЦЯ23) к целям.</p><p>Затем можете потратить 6 <lore>, чтобы выбрать и разыграть другой эффект из этого списка. Повторите это сколько угодно раз.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<cultivation>"},{"label":"ii","image":"<songweaver>"},{"label":"iii","image":"<scribe>"},{"label":"iv","image":"<starlitsea>"},{"label":"v","image":"<underworld>"}]},{"id":"outcomes-290","code":"290","description":{"en":"<p>A sudden lightning storm makes it perilous to be in a flat place!</p>\\n\\"Test to <awareness> to guess the lightning's path. Add +2 if you are <i>attuned</i> and +2 if you have a Map.\\n12+: You rush to a small ditch you saw earlier, and watch in awe as the fury of the clouds blasts the earth around you. Place <fire> in your hex.\\n8–11: You sense the energy building around you, and throw yourself flat. Suffer <minor_injury>.\\n1–7: You are struck by the bolt. Suffer <major_injury><major_injury>.\\"","ru":"<p><i><b>Внезапная гроза сделала пребывание на равнине крайне опасным!</b></i></p><p>Проведите проверку <awareness>, чтобы угадать путь молнии. +2, если вы <i>сосредоточенный</i>, и +2, если у вас есть «Карта».<br><b>≥12:</b>  Вы помчались к небольшой рытвине, замеченной ранее, и с изумлением наблюдали, как ярость небес обрушивается на землю вокруг вас. Поместите <fire> на свой участок местности.<br><b>8-11:</b>  Вы почувствовали, как вокруг сгущается электричество, и бросились ничком на землю. Получите <minor_injury>.<br><b>1-7:</b>  Рядом с вами ударила молния. Получите <major_injury><major_injury>.</p>"},"repeatable":false},{"id":"outcomes-291","code":"291","description":{"en":"<p>Overhunting depletes the prey-animals across the regions your people occupy. These populations are slow to recover, and your society faces a difficult decision...</p>\\n\\"As a group, the players must choose one of the following paths for your society:\\n\\n<b>A) Endure the hardship of continued overhunting:</b> Subtract <population><population><population>. Resolve as many of the following as you are able:\\n\\n1) If there is at least 1 Verdant Vale hex in the valley, remove FF03 from the Forest Foraging deck.\\n2) If there is at least 1 Skyreach Plateau hex in the valley, remove FP09 from the Prairie Foraging deck.\\n3) If there is at least 1 Maelstrom Hills hex in the valley, remove FM04 from the Jungle Foraging deck.\\n4) If there is at least 1 Tangle hex in the valley (and this region is available), remove FT04 from the Tangle Foraging deck.\\n\\n<b>B) Restrict harvesting of prey-beasts:</b> Add <unrest><unrest>.\\n\\n<b>C) Reconsider old beliefs about diet:</b> If you have a taboo against eating plants (grain, nuts, or roots), remove that taboo and add <unrest><unrest><unrest>.\\"","ru":"<p><i><b>Чрезмерная охота разорила звериные тропы в землях, где жил ваш народ. Добычи становилось всё меньше, и животные не успевали размножиться. Перед вашей общиной встал трудный выбор…</b></i></p><p>Совместно выберите один из следующих путей развития общины:<br><b>А. Продолжите охотиться несмотря на трудности.</b> Уберите <population><population><population>. Разыграйте как можно больше из следующего:<br>1. Если в долине есть хотя бы 1 участок Дивной долины, верните в коробку карту ДЛ03 из колоды добычи припасов в лесу.<br>2. Если в долине есть хотя бы 1 участок Поднебесной равнины, верните в коробку карту ДС09 из колоды добычи припасов в степи.<br>3. Если в долине есть хотя бы 1 участок Ураганных холмов, верните в коробку карту ДД04 из колоды добычи припасов в джунглях.<br>4. Если в долине есть хотя бы 1 участок Сплетения (и этот регион доступен), верните в коробку карту ДП04 из колоды добычи припасов на полянах.<br><b>Б. Ограничьте убийство диких животных. </b>Добавьте <unrest><unrest>.<br><b>В. Пересмотрите прежние взгляды на питание. </b>Если у вас есть табу на поедание растений (злаки, орехи или коренья), зачеркните или сотрите это табу и добавьте <unrest><unrest><unrest>.</p>"},"repeatable":false},{"id":"outcomes-292","code":"292","description":{"en":"<p>\\"Conflict bubbles over. Fights begin to break out, and you suspect that if you don't take swift action, your society might splinter at its foundation.\\"</p>\\nIf you have not completed it this epoch, add Quell the Embers (GZ21) to your goals. Otherwise, subtract <population><population>.","ru":"<p><i><b>Вражда нарастала. Повсюду случались стычки. Вы понимали, что если не принять немедленных мер, община расколется у самого основания.</b></i></p><p>Если уровень <unrest> 6 или ниже, он становится равным 7. Если в эту эру вы ещё не достигли цели «Погасите искры» (ЦЯ21), добавьте её к целям. В противном случае уберите <population><population>.</p>"},"repeatable":false},{"id":"outcomes-293","code":"293","description":{"en":"<p>The behemoth slumps, stunned. Its stony face betrays no emotion you can recognize, but the thrum you feel while touching it seems almost wistful. You find you do not have it within yourself to kill such a creature, no matter your past conflicts. You wait for several heartbeats as the behemoth decides its next move. After the stony creature struggles to its feet, it does not resume its attack, and instead rumbles back to its lair.</p>\\n\\"End this challenge.\\n\\nAdd <unrest><unrest><unrest><unrest>. Set the alert behemoth's demeanor to \\\\\\"2.\\\\\\" Illustrate the saga of the broken cycle on the primal cave wall, including the alert behemoth's mark, the caution mark (i), and the growth mark (ii). Permanently raise the <conviction> and <awareness> of each character who was on the venture when it was completed by 1 (to a maximum of 7). Add the alert behemoth's mark and the growth mark (ii) to the Legend side of each of those Character cards.\\n\\nThen end the Epoch. See Codex p.204 to begin Epoch 3.\\"","ru":"<p><i><b>Оглушённое чудище обрушилось на землю. Его каменный лик казался лишённым человеческих чувств, но глухой гул, исходящий от него, звучал почти как печаль. Вы поняли, что не способны убить такое создание — как бы ни были горьки прежние схватки. Несколько ударов сердца вы выжидали, пока чудище решит, что делать дальше. Наконец, с трудом поднявшись, оно не стало нападать снова — лишь тяжело застонало и вернулось в своё логово.</b></i></p><p>Завершите текущее испытание.</p><p>Добавьте <unrest><unrest><unrest><unrest>. Установите значение нрава бодрствующего чудища на «2». На стене первобытной пещеры изобразите историю о разомкнутом круге, включив в неё отметку бодрствующего чудища, отметку осторожности [i] и отметку становления [ii].<br>Навсегда увеличьте <conviction> и <awareness>  каждого персонажа, участвовавшего в этом походе на момент его завершения, на 1 (не более чем до 7). Добавьте отметку бодрствующего чудища и отметку становления [ii] на сторону легенды карты каждого из этих персонажей.</p><p>Затем завершите эру. См. с. 204, чтобы начать эру 3.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<caution>"},{"label":"ii","image":"<growth>"}]},{"id":"outcomes-299","code":"299","description":{"en":"<p>As you push the last dangling vines from your path, you take your first steps into a dense and damp jungle. The sunlight scatters down through an enormous canopy of fragrant flowers.</p>\\n\\"Resolve the first you are able:\\n\\nA) Slip into the familiar shadows through a previously unknown tunnel: If the Tangle mark is on the primal cave wall, place your character in any Tangle hex, then add <lore><lore><lore>. \\n\\nB) Explore this region of vast flowers: If you have 1 or more available terrain trays, illustrate the saga of the soaring flowers on the primal cave wall, including the discovery mark and the Tangle mark. Add Beneath the Canopy (CN01) to your looming challenges. Then expand your valley by following the steps below:\\n\\nStep 1: Add a new tray to your valley. Place it adjacent to your hex, if able. The tray must be placed such that its edges are adjacent to as many edges of placed trays as posslble. If multiple valid positions exist, select one at random.\\n\\nStep 2: Place all Tangle hexes into the draw bag (except for the starting hex). Shuffle the hexes in the draw bag. Then, one at a time, draw three of those hexes. and place them unexplored in the slots of the tray you just placed, filling empty slots from north to south and east to west.\\n\\nC) A strange jungle has temporarily spread into this area, opening a path previously blocked by mountains: If you have no available terrain trays, randomly select a hex from the Tangle region and place it adjacent to your current hex, not in a terrain tray. Place your character in that hex. Until the end of the challenge, treat that hex as the Tangle region (see Nature of the Beast Rulebook p.4). At the end of the challenge, return that hex to the game box; any tokens or overlays on that hex at that time are returned to the game box, and any characters in that hex perish.\\"","ru":"<p><i><b>Раздвинув свисающие лианы, вы сделали первые шаги в густые влажные заросли. Сквозь необъятный полог благоухающих цветов просачивался рассеянный свет.</b></i></p><p>Разыграйте первое, что можете:<br><b>А. Проскользните в знакомую тень по нехоженому туннелю. </b>Если на стене первобытной пещеры есть отметка Сплетения, поместите своего персонажа на любой участок местности Сплетения, затем добавьте <lore><lore><lore>.<br><b>Б. Исследуйте этот регион громадных цветов. </b>Если у вас есть хотя бы 1 неразмещённая основа местности, на стене первобытной пещеры изобразите историю о парящих цветах, включив в неё отметку открытия [ii] и отметку Сплетения [i]. Добавьте карту «Под навесом» (ИЖ01) к грядущим испытаниям. Затем расширьте долину, пройдя описанные ниже этапы.<br><b>Этап 1. </b>Добавьте новую основу местности в долину. Поместите её по соседству с участком местности с вашим персонажем, если возможно. Границы основы должны соседствовать с как можно большим количеством границ уже размещённых основ. Если есть несколько возможных позиций, выберите одну случайным образом.<br><b>Этап 2.</b> Положите в мешочек все неразмещённые участки Сплетения, кроме начального, и перемешайте. Затем по одному вытащите 3 участка и поместите их неисследованной стороной вверх в ячейки новой основы по направлению с севера на юг и с востока на запад.<br><b>В. Странные джунгли временно раскинулись в этих местах, открыв путь, который прежде преграждали горы. </b> Если у вас нет неразмещённых основ местности, поместите случайный участок Сплетения рядом со своим участком (не в ячейку основы  местности), а затем поместите своего персонажа на него. До конца текущего испытания считайте этот участок частью региона Сплетения (см. с. 4 правил дополнения «Природа зверя»). Завершив испытание, верните в коробку этот участок местности вместе с жетонами и накладками на нём. Персонажи, которые находились на убранном участке, умирают.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<tangle>"},{"label":"ii","image":"<discovery>"}]},{"id":"outcomes-300","code":"300","description":{"en":"<p>\\"From atop its brow, you strike at the behemoth's great head. Your sputtering weapon pierces the behemoth's brow. For a moment, it seems unphased. But then the poison begins its work and with a thunderous crash, the creature slumps. Cracks run through its great visage, and a flood of bubbling ooze spills from its body, spreading across the land and seeping into the soil, turning it to blackened mud. In dying wrath, its tendrils twist up from the earth, grappling nearby works of your people to dust. Then the vines grow brittle and break, and the creature is finally extinguished.\\"</p>\\n\\"End this challenge.\\n\\nIllustrate the saga of the felled ancient on the primal cave wall, including the battle mark (i) and the alert behemoth's mark adorned by the behemoth's blood mark (ii). Add the behemoth's blood (ii) mark to the Legend side of the card of each character who participated in the venture. One character who participated in the venture must discard a <i>weapon</i> item, if able.\\n\\nPlace the alert behemoth's lair in its current hex in its inactive state. Then, if there are any unplaced twisted wake overlays, place them in randomly selected hexes adjacent to the behemoth's inactive lair. For each wake placed this way, roll <1d6> and place it in the corresponding zone: 1–2: A, 3–4: B, 5–6: C. If a wake would be placed in a zone with an overlay this way, remove the overlay and replace it with the twisted wake. \\n\\nThen end the Epoch. See Codex p.204 to begin Epoch 3.\\"","ru":"<p><i><b>Вы нанесли удар по голове чудища и пронзили его лоб своим отравленным оружием. На мгновение показалось, что существо не ощутило боли. Но затем яд начал действовать, и чудище рухнуло с оглушительным грохотом. Его исполинский лик покрылся трещинами, а из тела хлынула бурлящая слизь. Она растеклась и пропитала почву, превратив её в почерневшее месиво. В предсмертном всплеске ярости побеги чудища взметнулись из земли и обратили в пыль близлежащие постройки. Когда лианы стали ломкими настолько, что рассыпались, существо окончательно исчезло.</b></i></p><p>Завершите текущее испытание.</p><p>На стене первобытной пещеры изобразите историю о поверженном древнем существе, включив в неё отметку битвы [i] и отметку бодрствующего чудища, украшенную отметкой крови чудища [ii]. Добавьте отметку крови чудища [ii] на сторону легенды каждой карты персонажа, участвовавшего в походе. Один из персонажей, участвовавших в походе, должен сбросить оружие, если возможно. <br>Поместите логово бодрствующего чудища неактивной стороной вверх на участок местности с чудищем. Затем, если остались неразмещённые накладки скрученных отпечатков, поместите их на случайные участки местности, соседние с неактивным логовом чудища. Для каждого отпечатка бросьте <1d6>, чтобы поместить в соответствующий район: [1-2] А, [3-4] Б, [5-6] В. Если при этом вы должны поместить отпечаток в район с другой накладкой, замените её на скрученный отпечаток.</p><p>Затем завершите текущую эру. См. с. 204, чтобы начать эру 3.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<battle>"},{"label":"ii","image":"<behemothsblood>"}]},{"id":"outcomes-302","code":"302","description":{"en":"<p>Curiosity and wonder at the world flourishes among your people, and you seek new knowledge of the valley you call home.</p>\\n\\"As a group, the players must choose one of the following paths for your society:\\n\\n<b>A) Explore a discovered region:</b> If you have 1 or more unplaced terrain trays and at least 1 region that has both 3 placed hexes and 3 unplaced hexes, choose one of those regions. Add 1 new tray to the valley, touching the chosen region on as many edges as possible. Then randomly select 3 hexes from that region and place them in each empty slot of the new tray, from north to south and from east to west. Place these hexes with their unexplored side faceup.\\n\\n<b>B) Challenge the glacial walls:</b> If the glacier cap hex (HX01a) is not in the valley, add Across the Ice (GA06) to your goals.\\n\\n<b>C) Study the omens:</b> Add Painted in the Sky (GA24) to your goals. \\n\\n<b>D) Seek a new region:</b> If the glacier mark (i) is on the primal cave wall, choose one of the following and add it to your goals: Beyond the Jagged Rim (GZ04), A World Below (GZ05), Shrouded Lands (GZ28), Seek the Shadow Column (GY02), or Seek the Tangle (GN01).\\n\\n<b>E) Search for lost cousins:</b> If the schism mark (ii) is on the primal cave wall, add Seek Contact (GZ10) to your goals.\\n\\n<b>F) Find answers in the past:</b> If there is a ruin in the valley, add Hidden Treasures (GZ30) and Restore a Ruin (GZ22) to your goals.\\n\\n<b>G) Study an ancient behemoth's sepulchre:</b> If there is an inactive behemoth's lair in the valley, add Survey the Grave (GZ14) to your goals.\\n\\nThen, you may spend 6<lore> to choose another effect from this list and resolve it. You may do this any number of times.\\"","ru":"<p><i><b>Любопытство и восхищение миром определяли воззрения вашего народа, и вы устремились к новым знаниям о долине, которую называли домом.</b></i></p><p>Совместно выберите один из следующих путей развития общины:<br><b>А. Исследуйте открытый регион. </b>Если у вас есть хотя бы 1 неразмещённая основа местности, и в долине есть хотя бы 1 регион с 3 размещёнными и 3 неразмещёнными участками, выберите 1 из таких регионов. Добавьте 1 новую основу местности в долину так, чтобы она соприкасалась с выбранным регионом как можно большим количеством сторон. Затем возьмите 3 случайных участка этого региона и поместите их неисследованной стороной вверх в пустые ячейки новой основы местности по направлению с севера на юг и с востока на запад.<br><b>Б. Бросьте вызов ледяным стенам. </b>Если в долине нет накладки ледяного купола (ОБ01а), добавьте карту «Пройдите по ледяному покрову» (ЦA06) к целям.<br><b>В. Изучите знамения. </b>Добавьте карту «Прочтите, что начертано в небесах» (ЦA24) к целям.<br><b>Г. Отыщите новый регион. </b>Если на стене первобытной пещеры есть отметка ледника [i], выберите одну из следующих карт и добавьте её к целям: «Отправьтесь за зубчатый край» (ЦЯ04), «Отправьтесь в подземный мир» (ЦЯ05), «Отправьтесь в сокрытые земли» (ЦЯ28), «Найдите луч света» (ЦЕ02) или «Найдите Сплетение» (ЦЖ01).<br><b>Д. Отыщите потерянных родственников. </b>Если на стене первобытной пещеры есть отметка раскола [ii], добавьте карту «Установите контакт» (ЦЯ10) к целям.<br><b>Е. Найдите ответы в прошлом. </b>Если в долине есть руины, получите карту знаний «Раскопки» (ЗБ12), добавьте карты «Отыщите спрятанные сокровища» (ЦЯ30) и «Восстановите руины» (ЦЯ22) к целям.<br><b>Ж. Изучите гробницу древнего чудища. </b>Если в долине есть неактивное логово чудища, добавьте карту «Осмотрите могилу» (ЦЯ14) к целям.</p><p>Затем можете потратить 6 <lore>, чтобы выбрать другой эффект из этого списка и разыграть его. Повторите это сколько угодно раз.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<glacier>"},{"label":"ii","image":"<schism>"}]},{"id":"outcomes-303","code":"303","description":{"en":"<p>In the coral overgrowth, you uncover...</p>\\n\\"Embark on the venture below (see Ventures on Rulebook p.60).\\n\\n<bi>A strange pattern has formed within the stalks of coral that swish around your feet. As the light of the comet grows brighter, the path before you seems to become clearer.</bi>\\n<b>Champion, Coral:</b> Someone must test <awareness> to discern the pattern add +4 if <comet> is a current omen.\\n11+: You are sure of it: the flickers of light beckon you deeper into the glade. The venture continues.\\n1–10: You become lost amidst the glade, and the choking spores aggravate your lungs. The venture fails unless a character suffers <minor_disease> or spends <lore> to attempt this test again.\\n\\n<bi>Making your way deeper into the glade, you suddenly feel eyes upon you. There are creatures here, darting amidst the swaying fronds. And they are hungry.</bi>\\n<b>Coral, Group, Hazard:</b> Everyone must test <dexterity> to drive back the creatures. Each character adds +2 if they have an item with a <fire> token on it.\\n9+: You keep the creatures at bay. If any character resolves this result, the venture continues.\\n1–8: You are bitten badly by an unseen creature which withdraws again to the safety of the coral to wait for you to expire. Suffer <minor_injury><major_disease>. If all characters on the venture resolve this result, the venture fails.\\n\\n<bi>You make your way into what must be the center of the glade. A large stalk rises above the others.</bi>\\n<b>Champion, Coral, Wonder:</b> Someone must test <conviction> to approach the stalk. Add +4 if you have a <i>coral</i> or <i>moonblood</i> item and +4 if <comet> is a current omen.\\n12+: You approach the stalk, and it opens before you, gently caressing your face. Then suddenly, the entire glade begins to wither. Flip the coral overgrowth to its inactive side, and add the coral mark to the Legend side of your character card. Complete this venture and the associated goal.\\n1–11: None dares approach. The venture fails unless a character spends <energy><energy> or <lore> to attempt this test again.\\"","ru":"<p><i><b>В коралловых зарослях вы обнаружили...</b></i></p><p>Отправьтесь в поход (см. раздел «Походы» в правилах игры на с. 60).</p><p><b><i>Коралловые отростки, что качались у вас под ногами, складывались в странный узор. Комета светила всё ярче, и казалось, что путь перед вами становился яснее.</i></b></p><p><b>Защитник, коралл.</b> Один из персонажей в походе должен провести проверку <awareness>, чтобы изучить узор. +4, если <comet>— текущее знамение.<br><b>≥11:</b> Вы были уверены, что мерцающий свет манил вас вглубь зарослей. Продолжите поход.<br><b>1-10:</b> Вы заблудились среди зарослей, и удушающие споры начали разъедать ваши лёгкие. Поход окончился неудачно, если только любой персонаж в походе не получит <minor_disease> или не потратит <lore>, чтобы провести проверку ещё раз.</p><p><b><i>Продвигаясь вглубь зарослей, вы вдруг ощутили на себе взгляд. Это были существа, что мелькали среди качающихся кораллов. И они были голодны.</i></b></p><p><b>Коралл, группа, угроза. </b>Все персонажи в походе должны провести проверку <dexterity>, чтобы отогнать существ. +2, если у персонажа есть предмет с <fire>.<br><b>≥9:</b> Вы сдержали существ на расстоянии. Если хотя бы один персонаж получил этот результат, продолжите поход.<br><b>1-8:</b> Вас укусило существо, которое вы даже не успели увидеть, и вновь скрылось в кораллах, ожидая, пока вы лишитесь сил. Получите <minor_injury> и <major_disease>. Если все персонажи получили этот результат, поход окончился неудачно.</p><p><b><i>Вы добрались до места, которое казалось центром зарослей. Огромный коралловый стебель возвышался  над остальными.</i></b></p><p><b>Защитник, коралл, чудо. </b>Один из персонажей в походе должен провести проверку <conviction>, чтобы подойти к стеблю. +4, если у него есть предмет <i>коралла </i>или <i>лунной крови</i>, и +4, если <comet>— текущее знамение.<br><b>≥12:</b> Вы подошли к стеблю, и он раскрылся, нежно прикоснувшись к вашему лицу. Вдруг все заросли начали увядать. Переверните коралловые заросли неактивной стороной вверх. Затем добавьте отметку коралла на сторону легенды карты своего персонажа. Завершите этот поход и достигните соответствующей цели.<br><b>1-11:</b> Никто не решился подойти. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy> или <lore>, чтобы попытаться снова.</p>"},"repeatable":false,"marks":[{"label":"","image":"<coral>"}]},{"id":"outcomes-309","code":"309","description":{"en":"<p>You have found out the root of the issue and uprooted it, allowing reconciliation within the valley.</p>\\nSet <unrest> to 0. Illustrate the saga of flourishing peace on the primal cave wall, including the mediator mark. At the end of any day, you may end this challenge.","ru":"<p><i><b>Вы выявили корень проблемы и устранили его, что позволило жителям долины вновь зажить в согласии.</b></i></p><p>В конце любого дня можете завершить текущее испытание.</p><p>Установите значение <unrest> на «0». На стене первобытной пещеры изобразите историю о процветающем спокойствии, включив в неё отметку посредника.</p>"},"repeatable":false,"marks":[{"label":"","image":"<mediator>"}]},{"id":"outcomes-310","code":"310","description":{"en":"<p>You discover that some among your people have been hoarding resources and refusing to share in times of need.</p>\\n\\"As a group, the players must choose one of the following paths for your society:\\n\\n<b>A) Enforce sharing of resources, expelling those who refuse:</b> Subtract <population><population><population>. Illustrate the saga of the expulsion on the primal cave wall, including the schism mark (i).\\n\\n<b>B) Allow disparity of resources to persist:</b> Add <unrest><unrest><unrest> and subtract <population>. Add Fireside Grumbles (NN01) to the Night deck, if able. Illustrate the saga of hunger's pangs on the primal cave wall, including the harrowing mark (ii).\\"","ru":"<p><i><b>Вы обнаружили, что некоторые члены вашей общины тайно запасали ресурсы и отказывались делиться ими в трудные времена.</b></i></p><p>Совместно выберите один из следующих путей развития общины:<br><b>А. Принудительно распределите ресурсы, изгнав тех, кто отказывается делиться.</b> Уберите <population><population><population>. На стене первобытной пещеры изобразите историю об изгнании, включив в неё отметку раскола [i].<br><b>Б. Не перераспределяйте ресурсы. </b>Добавьте <unrest><unrest><unrest> и уберите <population>. Добавьте карту «Ворчание у костра» (НО01) в колоду ночи, если возможно. На стене первобытной пещеры изобразите историю о муках голода, включив в неё отметку ужаса [ii].</p>"},"repeatable":false,"marks":[{"label":"i","image":"<schism>"},{"label":"ii","image":"<harrowing>"}]},{"id":"outcomes-311","code":"311","description":{"en":"<p>\\"Without an outpost, your people are at the mercy of the howling winds and icy nights. Losses begin to accumulate, leaving your people at the precipice of disaster. What's more, there are strange signs. A glimmering comet burns high above you in the sky, and traces of some great creature moving within the valley grow ever more undeniable...\\"</p>\\n\\"End this challenge.\\n\\nThen, as a group, the players must choose one of the following paths for your society:\\n\\n<b>A) Keep fighting to persist within the valley:</b> Subtract <population><population><population> and add <unrest><unrest>. Though your people have suffered, they have also learned new techniques that might be the difference between survival and doom. Your society gains the following mantle powers: Prey-Stalker (MA01), Secret-Finder (MA02), Friend-Guide (MA03), Safe-Keeper (MA04). Record these in the Mantle Powers section on the Culture page of the Journal. At the start of each subsequent challenge, players will select one mantle power for each character based on their mantle, as described in Mantle Powers on Rulebook p.65. Then illustrate the saga of the dire wanderings on the primal cave wall, including the <comet> mark and the harrowing mark. Add Arrival (CA04) to your looming challenges.\\n\\n<b>B) Leave the valley, hoping your descendents may someday return:</b> Illustrate the saga of the bitter retreat on the primal cave wall, including the exodus mark and the harrowing mark. Your campaign ends and your society <b>vanishes</b>. See Ending a Campaign on Rulebook p.97.\\n\\nHowever, not all hope is lost, as your people's hard-won knowledge is passed down to new generations! To continue playing Stonesaga, see Beginning Subsequent Campaigns on Rulebook p.97. When you begin your new campaign, you may add any number of forgotten Legend cards to your new society as Legends. You may also copy any information from the Culture and Recipes pages from your old Journal into the new one when you begin your new campaign.\\"","ru":"<p><i><b>Без поселений ваш народ сдался на милость воющих ветров и леденящих ночей. Потери росли, и община очутилась на грани бедствия. Более того, начали появляться странные знамения: в небе ярко пылала сверкающая комета, а следы неведомого чудища, что бродило по долине, сложно было не замечать…</b></i></p><p>Завершите текущее испытание. </p><p>Затем совместно выберите один из следующих путей развития общины:<br><b>А. Продолжите борьбу за выживание в долине. </b>Уберите <population><population><population> и добавьте <unrest><unrest>. Несмотря на потери, ваш народ обрёл новые знания, которые могут оказаться решающими в борьбе за выживание. Ваша община получает следующие силы мантий: «Следопыт» (MA01), «Знаток секретов» (MA02), «Друг-наставник» (MA03), «Хранитель» (MA04). Запишите их в раздел «Силы мантий» на странице «Культура» в журнале. В начале каждого последующего испытания выбирайте одну силу для каждого персонажа, основываясь на его мантии, как описано в разделе «Силы мантий» на с. 65 правил. На стене первобытной пещеры изобразите историю о мрачных скитаниях, включив в неё отметку <comet> и отметку ужаса [i]. Добавьте карту «Вторжение» (ИA04) к грядущим испытаниям.<br><b>Б. Покиньте долину в надежде, что ваши потомки однажды вернутся. </b>На стене первобытной пещеры изобразите историю о горьком отступлении, включив в неё отметку исхода [ii] и отметку ужаса [i]. Завершите кампанию. Ваша община <b>исчезла</b>. См. раздел «Конец кампании» в правилах игры на с. 97.<br>Однако не вся надежда утрачена, поскольку знания, добытые вашим народом, передаются новым поколениям! Чтобы продолжить играть в «Наскальную историю», см. в правилах игры раздел «Начало следующих кампаний» на с. 97 или раздел «Бесконечный режим» на с. 102. Когда начнёте новую кампанию, можете добавить любое количество забытых карт легенд в свою новую общину. Вы также можете перенести любые сведения со страниц «Культура» и «Рецепты» из старого журнала в новый.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<harrowing>"},{"label":"ii","image":"<exodus>"}]},{"id":"outcomes-312","code":"312","description":{"en":"<p>\\"As if you had reached up to grab the moon in the sky, you have halted the Tangle's cycle of death and rebirth. The Tangle's health improves over time, the blight fading into distant memory. And hidden away, the Tangle's seed still slumbers, awaiting the day it slips from your grip and the cycle can begin again.\\"</p>\\n\\"Add <population><population><population> and subtract <unrest><unrest><unrest>.\\n\\nIllustrate the saga of the Tangle preserved on the primal cave wall, including the moonblood mark and the Tangle mark. Your society <b>persists.</b>\\n\\nCongratulations! You have completed Stonesaga's campaign! To immortalize a photo of your primal cave wall and see other people's works of art, we invite you to share your saga with our community!\\n\\n@[Insert Link]@\\n\\nTo continue playing Stonesaga, see Playing Endless Mode After a Campaign on Rulebook p.97, or Beginning Subsequent Campaigns on Rulebook p.97.\\"","ru":"<p><i><b>Вы словно протянули руку к луне и разомкнули круг смерти и возрождения Сплетения. Со временем оно вернулось к прежнему состоянию, а гниль осталась лишь в далёком прошлом. Но где‑то в укромном месте семя Сплетения всё ещё дремало, дожидаясь момента, когда вы ослабите хватку и цикл сможет повториться.</b></i></p><p>Добавьте <population><population><population> и уберите <unrest><unrest><unrest>. На стене первобытной пещеры изобразите историю о сохранении Сплетения, включив в неё отметку лунной крови [i] и отметку Сплетения [ii]. Ваша община <b>выжила</b>.</p><p>Поздравляем! Вы завершили кампанию «Наскальной истории»! Чтобы увековечить фотографию своей стены первобытной пещеры и увидеть произведения искусства других игроков, мы приглашаем вас поделиться своей историей с нашим сообществом!</p><p>Чтобы продолжить играть в «Наскальную историю», см. в правилах игры раздел «Начало следующих кампаний» на с. 97 или раздел «Бесконечный режим» на с. 102.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<moonblood>"},{"label":"ii","image":"<tangle>"},{"label":"","image":"<qrcode>"}]},{"id":"outcomes-317","code":"317","description":{"en":"<p>A sudden wriggling from your bag causes you to start, and you drop your pouch, spilling materials everywhere. You see the coral that was in your bag wriggling away, moving toward a distant overgrowth. In fascination and fright, you watch the coral fuse with the dead branches of the glade, and it begins to bloom.</p>\\nFlip the coral overgrowth overlay it to its active side. Then degrade each of your maladies twice and add <lore><lore>.","ru":"<p><i><b>Вдруг что‑то зашевелилось в вашей сумке — вы вздрогнули и уронили её, рассыпав все материалы. Вы заметили, как выпавший из сумки коралл, извиваясь, пополз к засохшим зарослям. С изумлением и страхом вы наблюдали, как живой коралл слился с мёртвыми ветвями — и те зацвели.</b></i></p><p>Переверните накладку коралловых зарослей активной стороной вверх. Затем уменьшите каждый из своих недугов дважды и добавьте <lore><lore>.</p>"},"repeatable":false},{"id":"outcomes-319","code":"319","description":{"en":"<p>The predator collapses upon you, dragging you to the ground beneath its weight. Its mandibles shudder, then the light fades from its eyes and it perishes.</p>\\n<p>\\"Gain 3 game, 1 shell, and 1 tooth. Add The Hunter's Trial (GA05) to your goals.\\"</p>","ru":"<p><i><b>Хищник рухнул на вас, придавив к земле. Его жвалы дёрнулись, затем свет в его глазах погас — и он испустил дух.</b></i></p><p>Получите 3 дичи, 1 ракушку и 1 клык. Добавьте карту «Пройдите испытание охотника» (ЦA05) к целям.</p>"},"repeatable":false},{"id":"outcomes-321","code":"321","description":{"en":"<p>An unexpected feature juts from the landscape. It seems to be...</p>\\n\\"Randomly select an unexplored hex adjacent to your hex, choosing one without overlays if able, then resolve the first you are able:\\n\\n<b>A) An unusual biome border:</b> If the selected hex borders another region that also has at least 1 unexplored hex, exchange the positions of the selected hex and an unexplored hex of your choice from the other region. Place both unexplored. If this is true for multiple regions, choose one for which to resolve the exchange.\\n\\n<b>B) A ruin that is not in the tales of your people:</b> If the schism mark is on the primal cave wall and there are 1 or more unplaced outpost overlays, place a ruin overlay in a zone of your choice in the unexplored hex without an overlay.\\n\\n<b>C) A set of strange cracks and crevices:</b> If there are 1 or more unplaced geothermal vents overlays, place an inactive geothermal vents overlay in a zone of your choice in the unexplored hex without an overlay (see geothermal vents on Codex p.210).\\n\\n<b>D) A massive wall of ice:</b> If there are 1 or more unplaced glacier overlays, place a glacier overlay in the unexplored hex in a zone of your choice in the unexplored hex without an overlay.\\n\\n<b>E) A mysterious occurence:</b> Place a mystery token in the hex.\\"","ru":"<p><i><b>Впереди виднелось нечто неожиданное. Кажется, это…</b></i></p><p>Случайным образом выберите один из неисследованных участков местности по соседству со своим, выбрав участок без накладок, если возможно. Затем разыграйте первое, что можете:<br><b>А. …необычная граница местности. </b>Если выбранный участок местности граничит с другим регионом, в котором есть хотя бы 1 неисследованный участок, поменяйте местами выбранный участок и любой неисследованный участок из того региона. Поместите оба участка неисследованной стороной вверх. Если это условие выполняется для нескольких регионов, выберите один.<br><b>Б. …руины, о которых не рассказывали ваши предки. </b>Если на стене первобытной пещеры есть отметка раскола и у вас есть хотя бы 1 неиспользованная накладка поселения, поместите её стороной руин вверх в любой район, где нет накладки, неисследованного участка.<br><b>В. …странные трещины и расселины. </b>Если есть хотя бы 1 неиспользованная накладка геотермальных источников, поместите её неактивной стороной вверх в любой район, где нет накладки, неисследованного участка (подробнее о геотермальных источниках см. на с. 210).<br><b>Г. …огромная ледяная стена. </b>Если есть хотя бы 1 неиспользованная накладка ледника, поместите её в любой район, где нет накладки, неисследованного участка.<br><b>Д. …некое таинственное явление. </b>Поместите жетон тайны на выбранный участок местности.</p>"},"repeatable":false,"marks":[{"label":"","image":"<schism>"}]},{"id":"outcomes-323","code":"323","description":{"en":"<p>The behemoth watches you approach with an impassive visage...</p>\\n\\"Embark on the venture below (see Ventures on Rulebook p.60).\\n\\n<bi>...and fear grips your heart. The creature towers over the tree line. How can you possibly fell such a thing?</bi>\\n<b>Behemoth, Champion:</b> Someone must contest <conviction> versus the behemoth's <dexterity> to lead the charge. Add +2 if you are <i>indomitable</i>.\\nWin (Equal or higher): You rally, and the others fall in behind you. The venture continues.\\nLose (Lower): Your will waivers. The venture fails unless a character spends <energy><energy> to attempt this test again.\\n\\n<bi>The behemoth lets out a bellow and slams a stony fist into the ground, sending chunks of earth flying toward you.</bi>\\n<b>Behemoth, Group, Hazard:</b> Everyone must contest <might> or <awareness> versus the behemoth's <awareness> to avoid harm. Each character adds +2 if they have a <i>clothing</i> item and +2 if they are <i>wary</i>.\\nWin (Equal or higher): You push through the pelting earth unharmed. If any character resolves this result, the venture continues.\\nLose (Lower): A stone catches you, and you are injured. Leave the venture unless you suffer <major_injury> and degrade all of your boosts. If all characters on the venture resolve this result, the venture fails.\\n\\n<bi>The behemoth's fist is still on the ground, giving you a chance to rush up it. An exact strike to the top of the head might lay it low, but who has such unerring precision?</bi>\\n<b>Behemoth, Champion:</b> Someone contest <might> or <dexterity> versus the behemoth's <might> to fight. Add +2 if you have a <i>weapon</i> item and +4 if you have a <i>trophy</i> item.\\nWin (Equal or higher): You bring down your weapon in exactly the right spot. Complete this venture and the associated goal.\\nLose (Lower): Your weapon deflects off the stony plate of the behemoth's head, and it swipes you off with a rocky hand as you might swat an insect. Suffer <major_injury><major_injury><minor_injury>. The venture fails unless a character spends <energy><energy> or <lore> to attempt this test again.\\n\\"","ru":"<p><i><b>Чудище бесстрастно наблюдало за вами…</b></i></p><p>Отправьтесь в поход (см. раздел «Походы» в правилах игры на с. 60).</p><p><i><b>…а ваше сердце пронизывал страх. Это существо возвышалось над деревьями — неужели его можно одолеть?</b></i></p><p><b>Чудище, защитник.</b> Один из персонажей в походе должен провести состязание, чтобы первым пойти в атаку: его <conviction> против <dexterity> чудища. +2, если этот персонаж <i>неукротимый</i>.<br><b>Успех. </b>Вы воспряли духом, и остальные последовали за вами. Продолжите поход.<br><b>Провал. </b>Ваша решимость испарилась. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy>, что бы провести проверку ещё раз.</p><p><b><i>Чудище издало рёв, обрушило каменный кулак на землю, и на вас полетели тяжёлые глыбы.</i></b></p><p><b>Чудище, группа, угроза. </b>Все персонажи в походе должны провести состязание, чтобы избежать урона: <might> или <awareness> против <awareness> чудища. +2, если у персонажа есть <i>одежда</i>, и +2, если он <i>осторожный</i>.<br><b>Успех. </b>Вы смогли увернуться от летящих глыб. Если хотя бы один персонаж получил этот результат, продолжите поход.<br><b>Провал. </b>Вас задело камнем. Покиньте поход либо получите <major_injury> и уменьшите все свои усиления. Если все персонажи покинули поход, он окончился неудачно.</p><p><i><b>Пока кулак чудища оставался на земле, вы успели взобраться по нему. Прицельный удар по макушке мог бы повалить исполина, но кто из вас похвастается такой безошибочной точностью?</b></i></p><p><b>Чудище, защитник. </b>Один из персонажей в походе должен провести состязание, чтобы сразиться: его <might> или <dexterity> против <might> чудища. +2, если у этого персонажа есть <i>оружие</i>, и +4, если у него есть <i>трофей</i>.<br><b>Успех. </b>Вы нанесли удар именно туда, куда было нужно. Завершите этот поход и достигните соответствующей цели.<br>Провал. Ваше оружие отскочило от каменной головы чудища, и существо небрежно сбросило вас лапой, будто отмахиваясь от насекомого. Получите <major_injury><major_injury><minor_injury>. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy> или <lore>, чтобы провести проверку ещё раз.</p>"},"repeatable":false},{"id":"outcomes-327","code":"327","description":{"en":"<p>Your population flourishes in the valley. While the large group offers certain protections, it also requires more resources to sustain.</p>\\n\\"Resolve the first you are able:\\n\\n<b>A) Your heavy harvesting affects the valley:</b> If 3 or more hexes have depletion tokens, add <activity><activity>.\\n\\n<b>B) Your people's actions across the valley stir up minor disturbances:</b> Add <activity>.\\"","ru":"<p><i><b>В долине ваша община росла и процветала. Однако растущее население хоть и давало некоторые преимущества, но при этом требовало больше ресурсов для своего существования.</b></i></p><p>Разыграйте первое, что можете:<br><b>А. Вы собирали много ресурсов, и это сказывалось на долине. </b>Если хотя бы на 3 участках местности есть жетоны истощения, добавьте <activity><activity>.<br><b>Б. Ваши действия слегка нарушали равновесие в долине. </b>Добавьте <activity>.</p>"},"repeatable":false},{"id":"outcomes-329","code":"329","description":{"en":"<p>Fear of rumored outsiders grows within your society, further agitating your populace. Without contact with this group, the tales of the risk they might pose grow ever-more dire...</p>\\n\\"Add <unrest><unrest><unrest>. Then, as a group, the players must choose one of the following paths for your society:\\n\\n<b>A) Set a taboo against straying from your outposts at night:</b> Add \\\\\\"Resting in hexes without <shelter> or an outpost\\\\\\" to the Taboos section of the Culture page of the Journal. Gain the Taboos (KN18) Knowledge card. Illustrate the saga of the fearful nights on the primal cave wall, including the <moon> mark and the taboo mark.\\n\\n<b>B) Put your people's nervous energy to work building defenses:</b> If you have designed the Palisade or Watchtower structure, add one of these structures to each of your outposts that does not have one (without spending <energy> or resources). If an outpost has the maximum number of structures, choose one of the current structures at random and destroy it to add the new structure.\\n\\n<b>C) Reassure your people that you are prepared:</b> If each of your outposts has a Palisade or Watchtower structure, subtract <unrest>.\\"","ru":"<p><i><b>В общине рос страх перед чужаками, о которых ходили тревожные слухи. Если не связаться с теми людьми, рассказы о возможной угрозе могут стать ещё более мрачными…</b></i></p><p>Добавьте <unrest><unrest><unrest>. Затем совместно выберите один из следующих путей развития общины:<br><b>А. Запретите выходить за пределы поселений ночью.</b> Запишите «Отдыхать на участках без убежища или поселения» в раздел «Табу» на странице «Культура» в журнале. Получите карту знаний «Табу» (ЗБ18), если у вас её нет. На стене первобытной пещеры изобразите историю о пугающих ночах, включив в неё отметку <moon> и отметку табу.<br><b>Б. Направьте энергию своих людей на строительство защитных сооружений.</b> Если вы спроектировали частокол (СР11) или сторожевую башню (СР19), добавьте любое из этих сооружений в каждое из своих поселений, где нет таких сооружений (не тратя <energy> и ресурсы). Если в поселении уже построено максимальное количество сооружений, разрушьте случайное из них, чтобы построить новое.<br><b>В. Успокойте людей, заверив, что вы хорошо подготовлены. </b>Если в каждом из ваших поселений есть частокол или сторожевая башня, уберите <unrest>.</p>"},"repeatable":false,"marks":[{"label":"","image":"<taboo>"}]},{"id":"outcomes-331","code":"331","description":{"en":"<p>As the last of the sun slips through some vast, unseen gullet, your people turn to you for guidance in their moment of dread...</p>\\n\\"Choose one and resolve it:\\n\\n<b>A) Enshrine this event in story:</b> Spend <lore><lore><lore> to illustrate the saga of the sun's return on the primal cave wall, including the <moon> mark and the <sun> mark.\\n\\n<b>B) Encourage others to take shelter:</b> Subtract <unrest><unrest>.\\"","ru":"<p><i><b>Когда последние лучи солнца словно исчезли в огромной невидимой пасти, ваш народ в ужасе обратился к вам…</b></i></p><p>Выберите и разыграйте одно:<br><b>А. Увековечьте это событие в истории. </b>Потратьте <lore><lore><lore>. Затем на стене первобытной пещеры изобразите историю о возвращении солнца, включив в неё отметку <moon> и отметку <sun>. <br><b>Б. Призовите людей укрыться. </b>Уберите <unrest><unrest>.</p>"},"repeatable":false},{"id":"outcomes-332","code":"332","description":{"en":"<p>Your failure to address the grievances of your people turns a crisis into a catastrophe. A quarrel spills into a brawl, and suddenly, blood is shed. A group of belligerents wreak havoc across your outposts and are driven out, fleeing into the wilds.</p>\\n\\"End this challenge. \\n\\nSubtract <population><population><population><population>. For each of your outposts, two randomly selected structures are destroyed. If an outpost is reduced to 0 structures this way, it becomes a ruin. \\n\\nIllustrate the saga of the bloody schism on the primal cave wall, including the battle mark (i) and the schism mark (ii).\\"","ru":"<p><i><b>То, что вы игнорировали жалобы своего народа, превратило проблему в настоящую катастрофу. Небольшая ссора переросла в драку, и вскоре пролилась кровь. Зачинщиков вы изгнали, но они успели причинить вред.</b></i></p><p>Завершите текущее испытание.</p><p>Уберите <population><population><population><population>. Разрушьте 2 случайных сооружения в каждом поселении. Если после этого в поселении не осталось ни одного сооружения, оно становится руинами. </p><p>На стене первобытной пещеры изобразите историю о кровавом расколе, включив в неё отметку битвы [i] и отметку раскола [ii].</p>"},"repeatable":false,"marks":[{"label":"i","image":"<battle>"},{"label":"ii","image":"<schism>"}]},{"id":"outcomes-333","code":"333","description":{"en":"<p>Unable to establish a foothold in the valley, too many of your people are lost to time amidst the rising snows. To survive, your people will need to take drastic action.</p>\\n\\"Resolve the first you are able: \\n\\n<b>A): Flee the valley:</b> If you are playing a campaign, remove all of your looming challenges, then add Exodus (CZ09) to your looming challenges.\\n\\n<b>B): Leave the valley to search for more people, returning in the distant future:</b> If you are playing Endless Mode, search the Event deck for Legends Lost (EM10) and set it aside. Shuffle the event deck, then place Legends Lost on top. Then add 12<population>. Remove all ruins, then all outposts become ruins.\\"","ru":"<p><i><b>Не сумев обосноваться в долине, слишком много людей потерялось из‑за обильных снегопадов. Чтобы выжить, вашему народу предстояло пойти на отчаянные меры.</b></i></p><p>Разыграйте первое, что можете:<br><b>А. Покиньте долину. </b>Если вы проходите кампанию, уберите все грядущие испытания, затем добавьте карту «Исход» (ИЯ09) к грядущим испытаниям.<br><b>Б. Отправьтесь на поиски людей, зная, что вернётесь нескоро. </b>Если вы играете в бесконечном режиме, найдите в колоде событий карту «Утраченные легенды» (БР10) и отложите её. Перемешайте колоду событий и положите карту «Утраченные легенды» на верх колоды событий. Добавьте 12 <population>. Уберите все руины, затем все поселения становятся руинами.</p>"},"repeatable":false},{"id":"outcomes-339","code":"339","description":{"en":"<p>A great cacophony of breaking earth erupts, then silence creeps across the valley as dust clouds swarm the sky. The point of origin of the catastrophe seems to be the pass by which you entered the valley.</p>\\n\\"If the mystery mark is on the primal cave wall, add <lore><lore><lore>. Then the behemoth's cataclysmic arrival alters the valley. Resolve the steps below: \\n\\n<b>Step 1:</b> The behemoth's entry into the valley shatters the passage by which you entered. Flip the starting hex. Place any overlays in this hex on their inactive side (e.g. an outpost in this hex becomes a ruin).\\n\\n<b>Step 2:</b> From the swirling dust, a behemoth strides forth. Choose a behemoth. You must choose a behemoth that does not have its lair overlay in the valley, if able, and that does not have its mark on the primal cave wall, if able. That behemoth arrives, as described in Behemoth Arrival on Rulebook p.74.\\n\\n<b>Step 3:</b> The behemoth occupies a lair. Place that behemoth's lair in the the starting hex. Roll 1d6 and place it in the corresponding zone: (1–3) A, (4–6) C. If it would be placed on top of another overlay (e.g. a ruin), remove that overlay from the valley. If that behemoth has an inactive lair in the valley, flip it to its active side instead.\\n\\n<b>Step 4:</b> The great thunderous crash breaks new paths in the valley, opening the way to reach deeper vales. If your valley has 2 or fewer trays, expand your valley by following the steps below.\\n\\n<b>Step 1:</b> Add a new tray to your valley. Place it adjacent to a hex of your choice with at least 2 open edges. The tray must be placed such that its edges are adjacent to as many edges of placed trays as posslble. If multiple valid positions exist, place it in a northernmost position.\\n\\n<b>Step 2:</b> Place all of your starting region's unplaced hexes into the draw bag. Shuffle the hexes in the draw bag. Then, one at a time, draw three of those hexes and place them unexplored in the slots of the tray you just placed, filling empty slots from north to south and east to west.\\n\\n<b>Step 3:</b> If there are 1 or more unplaced glacier overlays, roll <1d6> and place glaciers as foillows:\\n1–2: 1 glacier in Zone \\\\\\"A\\\\\\" of one of the hexes without an overlay.\\n[diagram]\\n3–4: 1 glacier in Zone \\\\\\"B\\\\\\" of one of the hexes without an overlay.\\n[diagram]\\n5: Resolve both 1–2 and 3–4.\\n[diagram]\\n6: Roll <1d6> again and read the corresponding outcome instead.\\n1–3: <outcome> 846\\n4–6: <outcome> 134\\"","ru":"<p><i><b>Вся долина наполнилась раскатами грохота, в небо поднялись облака пыли, а затем наступила тишина. Видимо, источник разрушения находился там, откуда вы пришли в долину.</b></i></p><p>Если на стене первобытной пещеры есть отметка тайны, добавьте <lore><lore><lore>. Затем катастрофическое появление чудища изменяет долину. Пройдите описанные ниже этапы.</p><p><b>Этап 1. Чудище разрушило проход, через который вы вошли в долину. </b>Переверните начальный участок местности. Также переверните все накладки на этом участке неактивной стороной вверх (например, если на этом участке было поселение, оно становится руинами).<br><b>Этап 2. Из облака пыли появилось гигантское существо. </b>Если у одного или нескольких чудищ ещё нет логова в долине, выберите любое из этих чудищ (если возможно, выберите то чудище, отметка которого есть на стене первобытной пещеры). Это чудище появляется в долине (см. раздел «Появление чудища» в правилах игры на с. 74).<br><b>Этап 3. Чудище заняло логово. </b>Поместите активное логово этого чудища на начальный участок местности. Бросьте <1d6>, чтобы поместить логово в соответствующий район: [1-3] А, [4-6] В. Если в этом районе есть другая накладка (например, руины), замените её логовом. Если у этого чудища уже есть неактивное логово, переверните его активной стороной вверх.<br><b>Этап 4. Оглушительный удар разрушил старые пути, зато открыл новые, ведущие вглубь долины. </b>Если в долине не более 2 основ местности, пройдите следующие шаги по порядку, чтобы расширить долину.<br><b>Шаг 1.</b> Добавьте новую основу местности в долину. Поместите её по соседству с любым участком местности с хотя бы 2 открытыми границами. Границы основы должны соседствовать с как можно большим количеством границ уже размещённых основ. Если есть несколько возможных позиций, выберите одну случайным образом.<br><b>Шаг 2. </b>Положите в мешочек все неразмещённые участки начального региона и перемешайте их. Затем по одному вытащите 3 участка и поместите их неисследованной стороной вверх в ячейки новой основы по направлению с севера на юг и с востока на запад. <br><b>Шаг 3 (только для эры 1 и бесконечного режима). </b>Если в запасе есть хотя бы 1 непомещённая накладка ледника, бросьте <1d6> и поместите ледники по результату броска: [1-2] один ледник в район А одного из участков местности без накладки, [3-4] один ледник в район Б одного из участков местности без накладки, [5] разыграйте результаты 1-2 и 3-4, [6] бросьте <1d6> ещё раз и прочитайте один из исходов ниже, соответствующий результату броска.<br>[1-3] <outcome> 846, [4-5] <outcome> 134, [6] <outcome> 446.</p>"},"repeatable":false},{"id":"outcomes-342","code":"342","description":{"en":"<p>Your culinary experiments open your eyes to interesting new resources in your environment that might spice or augment your meals...</p>\\n\\"Resolve as many of the following as you are able:\\n\\n<b>A) You have noticed that birds and insects often make nests in the trees of the forests:</b> Add EF01-03 to the Forest Foraging deck.\\n\\n<b>B) Trees may be more sparse than in the forests, but birds and insects still find places to nest:</b> Add EP01-03 to the Prairie Foraging deck.\\n\\n<b>C) Within the Tangle, many winged creatures flourish and make their nests:</b> If you are playing with the <i>Nature of the Beast</i> expansion, add EG01-03 to the Glade Foraging deck.\\"","ru":"<p><i><b>Благодаря кулинарным экспериментам вы обратили внимание на новые ингредиенты, которые могли бы придать вашим блюдам пикантности и обогатить их вкус. </b></i></p><p>Получите карту знаний «Готовка» (ЗЕ01). Разыграйте как можно больше из следующего:<br><b>А. Вы заметили, что птицы и насекомые часто вьют гнёзда на лесных деревьях. </b>Добавьте карты EЛ01–ЕЛ03 в колоду добычи припасов в лесу.<br><b>Б. Хотя деревья в степи встречались реже, чем в лесу, птицы и насекомые всё равно находили здесь места для гнёзд. </b>Добавьте карты EС01–ЕС03 в колоду добычи припасов в степи.<br><b>В. В Сплетении обитало множество крылатых существ, вьющих гнёзда. </b>Если вы используете дополнение «Природа зверя», добавьте карты EП01–ЕП03 в колоду добычи припасов на полянах.</p>"},"repeatable":false},{"id":"outcomes-347","code":"347","description":{"en":"<p>\\"You have journeyed into the hidden realm below the valley and returned to the land of sun's grace. Emboldened by your success, your people can now follow your example in adventuring into the depths below.\\"</p>\\n<p>\\"You can now delve into the valley's shadowy underworld.Gain the Delving (KN07) Knowledge card. See Delve on Rulebook p.82 for full rules. Illustrate the saga of the depths defied on the primal cave wall, including the underworld mark.\\"</p>","ru":"<p><i><b>Вы вернулись из тёмных глубин в залитые солнцем земли. Воодушевившись вашим успехом, община смогла последовать примеру и начать спускаться под землю.</b></i></p><p>Теперь община может исследовать подземный мир долины. Получите карту знаний «Спуск» (ЗБ07). Подробнее см. в разделе «Спуск» на с. 82 правил игры. На стене первобытной пещеры изобразите историю о преодолённых глубинах, включив в неё отметку подземного мира.</p>"},"repeatable":false,"marks":[{"label":"","image":"<underworld>"}]},{"id":"outcomes-348","code":"348","description":{"en":"<p>Your investigations into the coral leave you mostly puzzled. There must be some bigger picture, but it eludes your people for now.</p>\\n\\"Add <unrest><unrest><unrest><unrest>. Add The Sky Descends (CC04) to your looming challenges.\\n\\nThen, resolve as many of the following as possible:\\n\\n<b>A) The forests are twisted by the coral's presence:</b> If there are 1 or more Verdant Vale hexes in the valley, add CF01-CF04 to the Forest Foraging deck.:\\n\\n<b>B) The prairies teem with odd new life:</b> If there are 1 or more Skyreach Plateau hexes in the valley, add CP01-CP04 to the Prairie Foraging deck.:\\n\\n<b>C) The Tangle becomes even stranger than usual:</b> If there are 1 or more Tangle hexes in the valley, add CT01-CT04 to the Glade Foraging deck (if available).:\\n\\n<b>D) Ominous things stalk the night:</b> Add NR01-NR02 to the Night deck.:\\n\\n<b>E) The land itself is transformed:</b> Add JY04 to the Journey deck.:\\n\\nLiving coral appears as a bonus object on these new Foraging cards.\\"","ru":"<p><i><b>Исследования коралла привели вас в ещё большее замешательство. Должна была существовать какая‑то закономерность, но она пока ускользала от вас. </b></i></p><p>Завершите текущее испытание.</p><p>Добавьте <unrest><unrest><unrest><unrest>. Добавьте карту «Падение небес» (ИВ04) к грядущим испытаниям.<br>Затем разыграйте как можно больше из следующего:<br><b>А. Из-за кораллов преобразились леса. </b>Если в долине есть хотя бы 1 участок Дивной долины, добавьте карты КЛ01–КЛ04 в колоду добычи припасов в лесу.<br><b>Б. В степи закипела странная новая жизнь.</b> Если в долине есть хотя бы 1 участок Поднебесной равнины, добавьте карты КC01–КС04 в колоду добычи припасов в степи.<br><b>В. Сплетение стало ещё более таинственным, чем прежде. </b>Если в долине есть хотя бы один 1 участок Сплетения, добавьте карты КП01–КП04 в колоду добычи припасов на полянах, если возможно.<br><b>Г. Зловещие создания начали рыскать в ночи. </b>Добавьте карты НК01 и НК02 в колоду ночи.<br><b>Д. Сама земля изменилась. </b>Добавьте карту ПЕ04 в колоду пути.</p><p>На новых картах добычи припасов появляется новый бонусный ресурс — живой коралл.</p>"},"repeatable":false},{"id":"outcomes-349","code":"349","description":{"en":"<p>Searching the lair, you push past dried leaves and ancient vines to find a chamber filled with pearlescent blooms. You touch one of the flowers, and it opens, spilling forth a vision of into your mind. Is this something that once was, something that will be, or an event that might yet be averted?</p>\\n\\"Resolve the first you are able:\\n\\n<b>A) You see a vast unfurling that shadows the land:</b> If <comet> or <cloud> is a current omen, find Goal card GC02. The player who completed the final <i>champion</i> test may look at that card for no more than 1 minute, then returns it to the Goal deck and describes it to the other players for any amount of time. Then illustrate the saga of spreading change on the primal cave wall, including BH2's mark (i) and the prophecy mark (ii) enclosing the <comet> mark.\\n\\n<b>B) Water trickles down the back of your mind in the darkness as you seek salvation:</b> If <sun> is a current omen, find Goal card GZ09. The player who completed the final <i>champion</i> test may look at that card for no more than 1 minute, then returns it to the Goal deck and describes it to the other players for any amount of time. Then illustrate the saga of the miraculous cure on the primal cave wall, including BH2's mark (i), the harrowing mark (iii), and the prophecy mark (ii) enclosing the <sun> mark. \\n\\n<b>C) As the vision fades, the rush of adrenaline clings to your spine:</b> If <star> is a current omen, find Goal card GZ07. The player who completed the final <i>champion</i> test may look at that card for no more than 1 minute, then returns it to the Goal deck and describes it to the other players for any amount of time. Then illustrate the saga of blood yet unshed on the primal cave wall, including BH2's mark (i) and the prophecy mark (ii) enclosing the <star> mark. \\n\\n<b>D) Your body shakes until you awaken, your muscles clenched and your breath tight:</b> If <moon> is a current omen, find Goal card GZ17. The player who completed the final <i>champion</i> test may look at that card for no more than 1 minute, then returns it to the Goal deck and describes it to the other players for any amount of time. Then illustrate the saga of desperate alliance on the primal cave wall, including BH2's mark (i) and the prophecy mark (ii) enclosing the <moon> mark.\\n\\nAt the end of this challenge, end the current epoch. Refer to Codex p.196 to continue your campaign into Epoch 2.\\"","ru":"<p><i><b>В логове вы пробирались через высохшие листья и древние лианы, пока не нашли зал, поросший перламутровыми цветами. Когда вы прикоснулись к одному из них, бутон раскрылся и ваш разум наполнился видением. Что это было? Событие из прошлого? Предсказание будущего? Или пророчество, которое можно предотвратить?</b></i></p><p>Разыграйте первое, что можете:<br><b>А. Вам показалось, что цветок раскрылся настолько, что затмил всю землю. </b>Если <comet> или <cloud> — текущее знамение, найдите карту цели ЦВ02. Игрок, прошедший последнюю проверку защитника, может изучать эту карту не более 1 минуты, после чего должен вернуть её в колоду целей и описать её другим игрокам. Затем на стене первобытной пещеры изобразите историю о распространившихся изменениях, включив в неё отметку ЧД2 [i] и отметку <comet>, заключённую в отметку пророчества [iii].<br><b>Б. Где-то в глубине вашего разума струилась вода, пока вы искали спасения в темноте.</b> Если <sun> — текущее знамение, найдите карту цели ЦЯ09. Игрок, прошедший последнюю проверку защитника, может изучать эту карту не более 1 минуты, после чего должен вернуть её в колоду целей и описать её другим игрокам. Затем на стене первобытной пещеры изобразите историю о чудотворном исцелении, включив в неё отметку ЧД2 [i], отметку ужаса [ii] и отметку  <sun>, заключённую в отметку пророчества [iii].<br><b>В. Когда видение рассеялось, вы ощутили мощный прилив сил.</b> Если <star> — текущее знамение, найдите карту цели ЦЯ07. Игрок, прошедший последнюю проверку защитника, может изучать эту карту не более 1 минуты, после чего должен вернуть её в колоду целей и описать её другим игрокам. Затем на стене первобытной пещеры изобразите историю о ещё не пролитой крови, включив в неё отметку ЧД2 [i] и отметку <star>, заключённую в отметку пророчества [iii].<br><b>Г. Пока вы не очнулись, вас трясло от напряжения и было трудно дышать. </b>Если <moon> — текущее знамение, найдите карту цели ЦЯ17. Игрок, прошедший последнюю проверку защитника, может изучать эту карту не более 1 минуты, после чего должен вернуть её в колоду целей и описать её другим игрокам. Затем на стене первобытной пещеры изобразите историю об отчаянном союзе, включив в неё отметку ЧД2 [i] и отметку <moon>, заключённую в отметку пророчества [iii].</p><p>В конце текущего испытания завершите эру. См. с. 196, чтобы начать эру 2.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<bh2>"},{"label":"ii","image":"<harrowing>"},{"label":"iii","image":"<prophecy>"}]},{"id":"outcomes-353","code":"353","description":{"en":"<p>The open stretch of the cave beckons you to draw.</p>\\n\\"Choose one and resolve it:\\n\\n<b>A) Leave your mark on the empty space:</b> If there are 2 or fewer omen marks on the Delving card, add one omen marks to the open space on the card.\\n\\n<b>B) Study the marks for clues about challenges in the shadowy underworld:</b> If there are three or more omen marks on the Delving card already, resolve the effect corresponding to one of the omen marks on the wall, as follows:\\n\\n<cloud> – gain <major_boost> to <might>\\n<comet> – degrade 1 of your maladies twice\\n<star> – gain <major_boost> to <dexterity>\\n<moon> – gain <major_boost> to <awareness>\\n<sun> – gain <major_boost> to <conviction>\\n\\n<b>C) Learn about the valley's history from the marks:</b> If there are 1 or more omen marks on the Delving card already, add <lore> per mark on the card.\\"","ru":"<p><i><b>Открытый участок стены пещеры словно манил вас оставить на ней след.</b></i></p><p>Выберите и разыграйте одно:<br><b>А. Оставьте отметку на стене. </b>Если на этой карте спуска не более 2 отметок знамений, добавьте отметку текущего знамения на пустое пространство на карте. <br><b>Б. Изучите отметки в поисках подсказок о том, какие испытания ждут вас в тёмном подземном мире. </b>Если на этой карте спуска уже есть хотя бы 3 отметки знамений, разыграйте эффект, соответствующий одной из этих отметок, как указано ниже:<br><cloud> — получите <major_boost> к <might>.<br><star>— получите <major_boost> к <dexterity>.<br><moon>— получите <major_boost> к <awareness>.<br><sun>— получите <major_boost> к <conviction>.<br><comet>— уменьшите один из своих недугов дважды.<br><b>В. Узнайте больше об истории долины. </b> Если на этой карте спуска есть хотя бы 1 отметка знамения, добавьте <lore> за каждую отметку на этой карте.</p>"},"repeatable":false},{"id":"outcomes-358","code":"358","description":{"en":"<p>The engraved monuments you have made keep the past close at hand. Your people will take pride in these great works for generations to come.</p>\\nAt the end of any day, you may end this challenge. Then, subtract <unrest><unrest>. Illustrate the saga of the graven monuments on the primal cave wall, including the scribe mark. Gain the Legends (KN15) and Symbols (KN17) Knowledge cards if you do not already have them.","ru":"<p><i><b>Вы создавали высеченные из камня памятники, чтобы сохранить память о прошлом и чтобы ваш народ мог гордиться этими великими творениями ещё много поколений.</b></i></p><p>В конце любого дня можете завершить текущее испытание.</p><p>Затем уберите <unrest><unrest>. На стене первобытной пещеры изобразите историю о памятниках из камня, включив в неё отметку летописца. Получите карты знаний «Легенды» (ЗБ15) и «Символы» (ЗБ17), если у вас их ещё нет.</p>"},"repeatable":false,"marks":[{"label":"","image":"<scribe>"}]},{"id":"outcomes-363","code":"363","description":{"en":"<p>The ground twists beneath your feet as some massive limb shakes off an ancient slumber. You flee, and when you look back, the earth has returned to place, yet a crack remains...</p>\\n\\"Each character in your hex flees. Then, resolve the first you are able: \\n\\n<b>A) Disturbed by the breaking of the ground, a behemoth smashes forth from its ancient lair, newly invigorated and enraged:</b> If the current epoch is 2 or later and the broken earth mark is on the primal cave wall, flip the behemoth lair in the hex you fled to its active side. That behemoth arrives in the valley (see Behemoth Arrival on Rulebook p.74). Then, if there is another active lair in the valley, add Clash of Titans (CZ08) to your looming challenges. \\n\\n<b>B) The rumble subsides over time:</b> Place a mystery token in the hex you fled.\\"","ru":"<p><i><b>Земля словно завращалась у вас под ногами, когда бугор превратился в лапу существа, стряхнувшего с себя вековой сон. Вы обратились в бегство, а оглянувшись, увидели, что земля хоть и легла вновь на место, но разлом остался…</b></i></p><p>Каждый персонаж на вашем участке местности сбегает. Затем разыграйте первое, что можете:<br><b>А. Чудище вырвалось из своего древнего логова, вновь преисполненное ярости.</b> Если сейчас эра 2 или эра 3 и на стене первобытной пещеры есть отметка расколотой земли, переверните логово чудища на участке местности, с которого вы бежали (или на соседнем с ним), активной стороной вверх. Это чудище появляется в долине (см. раздел «Появление чудища» в правилах игры на с. 74). Затем, если в долине есть ещё одно активное логово, добавьте карту «Битва титанов» (ИЯ08) к грядущим испытаниям.<br><b>Б. Грохот постепенно утих.</b> Поместите жетон тайны на участок местности, с которого вы сбежали.</p>"},"repeatable":false,"marks":[{"label":"","image":"<brokenearth>"}]},{"id":"outcomes-372","code":"372","description":{"en":"<p>The omens have revealed to you that the behemoth is deeply interlinked with the life of the world. Its tread changes the land, and through the omens, you believe you can predict its desires.</p>\\n\\"At the end of any day, you may end this challenge.\\n\\nThen, as a group, the players must choose one of the following paths for your society:\\n\\n<b>A) Show reverence to the behemoth:</b> Subtract <unrest><unrest>. Placate the alert behemoth's demeanor by 3. Illustrate the saga of the sacred bond the primal cave wall, including the bond mark (i) enclosing the alert behemoth's mark. Add that behemoth's mark to the legend side of each Character card. Your society gains the Behemoth-Speaker (MA18) mantle power.\\n\\n<b>B) Explain that the behemoth is enraged when one among you breaks a taboo:</b> If the taboo mark is on the primal cave wall, subtract 6<unrest>. Illustrate the saga of ancient law on the primal cave wall, including the alert behemoth's mark and the bond mark (i) enclosing the taboo mark (ii).\\n\\n<b>C) Record the behemoth's movement for future generations:</b> If the scribe mark (iii) or songweaver mark (iv) is on the primal cave wall, add <population><population>. Placate the alert behemoth's demeanor by 1. Illustrate the saga of the wild's harbinger on the primal cave wall, including the alert behemoth's mark and the scribe mark (iii) or songweaver mark (iv) (choose one that is on the primal cave wall already). \\n\\nAt the end of this challenge, end the current epoch. Refer to Codex p.196 to continue your campaign into Epoch 2.\\"","ru":"<p><i><b>Знамения поведали вам, что чудище глубоко связано с жизнью этого мира. Его поступь меняет саму землю, и, если верить знамениям, вы можете предсказать его желания.</b></i></p><p>Завершите текущее испытание.</p><p>Затем совместно выберите один из следующих путей развития общины:<br><b>А. Проявите почтение к чудищу. </b>Уберите <unrest><unrest>. Успокойте бодрствующее чудище на 3. На стене первобытной пещеры изобразите историю о священной связи, включив в неё отметку бодрствующего чудища, заключённую в отметку связи [i]. Добавьте отметку этого чудища на сторону легенды карты каждого персонажа. Ваша община получает силу мантии «Говорящий с чудищами» (MA18).<br><b>Б. Объясните людям, что чудище приходит в ярость, когда кто-то нарушает запрет. </b>Если на стене первобытной пещеры есть отметка табу [ii], уберите 6 <unrest>. На стене первобытной пещеры изобразите историю о древнем законе, включив в неё отметку бодрствующего чудища и отметку табу, заключённую в отметку связи [i].<br><b>В. Увековечьте путь чудища для будущих поколений. </b>Если на стене первобытной пещеры есть отметка летописца [iii] или отметка песнопевца [iv], добавьте <population><population>. Успокойте бодрствующее чудище на 1. На стене первобытной пещеры изобразите историю о вестнике дикой природы, включив в неё отметку бодрствующего чудища и отметку летописца [iii] или отметку песнопевца [iv] (выберите ту, которая уже есть на стене).</p><p>Затем завершите текущую эру. См. с. 196, чтобы начать эру 2.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<bond>"},{"label":"ii","image":"<taboo>"},{"label":"iii","image":"<scribe>"},{"label":"iv","image":"<songweaver>"}]},{"id":"outcomes-378","code":"378","description":{"en":"<p>Your fields flourish, and you reap the rewards before winter sets in. In the coming seasons and years, your people thrive, and your population surges to new, greater heights.</p>\\n\\"At the end of any day, you may end this challenge.\\n\\nThen, add <population><population><population><population>. Illustrate the saga of the earth-breakers on the primal cave wall, including the broken earth mark (i), the cultivation mark (ii), and the plenty mark (iii). Your society gains the Work-Builder (MA16) mantle power. Add A Peaceful Season (CZ01) (even if already completed) and Citadel (CB10) to your looming challenges.\\"","ru":"<p><i><b>Ваши поля процветали, и вы собрали богатый урожай до наступления зимы. Годы спустя ваш народ продолжил развиваться, а община достигла небывалых размеров.</b></i></p><p>В конце любого дня можете завершить текущее испытание.</p><p>Затем добавьте <population><population><population><population>. На стене первобытной пещеры изобразите историю о меняющих землю, включив в неё отметку расколотой земли [i], отметку изобилия [ii] и отметку возделывания [iii]. Ваша община получает силу мантии «Строитель» (MA16). Добавьте карты «Период затишья» (ИЯ01), даже если вы уже завершили это испытание ранее, и «Цитадель» (ИБ10) к грядущим испытаниям.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<brokenearth>"},{"label":"ii","image":"<cultivation>"},{"label":"iii","image":"<plenty>"}]},{"id":"outcomes-382","code":"382","description":{"en":"<p>The coming of the comet has brought change to the valley, but your people have been able to adapt to the new perils and deprivations the shift in the valley brings. Still, anger at the change seethes within the populace...</p>\\n\\"Add <unrest><unrest><unrest>. Then, resolve the first you are able:\\n \\n<b>A) Your people accept your efforts, grudgingly:</b> If unrest is 12 or lower, add Scorn of the Earth (CC06) to your looming challenges. \\n\\n<b>B) Your people blame you for this disaster:</b> Add Scorn of Humanity (CC05) to your looming challenges.\\"","ru":"<p><i><b>Появление кометы изменило долину, но ваш народ сумел приспособиться к новым опасностям и лишениям. Однако гнев от этих перемен продолжал бурлить в сердцах людей… </b></i></p><p>Добавьте <unrest><unrest><unrest>. Затем разыграйте первое, что можете:<br><b>А. Ваши усилия приняли, но неохотно. </b>Если значение <unrest> равно 12 или меньше, добавьте к грядущим испытаниям карту «Презрение земли» (ИВ06).<br><b>Б. В этом бедствии обвинили вас. </b>Добавьте карту «Презрение человечества» (ИВ05) к грядущим испытаниям.</p>"},"repeatable":false},{"id":"outcomes-386","code":"386","description":{"en":"<p>\\"You venture into the dread depths of the behemoth's sepulcre...\\"</p>\\n\\"Embark on the venture below (see Ventures on Rulebook p.60).\\n\\n<bi>From the exterior, it is not obvious how you might enter the tomb. you'll have to find a way in.</bi>\\n<b>Champion, Wonder:</b> Someone must test <awareness> to find a path. Add +1 for each <i>exploration</i> item a member of the venture has, +2 if you are <i>attuned</i>, and +4 if one or more Secrets have been recorded in the Journal for this behemoth.\\n10+: You find a way within. The venture continues.\\n1–9: You are stymied by the apparent impenetrability of the lair. The venture fails unless a character spends <energy><energy> to attempt this test again.\\n\\n<bi>Slipping inside the crack, you are suddenly menaced by a growl. A nest of predators have taken up refuge here. You have a chance to drive them off before they strike!</bi>\\n<b>Champion, Hazard:</b> Someone must test <might> or <conviction> to drive off the beasts. Add +2 if you have an item with a <fire> token on it, +2 if you have a <i>weapon</i> item, and +2 if you are <i>vengeful</i>.\\n11+: With a ferocity eclipsing the beasts, you drive the predators off before they can mount an attack! The venture continues.\\n1–10: The predators strike. Each character must encounter a predator. If a character chooses to flee, they must leave the venture. Then, if all characters left the venture, the venture fails. Otherwise, the venture continues.\\n\\n<bi>The clinging darkness surrounds you, and approach a narrow strand over a vast pit. You must step carefully to avoid falling...</bi>\\n<b>Behemoth, Champion, Hazard:</b> Someone must test <dexterity> to cross the abyss. Add +2 if you have an item with a <fire> token on it. You may discard up to 3 of this behemoth's curio to add +2 per curio discarded.\\n14+: A sliver of light cuts through the darkness to reveal something... unexpected. Complete this venture and the associated goal.\\n1–13: The overwhelming darkness presses down upon you, and you retreat. The venture fails unless a character spends <energy><energy> or <lore> to attempt this test again.\\"","ru":"<p><i><b>Вы отправились в гробницу чудища, уходя всё глубже... </b></i></p><p>Отправьтесь в поход (см. раздел «Походы» в правилах игры на с. 60).</p><p><b><i>Снаружи не было видно, как попасть в древнее логово. Вам пришлось искать путь внутрь.</i></b></p><p><b>Защитник, чудо. </b>Один из персонажей в походе должен провести проверку <awareness>, чтобы отыскать проход. +1 за каждый предмет для <i>исследования </i>у любого участника похода, +2, если выбранный персонаж <i>сосредоточенный</i>, и +4, если в журнале записан хотя бы 1 секрет этого чудища.<br><b>≥10:</b>  Вы нашли путь внутрь логова. Продолжите поход.<br><b>1-9:</b>  Логово осталось неприступным. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy>, что бы провести проверку ещё раз.</p><p><i><b>Вы проскользнули в расщелину и вдруг услышали рычание. Здесь устроили логово хищники. У вас был шанс прогнать их до того, как они нападут.</b></i></p><p><b>Защитник, угроза. </b>Один из персонажей в походе должен провести проверку <might> или <conviction>, чтобы прогнать зверей. +2, если у него есть предмет с <fire>, +2, если у него есть <i>оружие</i>, и +2, если он <i>мстительный</i>.<br><b>≥11:</b>  Вы обрушились на хищников с яростью, превосходящей их собственную, и прогнали их. Продолжите поход.<br><b>1-10:</b>  Хищники напали на вас. Каждый персонаж в походе должен встретиться с хищником. Если персонаж решит сбежать, он покидает поход. Если все персонажи покинули поход, он окончился неудачно.</p><p><b><i>Окутанные тьмой, вы приблизились к узкому выступу над пропастью. Пришлось идти осторожно, чтобы не сорваться. </i></b></p><p><b>Чудище, защитник, угроза. </b>Один из персонажей в походе должен провести проверку <dexterity>, чтобы пройти через пропасть. +2, если у него есть предмет с <fire>, и +2 за каждое сброшенное им сокровище этого чудища (не более +6).<br><b>≥14:</b>  Сквозь тьму пробивался свет, открывающий взору нечто... неожиданное. Завершите этот поход и достигните соответствую щей цели.<br><b>1-13:</b>  Всепоглощающая тьма взяла верх, и вы отступили. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy> или <lore>, чтобы провести проверку ещё раз.</p>"},"repeatable":false},{"id":"outcomes-388","code":"388","description":{"en":"<p>Your people adopt a rare diet that hinges neither on vegetables nor meat for primary sustenance. You face a choice of whether to pursue this unusual repast or seek more available foodstores.</p>\\n\\"As a group, the players must choose one of the following paths for your society:\\n\\n<b>A) Make these unusual foodstuffs a core part of your diet:</b> If you had 1 or more honey among the tokens on the Goal card, design the Apiary (SM04) structure (without spending <lore>). If you had 1 or more eggs among the food tokens on the goal card, design the Coop (SM05) structure (without spending <lore>). \\n\\n<b>B) Specialize in seeking nourishment from plants:</b> If you had 1 or more vegetables among the tokens on this card, add <lore><lore><lore> and add Herbalism (GA04) to your goals.\\n\\n<b>C) Focus your energies on hunting:</b> If you had 1 or more meat among the tokens on this card, add <lore><lore><lore> and add The Hunter's Trial (GA05) to your goals.\\"","ru":"<p><i><b>Ваш народ перешёл на редкий рацион, основой которого стали не мясо и не овощи. Вам предстояло решить, следовать ли этой необычной диете дальше или искать более привычные источники пропитания.</b></i></p><p>Совместно выберите один из следующих путей развития общины:<br><b>А. Оставьте необычные продукты основой рациона. </b>Если на карте цели есть хотя бы 1 жетон мёда, спроектируйте улей (СЕ04), не тратя <lore>. Если на карте цели есть хотя бы 1 жетон яйца, спроектируйте курятник (СЕ05), не тратя <lore>.<br><b>Б. Сосредоточьтесь на растительных продуктах.</b> Если на карте цели есть хотя бы 1 жетон овощей, добавьте <lore><lore><lore>, затем добавьте карту «Освой те травничество» (ЦA04) к целям.<br><b>В. Сделайте охоту приоритетной. </b>Если на карте цели есть хотя бы 1 жетон мяса, добавьте <lore><lore><lore>, затем добавьте карту «Пройдите испытание охотника» (ЦA05) к целям.</p>"},"repeatable":false},{"id":"outcomes-391","code":"391","description":{"en":"<p>In the darkness, you see the shimmering eyes of a predator. The beast surges forth on chitinous claws, and you must defend yourself.</p>\\nEncounter a predator (see Wildlife Encounters on Rulebook p.48). If you choose to <i>fight</i>, add +2 if you have a Torch. If you choose to <i>retreat</i> and you resolve a result of 1–9, you lose all of your rewards.","ru":"<p><i><b>Во тьме вы заметили сверкающие глаза хищника. Существо бросилось вперёд — и вам пришлось защищаться.</b></i></p><p>Проведите встречу с хищником (см. раздел «Встреча с хищником» в правилах игры на с. 48). +2, если вы выбрали сражение и у вас есть «Факел». Если вы решили отступить, при результате [1-9] потеряйте все свои награды.</p>"},"repeatable":false},{"id":"outcomes-392","code":"392","description":{"en":"<p>\\"With patience and effort, you manage to soothe the behemoth's temper. With a great groan heard round the valley, it returns to its home. You wonder if your people have been chastened or emboldened by this closer brush with the behemoth's wrath.\\"</p>\\n<p>\\"Illustrate the saga of the soothing on the primal cave wall, including the alert behemoth's mark and the mark of the mediator. Add Vision of One (CB07) to your looming challenges.\\"</p>","ru":"<p><i><b>Приложив немалые усилия и проявив терпение, вам удалось усмирить гнев чудища. С протяжным стоном существо вернулось в своё логово. Стало ли это столкновение уроком для вашего народа или, наоборот, придало людям смелости?</b></i></p><p>Завершите текущее испытание.</p><p>На стене первобытной пещеры изобразите историю об усмирении, включив в неё отметку бодрствующего чудища и отметку посредника. Добавьте карту «Единое видение» (ИБ07) к грядущим испытаниям.</p>"},"repeatable":false,"marks":[{"label":"","image":"<mediator>"}]},{"id":"outcomes-393","code":"393","description":{"en":"<p>\\"The echoes of the extinct behemoth ripple across the ages. Its footfalls thunder only in the stories of your people, and children frolic in the shadows of the vast mound. But tales of the behemoth's dread grows year by year, and your people grow afraid that it may return...\\"</p>\\n\\"Add <unrest><unrest>. Then, as a group, the players must choose one of the following paths for your society:\\n\\n<b>A) Forbid your people from against straying near the forbidding tomb:</b> If there is an inactive lair in the valley, add \\\\\\"Resting in a hex with an inactive behemoth's lair\\\\\\" to the Taboos section of the Culture page of the Journal. Gain the Taboos (KN18) Knowledge card. Add <unrest><unrest>. Illustrate the saga of the dread grave on the primal cave wall, including the mark of a behemoth with an inactive lair in the valley and the taboo mark.\\n\\n<b>B) Send someone to face the lair alone:</b> If there is an inactive lair in the valley, choose an inactive behemoth's lair in the valley and a character to test <conviction>. On a result of 10+, subtract <unrest><unrest><unrest> and add that behemoth's mark to the Legend side of that character card. On any other result, that character's Legend is forgotten at the start of the next epoch (see Forgotten Legends on Rulebook p.72).\\n\\n<b>C) What were those rumors about, anyway? Seems like superstitions:</b> If there are no inactive lairs in the valley, no effect.\\"","ru":"<p><i><b>Эхо вымершего чудища звучало сквозь века. Его поступь гремела лишь в преданиях вашего народа, а в тени огромного кургана резвились дети. Но с каждым годом рассказы о страхе перед чудищем становились всё мрачнее, и ваш народ начинал опасаться, что оно может вернуться…</b></i></p><p>Добавьте <unrest><unrest>. Затем совместно выберите один из следующих путей развития общины:<br><b>А. Запретите приближаться к зловещей гробнице. </b>Если в долине есть неактивное логово, запишите «Отдыхать на участке местности с неактивным логовом чудища» в раздел «Табу» на странице «Культура» в журнале. Получите карту знаний «Табу» (ЗБ18), если у вас её нет. Добавьте <unrest><unrest>. На стене первобытной пещеры изобразите историю об устрашающей могиле, включив в неё отметку чудища с неактивным логовом и отметку табу.<br><b>Б. Отправьте смельчака в логово. </b>Если в долине есть неактивное логово, выберите любое из них. Один из персонажей должен провести проверку <conviction>. При результате [≥10] уберите <unrest><unrest><unrest> и добавьте отметку этого чудища на сторону легенды карты выбранного персонажа. При любом другом результате легенда этого персонажа будет забыта в начале следующей эры (см. раздел «Забытые легенды» в правилах игры на с. 72).<br><b>В. А стоило ли вообще обращать внимание на эти слухи? Они больше походили на суеверия.</b> Если в долине нет неактивного логова, без эффекта.</p>"},"repeatable":false,"marks":[{"label":"","image":"<taboo>"}]},{"id":"outcomes-394","code":"394","description":{"en":"<p>You are unable to extract the seed from the Tangle. The doom of the great jungle is assured, and without a successor, the land around it withers. In generations, the valley grows desolate and dry. Your people will have to leave the vale of their ancestors to survive.</p>\\n<p>\\"End this challenge.\\n\\nIllustrate the saga of the doomed garden on the primal cave wall, including the harrowing mark (i), the misfortune mark (ii), and the Tangle mark (iii). Add Exodus (CZ09) to your looming challenges.\\"</p>","ru":"<p><i><b>Вам не удалось выкопать семя Сплетения. Судьба великого леса была предрешена, и земля вокруг него начала чахнуть. Спустя года долина стала пустынной и засушливой. Чтобы выжить, вашему народу пришлось покинуть земли предков.</b></i></p><p>Завершите текущее испытание.</p><p>На стене первобытной пещеры изобразите историю о погибшем саде, включив в неё отметку ужаса [i], отметку несчастья [ii] и отметку Сплетения [iii]. Добавьте карту «Исход» (ИЯ09) к грядущим испытаниям.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<harrowing>"},{"label":"ii","image":"<misfortune>"},{"label":"iii","image":"<tangle>"}]},{"id":"outcomes-398","code":"398","description":{"en":"<p>Through the skin of a worm, you feel the moist earth. You slide through rootways, pursuing the sour taste of rot. Death has touched the vast world of green above you, and the time to feast is coming. You shudder awake, terrified and confused.</p>\\n\\"Resolve the first you are able:\\n\\n<b>A) Your dream makes no sense. Unless... no, that couldn't be:</b> If the doom mark is on the primal cave wall, degrade all your boosts and add <lore> for each boost you degrade this way.\\n\\n<b>B) You are certain that this is no dream, but a doom set upon your people's home:</b> lllustrate the saga of the gnawed roots on the primal cave wall, including the doom mark (i) enclosing the broken earth mark (ii).\\n\\nThen return Roots of the World (NT03) to the game box.\\n\\"","ru":"<p><i><b>Сквозь кожу червя вы ощущали влажную землю. Вы скользили, прогрызая корни и двигаясь за кисловатым привкусом гнили. Смерть коснулась необъятного зелёного мира над вами, и время пира приближалось… Вы пробудились в ужасе и смятении.</b></i></p><p>Разыграйте первое, что можете:<br><b>А. В вашем сне не было никакого смысла. Хотя… нет, не может этого быть! </b>Если на стене первобытной пещеры есть отметка погибели, уменьшите все свои усиления и получите <lore> за каждое такое уменьшение. <br><b>Б. Вы были уверены, что это не сон, а предвестие рока, обрушившегося на родные земли. </b>На стене первобытной пещеры изобразите историю о подточенных корнях, включив в неё отметку расколотой земли, заключённую в отметку погибели. Затем верните в коробку карту «Корни мироздания» (НС03).</p>"},"repeatable":false,"marks":[{"label":"i","image":"<doom>"},{"label":"ii","image":"<brokenearth>"}]},{"id":"outcomes-400","code":"400","description":{"en":"<p>Banished from their homes and crushed under the terrible weight of isolation, these characters fade into legend...</p>\\n<p>\\"End this challenge. \\n\\nAll of your characters perish and become Legends. Illustrate the saga of the heroes reviled on the primal cave wall, including the coral mark (i) and the misfortune mark (ii). Add Scorn of the Earth (CC06) to your looming challenges.\\"</p>","ru":"<p><i><b>Вдали от своих домов, сломленные ужасным бременем изгнания, ваши люди затерялись в легендах…</b></i></p><p>Завершите текущее испытание.</p><p>Все персонажи становятся легендами. На стене первобытной пещеры изобразите историю о презираемых героях, включив в неё отметку коралла [i] и отметку несчастья [ii]. Добавьте к грядущим испытаниям карту «Презрение земли» (ИВ06).</p>"},"repeatable":false,"marks":[{"label":"i","image":"<coral>"},{"label":"ii","image":"<misfortune>"}]},{"id":"outcomes-402","code":"402","description":{"en":"<p>Your experiences have taught you that the midden is worth exploring, and that it is not fresh enough for its owner to be nearby. Carefully picking through it, you find several interesting items that the creature buried. Its diet is obviously varied.</p>\\n<p>\\"You must choose one of the following: \\n\\nA) Feathers suggest avian prey. Gain 2 feathers.\\n\\nB) A tangled knot of skin was left behind by some prey-beast it ate. Gain 1 hide.\\n\\nC) You just hope the cracked and drained bones don't belong to anyone you knew. Gain 1 bone.\\"</p>","ru":"<p><i><b>Вы знали, что такие залежи мусора стоит исследовать, тем более что они явно несвежие, а значит, владельца не было поблизости. Перебрав содержимое логова, вы нашли кое‑что полезное. Было видно, что существо питалось разнообразно.</b></i></p><p>Выберите одно:<br><b>А. Хищник, похоже, предпочитал охотиться на птиц. </b>Получите 2 пера.<br><b>Б. От съеденного зверя остался только кусок кожи. </b>Получите 1 шкуру.<br><b>В. Вам оставалось лишь надеяться, что обглоданные кости не принадлежали кому-то, кого вы знали. </b>Получите 1 кость.</p>"},"repeatable":false},{"id":"outcomes-403","code":"403","description":{"en":"<p>\\"The behemoth's roots spread deep into the valley. Then, suddenly, new shoots emerge where it has passed, twisting into brambles that remain in its wake. These twisted forests are dangerous, but provide ample sustenance for game and predators alike.\\"</p>\\n<p>\\"Remove all twisted wake overlays from the valley, then place an active twisted wake overlay in each hex with a trace marker. Choose whether it is placed in zone A, B, or C, placing it in a zone without an overlay and with a lake, wetland, or river, if able. See Codex p.212 for the twisted wake rules.\\n\\nThen remove this behemoth's aim and all of its trace tokens. Assign it the Return to Slumber (BT20) instinct (replacing its previous instinct).\\"</p>","ru":"<p><i><b>Корни этого чудища простирались вглубь долины. В какой‑то момент на месте его следов начали появляться новые побеги. Они извивались, переплетались и превращались в колючие заросли. Эти места были опасны, но там было много пищи как для дичи, так и для хищников.</b></i></p><p>Уберите все накладки скрученных отпечатков из долины, затем поместите накладку скрученного отпечатка активной стороной вверх на каждый участок местности с жетоном следов. Каждый раз выбирайте район с озером, болотом или рекой и без накладки, если возможно. Подробнее о скрученном отпечатке см. на с. 212.</p><p>Затем уберите жетон направления и все жетоны следов этого чудища. Замените его текущий инстинкт на «Вернуться в забытьё» (ЧК20).</p>"},"repeatable":false},{"id":"outcomes-406","code":"406","description":{"en":"<p>You imagine a person and describe them with such vividness and grace that the others around the fire feel as if they know them. From your mind to your listeners ears to the annals of legend, this figure wends their way to eternity.</p>\\n<p>\\"Using the character creation process on Rulebook p.6, create a new character card that will be added to your society's Legends immediately. You may choose whether they are Young or Old. After creating the character, choose one of the following and resolve it:\\n\\nA) Imbue the character with your own strengths or weaknesses to make them feel more real: Change one of the character's attributes to one of your attribute values\\n\\nB) Attribute a deed that mirrors your own to this fictional figure: Add one of your marks to the Legend side of the character's card.\\n\\nC) Apply a bit of your own personality into to the mythic figure: Add one of your traits to the character.\\n\\nThen, check the Legend box of the new Character card. Add them to your society's Legends.\\"</p>","ru":"<p><i><b>Вы вообразили человека и так живо описали его, что остальные у костра почувствовали, будто знают его лично. Со временем этот образ, созданный вашим разумом, стал легендой на века.</b></i></p><p>Следуя указаниям на с. 6 правил игры, создайте новую карту персонажа, которую после добавите в легенды общины. Вы можете выбрать, будет он молодым или пожилым. Затем выберите и разыграйте одно:<br><b>А. Наделите легендарного персонажа собственными сильными или слабыми сторонами, чтобы он сильнее казался настоящим. </b>Замените значение одной из характеристик нового персонажа на значение такой же своей характеристики.<br><b>Б. Припишите вымышленному образу поступок, отражающий вас.</b> Добавьте одну из своих отметок на сторону легенды карты нового персонажа.<br><b>В. Привнесите частичку своей личности в выдуманного персонажа. </b>Добавьте персонажу одну из своих черт.</p><p>Затем отметьте клетку рядом со словом «легенда» на карте нового персонажа и добавьте эту карту в легенды общины.</p>"},"repeatable":false},{"id":"outcomes-407","code":"407","description":{"en":"<p>\\"By undertaking your survey of the diseased region, you have found that the Tangle's sickness run down to the roots, which burst with strange nodules. You cut back the nodules as best you can across the Tangle's span, and the plague seems to loosen its grip. Howver, there may come a day when the blight returns, and a journey to through the rootways to find the affliction becomes necessary. For now, however, there is little you can do but wait to see if the Tangle recovers on its own.\\"</p>\\nAt the end of any day, you may end this challenge. Then, subtract <unrest><unrest><unrest>. Illustrate the saga of the rot repelled on the primal cave wall, including the Tangle mark (i) and the doom mark enclosing the broken earth mark (ii).","ru":"<p><b><i>Вы изучили поражённый регион и обнаружили, что болезнь Сплетения проникала глубоко в корни, делая их узловатыми. Вы срезали столько этих странных наростов, сколько смогли, и хватка заразы, казалось, ослабла. Однако может настать день, когда гниль вернётся, и тогда придётся отправиться вглубь, чтобы найти источник заразы. Пока же вам оставалось лишь ждать и надеяться, что Сплетение восстановится.</i></b></p><p>В конце любого дня можете завершить текущее испытание.</p><p>Затем уберите <unrest><unrest><unrest>. На стене первобытной пещеры изобразите историю о побеждённой гнили, включив в неё отметку Сплетения [i] и отметку расколотой земли, заключённую в отметку погибели [ii].</p>"},"repeatable":false,"marks":[{"label":"i","image":"<tangle>"},{"label":"ii","image":"<doom>EncBrokenEarth"}]},{"id":"outcomes-409","code":"409","description":{"en":"<p>\\"Even as it towers over you, you can see the behemoth recoils from the light. Where it touches, pockets of the behemoth's stony skin begin to melt like ice. Over several agonizing minutes, the moving forest recedes into the distance, leaving behind great pools of liquifying flesh in its wake. Within the liquid, you find a stone.\\"</p>\\n<p>\\"End the encounter. Aggravate the behemoth's demeanor by 1. The behemoth flees.\\n\\nThen, if a character, animal companion, or storage structure has an item with Sundered in its name, gain 2 of the behemoth's curio; otherwise, gain the Sundered Stone (IT88) Item card.\\"</p>","ru":"<p><i><b>Чудище отпрянуло от света, касание которого заставляло кожу чудища таять, словно лёд. В агонии существо отступало всё дальше, оставляя за собой огромные лужи из жидкой плоти. В одной из этих луж вы нашли необычный камень. </b></i></p><p>Завершите встречу. Разозлите чудище на 1. Чудище сбегает. Затем, если у персонажа, животного-компаньона или в <i>сооружении-хранилище</i> есть предмет со словом «расколотый» в названии, получите 2 сокровища этого чудища; в противном случае получите карту предмета «Расколотый камень» (ВЩ88).</p>"},"repeatable":false},{"id":"outcomes-410","code":"410","description":{"en":"<p>The behemoth returns to its great blazing tree to slumber. As it steps into the hollow chasm in the wood, the light of the tree vanishes and becomes extinct.</p>\\n\\"End this challenge.\\n\\nIllustrate the saga of the sleeping fire on the primal cave wall, including BH4's mark and the <star> mark. Flip BH4's lair to its inactive side. Set each other behemoth to dormant at the start of the next challenge. Add Ashfall (CY05) to your looming challenges.\\"","ru":"<p><i><b>Чудище вернулось к своему громадному сверкающему дереву. Когда оно ступило в полую расщелину в древесине, свет угас.</b></i></p><p>Завершите текущее испытание. На стене первобытной пещеры изобразите историю о спящем огне, включив в неё отметку ЧД4 и отметку <star>. Переверните логово ЧД4 неактивной стороной вверх. В начале следующего испытания каждое другое чудище становится спящим. Добавьте карту «Пеплопад» (ИЕ05) к грядущим испытаниям.</p>"},"repeatable":false,"marks":[{"label":"","image":"<bh4>"}]},{"id":"outcomes-411","code":"411","description":{"en":"<p>Studying a place where the behemoth cut an icy furrow into the earth, you find a set of items. Strangely, they were clearly worked by human hands.</p>\\n\\"Choose one of the following and resolve it:\\n\\n<b>A) Interpret the meaning of the object:</b> If the behemoth has an unrevealed Secret card assigned to it, reveal this behemoth's currently assigned Secret card, then record it under the Secrets for that behemoth in the Journal.\\n\\n<b>B) Pick something from the pile of relics:</b> Gain the Scavenging (KN12) Knowledge card. Then, you may perform a scavenge action (without spending <energy> as normal>). If you have the relic mark, you may add 1 moonblood or silk to the draw bag while scavenging.\\"","ru":"<p><i><b>Изучая место, где чудище оставило ледяную борозду в земле, вы нашли предметы, явно созданные человеком.</b></i></p><p>Выберите и разыграйте одно:<br><b>А. Истолкуйте значение предмета. </b>Если у чудища есть назначенная неоткрытая карта секрета, откройте её. Затем запишите её в раздел секретов этого чудища в журнале.<br>Б. Заберите одну из реликвий. Получите карту знаний «Раскопки» (ЗБ12). Затем можете выполнить действие раскопок, не тратя <energy>. Если у вас есть отметка реликвии, можете также добавить 1 лунную кровь или 1 шёлк в мешочек для раскопок.</p>"},"repeatable":false,"marks":[{"label":"","image":"<relic>"}]},{"id":"outcomes-414","code":"414","description":{"en":"<p>The sickness spreads uncontrollably, sweeping through your outposts without mercy.</p>\\n\\"For each hex with an outbreak, roll <1d6>. Add +2 if there is a Waste Pit in this outpost\\n1–3: Subtract <population><population>, then each character in this hex suffers <major_disease>..\\n4–5: Subtract <population>. Each character in this hex suffers <major_disease>.\\n6: Each character in this hex suffers <minor_disease>.\\n7+: No effect.\\"","ru":"<p><i><b>Болезнь распространилась, без пощады накрыв ваши поселения.</b></i></p><p>Для каждого участка местности со вспышкой болезни бросьте <1d6>. +2, если в этом поселении есть мусорная яма.<br><b>1-3:</b>  Уберите <population><population>. Каждый персонаж на этом участке местности получает <major_disease>. <br><b>4-5:</b>  Уберите <population>. Каждый персонаж на этом участке местности получает <major_disease>.<br><b>6:</b>  Каждый персонаж на этом участке местности получает <minor_disease>.<br><b>≥7:</b>  Без эффекта.</p>"},"repeatable":false},{"id":"outcomes-415","code":"415","description":{"en":"<p>The behemoth regards the offering with great interest, bowing its head low to observe.</p>\\n\\"Choose one and resolve it:\\n\\n<b>A) Offer a fine work:</b> If you have a processed material or an item in your inventory, discard a processed material or an item to end the encounter. Placate the behemoth's demeanor by 1. Then, if a character, animal companion, or storage structure has an item with Iridescent in its name, gain 2 of the behemoth's curio; otherwise, gain the Iridescent Skin (IT89) Item card.\\n\\n<b>B) Fish around in you pocket for something to offer:</b> If you have at least 1 material in your inventory, discard 1 material to gain 1 fiber. Then end the encounter.\\n\\n<b>C) Offer nothing:</b> End the encounter. Aggravate the behemoth's demeanor by 2.\\"","ru":"<p><i><b>Чудище с большим интересом ожидало подношения, низко склонив голову.</b></i></p><p>Выберите и разыграйте одно:<br><b>А. Предложите чудищу изящное изделие.</b> Если у вас есть обработанный материал или предмет в инвентаре, сбросьте 1 любой обработанный материал или предмет. Завершите встречу. Успокойте чудище на 1. Затем, если у любого персонажа, животного-компаньона или в сооружении-хранилище есть предмет со словом «радужный» в названии, получите 2 сокровища чудища; в противном случае получите карту предмета «Радужная кожа» (ВЩ89).<br><b>Б. Поройтесь в кармане в поисках чего-нибудь для подношения. </b>Если у вас есть материал в инвентаре, сбросьте 1 любой материал и получите 1 волокно. Затем завершите встречу.<br><b>В. Ничего не предлагайте. Завершите встречу. </b>Разозлите чудище на 2.</p>"},"repeatable":false},{"id":"outcomes-416","code":"416","description":{"en":"<p>\\"A flaky chunk of the behemoth's shed skin sits in the sunlight, slowly crumbling to dust. There seems to be something embedded in it...\\"</p>\\n\\"Choose one of the following and resolve it:\\n\\n<b>A) Ponder the sunlit stone:</b> If the behemoth has an unrevealed Secret card assigned to it, reveal this behemoth's currently assigned Secret card, then record it under the Secrets for that behemoth in the Journal.\\n\\n<b>B) Break apart the stone:</b> Gain 2 clay. If you have <stoneworking>, gain 1 shell instead.\\"","ru":"<p><i><b>Хрупкий кусок кожи чудища лежал на солнце, медленно рассыпаясь в пыль. Казалось, внутри него что‑то есть…</b></i></p><p>Выберите и разыграйте одно:<br><b>А. Поразмышляйте о значении залитого солнцем камня.</b> Если у чудища есть назначенная неоткрытая карта секрета, откройте её. Затем запишите её в раздел секретов этого чудища в журнале.<br><b>Б. Разбейте камень. </b>Получите 2 глины. Если у вас есть <stoneworking>, вместо этого получите 1 ракушку.</p>"},"repeatable":false},{"id":"outcomes-417","code":"417","description":{"en":"<p>\\"The behemoth's hand descends toward you, but there are large cracks in its rocky hide from baking in the sun. You slip into one of these cracks and wait until the hand passes, then make your way safely down the behemoth.\\"</p>\\nEnd the encounter. Then, gain <minor_boost> to <dexterity>.","ru":"<p><i><b>Над вами нависла лапа чудища. Но под светом солнца в его каменной коже стали появляться большие трещины. Вы проскользнули в одну из них, дождались, пока лапа сдвинется, а затем благополучно спустились на землю.</b></i></p><p>Завершите встречу. Получите <minor_boost> к <dexterity>.</p>"},"repeatable":false},{"id":"outcomes-418","code":"418","description":{"en":"<p>Resentments have long hung like thunderclouds above your people. Now, the storm descends. Factions form and battles break out. Bonds are broken, blood is spilled, and at the end of the skirmishes, nobody is the winner. The human toll is too great to bear, and so an uneasy detente between the belligerents is formed. But periodic violence still punctuates the once-peaceful valley, and the swirling stormclouds of recrimination and revenge do not fully dissipate.</p>\\nSet <unrest> to 10. Subtract 8<population>. Illustrate the saga of the bloody days on the primal cave wall, including the battle (i) and harrowing (ii) marks. Add Cycle of Violence (JE06) to the Journey deck and Open Hostilities (NN02) to the Night deck.","ru":"<p><i><b>Недовольство давно нависало над вашим народом, словно грозовая туча. Теперь же буря обрушилась… Начались распри и сражения, разорвались узы, пролилась кровь. А когда столкновения утихли, победителей не оказалось. Человеческие потери были слишком велики, чтобы их вынести, и между враждующими сторонами установилось хрупкое перемирие. Однако жестокость то и дело продолжала сотрясать прежде мирную долину, а грозовые тучи взаимных обвинений и жажды мести так и не рассеялись.</b></i></p><p>Установите значение <unrest> на 10. Уберите 8 <population>. На стене первобытной пещеры изобразите историю о кровавых днях, включив в неё отметку битвы [i] и отметку ужаса [ii]. Добавьте карту «Беспрестанное насилие» (ПР06) в колоду пути и карту «Открытая враждебность» (НО02) в колоду ночи.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<battle>"},{"label":"ii","image":"<harrowing>"}]},{"id":"outcomes-420","code":"420","description":{"en":"<p>Beneath the Tangle, you discover a great seed. Could this be the sort of seed from which the Tangle itself sprang? You stand in awe of the grand cycle of life.</p>\\nAdd <lore><lore><lore><lore>.","ru":"<p><i><b>Под землёй вы обнаружили огромное семя. Неужели из него и проросло само Сплетение? Вы с благоговением взирали на великий круговорот жизни. </b></i></p><p>Добавьте <lore><lore><lore><lore>.</p>"},"repeatable":false},{"id":"outcomes-421","code":"421","description":{"en":"<p>As you look at the rootmarks of the great behemoth, you notice they cautiously skirt an area of seared earth.</p>\\n\\"Choose one of the following and resolve it:\\n\\n<b>A) Think on the blistered patch of earth:</b> If the behemoth has an unrevealed Secret card assigned to it, reveal this behemoth's currently assigned Secret card, then record it under the Secrets for that behemoth in the Journal.\\n\\n<b>B) Reignite the flames to drive off the behemoth:</b> Degrade one of the behemoth's boosts of your choice. If you have an item with a <fire> token on it or there is a <fire> token in your hex, degrade each of the behemoth's boosts instead.\\"","ru":"<p><i><b>Разглядывая следы корней чудища, вы заметили, что они аккуратно огибают участок обожжённой земли.</b></i></p><p>Выберите и разыграйте одно:<br><b>А. Поразмышляйте об этом обугленном участке земли. </b>Если у чудища есть назначенная неоткрытая карта секрета, откройте её. Затем запишите её в раздел секретов этого чудища в журнале.<br><b>Б. Возродите пламя, чтобы отпугнуть чудище. </b>Уменьшите любое усиление чудища. Если у вас есть предмет с <fire> или на вашем участке местности есть <fire>, уменьшите все усиления чудища.</p>"},"repeatable":false},{"id":"outcomes-422","code":"422","description":{"en":"<p>\\"The behemoth's tracks burn with a blaze that persists unnaturally, withering plants and scaring animals away.\\"</p>\\n\\"Place a depletion token in each hex with a trace token. Each character in a hex with a trace token suffers <minor_disease>.\\n\\nThen, remove all of this behemoth's trace markers from the valley. Assign the Return to Slumber (BT20) instinct to this behemoth (replacing its previous instinct).\\"","ru":"<p><i><b>Следы чудища горели неестественным пламенем, иссушая растения и отпугивая зверей.</b></i></p><p>Поместите жетон истощения на каждый участок местности с жетоном следов. Каждый персонаж на участке с жетоном следов получает <minor_disease>. Затем уберите жетон направления и все жетоны следов этого чудища. Замените его текущий инстинкт на «Вернуться в забытьё» (ЧК20).</p>"},"repeatable":false},{"id":"outcomes-423","code":"423","description":{"en":"<p>You can hear water trickling down the side of the glacier, and branches rustling in the distance. There must be a great forest somewhere just past the glacier.</p>\\nAdd <lore><lore><lore>. Add A World Below (GZ05) to your goals.","ru":"<p><i><b>Вы услышали, как вода струится по склону ледника, а вдали шелестят ветви. Где‑то там, должно быть, раскинулся лес.</b></i></p><p>Добавьте <lore><lore><lore>. Добавьте к целям карту «Отправьтесь в подземный мир» (ЦЯ05).</p>"},"repeatable":false},{"id":"outcomes-424","code":"424","description":{"en":"<p>With sweat, blood, and toil, you have brought the seed of the Tangle up into the light of day.</p>\\n<p>\\"At the end of any day, you may end this challenge.\\n\\nIllustrate the saga of the Tangle seed on the primal cave wall, including the growth mark (i) and the Tangle mark (ii). Add A New Flourishing (CN05) to your looming challenges.\\"</p>","ru":"<p><i><b>Ценой пота и крови вы вынесли семя Сплетения на поверхность.</b></i></p><p>В конце любого дня можете завершить текущее испытание.</p><p>На стене первобытной пещеры изобразите историю о семени Сплетения, включив в неё отметку становления [i] и отметку Сплетения [ii]. Добавьте карту «Новый расцвет» (ИЖ05) к грядущим испытаниям.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<growth>"},{"label":"ii","image":"<tangle>"}]},{"id":"outcomes-425","code":"425","description":{"en":"<p>\\"The behemoth's ashy treads fill with verdant, blooming life.\\"</p>\\n<p>\\"Remove all depletion tokens from hexes with traces, then place a mystery token in each of those hexes.\\n\\nThen, remove all of this behemoth's trace markers from the valley. Assign the Return to Slumber (BT20) instinct to this behemoth (replacing its previous instinct).\\"</p>","ru":"<p><i><b>Там, где были пепельные следы чудища, расцвела жизнь.</b></i></p><p>Уберите все жетоны истощения с участков местности с жетонами следов и поместите по 1 жетону тайны на каждый из этих участков. Затем уберите жетон направления и все жетоны следов этого чудища. Замените его текущий инстинкт на «Вернуться в забытьё» (ЧК20).</p>"},"repeatable":false},{"id":"outcomes-426","code":"426","description":{"en":"<p>Your delve comes to an end in a vast cavern. You hear the rippling of water from what must be a lake, and follow it. The water is tinged with an icy glow that illuminates the nearby shore.</p>\\n\\"Embark on the venture below (see Ventures on Rulebook p.60).\\n\\n<bi>This chamber may be sheltered from the coral, but that does not mean it is free of other dangers.</bi>\\n<b>Champion, Hazard:</b> Someone must test <awareness> to search for danger. Add +1 for each <i>exploration</i> item you have, +2 if you have an item with a <fire> token on it, and +2 if you are <i>wary</i>.\\n10+: You are reasonably certain it is safe here. The venture continues.\\n1–9: The darkness might hide many dangers still. The venture fails unless a character spends <energy><energy> or <lore> to attempt this test again.\\n\\n<bi>Setting up even a basic outpost underground is no easy feat. For starters, you'll need to cut airflow shafts to allow for fires.</bi>\\n<b>Champion:</b> Someone must test <might> to excavate. Add +2 if you have <dig> and +2 if you have <stoneworking>. You may discard up to 3 wood from your inventory. If you do, add +2 for each wood you discard this way.\\n12+: You reshape the cavern to your needs. The venture continues.\\n1–11: You are unable to create the necessary earthworks. The venture fails unless a character spends <energy><energy> or <lore> to attempt this test again.\\n\\n<bi>You'll need to have a clearly marked route to your underground retreat if you want your people to be able to live there permanently.</bi>\\n<b>Champion:</b> Someone must test <awareness> to leave signs to reach the chamber. Add +4 if you have the scribe mark (i), +2 if you have the plenty mark (ii), +4 if you have a Map, and +2 if you are <i>inquisitive</i>.\\n12+: You create a set of guiding marks that can help people reach the chamber safely. Complete this venture and the associated goal.\\n1–11: You're unable to create a coherent system. The venture fails unless a character spends <energy><energy> or <lore> to attempt this test again.\\"","ru":"<p><i><b>Вы спустились в огромный грот. Услышав плеск воды, вы направились к подземному озеру, берег которого освещался ледяным сиянием.</b></i></p><p>Отправьтесь в поход (см. раздел «Походы» в правилах игры на с. 60).</p><p><b><i>Этот грот хоть и казался защищённым от кораллов, но это вовсе не означало, что здесь нет других опасностей. </i></b></p><p><b>Защитник, угроза. </b>Один из персонажей в походе должен провести проверку <awareness>, чтобы распознать угрозу. +1 за каждый его предмет для <i>исследования</i>, +2, если у него есть предмет с <fire>, и +2, если он <i>осторожный</i>.<br><b>≥10:</b>  Вы убедились, что здесь безопасно. Продолжите поход.<br><b>1-9:</b> Во тьме всё ещё могли скрываться опасности. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy> или <lore>, чтобы провести проверку ещё раз.</p><p><i><b>Основать даже небольшое поселение под землёй — задача не из лёгких. Для начала вам придётся прорубить вентиляционные шахты, чтобы зажечь огонь.</b></i></p><p><b>Защитник. </b>Один из персонажей в походе должен провести проверку <might>, чтобы копать. +2, если у него есть <dig>, +2, если у него есть <stoneworking>, а также +2 за каждое сброшенное из его инвентаря дерево (не более +6).<br><b>≥12:</b>  Вы перестроили грот под свои нужды. Продолжите поход.<br><b>1-11:</b>  Вам не удалось создать условия для жизни под землёй. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy> или <lore>, чтобы провести проверку ещё раз.</p><p><i><b>Вам предстояло отметить путь к подземному убежищу, чтобы ваши люди могли жить там постоянно. </b></i></p><p><b>Защитник. </b>Один из персонажей в походе должен провести проверку <awareness>, чтобы оставить метки, ведущие в грот. +4, если у него есть отметка летописца [i], +2, если у него есть отметка изобилия [ii], +4, если у него есть «Карта», и +2, если он <i>любознательный</i>.<br><b>≥12:</b>  По вашим меткам люди смогут безопасно добраться до грота. Завершите этот поход и достигните соответствующей цели. <br><b>1-11:</b>  Вам не удалось создать понятную систему меток. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy> или <lore>, чтобы провести проверку ещё раз.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<scribe>"},{"label":"ii","image":"<plenty>"}]},{"id":"outcomes-428","code":"428","description":{"en":"<p>\\"You notice small cracks forming atop the behemoth's brow where the light has made its skin brittle...\\"</p>\\n\\"Choose one and resolve it:\\n\\n<b>A) Under your withering sight and mighty blows, the cracks spread into deep shadows. A large chunk of the behemoth's head shears off, crashing into the ground:</b> If you have <stoneworking> or <sun> is a current omen, end the encounter. Aggravate the behemoth's demeanor by 1. The behemoth flees. Then, if a character, animal companion, or storage structure has an item with Ruinous in its name, gain 2 of the behemoth's curio; otherwise, gain the Ruinous Shard (IT85) Item card.\\n\\n<b>B) You relent for an instant, and the behemoth shakes you from its head:</b> Suffer <minor_injury>. End the encounter. Then flee.\\"","ru":"<p><i><b>Вы заметили мелкие трещины на лбу чудища. Видимо, там, куда попадал свет, его кожа становилась хрупкой...</b></i></p><p>Выберите и разыграйте одно: <br><b>А. От ваших мощных ударов трещины превратились в глубокие разломы. Большой кусок головы чудища откололся и с грохотом рухнул на землю. </b>Если <sun>— текущее знамение или у вас есть <stoneworking>, завершите встречу. Разозлите чудище на 1. Чудище сбегает. Затем, если у любого персонажа, животного-компаньона или в сооружении-хранилище есть предмет со словом «разрушительный» в названии, получите 2 сокровища чудища; в противном случае получите карту предмета «Разрушительный осколок» (ВЩ85).<br><b>Б. Вы на мгновение потеряли хватку, и чудище сбросило вас с головы.</b> Получите <minor_injury>. Завершите встречу и сбегите.</p>"},"repeatable":false},{"id":"outcomes-430","code":"430","description":{"en":"<p>You look up nervously from your cooking pots to see how the fare is being received. Around the fireside, people shift and grumble, poking at the food in their bowls with little enthusiasm. Nobody is seen eating seconds.</p>\\n\\"If <i>The Main Course</i> is incomplete, add <unrest><unrest><unrest>, reducing the amount of unrest gained this way by <unrest> for each dish you cooked this game.\\n\\nIf <i>Stockpile Supplies</i> is incomplete, add <unrest><unrest><unrest><unrest>, reducing the amount of <unrest> gained this way per 2 tokens (rounding up) that were on that goal card.\\"","ru":"<p><i><b>Вы с волнением подняли глаза от котлов с едой, чтобы увидеть, как принимают угощение. Люди у костра ворчали, без особого энтузиазма ковыряясь в мисках. Никто не просил добавки.</b></i></p><p>Завершите текущее испытание.</p><p>Если цель «Приготовьте главное блюдо» не выполнена, добавьте <unrest><unrest><unrest>(уменьшите добавленное таким образом недовольство на 1 за каждое блюдо, которое вы приготовили в этой партии).<br>Если цель «Сделайте запасы» не выполнена, добавьте <unrest><unrest><unrest><unrest>(уменьшите добавленное таким образом недовольство на 1 за каждые 2 жетона на этой карте цели, округляя в большую сторону).</p>"},"repeatable":false},{"id":"outcomes-431","code":"431","description":{"en":"<p>The behemoth looks at you expectantly for an offering. Did you come prepared?</p>\\n\\"Choose one and resolve it:\\n\\n<b>A) Offer tribute to the behemoth:</b> If you have a processed material or an item in your inventory, discard a processed material or an item to placate the behemoth's demeanor by 1.\\n\\n<b>B) Present no gift:</b> Aggravate the behemoth's demeanor by 1.\\n\\nThen, continue the encounter.\\"","ru":"<p><i><b>Чудище смотрело на вас, ожидая подношения. Вы пришли подготовленными?</b></i></p><p>Выберите и разыграйте одно:<br><b>А. Преподнесите чудищу дар. </b>Если у вас есть обработанный материал или предмет в инвентаре, сбросьте 1 обработанный материал или предмет. Успокойте чудище на 1.<br><b>Б. Не преподносите дар. </b>Разозлите чудище на 1.</p><p>Затем продолжите встречу.</p>"},"repeatable":false},{"id":"outcomes-432","code":"432","description":{"en":"<p>\\"You are swept downriver, bounced and rocked by the current's inexorable pull. Where you will end up, who can say? Your fate is in the hands of the river.\\"</p>\\n\\"Resolve the first you are able:\\n\\n<b>A) You are swept into an unexplored area:</b> If your current hex has at least 2 adjacent open edges, there are at least 3 unplaced hexes of your current region (excluding the starting hex, if applicable), and your valley has at least 1 unplaced tray, <outcome> 283.\\n\\n<b>B) You are swept in an unexpected direction:</b> If one or more adjacent hexes have a lake, river, or wetland, randomly select one of those hexes and place your character there (without drawing a Journey card).\\n\\n<b>C) You are caught in a blockage in the river:</b> Lose <energy><energy>. Gain 1 wood and 1 fiber.\\"","ru":"<p><i><b>Течение унесло вас вниз по реке, неумолимо швыряя из стороны в сторону. Куда вас вынесет — кто знает? Ваша судьба была во власти воды.</b></i></p><p>Разыграйте первое, что можете:<br><b>А. Вас унесло в неисследованные земли.</b> Если у вашего участка местности 2 открытые соседние границы, а также если есть хотя бы 1 ещё не помещённая основа местности и хотя бы 3 ещё не помещённых участка вашего текущего региона (не считая начального участка, если применимо), то <outcome> 283.<br><b>Б. Вас унесло в неожиданном направлении. </b>Если хотя бы на 1 соседнем участке местности есть озеро, река или болото, переместите туда персонажа, выбрав участок случайным образом.<br><b>В. Вы попали в преграду на реке.</b> Потеряйте <energy><energy>. Получите 1 дерево и 1 волокно.</p>"},"repeatable":false},{"id":"outcomes-434","code":"434","description":{"en":"<p>The light of the comet leads you to a lonesome coral stalk. It shivers slightly in tune with your breath.</p>\\n\\"Test to <conviction> to learn of the valley. Add +2 if you are <i>inquisitive</i> and +2 if you have the coral mark.\\n11+: You reach out and touch the stalk; it pulses and then fades to a dull color. Gain 1 dead coral. You may add <lore>, or you may spend <lore> to degrade 1 of your maladies once.\\n7–10: You reach for the coral hesitatingly and it withdraws. Add <lore>.\\n1–6: You withdraw quickly. No effect.\\"","ru":"<p><i><b>Свет кометы привёл вас к одинокому коралловому отростку. Он подрагивал, словно вторя вашему дыханию. </b></i></p><p>Проведите проверку <conviction>, чтобы узнать больше о долине. +2, если вы <i>любознательный</i>, и +2, если у вас есть отметка коралла.<br><b>≥11:</b>  Вы протянули руку и коснулись коралла — он дрогнул, а затем стал блёкнуть. Получите 1 мёртвый коралл. Затем можете добавить <lore> или вместо этого потратить <lore> и уменьшить один из своих недугов. <br><b>7-10:</b>  Вы нерешительно потянулись к кораллу, и он отпрянул. Добавьте <lore>.<br><b>1-6:</b>  Вы поспешно удалились. Без эффекта.</p>"},"repeatable":false,"marks":[{"label":"","image":"<coral>"}]},{"id":"outcomes-438","code":"438","description":{"en":"<p>Across the mists, you see them: vast, majestic ridgecrawlers. These walking hillsides wade through the caustic fog, the last bits of life in the region carried above the scarring clouds.</p>\\n\\"Resolve the first you are able:\\n\\nA) Make your way into this realm with hard-earned wariness: If the mist mark (i) is on the primal cave wall, place your character in any Maelstrom Hills hex with a ridgecrawler feature, then add <lore><lore><lore>. \\n\\nB) Explore this land of swirling horrors and walking dreams: If you have 2 or more available terrain trays, illustrate the saga of the roiling mists on the primal cave wall, including the <cloud> mark, the discovery mark (ii), and the mist mark (i). Add Mistwalkers (GZ25) to your goals. Finally, set up the Maelstrom Hills as described on Codex p.214.\\n\\nC) The mists seem to have spread into another region, temporarily transforming it into a land of sizzling peril: If you have no available terrain trays, randomly select a hex from the Maelstrom Hills region and place it adjacent to your current hex, not in a terrain tray. Place your character in that hex. Until the end of the challenge, treat that hex as the Maelstrom Hills region (see Codex p.214). At the end of the challenge, return that hex to the game box; any tokens or overlays on that hex at that time are returned to the game box, and any characters in that hex perish.\\"","ru":"<p><i><b>Сквозь туман вы увидели их: огромные, величественные шагающие хребты. Они двигались над едким маревом, неся на своих спинах последние островки жизни.</b></i></p><p>Разыграйте первое, что можете:<br><b>А. С осторожностью отправьтесь в этот край. </b>Если на стене первобытной пещеры есть отметка тумана [i], поместите своего персонажа на любой участок Ураганных холмов, где есть хотя бы 1 шагающий хребет. Затем добавьте <lore><lore><lore>.<br><b>Б. Исследуйте эту землю ужасных вихрей. </b>Если у вас есть хотя бы 2 неразмещённые основы местности, на стене первобытной пещеры изобразите историю о бурлящем тумане, включив в неё отметку <cloud>, отметку тумана [i] и отметку открытия [ii]. Добавьте к целям карту «Пройдите сквозь туман» (ЦЯ25). Затем подготовьте регион Ураганных холмов, как описано на с. 214.<br><b>В. Похоже, жгучий туман распространился на другие земли и на время сделал их опасными.</b> Если у вас нет неразмещённых основ местности, поместите случайный участок Ураганных холмов рядом со своим участком (не в ячейку основы местности), а затем поместите своего персонажа на него. До конца текущего испытания считайте этот участок частью региона Ураганных холмов (см. подробнее на с. 214). Завершив испытание, верните в коробку этот участок местности вместе с жетонами и накладками на нём. Персонажи, которые находились на убранном участке, умирают.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<mist>"},{"label":"ii","image":"<discovery>"}]},{"id":"outcomes-439","code":"439","description":{"en":"<p>\\"One hope remains: moving your people through the pass to escape the valley. You rally all your strength and lead your people on this journey to seize survival from winter's closing jaws.\\"</p>\\n\\"Embark on the venture below (see Ventures on Rulebook p.60).\\n\\n<bi>As you make your way toward the pass, snows begin to fall. Numbness besets your limbs as the white blankets pile on the valley.</bi>\\n<b>Group, Weather:</b> Everyone must test <might> to endure the conditions. A character adds +2 if they have a <i>clothing</i> item, +2 if they have an item with a <fire> token on it, and +2 if they are <i>indomitable</i>.\\n11+: You forge a path through the deepening snows that others can follow. If any character resolves this result, the venture continues.\\n1–10: The grip of winter sets itself tightly around you, and you stumble and struggle to stay upright as you march through the snow. Suffer <major_disease><minor_disease>. If all characters on the venture resolve this result, the venture fails unless a character spends <energy><energy> or <lore><lore> to attempt this test again. If the venture fails this way, then place a failed egress (<minor_boost>) in this hex.\\n\\n<bi>Hope wanes within your group, and your people grow fearful. Someone must inspire them!</bi>\\n<b>Champion:</b> Someone must test <conviction> to rally your people's flagging spirits. Add +1 for each character in the venture who has a Legend card. Add +4 if Stockpile Supplies is complete.\\n13+: You speak of the works you have done so far and the ancestors whose stories you carry. Inspired, your people find the strength to push on. The venture continues.\\n1–12: Your words are swallowed by the snows, and your people turn back. End the venture, then place a failed egress (<minor_boost>) in this hex.\\n\\n<bi>A rumble chills you to the bone, and then you see it: a great sheet of snow descening the side of the pass, threatening to bury you and block your escape!</bi>\\n<b>Group, Hazard:</b> Everyone must test <dexterity> or <awareness> to evade the tides of snow as you race through the pass. Add +2 if you have an <i>exploration</i> item, +2 if you are <i>wary</i>, and +6 if Beseech the Behemoth is complete. You may suffer up to 4 <major_injury> to add +1 to the result per <major_injury> suffered this way (you cannot voluntarily become incapacitated this way).\\n13+: You race on, not looking back as the rush of snow pursues you. Yet you feel a presence behind you, holding it back. Could it be the behemoth? Your ancestors? The valley itself? There is no time to look back and be sure. If any character resolves this result, complete this venture and the associated goal.\\n1–12: Your character is buried in the snows, entombed forever in the valley. If all characters on the venture resolve this result, <outcome> 475.\\"","ru":"<p><i><b>Оставалась лишь одна надежда: провести народ через перевал и покинуть долину. Вы собрались с силами и повели людей за собой, чтобы спастись из сжимающейся вокруг вас ледяной хватки зимы.</b></i></p><p>Отправьтесь в поход (см. раздел «Походы» в правилах игры на с. 60).</p><p><i><b>Когда вы приблизились к перевалу, пошёл снег. Конечности занемели, а белое покрывало всё плотнее укрывало долину. </b></i></p><p><b>Группа, погода. </b>Все персонажи в походе должны провести проверку <might>, чтобы справиться с холодом. +2, если у персонажа есть <i>одежда</i>, +2, если у него есть предмет с <fire>, и +2, если он <i>неукротимый</i>.<br><b>≥11:</b>  Вы проложили путь сквозь глубокий снег, и за вами смогли последовать другие. Если хотя бы один персонаж получил этот результат, продолжите поход.<br><b>1-10:</b>  Зима крепко сжала вас в своих объятиях — вы спотыкались и с трудом удерживались на ногах, пробираясь сквозь снег. Получите <major_disease> и <minor_disease>. Если все персонажи получили этот результат, поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy> или <lore><lore>, чтобы провести проверку ещё раз. Если поход окончился неудачно при таком результате, поместите на свой участок неудачный выход (<minor_boost>).</p><p><b><i>Надежда гасла, людей охватил страх. Кто‑то должен был вдохновить их!</i></b></p><p><b>Защитник. </b>Один из персонажей в походе должен провести проверку <conviction>, чтобы воодушевить людей. +1 за каждого персонажа в походе, у которого есть карта легенды, и +4, если цель «Сделайте запасы» достигнута в течение этого испытания.<br><b>≥13:</b>  Вы рассказали о своих свершениях и о предках, чьи истории вы несёте с собой. Воодушевившись, люди вновь обрели силы. Продолжите поход.<br><b>1-12:</b>  Ваши слова утонули в снегу, и люди повернули назад. Поход окончился неудачно. Поместите на свой участок неудачный выход (<minor_boost>).</p><p><b><i>Вдруг вас охватила леденящая дрожь — вы увидели, как огромный пласт снега сорвался с перевала, грозя погрести вас под собой и отрезать путь к спасению!</i></b></p><p><b>Группа, угроза. </b>Все персонажи в походе должны провести проверку <dexterity> или <awareness>, чтобы избежать снежной лавины. +2, если у персонажа есть предмет для <i>исследования</i>, +2, если персонаж <i>осторожный</i>, и +6, если цель «Воззовите к чудищу» достигнута в течение этого испытания. Также персонаж может получить одну или несколько <major_injury>, чтобы добавить 1 к результату за каждую (не более +4; персонаж не может добровольно стать недееспособным таким способом).<br><b>≥13:</b>  Вы бежали, не оглядываясь, пока за вами гналась снежная буря. Вдруг вам показалось, будто кто-то позади вас сдерживает лавину. Неужели это было чудище? Или предки? А может, сама долина? Времени, чтобы оглянуться, не было… Если хотя бы один персонаж получил этот результат, завершите этот поход и достигните соответствующей цели.<br><b>1-12:</b>  Вы оказались погребены под снегом и навеки остались в долине. Ваш персонаж умирает и становится легендой. Если все персонажи получили этот результат, то <outcome> 475.</p>"},"repeatable":false},{"id":"outcomes-440","code":"440","description":{"en":"<p>A plague sweeps the land in the days between epochs, harrowing your people.</p>\\n\\"Illustrate the saga of the wretched year on the primal cave wall, including the harrowing mark and the plague mark. Subtract <population><population>. Then, as a group, the players must choose one of the following paths for your society:\\n\\n<b>A) Endure the plague's ravages:</b> Subtract <1d6><population>.\\n\\n<b>B) Enforce the building of sanitation systems:</b> If you have designed the Waste Pit structure, add one of these structures to each of your outposts that does not have it (without spending <energy> or resources). If an outpost has the maximum number of structures, randomly select one of the current structures and destroy it to add the new structure. Add <unrest><unrest>.\\n\\n<b>C) Survive thanks to your preparations:</b> If each of your outposts has a Waste Pit structure, no effect.\\"","ru":"<p><i><b>Когда сменялись эры, чума охватила ваши земли, наводя ужас на людей.</b></i></p><p>На стене первобытной пещеры изобразите историю о годах несчастья, включив в неё отметку ужаса [i] и отметку чумы [ii]. Уберите <population><population>. Затем совместно выберите один из следующих путей развития общины:<br><b>А. Справьтесь с чумой. </b>Бросьте <1d6> и уберите столько <population>, сколько выпало на <1d6>.<br><b>Б. Побудите общину построить санитарные сооружения. </b>Если вы спроектировали мусорную яму, постройте по одному такому сооружению в каждом из поселений, где его ещё нет, не тратя <energy> и ресурсы. Если в поселении достигнуто максимальное количество сооружений, разрушьте 1 случайное сооружение в таком поселении, чтобы построить мусорную яму. Добавьте <unrest><unrest>.<br><b>В. Выживите благодаря подготовке. </b>Если в каждом поселении есть мусорная яма, без эффекта.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<harrowing>"},{"label":"ii","image":"<plague>"}]},{"id":"outcomes-442","code":"442","description":{"en":"<p>\\"Amid the bones of ancient beasts and primordial stones, you see generations of the Tangle blooming, dying, and blooming again. You see a great seed: the Tangle's child?\\"</p>\\nGain <major_boost> to <conviction> and add <lore><lore><lore>.","ru":"<p><i><b>Среди первобытных камней и костей древних чудищ вы увидели, как сменялись поколения Сплетения — расцветали, умирали, а затем расцветали вновь. Вы узрели великое семя. Было ли это дитя Сплетения?</b></i></p><p>Получите <major_boost> к <conviction> и добавьте <lore><lore><lore>.</p>"},"repeatable":false},{"id":"outcomes-443","code":"443","description":{"en":"<p>\\"You wade through the spiraling dust around the behemoth's lair to find...\\"</p>\\n\\"Embark on the venture below (see Ventures on Rulebook p.60).\\n\\n<bi>The bulbous mounds that form the behemoth's rocky home are difficult to breach. Perhaps by finding the right points to strike, you can break inside.</bi>\\n<b>Champion, Wonder:</b> Someone must test <awareness> to breach the walls. Add +2 if you have <stoneworking> and +2 for each <i>exploration</i> item you have.\\n10+: You manage to strike a thin spot in the wall, revealing a honeycomb of hollow passages. The venture continues.\\n1–9: You struggle to find an entry point. The venture fails unless a character spends <energy><energy> or <lore> to attempt this test again.\\n\\n<bi>Within the maze of tunnels, you grow more and more claustrophobic.</bi>\\n<b>Group, Hazard:</b> Everyone must test <conviction> to remain calm. A character adds +2 if they have an item with a <fire> token on it and +2 if they are <i>indomitable</i>.\\n10+: You remain steady in your goal. The venture continues.\\n1–9: You panic and start backing out of the tunnels! If all characters on the venture resolve this result, the venture fails.\\n\\n\\n<bi>The winding tunnels eventually lead to a chamber with a pool of corrosive acid. Perhaps this substance is how the behemoth creates these tunnels? If so, it might be able to bore through the creature's invulnerable rocky skin, if only you could imbue it upon your weapon.</bi>\\n<b>Champion, Hazard:</b> Someone must test <dexterity> to gather some of the substance. Add +4 if one or more Secrets have been recorded in the Journal for this behemoth.\\n10+: You manage to gather up some of the bitter ooze. Complete this venture and the associated goal.\\n1–9: You fumble, and some of the substance splashes upon you. Suffer <major_injury><major_injury>. Then the venture fails unless a character spends <energy><energy> or <lore> to attempt this test again.\\n\\"","ru":"<p><i><b>Вы с трудом прошли сквозь клубящуюся пыль у логова чудища. </b></i></p><p>Отправьтесь в поход (см. раздел «Походы» в правилах игры на с. 60).</p><p><b><i>Круглые насыпи, образующие каменное жилище чудища, было непросто пробить. Быть может, если найти подходящие точки для удара, вам удастся пробраться внутрь.</i></b></p><p><b>Защитник, чудо.</b> Один из персонажей в походе должен провести проверку <awareness>, чтобы пробить стену. +2, если у него есть <stoneworking>, и +2 за каждый его предмет для <i>исследования</i>.<br><b>≥10:</b>  Вы ударили по тонкому участку стены, и вам открылась сеть полых проходов. Продолжите поход.<br><b>1-9:</b>  Вы не смогли пробить вход в стене. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy> или <lore>, чтобы провести проверку ещё раз.</p><p><b><i>В узких туннелях вас всё сильнее охватывал страх.</i></b></p><p><b>Группа, угроза. </b>Все персонажи в походе должны провести проверку <conviction>, чтобы сохранить спокойствие. +2, если у персонажа есть предмет с <fire>, и +2, если персонаж <i>неукротимый</i>. <br><b>≥10:</b>  Вы твёрдо шли к цели. Продолжите поход.<br><b>1-9:</b>  Вас охватила паника, и вы стали отступать. Если все персонажи получили этот результат, поход окончился неудачно. </p><p><i><b>Извилистые туннели привели вас к полости с озером из разъедающей кислоты. Вероятно, именно с её помощью чудище прокладывало себе ходы. Если так, то, возможно, эта жидкость сможет пробить и его неуязвимую каменную кожу — нужно только пропитать оружие кислотой.</b></i></p><p><b>Защитник, угроза. </b>Один из персонажей в походе должен провести проверку <dexterity>, чтобы собрать немного жидкости. +4, если в журнале записан хотя бы 1 секрет этого чудища.<br><b>≥10:</b>  Вам удалось собрать немного едкой жижи. Завершите этот поход и достигните соответствующей цели.<br><b>1-9:</b>  Ваша рука неловко дёрнулась, и немного кислоты попало на кожу. Получите <major_injury><major_injury>. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy> или <lore>, чтобы провести проверку ещё раз.</p>"},"repeatable":false},{"id":"outcomes-445","code":"445","description":{"en":"<p>Atop the creature, your weapon falters in your hand. This creature heralds life and death. If you even can kill it, have you that right? Will its passing still the cycle of seasons and of lives? Is killing this terrible, perfect creature to become the fly trapped forever in its amber brilliance? Consciousness flees your mind in light of such questions, and when you awaken, your weapon has grown to a vibrant branch crowned in flowers. The behemoth is nowhere to be seen. You know that it observes you still, but you feel no malice in its hidden gaze.</p>\\n\\"Add <unrest><unrest><unrest><unrest>. Set the behemoth's demeanor to \\\\\\"2.\\\\\\" Illustrate the saga of the broken cycle on the primal cave wall, including the alert behemoth's mark, the caution mark (i), and the growth mark (ii). Permanently raise the <conviction> and <awareness> of each character who was on the venture when it was completed by 1 (to a maximum of 7). Add the alert behemoth's mark and the growth mark (ii) to the Legend side of each of those Character cards. If the character who completed the final contest of the venture has a <i>weapon</i> item and no character, animal companion, or storage structure has an item with Vivacious in its name, they must discard a <i>weapon</i> item and gain the Vivacious Sprout (IT90) Item card.\\n\\nThen end the Epoch. See Codex p.204 to begin Epoch 3.\\"","ru":"<p><i><b>Вы замахнулись, но оружие дрогнуло в вашей руке. Это существо несло в себе жизнь и смерть. Если вы были в силах его убить — имели ли вы на это право? Прервёт ли его смерть круговороты времён года и судеб? Станет ли убийство этого ужасного, но совершенного существа вашей собственной западнёй — каплей янтаря, навеки заключившей муху? Под тяжестью этих мыслей сознание покинуло вас. А когда вы очнулись, то увидели, что ваше оружие превратилось в яркий цветущий побег. Чудище исчезло. Вы знали: оно всё ещё наблюдает за вами. Но в его скрытом взгляде не чувствовалось злобы.</b></i></p><p>Завершите текущее испытание.</p><p>Добавьте <unrest><unrest><unrest><unrest>. Установите значение нрава чудища на 2. На стене первобытной пещеры изобразите историю о нарушенном круговороте, включив в неё отметку бодрствующего чудища, отметку осторожности [i] и отметку становления [ii]. Навсегда увеличьте <conviction> и <awareness> на 1 (не более чем до 7) каждого персонажа, участвовавшего в этом походе на момент его завершения. Также добавьте отметку бодрствующего чудища и отметку становления [ii] на сторону легенды карт этих персонажей. Если у персонажа, завершившего последнее испытание этого похода, есть <i>оружие </i>и ни у одного персонажа, животного-компаньона или в сооружении-<i>хранилище</i> нет предмета со словом «живой» в названии, этот персонаж должен сбросить <i>оружие </i>и получить карту предмета «Живой росток» (ВЩ90).</p><p>Затем завершите текущую эру. См. с. 204, чтобы начать эру 3.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<caution>"},{"label":"ii","image":"<growth>"}]},{"id":"outcomes-446","code":"446","description":{"en":"<p>\\"You spot a towering, cyclopean monolith through the valley's mists. Whatever once inhabited this strange structure, it has not passed in many turns of the sun and moon.\\"</p>\\n\\"Resolve the first you are able:\\n\\n<b>A) Stare up at the vast tomb in awe:</b> If there are one or more unplaced behemoth lair overlays, randomly select one of them and place a it in a hex in the newly added terrain tray. Roll <1d6> and place it in the corresponding zone: (1–2): A, (3–4), B, (5–6) C. It must be placed in a zone without an overlay. Illustrate the saga of the ancient tomb on the primal cave wall, including the mark of the behemoth whose lair you placed this way and the discovery mark.\\n\\n<b>B) Panic, daring not to look back at the ancient obelisk that pierces the mists:</b> Place a mystery token in each hex without a character in the newly added terrain tray. Then flee to a randomly selected hex not in the newly added terrain tray.\\n\\nRules for behemoth lairs are found in the Overlay Reference section beginning on Codex p.210.\\"","ru":"<p><i><b>В тумане долины возвышался огромный монолит. Какое бы существо ни обитало в этом странном сооружении, оно покинуло его много солнц и лун назад. </b></i></p><p>Разыграйте первое, что можете:<br><b>А. Застыньте в изумлении перед гигантской гробницей. </b>Если есть хотя бы 1 непомещённая накладка логова, поместите случайное логово неактивной стороной вверх на любой участок только что добавленной основы местности. Бросьте <1d6>, чтобы поместить логово в соответствующий район: [1-2] А, [3-4] Б, [5-6] В. Логово должно быть помещено в район без накладок. Подробнее о логовах чудищ см. на с. 211–212. На стене первобытной пещеры изобразите историю о древней гробнице, включив в неё отметку чудища, чьё логово вы поместили, и отметку открытия.<br><b>Б. Придите в ужас, не в силах смотреть на древний обелиск, рассекающий туман. </b>Поместите жетоны тайны на только что добавленную основу местности — по 1 жетону на каждый участок без персонажа. Затем сбегите на случайный участок, не находящийся на только что добавленной основе местности.</p>"},"repeatable":false,"marks":[{"label":"","image":"<discovery>"}]},{"id":"outcomes-447","code":"447","description":{"en":"<p>In the dark below the valley, the bustling of feet echoes. Your people have mastered the use of the subterranean gates. Travel between your outposts is now trivial, and the swift and safe transit allows your knowledge and culture to flourish even as you spread across the valley.</p>\\n<p>\\"At the end of any day, you may end this challenge.\\n\\nIllustrate the saga of the paths unearthed on the primal cave wall, including the broken_earth mark (i) and the underworld mark (ii).\\n.\\nAt the end of this challenge, end the Epoch. See Codex p.204 to begin Epoch 3.\\"</p>","ru":"<p><i><b>Во тьме под долиной раздавалось эхо множества шагов. Ваш народ освоил подземные врата, и путешествия между поселениями отныне не представляли труда. Быстрое и безопасное передвижение позволило знаниям и культуре расцвести, ведь расстояние между частями общины теперь не имело большого значения.</b></i></p><p>В конце любого дня можете завершить текущее испытание.</p><p>На стене первобытной пещеры изобразите историю о раскопанных путях, включив в неё отметку расколотой земли [i] и отметку подземного мира [ii].</p><p>В конце этого испытания завершите текущую эру. См. с. 204, чтобы начать эру 3.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<brokenearth>"},{"label":"ii","image":"<underworld>"}]},{"id":"outcomes-448","code":"448","description":{"en":"<p>The moonlight makes you the target of a large hunting bird. It dives toward you, threatening to scoop you up as its prey!</p>\\n\\"Test <conviction> to stand your ground. Add +2 if you are <i>indomitable</i> and +2 if you have an item with a <fire> token on it.\\n12+: You stare down the bird, and at the last second, it veers off, plumes falling around you. Gain 2 feathers.\\n8–11: The bird shoots past you, the wind from its wings almost throwing you from the mountainside and forcing you to brace. If you have a Piton or Walking stick, no effect. Otherwise, suffer <major_injury>.\\n1–7: The bird scoops you up and carries you skyward. Thrashing and fighting, you try desperately to break free, but its grip holds. Eventually, it drops you in a nest, and you make your escape while it rouses its hungry progeny. Lose <energy> and suffer <major_injury>, then place your character in a randomly selected unexplored hex, if able, and explore that hex. Otherwise, place your character in another hex of your choice, choosing a hex with a mountain, if able.\\"","ru":"<p><i><b>Лунный свет сделал вас мишенью для крупной хищной птицы. Она устремилась к вам, готовясь схватить как добычу!</b></i></p><p>Проведите проверку <conviction>, чтобы устоять. +2, если вы <i>неукротимый</i>, и +2, если у вас есть предмет с <fire>.<br><b>≥12:</b>  Вы смотрели прямо на птицу, и в последний миг она резко свернула в сторону, осыпав вас перьями. Получите 2 пера.<br><b>8-11:</b>  Птица пронеслась мимо, но порыв ветра от её крыльев едва не сбросил вас с горного склона. Если у вас есть «Скальный крюк» или «Трость», без эффекта. В противном случае получите <major_injury>.<br><b>1-7:</b>  Птица схватила вас и унесла в небо. Вы яростно вырывались, но её хватка оставалась крепкой. Наконец она сбросила вас в гнездо, и вы выбрались оттуда, пока она пробуждала ото сна своё голодное потомство. Потеряйте <energy> и получите <major_injury>. Затем переместите своего персонажа на случайный неисследованный участок местности, если возможно, и исследуйте его. В противном случае переместите персонажа на любой участок местности, выбрав участок с горами, если возможно.</p>"},"repeatable":false},{"id":"outcomes-449","code":"449","description":{"en":"<p>\\"You hold the light up close to the behemoth's great visage, and the mask cracks. Plunging your hand inside, you seize hold of something. Liquid gushes out of the gap, and the behemoth shakes you from its mighty head; you plummet to the ground. When you awaken, you lie in a pool of liquid, the still-beating thing you seized in your hand.\\"</p>\\n\\"Aggravate the behemoth's demeanor by 1. End the encounter. The behemoth flees. Suffer <major_injury>. \\n\\nThen, if a character, animal companion, or storage structure has an item with Symbiotic in its name, gain 2 game; otherwise, gain the Symbiotic Egg (IT93) Item card.\\"","ru":"<p><i><b>Вы поднесли свет к огромному лику чудища — и его маска треснула. Вы просунули руку внутрь разлома и что‑то нащупали. Из трещины хлынула жидкость, и чудище сбросило вас со своей массивной головы. Вы рухнули на землю. Очнувшись, вы лежали в разлитой жидкости, сжимая в руке нечто странное.</b></i></p><p>Разозлите чудище на 1. Завершите встречу. Чудище сбегает. Получите <major_injury>.</p><p>Затем, если у любого персонажа, животного-компаньона или в сооружении-хранилище есть предмет со словом «симбиотический» в названии, получите 2 дичи. В противном случае получите карту предмета «Симбиотическое яйцо» (ВЩ93).</p>"},"repeatable":false},{"id":"outcomes-452","code":"452","description":{"en":"<p>\\"Through forcing confrontation after confrontation with the new predators, you force these creatures to learn to respect humanity's strength. An uneasy detente begins in the valley.\\"</p>\\n<p>\\"At the end of the day, you may end this challenge.\\n\\nIllustrate the saga of broken fangs on the primal cave wall, including the beastslayer mark.\\"</p>","ru":"<p><i><b>Постоянно вступая в схватки с новыми хищниками, вы заставили этих созданий уважать силу человека. В долине установилось хрупкое перемирие.</b></i></p><p>В конце этого дня можете завершить текущее испытание.</p><p>На стене первобытной пещеры изобразите историю о сломанных клыках, включив в неё отметку зверобоя.</p>"},"repeatable":false,"marks":[{"label":"","image":"<beastslayer>"}]},{"id":"outcomes-461","code":"461","description":{"en":"<p>\\"The surface of the behemoth's horn grows brittle as you climb. As a chunk flakes away beneath your grip, you find something unexpected...\\"</p>\\n<p>\\"End the encounter. Aggravate the behemoth's demeanor by 1. The behemoth flees.\\n\\nThen, if a character, animal companion, or storage structure has an item with Lightless in its name, gain 2 of the behemoth's curio; otherwise, gain the Lightless Orb (IT92) Item card.\\"</p>","ru":"<p><i><b>Чем выше вы взбирались по громадному рогу чудища, тем более хрупкой становилась поверхность. Когда под вашей рукой откололся кусок рога, вы обнаружили нечто неожиданное...</b></i></p><p>Завершите встречу. Разозлите чудище на 1. Чудище сбегает. Затем, если у любого персонажа, животного-компаньона или в сооружении-<i>хранилище </i>есть предмет со словом «тёмный» в названии, получите 2 сокровища этого чудища; в противном случае получите карту предмета «Тёмный шар» (ВЩ92).</p>"},"repeatable":false},{"id":"outcomes-473","code":"473","description":{"en":"<p>\\"In the light, the behemoth's movements grow sluggish and stiff, as if a great weight bears down upon it. It slowly moves away before torpor can fully overtake it.\\"</p>\\n<p>\\"End the encounter. Placate the behemoth's demeanor by 1. The behemoth flees.\\"</p>","ru":"<p><i><b>На свету движения чудища становились вялыми и скованными, словно на него давил огромный груз. Существо медленно отходило прочь, пока оцепенение не завладело им. </b></i></p><p>Завершите встречу. Успокойте чудище на 1. Чудище сбегает.</p>"},"repeatable":false},{"id":"outcomes-475","code":"475","description":{"en":"<p>\\"Your people scrabble for an escape, searching every crag and passage for a way out of the valley that cannot be discovered. As one last winter descends, your people's saga falls quiet, its echoes fading into the winds and snow.\\"</p>\\n\\"Your society <b>vanishes</b>.\\n\\nThis end may not be a happy one, but it can still be instructive to future peoples who inhabit the valley. To immortalize a photo of your primal cave wall and see other people's works of art, we invite you to share your saga with our community!\\n\\n@[Insert Link]@\\n\\nTo continue playing Stonesaga, see Beginning Subsequent Campaigns on Rulebook p.97. Or you could switch to Endless Mode, as described on Rulebook p.97.\\"","ru":"<p><i><b>Ваш народ отчаянно искал путь к спасению, осматривая каждый уступ и проход в надежде найти выход из долины, но всё было тщетно. Когда на долину опустилась последняя зима, история вашего народа утихла и эхо её растворилось в ветре и снегах.</b></i></p><p>Завершите кампанию. Ваша община <b>исчезла</b>. См. раздел «Конец кампании» в правилах игры на с. 97.</p><p>Такой конец хоть и далёк от счастливого, но он всё же может послужить уроком для народов, которые заселят эту долину в будущем. Чтобы увековечить фотографию своей стены первобытной пещеры и увидеть произведения искусства других игроков, мы приглашаем вас поделиться своей историей с нашим сообществом!</p><p>Чтобы продолжить играть в «Наскальную историю», см. в правилах игры раздел «Начало следующих кампаний» на с. 97 или раздел «Бесконечный режим» на с. 102.</p>"},"repeatable":false,"marks":[{"label":"","image":"<qrcode>"}]},{"id":"outcomes-478","code":"478","description":{"en":"<p>The shard crashes through the canopy of clouds, burning the great sky-mountains to mist. As it collides with the earth, a great resounding crack topples trees and breaks mountains. Amidst the ruin, you see coral tendrils begin to spread. Then the vision ends.</p>\\n\\"Place an inactive coral overgrowth in a hex of your choice, choosing an unexplored hex without an overlay, if able. Roll <1d6> and place it in the corresponding zone: (1–2): A, (3–4), B, (5–6) C. Place a mystery token in that hex if there is no character there.\\n\\nThen return Diverging Paths (NY01) to the game box.\\"","ru":"<p><i><b>Осколок прорвался сквозь покров облаков, превращая огромные небесные глыбы в туман. Когда он врезался в землю, раздался оглушительный треск, поваливший деревья и расколовший горы. Среди разрушения вы увидели, как начинают расползаться коралловые побеги. Затем видение исчезло.</b></i></p><p>Поместите неактивные коралловые заросли на любой участок местности, выбрав неисследованный участок без накладок, если возможно. Бросьте <1d6>, чтобы поместить заросли в соответствующий район: [1-2] A, [3-4] Б, [5-6] В. Поместите жетон тайны на этот участок, если на нём нет персонажа. Затем верните в коробку карту «Расходящиеся пути» (НЭ01).</p>"},"repeatable":false},{"id":"outcomes-481","code":"481","description":{"en":"<p>\\"As each of the vestiges of your civilization vanishes beneath the coral, your people become unrecognizable to you. You can join those who file behind the comet's champion, or you can flee and embrace the wilds, but what you once knew is gone forever.\\"</p>\\n\\"Illustrate the saga of the inscrutable future on the primal cave wall, including the coral mark and the misfortune mark. Then, as a group, the players must choose one of the following paths for your society:\\n\\n<b>A) Enter the comet's embrace:</b> Your campaign ends and your society <b>vanishes</b>. See Ending a Campaign on Rulebook p.97.\\n\\nThis end may not be a happy one, but it can still be instructive to future peoples who inhabit the valley. To immortalize your primal cave wall and see other people's works of art, we invite you to a picture of your final primal cave wall and share your saga on our Discord! \\n\\n@[Insert Link]@\\n\\nTo continue playing Stonesaga, see Beginning Subsequent Campaigns on Rulebook p.97. Or you could switch to Endless Mode, as described on Rulebook p.97.\\n\\n<b>B) Remain yourself, at any cost:</b> Add Exodus (CZ09) to your looming challenges.\\"","ru":"<p><i><b>Когда последние следы цивилизации исчезли под кораллами, вы перестали узнавать ваш народ. Вы могли присоединиться к тем, кто шёл за избранником кометы, или сбежать и слиться с дикой природой. Но то, что вы когда‑то знали, исчезло навсегда.</b></i></p><p>Завершите текущее испытание.</p><p>На стене первобытной пещеры изобразите историю о непостижимом будущем, включив в неё отметку коралла [i] и отметку несчастья [ii]. Затем совместно выберите один из следующих путей развития общины:<br><b>А. Примите объятия кометы.</b> Завершите кампанию. Ваша община исчезла. См. раздел «Конец кампании» в правилах игры на с. 97.<br>Такой конец хоть и далёк от счастливого, но он всё же может послужить уроком для народов, которые заселят эту долину в будущем. Чтобы увековечить фотографию своей стены первобытной пещеры и увидеть произведения искусства других игроков, мы приглашаем вас поделиться своей историей с нашим сообществом! Чтобы продолжить играть в «Наскальную историю», см. в правилах игры раздел «Начало следующих кампаний» на с. 97 или раздел «Бесконечный режим» на с. 102.<br><b>Б. Останьтесь собой любой ценой. </b>Добавьте к грядущим испытаниям карту «Исход» (ИЯ09).</p>"},"repeatable":false,"marks":[{"label":"i","image":"<coral>"},{"label":"ii","image":"<misfortune>"},{"label":"","image":"<qrcode>"}]},{"id":"outcomes-482","code":"482","description":{"en":"<p>Your people are pushed to the brink by famine. This time of deprivation will long be remembered by your people.</p>\\nSubtract <population><population>. Illustrate the saga of the bitter year on the primal cave wall, including the harrowing mark. Add Fireside Grumbles (NN01) to the Night deck, if able.","ru":"<p><i><b>Ваш народ оказался на самой грани из‑за голода. Это время лишений надолго останется в памяти общины.</b></i></p><p>Завершите текущее испытание.</p><p>Уберите <population><population>. На стене первобытной пещеры изобразите историю о страшном годе, включив в неё отметку ужаса. Добавьте карту «Ворчание у костра» (НО01) в колоду ночи, если возможно.</p>"},"repeatable":false,"marks":[{"label":"","image":"<harrowing>"}]},{"id":"outcomes-484","code":"484","description":{"en":"<p>\\"Atop the behemoth's head, you cannot help but notice the way its rocky skin has grown brittle and cracked under the beating sun. You could try to patch the cracks, perhaps giving it relief.\\"</p>\\n<p>\\"End the encounter. You may discard 2 of this behemoth's curio to placate the behemoth's demeanor by 1.\\"</p>","ru":"<p><i><b>Находясь на вершине головы чудища, вы заметили, что его каменная кожа стала хрупкой и потрескалась под палящим солнцем. Вы могли бы попытаться залатать трещины, чтобы облегчить страдания существа. </b></i></p><p>Завершите встречу. Затем можете сбросить 2 сокровища этого чудища, чтобы успокоить его на 1.</p>"},"repeatable":false},{"id":"outcomes-485","code":"485","description":{"en":"<p>In the days between the epochs, the behemoth takes its vengeance. Its attack devastates one of your villages and puts its people to flight, scattering them throughout the valley. Generations grow up in fear of the beast that darkens the sky...</p>\\n\\"Choose a behemoth with an active lair in the valley and the highest demeanor. Illustrate the saga of the shuddering hours on the primal cave wall, including the harrowing mark (i) and the mark of that behemoth adorned with the wrath mark (ii). Randomly select an outpost to become a ruin. Then, as a group, the players must choose one of the following paths for your society:\\n\\n<b>A) Face the behemoth with force of arms:</b> Subtract <1d6><population>.\\n\\n<b>B) Forbid your people from interfering with behemoths henceforth:</b> Add \\\\\\"Resting in a hex with an active behemoth's lair\\\\\\" to the Taboos section of the Culture page of the Journal. Gain the Taboos (KN18) Knowledge card. Add <unrest><unrest>. Add the taboo mark (iii) to the saga you just illustrated.\\n\\n<b>C) Abandon the region where the behemoth lives:</b> Each of your outposts in the same region as the behemoth's lair becomes a ruin.\\"","ru":"<p><i><b>Когда одна эра сменяла другую, чудище обрушило на вас свою месть. Оно разорило одно из ваших поселений и обратило людей в бегство, разогнав их по всей долине. Следующие поколения выросли в страхе перед затмевавшим небо чудищем…</b></i></p><p>Выберите чудище с активным логовом и с самым высоким значением нрава. На стене первобытной пещеры изобразите историю о пугающих временах, включив в неё отметку ужаса [i] и отметку этого чудища, украшенную отметкой гнева [ii]. Случайное поселение становится руинами. Затем совместно выберите один из следующих путей развития общины:<br><b>А. Встретьте чудище с оружием. </b>Бросьте <1d6> и уберите столько <population>, сколько выпало на <1d6>.<br><b>Б. Запретите своему народу вмешиваться в дела чудищ. </b>Запишите «Отдыхать на участке с активным логовом чудища» в раздел «Табу» на странице «Культура» в журнале. Получите карту знаний «Табу» (ЗБ18), если у вас её нет. Добавьте <unrest><unrest>. Добавьте отметку табу [iii] к только что изображённой истории.<br><b>В. Покиньте регион, где обитает чудище.</b> Каждое поселение в регионе с логовом чудища становится руинами.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<harrowing>"},{"label":"ii","image":"<wrath>"},{"label":"iii","image":"<taboo>"}]},{"id":"outcomes-486","code":"486","description":{"en":"<p>\\"From the behemoth's shaggy brow, you slide down a tuft of its white hair and hold a particularly interesting item in front of its gaze. The behemoth looks on with great interest. From somewhere in its fur, a small object emerges. It seems to be offering an exchange.\\"</p>\\n\\"Choose one and resolve it:\\n\\n<b>A) Make a trade:</b> If you have a processed material or an item in your inventory, discard a processed material or an item to end the encounter. Placate the behemoth's demeanor by 1. Then, if a character, animal companion, or storage structure has an item with Symbiotic in its name, gain 2 of the behemoth's curio; otherwise, gain the Symbiotic Egg (IT93) Item card.\\n\\n<b>B) Decline to trade:</b> End the encounter. Aggravate the behemoth's demeanor by 2.\\"","ru":"<p><i><b>Вы соскользнули по белой пряди чудища, демонстрируя ему занятный предмет. Чудище с живым интересом наблюдало за вами. Откуда‑то из глубины его шерстяного покрова вдруг появилась диковинная вещь — чудище предлагало обмен.</b></i></p><p>Выберите и разыграйте одно:<br><b>А. Заключите обмен. </b>Если у вас в инвентаре есть обработанный материал или предмет, сбросьте 1 обработанный материал или предмет, чтобы завершить встречу. Успокойте чудище на 1. Затем, если у любого персонажа, животного-компаньона или в сооружении-<i>хранилище </i>есть предмет со словом «симбиотический» в названии, получите 2 сокровища чудища; в противном случае получите карту предмета «Симбиотическое яйцо» (ВЩ93).<br><b>Б. Откажитесь от обмена. </b>Завершите встречу. Разозлите чудище на 2.</p>"},"repeatable":false},{"id":"outcomes-490","code":"490","description":{"en":"<p>Your search for the source of the inky trail across the sky ends in frustration at the edges of the valley. In days to come, the smoke dissipates, fading to a memory. Perhaps your descendents will discover what eluded you...</p>\\nIllustrate the saga of the coiling smoke on the primal cave wall, including the <cloud> and mystery marks.","ru":"<p><i><b>Ваши поиски источника чёрного следа в небе завершились лишь досадой, когда вы добрались до края долины. Вскоре дым рассеялся, превратившись в воспоминание. Быть может, вашим потомкам удастся раскрыть то, что ускользнуло от вас…</b></i></p><p>Завершите текущее испытание.</p><p>На стене первобытной пещеры изобразите историю о клубящемся дыме, включив в неё отметку <cloud> и отметку тайны.</p>"},"repeatable":false,"marks":[{"label":"","image":"<mystery>"}]},{"id":"outcomes-491","code":"491","description":{"en":"<p>You catch a strange creature with a soft body and several limbs, and in its stomach, you find what might be a tool. Did this creature swallow it? Was it made by a villager or by some being unfamiliar?</p>\\n<p>\\"Gain 1 bone knife (Red 2344). Add its item code to your society's known recipes in the Recipes section of the Journal.\\"</p>","ru":"<p><i><b>Вы поймали странное существо с мягким телом и множеством конечностей и в его желудке нашли нечто похожее на орудие. Видимо, существо проглотило его. Кем же было сделано это орудие? Жителем деревни или каким‑то чужаком?</b></i></p><p>Получите предмет «Костяной нож» (ВЩ01). Запишите его код (Красный 2344) на странице «Рецепты» в журнале.</p>"},"repeatable":false},{"id":"outcomes-492","code":"492","description":{"en":"<p>\\"Your efforts to quell the behemoth permanently end in failure. Its reprisal falls like the storm, smashing your people's greatest works before it and crushing all aspirations you held for this epoch...\\"</p>\\n\\"Subtract <population> for each token on Vanquish the Behemoth. Then, illustrate the saga of ageless wrath on the primal cave wall, including the alert behemoth's mark adorned by the wrath mark (i).\\n\\nOne at a time, for each of your outposts, the players as a group must choose one and resolve it:\\n\\n<b>A) Fight to the last:</b> Roll <1d6>. Destroy that many structures of your choice in the outpost and subtract that much <population>.\\n\\n<b>B) Flee before the behemoth:</b> The outpost becomes a ruin. Subtract <population><population><population>.\\n\\n<b>C) Distract the behemoth with tribute as your people flee:</b> If the plenty mark (ii) is on the primal cave wall and two or more Secrets have been recorded in the Journal for this behemoth, the outpost becomes a ruin. You can choose this option only once.\\n\\nThen end this challenge and end the Epoch. See Codex p.204 to begin Epoch 3\\"","ru":"<p><i><b>Ваши попытки усмирить чудище окончательно потерпели неудачу. Его ответный удар обрушился словно буря, уничтожив величайшие творения вашего народа и разрушив все надежды, что вы питали…</b></i></p><p>Уберите <population> за каждый жетон на карте «Дайте отпор чудищу». Затем на стене первобытной пещеры изобразите историю о вечном гневе, включив в неё отметку бодрствующего чудища, украшенную отметкой гнева [i]. </p><p>Поочерёдно для каждого из поселений совместно выберите один из следующих вариантов и разыграйте его:<br><b>А. Сражайтесь до конца. </b>Бросьте <1d6>. Разрушьте столько любых сооружений в поселении и уберите столько <population>, какой результат выпал на  <1d6>.<br><b>Б. Бегите от чудища. </b>Поселение становится руинами. Уберите <population><population><population>.<br><b>В. Отвлеките чудище подношением, пока ваш народ спасается бегством. </b>Если на стене первобытной пещеры есть отметка изобилия [ii] и в журнале записано хотя бы 2 секрета этого чудища, поселение становится руинами. Этот вариант можно выбрать только один раз.</p><p>Затем завершите текущие испытание и эру. См. с. 204, чтобы начать эру 3.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<wrath>"},{"label":"ii","image":"<plenty>"}]},{"id":"outcomes-493","code":"493","description":{"en":"<p>\\"You have encountered the outsiders. As you approach, they signal for you to halt. You'll have to win their trust if you wish to establish deeper relations.\\"</p>\\n\\"Embark on the venture below (see Ventures on Rulebook p.60).\\n\\n<bi>Approaching the camp, you find its inhabitants wary. Someone must be the first to break the tense silence.</bi>\\n<b>Champion:</b> Someone must test <conviction> or <awareness> to greet the newcomers. Add +2 if you are <i>patient</i>. You may discard up to 2 food tokens from your inventory. If you do, add +2 per food discarded.\\n12+: The strangers respond to your greeting in kind. The venture continues.\\n1–11: The tension does not abate in the slightest. Add <unrest>, then the venture fails unless a character spends <energy><energy> or <lore> to attempt this test again.\\n\\n<bi>Having made a good first impression, you approach their fire. The inhabitants of the camp speak in a language that is comprehensible to you, but not entirely familiar. You must learn their customs to maintain their good will.</bi>\\n<b>Group:</b> Everyone must test <awareness> to find common ground. A character adds +2 if they have a Legend card and +4 if they have <music>.\\n11+: You discover that there is much that connects your people with these supposed outsiders. If any character resolves this result, the venture continues.\\n1–10: You must have split from these people in the truly distant past, for you can find little to link you. If all characters on the venture resolve this result, the venture fails unless a character discards a Legend card or spends <lore><lore><lore> to attempt this test again.\\n\\n<bi>You feel comfortable with the outsiders, but you have still only just met. To be invited to their home, you will need to present a gift that shows your good intentions.</bi>\\n<b>Champion:</b> Someone must test <conviction> and discard an item or material to present a gift. Add +2 if you are <i>resourceful</i>. If you discarded an item, add +2. If you discarded a rare material, add +4.\\n12+: The outsiders present you with a fine gift in return. Put 1 coral, 1 moonblood, and 1 silk the the draw bag, then draw one material from the draw bag and gain it in its unprocessed state. Complete this venture and the associated goal.\\n1–11: The strangers seem unimpressed by your offer. Add <unrest><unrest>. The venture fails unless a character spends <energy><energy> or <lore> to attempt this test again.\\"","ru":"<p><i><b>Вы столкнулись с чужаками. Когда вы подошли, они жестами велели вам остановиться. Чтобы наладить более тесные отношения, придётся завоевать их доверие.</b></i></p><p>Отправьтесь в поход (см. раздел «Походы» в правилах игры на с. 60).</p><p><i><b>Обитатели лагеря казались вам настороженными. Кто‑то должен был первым прервать тишину.</b></i></p><p><b>Защитник. </b>Один из персонажей в походе должен провести проверку <conviction> или <awareness>, чтобы поприветствовать незнакомцев. +2, если он <i>терпеливый</i>, и +2 за каждый жетон еды, который он сбросит из своего инвентаря (не более +4).<br><b>≥12:</b>  Незнакомцы тепло ответили на ваше приветствие. Продолжите поход.<br><b>1-11:</b>  Напряжение ничуть не спало. Добавьте <unrest>. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy> или <lore>, чтобы провести проверку ещё раз.</p><p><i><b>Вы произвели хорошее первое впечатление на незнакомцев и подошли к костру. Обитатели лагеря говорили на языке, который был вам знаком, но всё же не до конца понятен. Чтобы сохранить расположение незнакомцев, вам нужно было узнать их обычаи.</b></i></p><p>Группа. Все персонажи в походе должны провести проверку <awareness>, чтобы найти общий язык. +2, если у персонажа есть карта легенды, и +4, если у него есть <music>.<br><b>≥11:</b>  Вы узнали, что между вашим народом и этими чужаками много общего. Если хотя бы один персонаж получил этот результат, продолжите поход.<br><b>1-10:</b>  Видимо, ваши народы разошлись в очень далёком прошлом, потому что вы нашли мало общего. Если все персонажи получили этот результат, поход окончился неудачно, если только любой персонаж в походе не сбросит карту легенды или не потратит <lore><lore><lore>, чтобы провести проверку ещё раз.</p><p><i><b>Вы почувствовали себя комфортно среди чужаков, но знакомство всё ещё было слишком поверхностным. Чтобы вас пригласили в дом, нужно было преподнести дар, который показал бы ваши добрые намерения.</b></i></p><p><b>Защитник. </b>Один из персонажей в походе должен провести проверку <conviction> и сбросить предмет или материал, чтобы преподнести дар. +2, если персонаж изобретательный. Также +2, если он сбросит предмет, либо +4, если сбросит редкий материал.<br><b>≥12:</b>  Чужаки ответили вам щедрым подарком. Положите 1 коралл, 1 лунную кровь и 1 шёлк в мешочек, затем достаньте один материал из мешочка и получите его в необработанном виде. Завершите этот поход и достигните соответствующей цели.<br><b>1-11:</b>  Чужаки, похоже, остались равнодушны к вашему дару. Добавьте <unrest><unrest>. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy> или <lore>, чтобы провести проверку ещё раз.</p>"},"repeatable":false},{"id":"outcomes-494","code":"494","description":{"en":"<p>People fall ill in new places, seemingly walking the paths your people travel between the villages.</p>\\n\\"For each hex with an outpost, roll <1d6>. Add +2 if there is a Waste Pit in the outpost.\\n1–2: Add an outbreak to this hex, then each character in this hex suffers <major_disease>.\\n3–4: Add outbreak to this hex.\\n5+: No effect.\\"","ru":"<p><i><b>Люди заболевали повсюду, словно болезнь передвигалась теми же тропами, по которым ваш народ ходил между поселениями.</b></i></p><p>За каждый участок местности с поселением бросьте <1d6>. +2, если в поселении есть мусорная яма.<br><b>1-2:</b>  Поместите вспышку болезни на этот участок местности. Затем каждый персонаж на этом участке получает <major_disease>. <br><b>3-4:</b>  Поместите вспышку болезни на этот участок местности.<br><b>≥5:</b>  Без эффекта.</p>"},"repeatable":false},{"id":"outcomes-495","code":"495","description":{"en":"<p>\\"You dodge through the perilous spines on the behemoth's back to reach the safety of its mane. Reaching the apex of the shell, you are startled to see the behemoth's head twisted and face-to-face with you. Thinking quickly, you ponder the tribute you have available...\\"</p>\\n\\"Choose one and resolve it:\\n\\n<b>A) Hand over a fine-wrought material:</b> If you have a processed material in your inventory, discard 1 processed material to gain <major_boost> to an attribute of your choice.\\n\\n<b>B) Pull some tattered scraps of fur and fiber from the bottom of your pouch:</b> Aggravate the behemoth's demeanor by 1.\\n\\nThen, end the encounter.\\"","ru":"<p><i><b>Вы лавировали среди опасных шипов на спине чудища, чтобы добраться до его гривы. Оказавшись на вершине панциря, вы с удивлением заметили, что голова чудища склонилась прямо к вам и вы оказались с ним лицом к лицу. Нужно было быстро решать, какой дар вы готовы предложить…</b></i></p><p>Выберите и разыграйте одно:<br><b>А. Отдайте обработанный материал. </b>Сбросьте 1 обработанный материал, чтобы получить <major_boost> к любой характеристике.<br><b>Б. Достаньте со дна сумы потрёпанные лоскуты меха и волокон. </b>Разозлите чудище на 1.</p><p>Затем завершите встречу.</p>"},"repeatable":false},{"id":"outcomes-497","code":"497","description":{"en":"<p>You are unsure what this might mean, but it cannot bode well.</p>\\n<p>Add The Sky Descends (CC04) to your looming challenges.</p>","ru":"<p><i><b>Вы не были уверены, что это может значить, но понимали, что ничего хорошего это не сулит.</b></i></p><p>Добавьте карту «Падение небес» (ИВ04) к грядущим испытаниям.</p>"},"repeatable":false},{"id":"outcomes-498","code":"498","description":{"en":"<p>The behemoth that prowls the valley grows bolder.</p>\\nEach alert behemoth gains <major_boost> to each of its attributes.","ru":"<p><i><b>Чудище, что рыскало по долине, становилось всё смелее.</b></i></p><p>Каждое бодрствующее чудище получает <major_boost> ко всем своим характеристикам.</p>"},"repeatable":false},{"id":"outcomes-499","code":"499","description":{"en":"<p>The behemoth finishes its excavation, apparently satisfied in whatever it accomplished. An icy berm has formed where it undertook its digging.</p>\\n<p>\\"Place an active icy wake overlay in one hex of your choice with a trace marker. For each overlay you place this way, choose a zone without an overlay and with a chasm, if able. See Codex p.212 for the icy wake rules.\\n\\nThen, remove all of this behemoth's trace markers from the valley. Assign the Return to Slumber (BT20) instinct to this behemoth (replacing its previous instinct).\\"</p>","ru":"<p><i><b>Чудище завершило раскопки и, похоже, было довольно результатом. Там, где оно копало, образовался ледяной вал. </b></i></p><p>Поместите накладку ледяного отпечатка активной стороной вверх на любой участок местности с жетоном следов. Выберите район без накладки, но с пропастью, если возможно. См. правила ледяного отпечатка на с. 212.</p><p>Затем уберите жетон направления и все жетоны следов этого чудища. Замените его текущий инстинкт на «Вернуться в забытьё» (ЧК20).</p>"},"repeatable":false},{"id":"outcomes-502","code":"502","description":{"en":"<p>\\"Your people's fear of the scar makes it hard to approach the impact site. You must avoid panicked bands of citizens to even reach the relative safety of the scar...\\"</p>\\n\\"Embark on the venture below (see Ventures on Rulebook p.60).\\n\\n<bi>The patrol nears you, but perhaps you can find cover to help avoid them...</bi>\\n<b>Group, Hazard:</b> Everyone must test <dexterity> to evade pursuers. Add +4 if there is a cave or chasm in an adjacent hex, +2 if you have a <i>cloak</i> item, and +2 if you are <i>cunning</i>.\\n12+: You avoid the patrol. Gain <minor_boost> to <conviction>. Then continue this venture by <outcome> 622.\\n10–11: You are chased for some distance, but manage to give your pursuers the slip. Add <unrest>. Continue the venture by <outcome> 622.\\n1–9: You scuffle with your pursuers before breaking free. Suffer <major_injury>, then add <unrest><unrest>. You leave the venture, then flee. If all characters on the venture resolve this result, the venture fails.\\"","ru":"<p><i><b>Всего лишь мысль о кратере отпугивала ваших людей от места падения. Чтобы чувствовать себя в безопасности, вам приходилось держаться подальше от паникёров на своём пути к кратеру…</b></i></p><p>Отправьтесь в поход (см. раздел «Походы» в правилах игры на с. 60). </p><p><i><b>Дозорные были уже совсем близко, но возможно, вам удастся найти укрытие, чтобы спрятаться от них…</b></i></p><p><b>Группа, угроза.</b> Все персонажи в походе должны провести проверку <dexterity>, чтобы уйти от преследователей. +4, если на соседнем с персонажами участке местности есть пещера или пропасть, +2, если у персонажа есть <i>накидка</i>, и +2, если он <i>хитрый</i>.<br><b>≥12:</b>  Вы избежали столкновения с дозорными. Получите <minor_boost> к  <conviction>. Затем продолжите этот поход: <outcome> 622.<br><b>10-11:</b>  Дозорные преследовали вас какое-то время, пока не сбились со следа. Добавьте <unrest>. Затем продолжите этот поход: <outcome> 622.<br><b>1-9:</b>  Вы сцепились с преследователями, прежде чем вырваться на свободу. Получите <major_injury>, затем добавьте <unrest><unrest>. Покиньте поход и сбегите. Если все персонажи получили этот результат, поход окончился неудачно.</p>"},"repeatable":false},{"id":"outcomes-503","code":"503","description":{"en":"<p>\\"You know that the reverberations stem from the valley's strange underworld, and precede the rise of new coral outgrowths. Searching about, you find a pearlescent tendril and quickly harvest it once it goes dormant.\\"</p>\\n<p>Gain 1 dead coral. If the coral mark is on the primal cave wall, gain 2 dead coral instead.</p>","ru":"<p><i><b>Вы знали, что эти вибрации исходят из странного подземного мира долины и предвещают появление новых коралловых зарослей. Обыскивая окрестности, вы нашли перламутровый отросток и быстро срезали его, пока тот был спящим.</b></i></p><p>Получите 1 мёртвый коралл. Если на стене первобытной пещеры есть отметка коралла, вместо этого получите 2 мёртвых коралла.</p>"},"repeatable":false,"marks":[{"label":"","image":"<coral>"}]},{"id":"outcomes-504","code":"504","description":{"en":"<p>A great behemoth arrives in the valley.</p>\\n<p>\\"Randomly select a behemoth without a lair in the valley. Illustrate the saga of the great arrival on the primal cave wall, including that behemoth's mark. Then, that behemoth arrives in the valley; it becomes alert (see Behemoth Arrival on Rulebook p.74). Place its lair in a hex, choosing one without an overlay and with one or more of its affinity features, if able.\\"</p>","ru":"<p><i><b>Громадное чудище появилось в долине.</b></i></p><p>Выберите случайное чудище, у которого нет логова в долине. На стене первобытной пещеры изобразите историю о великом появлении, включив в неё отметку этого чудища. Затем это чудище появляется в долине и становится бодрствующим (см. раздел «Появление чудища» в правилах игры на с. 74). Поместите его логово активной стороной вверх на участок местности без накладки и с его предпочитаемой особенностью местности, если возможно.</p>"},"repeatable":false},{"id":"outcomes-505","code":"505","description":{"en":"<p>The effort is the work not just of one generation but many. You have begun the process, but you realize it will be the task of your descendents to see it through. Still, the plants you favor flourish across the valley in small pockets, growing more numerous year over year.</p>\\n\\"You may end this challenge at the end of any day.\\n\\nThen, as a group, the players must choose one of the following paths for your society:\\n\\n<b>A) Focus on the forests:</b> If there is at least 1 Verdant Vale hex in the valley, add <population><population><population>. Then illustrate the saga of the tree-shapers on the primal cave wall, including the following marks: herbalism (iii), plenty (iv), Verdant Vale (i). Add FF13 to the Forest Foraging deck, if able.\\n\\n<b>B) Focus on the prairies:</b> If there is at least 1 Skyreach Plateau hex in the valley, add <population><population><population>. Then illustrate the saga of the plains-keepers on the primal cave wall, including the following marks: herbalism (iii), plenty (iv), Skyreach Plateau (ii). Add FP13 to the Priarie Foraging deck, if able.\\n\\n<b>C) Focus on the Tangle (If Available):</b> If there is at least 1 Tangle hex in the valley (and this region is available), add <population><population><population>. Then illustrate the saga of the floral bloom on the primal cave wall, including the following marks: herbalism (iii), plenty (iv), Tangle (v). Add FT13 to the Glade Foraging deck, if able.\\n\\n<b>D) Shun the red flesh of earthly beasts:</b> Add <population><population><population><population>. Illustrate the saga of the land's promise on the primal cave wall, including the following marks: herbalism (iii), plenty (iv), taboo (vi). Add \\\\\\"One or more characters eat game at night\\\\\\" to the Taboos section of the Culture page of the Journal. Gain the Taboos Knowledge card. Add the herbalism mark (i) to the Legend side of each Character card.Then resolve as many of the following as you are able: \\n\\n1) If there is at least 1 Verdant Vale hex in the valley, add FF13 to the Forest Foraging deck\\n\\n2) If there is at least 1 Skyreach Plateau hex in the valley, add FP13 to the Prairie Foraging deck. \\n\\n3) If there is at least 1 Tangle hex in the valley (and this region is available), add FT13 to the Glade Foraging deck.\\"","ru":"<p><i><b>Это был труд не одного поколения: пусть вы и начали это дело, но довести его до конца предстояло уже вашим потомкам. Растения, выбранные вами, расцвели в долине небольшими островками, и год за годом их становилось всё больше.</b></i></p><p>В конце любого дня можете завершить текущее испытание.</p><p>Затем совместно выберите один из следующих путей развития общины:<br><b>А. Сосредоточьтесь на изучении лесов. </b>Если в долине есть хотя бы 1 участок Дивной долины, добавьте <population><population><population>. Затем на стене первобытной пещеры изобразите историю о резцах по дереву, включив в неё отметку травничества [iii], отметку изобилия [iv] и отметку Дивной долины [i]. Добавьте карту ДЛ13 в колоду добычи припасов в лесу, если возможно.<br><b>Б. Сосредоточьтесь на изучении степей. </b>Если в долине есть хотя бы 1 участок Поднебесной равнины, добавьте <population><population><population>. Затем на стене первобытной пещеры изобразите историю о хранителях равнин, включив в неё отметку травничества [iii], отметку изобилия [iv] и отметку Поднебесной равнины [ii]. Добавьте карту ДС13 в колоду добычи припасов в степи, если возможно.<br><b>В. Сосредоточьтесь на изучении Сплетения (если доступно). </b>Если в долине есть хотя бы 1 участок Сплетения, добавьте <population><population><population>. Затем на стене первобытной пещеры изобразите историю о цветущих лугах, включив в неё отметку травничества [iii], отметку изобилия [iv] и отметку Сплетения [v]. Добавьте карту ДП13 в колоду добычи припасов на полянах, если возможно.<br><b>Г. Откажитесь от красного мяса. </b>Добавьте <population><population><population><population>. На стене первобытной пещеры изобразите историю об обещании земли, включив в неё отметку травничества [iii], отметку изобилия [iv] и отметку табу [vi]. Запишите «Есть дичь ночью» в раздел «Табу» на странице «Культура» в журнале. Получите карту знаний «Табу» (ЗБ18), если у вас её нет. Добавьте отметку травничества на сторону легенды карты каждого персонажа. Затем разыграйте как можно больше из следующего:<br>1. Если в долине есть хотя бы 1 участок Дивной долины, добавьте карту ДЛ13 в колоду добычи припасов в лесу.<br>2. Если в долине есть хотя бы 1 участок Поднебесной равнины, добавьте карту ДС13 в колоду добычи припасов в степи<br>3. Если в долине есть хотя бы 1 участок Сплетения, добавьте карту ДП13 в колоду добычи припасов на полянах.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<verdantvale>"},{"label":"ii","image":"<skyreachplateau>"},{"label":"iii","image":"<herbalism>"},{"label":"iv","image":"<plenty>"},{"label":"v","image":"<tangle>"},{"label":"vi","image":"<taboo>"}]},{"id":"outcomes-506","code":"506","description":{"en":"<p>The behemoth fixates on the peals of thunder.</p>\\n\\"Choose one of the following and resolve it:\\n\\n<b>A) Make a noise to intimidate the behemoth:</b> If you have <music>, end the encounter. Aggravate the behemoth's demeanor by 2. The behemoth flees.\\n\\n<b>B) Stand in silence:</b> If you have <conviction> 3 or higher, end the encounter. Then, if a character, animal companion, or storage structure has an item with Incandescent in its name, gain 2 of the behemoth's curio; otherwise, gain the Incandescent Blood (IT99) Item card.\\n\\n<b>C) Make a hasty retreat:</b> End the encounter. You flee.\\"","ru":"<p><i><b>Чудище сосредоточилось на раскатах грома.</b></i></p><p>Выберите и разыграйте одно:<br><b>А. Поднимите шум, чтобы напугать чудище. </b>Если у вас есть <music>, завершите встречу. Разозлите чудище на 2. Чудище сбегает.<br><b>Б. Затаите дыхание. </b>Если ваше значение <conviction>  равно хотя бы 3, завершите встречу. Затем, если у персонажа, животного-компаньона или в сооружении-хранилище есть предмет со словом «пламенный» в названии, получите 2 сокровища этого чудища; в противном случае получите карту предмета «Пламенная кровь» (ВЩ99).<br><b>В. Поспешно отступите. </b>Завершите встречу и сбегите.</p>"},"repeatable":false},{"id":"outcomes-508","code":"508","description":{"en":"<p>A foothold in the valley eludes your people, and you must weather a harsh winter without a permanent home. Still, there may be hope for you in this valley.</p>\\nSubtract <population><population><population>. Add A Place of Solace (CA03) to your looming challenges.","ru":"<p><i><b>Вашему народу не удалось обосноваться в долине, и без постоянного пристанища вам предстояло пережить суровую зиму. Но возможно, для вас в этих землях ещё таилась надежда.</b></i></p><p>Завершите текущее испытание.</p><p>Уберите <population><population><population>. Добавьте карту «Прибежище» (ИA03) к грядущим испытаниям.</p>"},"repeatable":false},{"id":"outcomes-509","code":"509","description":{"en":"<p>Standing beneath the thrashing behemoth, you play a calming note. The behemoth peers down at you, its curiosity almost too great to bear. Yet it stills, allowing you to withdraw as your notes flow forth. From high above you, a massive bloom floats down and opens to reveal something unexpected.</p>\\n<p>\\"End the encounter. Placate the behemoth's demeanor by 1. The behemoth flees. \\n\\nThen, if a character, animal companion, or storage structure has an item with Whispering in its name, gain 2 of the behemoth's curio. Otherwise, gain the Whispering Strands (IT87) Item card.\\"</p>","ru":"<p><i><b>Стоя под неистовствующим чудищем, вы сыграли умиротворяющую мелодию. Чудище склонило голову — его любопытству не было предела. Впитывая звуки вашей музыки, оно успокоилось и отступило. Когда оно уходило прочь, огромный бутон, оторвавшийся от тела чудища, опустился и раскрылся перед вами — в его лепестках скрывалось нечто неожиданное.</b></i></p><p>Завершите встречу. Успокойте чудище на 1. Чудище сбегает. Затем, если у персонажа, животного-компаньона или в сооружении-<i>хранилище </i>есть предмет со словом «шепчущий» в названии, получите 2 сокровища этого чудища; в противном случае получите карту предмета «Шепчущие нити» (ВЩ87).</p>"},"repeatable":false},{"id":"outcomes-511","code":"511","description":{"en":"<p>The behemoth has left behind a winding trail of spiraling furrows in the earth. As you observe the wending path, you begin to wonder if it is recording something in its trails...</p>\\n\\"Choose one of the following and resolve it:\\n\\n<b>A) Study the strange mark:</b> If the behemoth has an unrevealed Secret card assigned to it, reveal this behemoth's currently assigned Secret card, then record it under the Secrets for that behemoth in the Journal.\\n\\n<b>B) Look for the marks of your people's history in the pattern:</b> Gain the Legends (KN15) Knowledge card if you do not have it, then draw a Legend card. If you have a Legend card, you may instead choose a Legend card that your society has forgotten and return it to your society's Legends, then choose mark on that card and add it to the Legend side of your Character card.\\"","ru":"<p><i><b>Чудище оставило за собой извилистую цепочку спиральных борозд на земле. Наблюдая за этим петляющим узором, вы начали задумываться: не записывает ли оно что‑то своими следами?..</b></i></p><p>Выберите и разыграйте одно:<br><b>А. Изучите странный след. </b>Если у чудища есть неоткрытая назначенная карта секрета, откройте её. Затем запишите её в раздел секретов этого чудища в журнале.<br><b>Б. Найдите в этом узоре следы истории своего народа.</b> Получите карту знаний «Легенды» (ЗБ15), если у вас её нет, и возьмите 1 карту легенды. Если у вас уже есть карта легенды, вместо этого можете выбрать легенду из забытых вашей общиной, добавить одну из её отметок на сторону легенды карты своего персонажа и вернуть эту карту в колоду легенд.</p>"},"repeatable":false},{"id":"outcomes-512","code":"512","description":{"en":"<p>\\"The great hunt's failure leaves your people uncertain of what the future portends. While your harvest is sufficient to keep your people fed, winter's fangs bite deep into the spirits of your people this year.\\"</p>\\nAdd <unrest><unrest><unrest><unrest>. Illustrate the saga of the failed hunt on the primal cave wall, including the misfortune mark.","ru":"<p><i><b>Череда неудач во время великой охоты заставила ваш народ задуматься о том, сможет ли община пережить ближайшую зиму. Хоть урожая и хватило бы, чтобы прокормить людей, надвигающиеся холода заставляли людей сомневаться в этом.</b></i></p><p>Завершите текущее испытание.</p><p>Добавьте <unrest><unrest><unrest><unrest>. На стене первобытной пещеры изобразите историю о неудавшейся охоте, включив в неё отметку несчастья.</p>"},"repeatable":false,"marks":[{"label":"","image":"<misfortune>"}]},{"id":"outcomes-514","code":"514","description":{"en":"<p>The legend offers to take up your struggle, walking in the world once again to face the great crisis of the day. However, there is a cost: you will vanish into the mists of legend.</p>\\n<p>Choose a Legend card and copy all information from it onto a new Character card except the Legend box. Then check the Legend box on your current Character card. Finally, replace your current Character card with the new card you just created.</p>","ru":"<p><i><b>Легенда согласилась взвалить на свои плечи ваши невзгоды и вновь выйти в мир, чтобы встретиться с великим испытанием лицом к лицу. Однако за это придётся заплатить: вы исчезнете в тумане времён.</b></i></p><p>Выберите карту легенды и перепишите с неё все сведения на карту нового персонажа, не отмечая клетку легенды. Затем отметьте клетку легенды на карте своего персонажа и замените карту своего персонажа на только что созданную.</p>"},"repeatable":false},{"id":"outcomes-515","code":"515","description":{"en":"<p>\\"You begin to speak, and the fur ripples along the behemoth's body as it grows calm. As you conclude your story, a tuft of the behemoth's fur reaches out and brushes you, signaling recognition of your intentions.\\"</p>\\n\\"Placate the behemoth's demeanor by 1. Gain <major_boost> to two attributes of your choice. Then, end the encounter.\\"","ru":"<p><i><b>Вы начали говорить и заметили, как вздрагивает шерсть на теле чудища, пока оно успокаивается. Когда вы закончили свой рассказ, несколько волосков чудища слегка коснулись вас, давая понять, что оно уразумело ваши намерения.</b></i></p><p>Успокойте чудище на 1. Получите <major_boost> к двум любым характеристикам. Затем завершите встречу.</p>"},"repeatable":false},{"id":"outcomes-516","code":"516","description":{"en":"<p>A deep gash in the earth indicates a place the behemoth knelt close to the earth to observe some unfathomable signal.</p>\\n\\"Choose one of the following and resolve it:\\n\\n<b>A) Consider the deep gash:</b> If the behemoth has an unrevealed Secret card assigned to it, reveal this behemoth's currently assigned Secret card, then record it under the Secrets for that behemoth in the Journal.\\n\\n<b>B) Tap on the ground to signal to the behemoth:</b> The behemoth gains <minor_boost> to one of its attributes of your choice. If your hex has <shelter>, add <major_boost> instead.\\"","ru":"<p><i><b>В глубокой расселине в земле угадывалось место, где чудище склонилось, внимая какому‑то непостижимому зову.</b></i></p><p>Выберите и разыграйте одно:<br><b>А. Присмотритесь к глубокой расселине. </b>Если у чудища есть неоткрытая назначенная карта секрета, откройте её. Затем запишите её в раздел секретов этого чудища в журнале.<br><b>Б. Постучите по земле, чтобы подать сигнал чудищу. </b>Чудище получает <minor_boost> к любой характеристике. Если на вашем участке местности есть <shelter>, вместо этого чудище получает <major_boost> к любой характеристике.</p>"},"repeatable":false},{"id":"outcomes-517","code":"517","description":{"en":"<p>\\"The behemoth's hand descends, knocking the light from your eyes. When your scattered senses return, you are in darkness. The sound of breaking stones emanates from the walls around you. You are inside the behemoth. Knowing you must act quickly, you begin casting about in the dark. The stone beneath you vibrates slightly, and you follow the intensifying vibration until you find a smooth substance. Pulling on it with all your might, you yank it loose from the wall. A great bellow erupts from the depths of the behemoth, hurling you from inside its mount to the ground. You black out, and when you awaken, your hand still clasps the anomalous material tightly...\\"</p>\\n<p>\\"End the encounter. Aggravate the behemoth's demeanor by 1. The behemoth flees.\\n\\nThen, if a character, animal companion, or storage structure has an item with Lightless in its name, gain 2 of the behemoth's curio; otherwise, gain the Lightless Orb (IT92) Item card.\\"</p>","ru":"<p><i><b>Тяжёлая лапа чудища обрушилась на вас, разом погрузив мир в непроглядную мглу. Когда вы пришли в себя, вокруг не было видно ни зги. Из стен, окружавших вас, доносился звук крошащихся камней. Вы поняли, что находились внутри чудища, и немедля начали искать в темноте хоть что‑то, что сможет помочь вам выбраться. Каменный пол под вами слабо вибрировал, и вы последовали за нарастающими толчками, исходящими от него, пока не нащупали мягкую гладкую поверхность. Вы вцепились в неё и, собравшись с силами, вырвали её из стены. Раздался громовой рёв, волна от которого вышвырнула вас из пасти чудища на землю. Вы потеряли сознание, а очнувшись, обнаружили, что всё ещё сжимаете в руке какой‑то странный материал…</b></i></p><p>Завершите встречу. Разозлите чудище на 1. Чудище сбегает. Затем, если у персонажа, животного-компаньона или в сооружении-<i>хранилище </i>есть предмет со словом «тёмный» в названии, получите 2 сокровища чудища; в противном случае получите карту предмета «Тёмный шар» (ВЩ92).</p>"},"repeatable":false},{"id":"outcomes-521","code":"521","description":{"en":"<p>The scar in the earth left behind by the behemoth carefully avoids a single tree. Standing by the tree, you hear a nest of birds, their lilting song rising to the heavens. Did this behemoth spare the birds for their song?</p>\\n\\"Choose one of the following and resolve it:\\n\\n<b>A) Observe the weaving pattern:</b> If the behemoth has an unrevealed Secret card assigned to it, reveal this behemoth's currently assigned Secret card, then record it under the Secrets for that behemoth in the Journal.\\n\\n<b>B) Listen to the birdsong intently to understand the behemoth's action:</b> Add <minor_boost> to <awareness>, or <major_boost> to <awareness> if you have <music>. Add the songweaver mark to the Legend side of your Character card.\\"","ru":"<p><i><b>Трещина в земле, оставленная чудищем, осторожно огибала одно‑единственное дерево. У его подножия была слышна птичья трель, лёгкая и певучая, словно возносившаяся к небесам. Неужели чудище пощадило этих птиц ради их песни?</b></i></p><p>Выберите и разыграйте одно:<br><b>А. Понаблюдайте за узором переплетений. </b>Если у чудища есть неоткрытая назначенная карта секрета, откройте её. Затем запишите её в раздел секретов этого чудища в журнале.<br><b>Б. Вслушайтесь в птичью песню, пытаясь понять поступок чудища. </b>Добавьте <minor_boost> к <awareness>. Если у вас есть <music>, вместо этого добавьте <major_boost> к <awareness>. Добавьте отметку песнопевца на сторону легенды карты своего персонажа.</p>"},"repeatable":false,"marks":[{"label":"","image":"<songweaver>"}]},{"id":"outcomes-525","code":"525","description":{"en":"<p>The behemoth fled swiftly here, its tracks deep and angled as its hooves carved across the ground.</p>\\n\\"Choose one of the following and resolve it: \\n\\n<b>A) Follow the tracks to learn why it moved so swiftly:</b> If the behemoth has an unrevealed secret assigned to it, reveal it and record it under the Secrets for that behemoth in the Journal.: \\n\\n<b>B) Look within the tracks:</b> If <cloud> is a current omen, gain 3 water and a <minor_boost> to <dexterity> or <awareness>.\\"","ru":"<p><i><b>Чудище стремительно бежало отсюда — там, где его копыта рассекали землю, оставались глубокие и скошенные следы.</b></i></p><p>Выберите и разыграйте одно:<br><b>А. Пройдите по следам и узнайте, почему оно так спешило. </b>Если у чудища есть неоткрытая назначенная карта секрета, откройте её. Затем запишите её в раздел секретов этого чудища в журнале.<br><b>Б. Вглядитесь в следы. </b>Если <cloud>— текущее знамение, получите 3 воды и <minor_boost> к <dexterity> или <awareness>.</p>"},"repeatable":false},{"id":"outcomes-528","code":"528","description":{"en":"<p>\\"High on the behemoth's crown, you tap the horns and the behemoth turns, as if looking for something invisible behind it...\\"</p>\\n\\"Choose one of the following and resolve it:\\n\\n<b>A) As you continue tapping to a rhythm, it begins trudging in that direction:</b> End the encounter, and the behemoth flees. You may place your character in the hex into which it flees (without drawing a Journey card). Then, aggravate the behemoth's demeanor by 2 unless the hex you moved to has <shelter>.\\n\\n<b>B) Slide off to safety once it's distracted:</b> End the encounter, and the behemoth flees. Then, aggravate the behemoth's demeanor by 1 unless your hex has <shelter>.\\"","ru":"<p><i><b>Взобравшись на темя чудища, вы постучали по рогам — существо повернулось, будто пытаясь найти что‑то невидимое у себя за спиной…</b></i></p><p>Выберите и разыграйте одно:<br><b>А. Продолжите ритмично стучать, направляя чудище в одну сторону. </b>Завершите встречу. Чудище сбегает. Можете переместить своего персонажа на участок местности, куда сбежало чудище (не берите карту пути). Затем разозлите чудище на 2, если на участке местности, на который вы переместились, нет <shelter>.<br><b>Б. Соскользните в безопасное место, как только чудище отвлечётся. </b>Завершите встречу. Чудище сбегает. Затем разозлите чудище на 1, если на вашем участке местности нет <shelter>.</p>"},"repeatable":false},{"id":"outcomes-531","code":"531","description":{"en":"<p>The behemoth regards you with what you hope is interest, and not hunger. Knowing that it responds to memories, you begin to recount a story...</p>\\n\\"Choose one and resolve it:\\n\\n<b>A) Recount a legend:</b> If you have a Legend card, discard a Legend card to end the encounter. Placate the behemoth's demeanor by 1. Then, if a character, animal companion, or storage structure has an item with Whispering in its name, gain 1 of the behemoth's curio; otherwise, gain the Whispering Strands (IT87) Item card.\\n\\n<b>B) Spin a new tale:</b> If you have a boost to <awareness> or <conviction>, degrade that boost to end the encounter.\\n\\n<b>C) Come up with nothing:</b> End the encounter. Aggravate the behemoth's demeanor by 1.\\"","ru":"<p><i><b>Чудище смотрело на вас — и вам оставалось лишь надеяться, что оно не увидит в вас добычу. Зная, что его успокаивают воспоминания, вы начали рассказывать историю…</b></i></p><p>Выберите и разыграйте одно:<br><b>А. Поведайте легенду. </b>Если у вас есть карта легенды, сбросьте её, чтобы завершить встречу. Успокойте чудище на 1. Затем, если у персонажа, животного-компаньона или в сооружении-хранилище есть предмет со словом «шепчущий» в названии, получите 2 сокровища чудища; в противном случае получите карту предмета «Шепчущие нити» (ВЩ87).<br><b>Б. Сочините новую историю. </b>Если у вас есть усиление <awareness> или <conviction>, уменьшите это усиление, чтобы завершить встречу. <br><b>В. Промолчите. </b>Завершите встречу. Разозлите чудище на 1.</p>"},"repeatable":false},{"id":"outcomes-544","code":"544","description":{"en":"<p>\\"Your persistence and grit keep allow you to keep harvesting despite the coral's growing influence. In doing so, you make the regions where you forage slightly less dangerous for your people.\\"</p>\\n\\"Illustrate the saga of determination on the primal cave wall, including the coral mark (i) and the discovery mark (ii). Resolve as many of the following as you are able:\\n\\n<b>A) You learn to slip through the trees with the grace of a shadow:</b> If there is at least one Verdant Vale hex in the valley, remove FF06 from the Forest Foraging deck and place it in the game box. \\n\\n<b>B) You stalk the prairies low to the grass. avoiding detection:</b> If there is at least one Skyreach Plateau hex in the valley, remove FP06 from the Prairie Foraging deck and place it in the game box.\\n\\n<b>C) You glide through the Tangle's high canopy, avoiding the worst threats:</b> If there is at least one Tangle hex in the valley, remove FT06 from the Glade Foraging deck (if this region is available) and place it in the game box.\\"","ru":"<p><i><b>Ваши несгибаемая воля и упорство помогали добывать ресурсы, даже когда влияние коралла крепло. И чем больше вы работали, тем безопаснее становились земли для вашего народа.</b></i></p><p>На стене первобытной пещеры изобразите историю о стойкости, включив в неё отметку коралла [i] и отметку открытия [ii]. Разыграйте как можно больше из следующего:<br><b>А. Научитесь скользить меж деревьев, будто тень. </b>Если в долине есть хотя бы 1 участок Дивной долины, верните в коробку карту ДЛ06 из колоды добычи припасов в лесу.<br><b>Б. Прокрадитесь по степи, низко пригибаясь к траве, оставшись незамеченным. </b>Если в долине есть хотя бы 1 участок Поднебесной равнины, верните в коробку карту ДС06 из колоды добычи припасов в степи.<br><b>В. Проскользите по высокому пологу Сплетения, избегая страшных опасностей. </b>Если в долине есть хотя бы 1 участок Сплетения, верните в коробку карту ДП06 из колоды добычи припасов на полянах.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<coral>"},{"label":"ii","image":"<discovery>"}]},{"id":"outcomes-549","code":"549","description":{"en":"<p>You play an enticing song, and the behemoth begins to follow you. It continues moving that direction even after you stop, merrily bobbing along as it crushes tree and hill under its vast, writhing tread.</p>\\n<p>\\"End the encounter. Placate the behemoth's demeanor by 1. The behemoth flees.\\"</p>","ru":"<p><i><b>Вы сыграли зачаровывающую мелодию, и чудище последовало за вами. Даже когда вы перестали играть, оно продолжало двигаться следом, весело покачиваясь и сокрушая деревья и холмы своей тяжёлой поступью.</b></i></p><p>Завершите встречу. Успокойте чудище на 1. Чудище сбегает.</p>"},"repeatable":false},{"id":"outcomes-552","code":"552","description":{"en":"<p>While treating someone injured in a fight, you discover an eerie truth: some among your people have blood which glows with the strange luminescence of the coral. There are those who believe these individuals are cursed, while others claim in is the blessing of the wanderer.</p>\\n\\"As a group, the players must choose one of the following paths for your society:\\n\\n<b>A) Accept those marked by the coral:</b> Add <unrest><unrest>. Illustrate the saga of the wanderer's blessing on the primal cave wall, including the <comet> mark and the coral mark (i).\\n\\n<b>B) Expel those marked by the coral:</b> Subtract <population><population>. Illustrate the saga of the broken trust on the primal cave wall, including the schism mark (ii). Add a \\\\\\"Processing coral in a hex with an outpost\\\\\\" to the Taboos section of the Culture page of the Journal. Gain the Taboos (KN18) Knowledge card.\\"","ru":"<p><i><b>Когда вы оказывали помощь раненному в бою, вы узнали нечто пугающее: у некоторых людей из вашей общины кровь светилась странным коралловым сиянием. Одни считали, что эти люди прокляты, а другие верили, что это — благословение Скитальца.</b></i></p><p>Совместно выберите один из следующих путей развития общины:<br><b>А. Примите отмеченных кораллом. </b>Добавьте <unrest><unrest>. На стене первобытной пещеры изобразите историю о благословении Скитальца, включив в неё отметку <comet> и отметку коралла [i].<br>Б. Изгоните отмеченных кораллом. Уберите <population><population>. На стене первобытной пещеры изобразите историю о преданном доверии, включив в неё отметку раскола [ii]. Запишите «Обрабатывать коралл на участке с поселением» в раздел «Табу» на странице «Культура» в журнале. Получите карту знаний «Табу» (ЗБ18), если у вас её нет.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<coral>"},{"label":"ii","image":"<schism>"}]},{"id":"outcomes-556","code":"556","description":{"en":"<p>\\"You plunge your weapon into the great creature's flank, and amber light spills forth from it, welling up around you like resin from the wound of a tree. The creature brays a hollow, chilling call as it collapses. Its great, blazing eye transfixes you until its light fades. As you struggle to your feet before the vast corpse, you see that every tree, every flower, every plant within sight is gone, and only ash remains.\\"</p>\\n\\"End this challenge.\\n\\nIllustrate the saga of the felled ancient on the primal cave wall, including the battle mark (i) and the alert behemoth's mark adorned by the behemoth's blood mark (ii). Add the behemoth's blood mark (ii) to the Legend side of the card of each character who participated in the venture. One character who participated in the venture must discard a <i>weapon</i> item, if able. Then, for the character who succeeded in the final contest of the venture, cross out the Legend box and any unchecked age boxes on their character card. This character no longer ages. If they perish during a challenge, return their card to the pool of available characters at the start of each subsequent challenge. Add the behemoth's mark to the Legend side of their Character card.\\n\\nPlace the behemoth's lair in its current hex in its inactive state. Then, if there are any unplaced searing wake overlays, place them in randomly selected hexes adjacent to the behemoth's inactive lair. For each wake placed this way, roll <1d6> and place it in the corresponding zone: 1–2: A, 3–4: B, 5–6: C. If a wake would be placed in a zone with an overlay this way, remove the overlay and replace it with the searing wake. \\n\\nThen end the Epoch. See Codex p.204 to begin Epoch 3.\\"","ru":"<p><i><b>Вы вонзили оружие в бок великого создания, и янтарный свет хлынул из раны, обволакивая вас, словно смола, стекающая по дереву. Существо издало безжизненный, леденящий кровь вопль и рухнуло. Его огромное сверкающее око пронзало вас взглядом, пока свет в нём не угас. Поднимаясь на ноги перед гигантским телом, вы увидели, что все деревья, цветы и растения вокруг исчезли — осталась одна лишь зола.</b></i></p><p>Завершите текущее испытание.</p><p>На стене первобытной пещеры изобразите историю о поверженном древнем существе, включив в неё отметку битвы [i] и отметку бодрствующего чудища, украшенную отметкой крови чудища [ii]. Добавьте отметку крови чудища [ii] на сторону легенды карт персонажей, участвовавших в этом походе. Один из этих персонажей должен сбросить оружие, если возможно.</p><p>Затем игрок, чей персонаж прошёл финальную проверку похода, должен вычеркнуть клетку легенды и все неотмеченные клетки возраста на карте этого персонажа. Этот персонаж больше не стареет. Если он умирает во время испытания, каждый раз возвращайте его карту в число доступных персонажей в начале следующего испытания. Добавьте отметку поверженного чудища на сторону легенды карты этого персонажа.</p><p>Поместите логово бодрствующего чудища неактивной стороной вверх на участок местности с чудищем. Затем, если остались неразмещённые накладки обжигающих отпечатков, поместите их на случайные участки местности, соседние с неактивным логовом чудища. Для каждого отпечатка бросьте <1d6>, чтобы поместить отпечаток в соответствующий район: [1-2] А, [3-4] Б, [5-6] В. Если при этом вы должны поместить отпечаток в район с другой накладкой, замените её на обжигающий отпечаток.</p><p>Затем завершите текущую эру. См. с. 204, чтобы начать эру 3.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<battle>"},{"label":"ii","image":"<behemothsblood>"}]},{"id":"outcomes-558","code":"558","description":{"en":"<p>Your efforts to build ties with the strangers are in vain, and they vanish whence they came, wherever that might be. Some among your society believe this is for the best, but others fear this encounter might be a prelude to a greater conflict...</p>\\n\\"End this challenge. \\n\\nAdd <unrest><unrest><unrest><unrest>. Illustrate the saga of the vanished ones on the primal cave wall, including the mystery mark (i) and the schism mark (ii).\\"","ru":"<p><i><b>Ваши попытки наладить отношения с незнакомцами ни к чему не привели. Некоторые люди вашей общины считали, что так даже лучше, но другие опасались, что эта встреча может быть предвестием куда более серьёзных распрей…</b></i></p><p>Завершите текущее испытание.</p><p>Добавьте <unrest><unrest><unrest><unrest>. На стене первобытной пещеры изобразите историю об исчезнувших, включив в неё отметку тайны [i] и отметку раскола [ii].</p>"},"repeatable":false,"marks":[{"label":"i","image":"Mystery"},{"label":"ii","image":"<schism>"}]},{"id":"outcomes-560","code":"560","description":{"en":"<p>You race toward the massive battle, fear gripping your heart. You know what must be done to tip the balance. As hillsides crack and forests shatter around you, you seek the courage to challenge such unfathomable power.</p>\\n\\"Embark on the venture below (see Ventures on Rulebook p.60).\\n\\n<bi>As you grow closer to the rampaging titans, great clods of earth are hurled skyward.</bi>\\n<b>Behemoth, Group, Hazard:</b> Everyone must contest <dexterity> against the lower of the two behemoths' <might> to avoid harm. A character adds +2 if they have a <i>clothing</i> item and +2 if they are <i>wary</i>.\\nWin (Equal or higher): You dodge through unscathed. If any character resolves this result, the venture continues.\\nLose (Lower): Unless you break off, you'll be trampled underfoot! You leave the venture unless you suffer <major_injury><major_injury>. If all characters leave the venture, the venture fails.\\n\\n<bi>As you emerge from the tumult of beasts, the land is strangely silent save for the disorienting roars of the battling behemoths. To tip the battle toward one or the other, you'll need to find high ground!</bi>\\n<b>Champion, Wonder:</b> Someone must contest <awareness> against the lower of the two behemoths' <conviction> to find a proper vantage point. Add +4 if your hex has a moraine or mountain and +2 if you are <i>intrepid</i>.\\nWin (Equal or higher): You spot a promising location and lead the group up. The venture continues.\\nLose (Lower): The venture fails unless a character spends <energy><energy> or <lore> to attempt this test again.\\n\\n<bi>From your elevated position, you can leap onto the back of one behemoth and make your attack, temporarily distracting it to give the other the edge. Your moment has come: will you seize it?</bi>\\n<b>Behemoth, Group:</b> Everyone must test <conviction> against the higher of the two behemoths' <dexterity> to leap. A character adds +2 if they have at least one of either behemoth's curio and +2 if they are <i>indomitable</i>.\\nWin (Equal or higher): You vault onto the behemoth's back and rush to deliver the distracting blow. If any character resolves this result, continue the venture.\\nLose (Lower): You blanch at the prospect. You leave the venture unless you spend <energy> or <lore> to attempt this test again. If all characters leave the venture, the venture fails.\\n\\n<bi>You have reached what seems to be a vulnerable point; at least, it would be on any other creature. With all your might, you must strike!</bi>\\n<b>Behemoth, Champion:</b> Someone must choose a behemoth to attack, then contest <might> or <dexterity> that behemoth's <might> to fight. Add +2 if you have a <i>weapon</i> item and +2 if you are <i>vengeful</i>.\\nWin (Equal or higher): Your blow smashes into the behemoth with legendary fervor. Complete this venture and the associated goal.\\nLose (Lower): Your weapon bounces off harmlessly. The venture fails unless a character spends <energy> or <lore> to attempt this test again.\\"","ru":"<p><i><b>Вы мчались навстречу великой битве, и ваше сердце сжималось от страха. Вы знали, что нужно сделать, чтобы склонить чашу весов. Пока вокруг рассыпались холмы и сминались леса, вы искали в себе храбрость, чтобы бросить вызов такой непостижимой мощи.</b></i></p><p>Отправьтесь в поход (см. раздел «Походы» в правилах игры на с. 60).</p><p><i><b>Приближаясь к неистовствующим титанам, вы видели, как огромные глыбы земли взмывали в небо.</b></i></p><p><b>Чудище, группа, угроза. </b>Все персонажи в походе должны провести состязание, чтобы избежать урона: <dexterity> против меньшего из значений <might> двух чудищ. +2, если у персонажа есть <i>одежда</i>, и +2, если он <i>осторожный</i>.<br><b>Успех. </b>Вы пробрались сквозь опасность невредимыми. Если хотя бы один персонаж получил этот результат, продолжите поход.<br><b>Провал. </b>Вас растоптали бы, если бы вы не отступили! Покиньте поход или получите <major_injury><major_injury>. Если все персонажи покинули поход, он окончился неудачно.</p><p><i><b>Когда вы выбрались из пекла боя, всё вокруг казалось стихшим — лишь сбивающий с ног рёв сражающихся чудищ разносился вокруг. Чтобы переломить ход битвы, вам нужно было взобраться на возвышенность!</b></i></p><p>Защитник, чудо. Один из персонажей в походе должен провести состязание, чтобы найти подходящую точку обзора: его <awareness> против меньшего из значений <conviction> двух чудищ. +4, если на участке местности с этим персонажем есть морена или гора, и +2, если персонаж <i>отважный</i>.<br><b>Успех. </b>Вы заметили подходящее место и повели группу наверх. Продолжите поход.<br><b>Провал. </b>Поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy> или <lore>, чтобы провести проверку ещё раз.</p><p><b><i>С возвышения вы могли бы прыгнуть на спину одного из чудищ и нанести удар, чтобы временно отвлечь его и дать преимущество другому. Настал ваш момент: воспользуетесь ли вы им?</i></b></p><p><b>Чудище, группа. </b>Все персонажи в походе должны провести состязание, чтобы прыгнуть: <conviction> против большего из значений <dexterity> двух чудищ. +2, если у персонажа есть хотя бы 1 сокровище любого из чудищ, и +2, если он <i>неукротимый</i>.<br><b>Успех. </b>Вы запрыгнули на спину чудища и поспешили нанести отвлекающий удар. Если хотя бы один персонаж получил этот результат, продолжите поход.<br><b>Провал. </b>Вам стало страшно при одной лишь мысли о прыжке. Покиньте поход либо потратьте <energy> или <lore>, чтобы провести проверку ещё раз. Если все персонажи покинули поход, он окончился неудачно.</p><p><b><i>Вы достигли того, что казалось уязвимой точкой; по крайней мере, на любом другом существе она выглядела бы так. Вы должны были нанести удар изо всех сил!</i></b></p><p><b>Чудище, защитник. </b>Один из персонажей в походе должен выбрать чудище для атаки, а затем провести состязание, чтобы сразиться: его <might> или <dexterity> против <might> выбранного чудища. +2, если у персонажа есть оружие, и +2, если он <i>мстительный</i>.<br><b>Успех. </b>Ваш удар с ужасающей силой обрушился на чудище. Завершите этот поход и достигните соответствующей цели.<br><b>Провал. </b>Ваше оружие отскочило, не нанеся урона. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy> или <lore>, чтобы провести проверку ещё раз.</p>"},"repeatable":false},{"id":"outcomes-561","code":"561","description":{"en":"<p>\\"The behemoth's subtle senses detect shifts in its environment. By tapping on the horn, you can sway the behemoth's course.\\"</p>\\n<p>End the encounter. Place your character and this behemoth in the same adjacent hex (without drawing a Journey card).</p>","ru":"<p><i><b>Острое чутьё чудища позволяло ему улавливать перемены вокруг. Постучав по его рогу, вы сумели направить его в другую сторону.</b></i></p><p>Завершите встречу. Переместите персонажа и это чудище на один и тот же соседний участок местности (не берите карту пути).</p>"},"repeatable":false},{"id":"outcomes-562","code":"562","description":{"en":"<p>You place the material into the web, and suddenly it is tugged out of your view, vanishing into a nearby tree. Another bowl descends, this one holding a different material. Perhaps you have bartered with a creature living in the tree? When you search for the creature, however, you hear only the clicking of something receding into the canopy, just beyond your sight. Moments later, something glides away from the treetop, vanishing over the edge of the ridge. How strange. You turn to collect your spoils.</p>\\n<p>If you offered silk or woven silk, gain 1 living coral and 1 moonblood. Otherwise, gain 2 woven silk.</p>","ru":"<p><i><b>Стоило вам положить материал в чашу, как внезапно её будто что‑то выдернуло из вашего поля зрения — и она исчезла в ближайшем дереве. Спустилась ещё одна чаша, в которой лежал другой материал. Возможно, вы обменялись с существом, живущим в дереве? Едва вы начали искать это существо, как услышали лишь назойливое щёлканье, которое медленно растворилось в густой листве. Мгновение спустя что‑то скользнуло прочь с вершины дерева и исчезло за краем хребта. Как странно… Вы вернулись к чаше, чтобы забрать свои вещи.</b></i></p><p>Если вы сбросили шёлк или плетёный шёлк, получите 1 живой коралл и 1 лунную кровь. В противном случае получите 2 плетёных шёлка.</p>"},"repeatable":false},{"id":"outcomes-565","code":"565","description":{"en":"<p>With a roar of last defiance, the behemoth vanishes under the spreading tide of coral. Rid of the last great obstacle to its growth, the coral spreads like fire in the days that come, overtaking the valley in its entirety. Your civilization vanishes beneath.</p>\\n\\"Illustrate the saga of doom's dawn on the primal cave wall, including the alert behemoth's mark adorned with the coral mark (i) and the harrowing (ii) mark. Then, as a group, the players must choose one of the following paths for your society:\\n\\n<b>A) Remain with the behemoth's corpse as the coral overgrows the valley:</b> Your campaign ends and your society <b>vanishes</b>. See Ending a Campaign on Rulebook p.97.\\n\\nThis end may not be a happy one, but it can still be instructive to future peoples who inhabit the valley. To immortalize a photo of your primal cave wall and see other people's works of art, we invite you to share your saga with our community!\\n\\n@[Insert Link]@\\n\\nTo continue playing Stonesaga, see Beginning Subsequent Campaigns on Rulebook p.97. Or you could switch to Endless Mode, as described on Rulebook p.97.\\n\\n<b>B) Leave your ancient companion to sing its story in other vales:</b> Add Exodus (CZ09) to your looming challenges.\\"","ru":"<p><i><b>С отчаянным рёвом чудище исчезло под разрастающимся кораллом. Избавившись от последнего громадного препятствия на своём пути, коралл вскоре распространился как пожар, захватив долину целиком.</b></i></p><p>Завершите текущее испытание.</p><p>На стене первобытной пещеры изобразите историю о заре гибели, включив в неё отметку бодрствующего чудища, украшенную отметкой коралла [i], и отметку ужаса [ii]. </p><p>Затем совместно выберите один из следующих путей развития общины:<br><b>А. Останьтесь с телом чудища, пока коралл разрастается по всей долине. </b>Завершите кампанию. Ваша община <b>исчезла</b>.<br>См. раздел «Конец кампании» в правилах игры на с. 97.<br>Такой конец хоть и далёк от счастливого, но он всё же может послужить уроком для народов, которые заселят эту долину в будущем. Чтобы увековечить фотографию своей стены первобытной пещеры и увидеть произведения искусства других игроков, мы приглашаем вас поделиться своей историей с нашим сообществом! Чтобы продолжить играть в «Наскальную историю», см. в правилах игры раздел «Начало следующих кампаний» на с. 97 или раздел «Бесконечный режим» на с. 102.<br><b>Б. Покиньте своего древнего спутника, чтобы продолжить его историю в других землях. </b>Добавьте к грядущим испытаниям карту «Исход» (ИЯ09).</p>"},"repeatable":false,"marks":[{"label":"i","image":"<coral>"},{"label":"ii","image":"<harrowing>"},{"label":"","image":"<qrcode>"}]},{"id":"outcomes-571","code":"571","description":{"en":"<p>The wanderer sweeps across the sky, then vanishes into the sun. Several minutes later, it bursts forth from the glare of the sun, glistening with flame and fervor.</p>\\n\\"Choose one and resolve it:\\n\\n<b>A) Enshrine this event in story:</b> Spend <lore><lore><lore> to illustrate the saga of the coral's rebirth on the primal cave wall, including the coral mark and the <sun> mark.\\n\\n<b>B) Observe carefully to learn something of the cosmos:</b> Add <lore><lore>.\\"","ru":"<p><i><b>Скиталец пронёсся по небу и исчез в свете солнца. Спустя какое‑то время он вырвался из солнечного сияния, лучась пламенем и жаром.</b></i></p><p>Выберите и разыграйте одно:<br><b>А. Запечатлейте это событие. </b>Потратьте <lore><lore><lore>, чтобы на стене первобытной пещеры изобразить историю о возрождении коралла, включив в неё отметку коралла и отметку <sun>.<br><b>Б. Внимательно понаблюдайте, чтобы узнать что-то новое о мироздании. </b>Добавьте <lore><lore>.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<coral>"}]},{"id":"outcomes-572","code":"572","description":{"en":"<p>In a sweeping cloud of spores, you catch sight of the coral champion. This ancient stalks among the scintillating fog, which peels back as you rush to face them.</p>\\n\\"Embark on the venture below (see Ventures on Rulebook p.60).\\n\\n<bi>The floating motes of coral ignite as you approach, turning into tiny, blistering sparks. Your skin blisters and pops anywhere they touch you.</bi>\\n<b>Coral, Group, Hazard:</b> Everyone must test <conviction> to push on. A character adds +2 if they have a <i>clothing</i> item, +4 if they have a Moonblood Talisman, and +2 if they are <i>indomitable</i>.\\n12+: You grit your teeth and press on despite the pain. The venture continues.\\n1–11: The spores sear you, and you cry out. Suffer <major_disease><minor_disease> unless you leave the venture. Then the venture fails unless a character spends <energy> to attempt this test again.\\n\\n<bi>The coral champion curls their hand into a fist. Around you, tendrils of live coral twist out of the ground, attempting to catch you in a mirrored grip.</bi>\\n<b>Coral, Group:</b> Everyone must test <dexterity> to dodge. A character adds +2 if they have <cut> or +4 if they have a <i>moonblood</i> item with <cut>, +4 if they have a Moonblood Talisman, and +2 if they are <i>lucky</i>\\n12+: You slip through the grasping hands of coral and leap toward the coral champion.\\n1–11: You are trapped, and the only out is to wrench yourself free. Leave the venture unless you suffer <major_injury><major_injury>. Then the venture fails unless a character spends <energy><energy> or <lore> to attempt this test again.\\n\\n<bi>Standing before the coral champion, you know you have only an instant to strike!</bi>\\n<b>Coral, Champion:</b> Someone must test <might> to <i>fight</i>. Add +2 if you have a <i>moonblood weapon</i> item, +4 if you have a <i>trophy weapon</i> item, and +2 if you are <i>vengeful</i>.\\n13+: Your blow lands true. Complete this venture and the associated goal.\\n9–12: Your blow goes wide, but you create an other opportunity for an attack. Resolve 1–8 unless a character spends <energy> or <lore> to attempt this test again.\\n1–8: The champion springs back, evading your blow. Return to the second expedition of this venture.\\"","ru":"<p><i><b>В клубящемся облаке спор вы заметили кораллового защитника. Древнее создание шагало сквозь сверкающий туман, который расступился, когда вы бросились врагу наперерез. </b></i></p><p>Отправьтесь в поход (см. раздел «Походы» в правилах игры на с. 60).</p><p><i><b>Парящие частицы коралла превратились в крошечные обжигающие искры, как только вы приблизились. Там, где они вас касались, кожа покрывалась волдырями и лопалась.</b></i></p><p><b>Коралл, группа, угроза. </b>Все персонажи в походе должны провести проверку <conviction>, чтобы продолжить наступление. +2, если у персонажа есть <i>одежда</i>, +4, если у него есть «Талисман из лунной крови», и +2, если он <i>неукротимый</i>.<br><b>≥12:</b>  Вы стиснули зубы и продолжили наступление, несмотря на боль. Если хотя бы один персонаж получил этот результат, продолжите поход.<br><b>1-11:</b>  Споры обожгли вас, и вы закричали от боли. Покиньте поход или получите <major_disease> и <minor_disease>. Если все персонажи покинули поход, он окончился неудачно, если только любой персонаж в походе не потратит <energy>, чтобы провести проверку ещё раз.</p><p><b><i>Коралловый защитник сжал руку в кулак. Из земли вокруг вырвались отростки живого коралла и попытались схватить вас, будто повинуясь воле защитника.</i></b></p><p><b>Коралл, группа. </b>Все персонажи в походе должны провести проверку <dexterity>, чтобы увернуться. +2, если у персонажа есть  <cut>(или +4, если у него есть предмет <i>лунной крови </i>с <cut>). Также +4, если у персонажа есть «Талисман из лунной крови», и +2, если он <i>удачливый</i>.<br><b>≥12:</b>  Вы увернулись от устремившихся к вам кораллов и сделали прыжок в сторону кораллового защитника. Если хотя бы один персонаж получил этот результат, продолжите поход.<br><b>1-11:</b>  Кораллы схватили вас, выбив из сил. Покиньте поход или получите <major_injury><major_injury>. Если все персонажи покинули поход, он окончился неудачно, если только любой персонаж в походе не потратит <energy><energy> или <lore>, чтобы провести проверку ещё раз.</p><p><b><i>Стоя перед коралловым защитником, вы понимали, что у вас есть лишь мгновение, чтобы нанести удар!</i></b></p><p><b>Коралл, защитник. </b>Один из персонажей в походе должен провести проверку <might>, чтобы сразиться. +2, если у персонажа есть <i>оружие из лунной крови</i>, +4, если у него есть<i> оружие-трофей</i>, и +2, если он <i>мстительный</i>.<br><b>≥13:</b>  Ваш удар достиг цели. Завершите этот поход и достигните соответствующей цели.<br><b>9-12:</b>  Ваш удар не достиг цели, но вы увидели возможность для ещё одной атаки. Разыграйте исход как при [1-8], если только любой персонаж в походе не потратит <energy> или <lore>, чтобы провести проверку ещё раз.<br><b>1-8:</b>  Защитник с лёгкостью уклонился от вашего удара. Вернитесь ко второй вылазке этого похода.</p>"},"repeatable":false},{"id":"outcomes-573","code":"573","description":{"en":"<p>You make your song wild and frenzied, and the behemoth grows more and more agitated as it tries to keep up with the song. Eventually, it grows exhausted and departs, leaving behind a patch of moss you. You dig into the moss and push it aside to uncover something strange.</p>\\n<p>\\"End the encounter. Aggravate the behemoth's demeanor by 1. The behemoth flees.\\n\\nThen, if a character, animal companion, or storage structure has an item with Shimmering in its name, gain 2 of the behemoth's curio; otherwise, gain the Shimmering Moss (IT86) Item card.\\"</p>","ru":"<p><i><b>Ваша песня была лихой и неистовой: чудище всё больше и больше раздражалось, пытаясь угнаться за ней. В конце концов оно выбилось из сил и ушло, оставив после себя клочок мха. Вы решили осмотреть его поближе — вдруг вы найдёте в нём что‑то необычное?</b></i></p><p>Завершите встречу. Разозлите чудище на 1. Чудище сбегает.</p><p>Затем, если у персонажа, животного- компаньона или в сооружении-хранилище есть предмет со словом «мерцающий» в названии, получите 2 сокровища чудища; в противном случае получите карту предмета «Мерцающий мох» (ВЩ86).</p>"},"repeatable":false},{"id":"outcomes-575","code":"575","description":{"en":"<p>\\"Your wide range of interactions with the behemoth have revealed certain truths of its being. Yes, it is powerful and connected to the world around you, but it is not separate from it. Its power far exceeds any person's strength, yet it is not limitless. Whatever it is, you believe it will be important to your people' future.\\"</p>\\n\\"At the end of any day, you may end this challenge.\\n\\nThen, as a group, the players must choose one of the following paths for your society:\\n\\n<b>A) Advise your people to avoid the behemoths' lairs:</b> Subtract <unrest>. Placate the alert behemoth's demeanor by 2. Illustrate the saga of the mighty neighbor on the primal cave wall, including the alert behemoths' mark, the caution mark (i), and the taboo mark (iv). Add \\\\\\"Resting in a hex with a behemoth's lair\\\\\\" to the Taboos section of the Culture page of the Journal. Gain the Taboos (KN18) Knowledge card.\\n\\n<b>B) Gather resources close in the behemoth's wake:</b> Add <population><population><population>. Aggravate the alert behemoth's demeanor by 3. Illustrate the saga of the earthbreaker's bounty on the primal cave wall, including the alert behemoths' mark, the broken earth mark (ii), the mystery mark (vii) and the plenty mark (iii).\\n\\n<b>C) Postulate that the behemoth is a divine enforcer of your people's taboos:</b> If the taboo mark (v) is on the primal cave wall, subtract 6<unrest>. Illustrate the saga of ancient law on the primal cave wall, including the bond mark enclosing the alert behemoth's mark, the mystery mark (vii), taboo mark (v).\\n\\n<b>D) Record the behemoth's movement for future generations:</b> Add <population><population>. Placate the behemoth's demeanor by 1. Illustrate the saga of the wild's harbinger on the primal cave wall, including the alert behemoth's mark and the scribe mark (iv). \\n\\nAt the end of this challenge, end the current epoch. Refer to Codex p.196 to continue your campaign into Epoch 2.\\"","ru":"<p><i><b>Ваши частые встречи с чудищем раскрыли скрытые истины о его природе. Да, оно было могущественным, но в то же время было тесно связано с окружающим миром. Его сила далеко превосходила мощь любого человека, но и она не была безграничной. Чем бы ни было это чудище, вы верили: оно сыграет важную роль в будущем вашего народа.</b></i></p><p>В конце любого дня можете завершить текущее испытание.</p><p>Затем совместно выберите один из следующих путей развития общины:<br><b>А. Посоветуйте своему народу обходить стороной логова чудищ.</b> Уберите <unrest>. Успокойте бодрствующее чудище на 2. На стене первобытной пещеры изобразите историю о могучем соседе, включив в неё отметку бодрствующего чудища, отметку осторожности [i] и отметку табу [iv]. Запишите «Отдыхать на участке местности с логовом чудища» в раздел «Табу» на странице «Культура» в журнале. Получите карту знаний «Табу» (ЗБ18), если у вас её нет.<br><b>Б. Соберите ресурсы рядом с отпечатком чудища. </b>Добавьте <population><population><population>. Разозлите бодрствующее чудище на 3. На стене первобытной пещеры изобразите историю о дарах разрушителя земли, включив в неё отметку бодрствующего чудища, отметку расколотой земли [ii], отметку тайны [vii] и отметку изобилия [iii].<br><b>В. Провозгласите, что чудище — посланник богов, следящий за соблюдением табу. </b>Если на стене первобытной пещеры есть отметка табу [iv], уберите 6<unrest>. На стене первобытной пещеры изобразите историю о древнем законе, включив в неё отметку бодрствующего чудища, отметку тайны [vii] и отметку табу [iv], заключённую в отметку связи [v].<br><b>Г. Запишите передвижения чудища для будущих поколений. </b>Добавьте <population><population>. Успокойте чудище на 1. На стене первобытной пещеры изобразите историю о вестнике дикой природы, включив в неё отметку бодрствующего чудища и отметку летописца [vi].</p><p>В конце этого испытания завершите текущую эру. См. с. 196, чтобы начать эру 2.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<caution>"},{"label":"ii","image":"<brokenearth>"},{"label":"iii","image":"<plenty>"},{"label":"iv","image":"<taboo>"},{"label":"v","image":"<bond>"},{"label":"vi","image":"<scribe>"},{"label":"vii","image":"<mystery>"}]},{"id":"outcomes-582","code":"582","description":{"en":"<p>Your hunt aligned with the omens, and signaling plenty in the year to come. Of course, there is still much work to do to prepare as the great hunt continues.</p>\\nSubtract <unrest>. Each character gains <minor_boost> to <dexterity> or <conviction>. Illustrate the saga of the auspicious hunt on the primal cave wall, including the mark of each omen you found on a Foraging card as part of Hunt an Omen-Beast and the hunter mark.","ru":"<p><i><b>Ваша охота совпала со знамениями, предвещая изобилие в грядущем году. Конечно, впереди было ещё много работы, чтобы подготовиться к продолжению великой охоты.</b></i></p><p>Уберите <unrest>. Каждый персонаж получает <minor_boost> к <dexterity> или <conviction>. На стене первобытной пещеры изобразите историю об удачной охоте, включив в неё отметки всех знамений, которые вы нашли на картах добычи припасов во время достижения цели «Выйдите на охоту под светом знамения», и отметку охотника.</p>"},"repeatable":false,"marks":[{"label":"","image":"<hunter>"}]},{"id":"outcomes-584","code":"584","description":{"en":"<p>\\"On the behemoth's stony brow, you notice a tough, wiry moss growing in the cracks and crevices.\\"</p>\\n\\"Choose one and resolve it:\\n\\n<b>A) You pull some up, causing the behemoth to startle:</b> End the encounter. Aggravate the behemoth's demeanor by 1. Gain 3 fiber.\\n\\n<b>B) You spot a shimmering patch amidst the moss and slice it free:</b> If you have <cut>, end the encounter. Then, if a character, animal companion, or storage structure has an item with Shimmering in its name, gain 2 of the behemoth's curio; otherwise, gain the the Shimmering Moss (IT86) Item card.\\n\\n<b>C) Shimmy down the moss to escape:</b> End the encounter. Gain <minor_boost> to <dexterity>.\\"","ru":"<p><i><b>На каменной брови чудища вы заметили жёсткий мох, растущий в трещинах.</b></i></p><p>Выберите и разыграйте одно:<br><b>А. Сорвите немного мха и заставьте чудище вздрогнуть. </b>Завершите встречу. Разозлите чудище на 1. Получите 3 волокна.<br><b>Б. Срежьте мерцающий кусок мха, который вы заметили.</b> Если у вас есть <cut>, завершите встречу. Затем, если у персонажа, животного-компаньона или в сооружении-хранилище есть предмет со словом «мерцающий» в названии, получите 2 сокровища чудища; в противном случае получите карту предмета «Мерцающий мох» (ВЩ86).<br><b>В. Соскользните по мху, чтобы сбежать. </b>Завершите встречу. Получите <minor_boost> к <dexterity>.</p>"},"repeatable":false},{"id":"outcomes-586","code":"586","description":{"en":"<p>\\"Sitting in the behemoth's mane, you know it wishes to hear a tale of your people. The behemoth's strands of hair ripple as you speak, seeming to drink in the words. As you complete your story, it places you gently on the ground, then digs in the earth for a moment with its great paw.\\"</p>\\n\\"Choose one and resolve it:\\n\\n<b>A) Recount a venerable tale:</b> If you have a Legend card, discard a Legend card to end the encounter. Placate the behemoth's demeanor by 1. Then, if a character, animal companion, or storage structure has an item with Symbiotic in its name, gain 2 of the behemoth's curio; otherwise, gain the Symbiotic Egg (IT93) Item card.\\n\\n<b>B) Spout some nonsense that you hope sounds convincing:</b> End the encounter. Aggravate the behemoth's demeanor by 1. Gain 1 sunstone.\\"","ru":"<p><i><b>Сидя в гриве чудища, вы поняли, что оно хочет услышать рассказ о вашем народе. Пока вы говорили, волоски на его теле колыхались, будто впитывая каждое слово. Когда вы закончили рассказ, чудище бережно спустило вас с себя, а потом мгновенно зарылось в землю.</b></i></p><p>Выберите и разыграйте одно:<br><b>А. Поведайте древнюю быль. </b>Если у вас есть карта легенды, сбросьте её, чтобы завершить встречу. Успокойте чудище на 1. Затем, если у персонажа, животного-компаньона или в сооружении-хранилище есть предмет со словом «симбиотический» в названии, получите 2 сокровища чудища; в противном случае получите карту предмета «Симбиотическое яйцо» (ВЩ93).<br><b>Б. Придумайте какую-нибудь чушь в надежде, что она будет убедительной.</b> Завершите встречу. Разозлите чудище на 1. Получите 1 солнечный камень.</p>"},"repeatable":false},{"id":"outcomes-588","code":"588","description":{"en":"<p>Its fell work done, the behemoth thunders away, devastation in its wake.</p>\\n<p>\\"Until the end of the challenge (or the end of the current event in Endless Mode), when you enter a hex with this behemoth's lair or one of its overlays, place a depletion token in that hex.\\n\\nThen, remove all of this behemoth's trace markers from the valley. Assign the Return to Slumber (BT20) instinct to this behemoth (replacing its previous instinct).\\"</p>","ru":"<p><i><b>Свершив своё жуткое дело, чудище с грохотом умчалось прочь, оставив за собой след разрушений.</b></i></p><p>До конца текущего испытания (или события в бесконечном режиме), когда вы перемещаетесь на участок местности с логовом этого чудища или с одной из накладок этого чудища, помещайте на этот участок местности жетон истощения.</p><p>Уберите жетон направления и все жетоны следов этого чудища. Замените его текущий инстинкт на «Вернуться в забытьё» (ЧК20).</p>"},"repeatable":false},{"id":"outcomes-590","code":"590","description":{"en":"<p>\\"At the rippling sound of thunder, the behemoth's light seems to dim. You reach down to touch its great spine...\\"</p>\\n\\"Choose one of the following and resolve it:\\n\\n<b>A) Gently place your hand on the spine, feeling the warmth flow within:</b> Placate the behemoth's demeanor by 2. You may replace its Instinct with Return to Slumber (BT20). Then, if <cloud> is a current omen, erase 1 age box on your Character card.\\n\\n<b>B) Seize the spine with all your might:</b> End the encounter. Aggravate the behemoth's demeanor by 1. The behemoth flees.\\"","ru":"<p><i><b>С раскатом грома сияние чудища словно померкло. Вы протянули руку, чтобы коснуться его огромного хребта…</b></i></p><p>Выберите и разыграйте одно:<br><b>А. Осторожно положите ладонь на хребет и ощутите тёплое течение жизни внутри.</b> Успокойте чудище на 2. Можете заменить его инстинкт на «Вернуться в забытьё» (ЧК20). Затем, если <cloud>— текущее знамение, сотрите или зачеркните одну отметку в клетке возраста на карте персонажа.<br><b>Б. Схватите хребет изо всех сил. Завершите встречу.</b> Разозлите чудище на 1. Чудище сбегает.</p>"},"repeatable":false},{"id":"outcomes-591","code":"591","description":{"en":"<p>\\"With the fury of a storm wall, the behemoth sweeps toward your outposts, driving your people before it. You have no refuge from the behemoth's fury.\\"</p>\\n\\"End this challenge.\\n\\nThen, as a group, the players must choose one of the following paths for your society:\\n\\n<b>A) Draw the line and stand firm at your outposts:</b> Subtract <population><population><population><population>. For each of your outposts, roll <1d6> and resolve the following: (1–2) this outpost becomes a ruin, (3–5) randomly select two structures in the outpost to be destroyed, (6) subtract <population>. Permanently raise each character's <conviction> by 2 (to a maximum of 7). Add the growth mark (iv) to the Legend side of each Character card. Then illustrate the saga of the desolate days on the primal cave wall, including the battle mark (i) and the alert behemoth's mark adorned by the wrath mark (ii).\\n\\n<b>B) Flee from the behemoth's fury:</b> Add <unrest><unrest><unrest>. Each of your outposts becomes a ruin. Illustrate the saga of the desperate flight on the primal cave wall, including the broken earth mark (ii) and the alert behemoth's mark adorned by the wrath mark (iii).\\n\\nThen end the current epoch. Refer to page Codex p.196 to continue your campaign into Epoch 2.\\"","ru":"<p><i><b>Как неукротимая буря, чудище обрушилось на ваши поселения, заставив ваш народ спасаться бегством. Вам негде было спрятаться от его ярости. </b></i></p><p>Завершите текущее испытание.</p><p>Затем совместно выберите один из следующих путей развития общины:<br><b>А. Займите оборону и защитите свои поселения. </b>Уберите <population><population><population><population>. За каждое своё поселение бросьте <1d6> и разыграйте эффект по результату броска: [1-2] это поселение становится руинами, [3-5] разрушьте 2 случайных сооружения в этом поселении, [6] уберите <population>. Навсегда увеличьте <conviction> каждого персонажа на 2 (не более чем до 7). Добавьте отметку становления [iv] на сторону легенды карты каждого персонажа. Затем на стене первобытной пещеры изобразите историю о несчастных днях, включив в неё отметку битвы [i] и отметку бодрствующего чудища, украшенную отметкой гнева [iii].<br><b>Б. Сбегите прочь от ярости чудища. </b>Добавьте <unrest><unrest><unrest>. Каждое из ваших поселений становится руинами. На стене первобытной пещеры изобразите историю об отчаянном бегстве, включив в неё отметку расколотой земли [ii] и отметку бодрствующего чудища, украшенную отметкой гнева [iii].</p><p>Затем завершите текущую эру. См. с. 196, чтобы начать эру 2.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<battle>"},{"label":"ii","image":"<brokenearth>"},{"label":"iii","image":"<wrath>"},{"label":"iv","image":"<growth>"}]},{"id":"outcomes-592","code":"592","description":{"en":"<p>Your search begins in a vast cavern. Coral fills part of the chamber, but stops at a hissing crack that runs through the floor...</p>\\n\\"Embark on the venture below (see Ventures on Rulebook p.60).\\n\\n<bi>You stand at the precipice of the hissing crack. Someone will have to be the first to clamber within.</bi>\\n<b>Champion, Wonder:</b> Someone must test <conviction> to clamber within. Add +2 if you have an item with a <fire> token on it, +2 if you are <i>intrepid</i> and +1 for each <i>exploration</i> item you have.\\n11+: You confidently crawl into the hissing crack. The venture continues.\\n1–10: Your nerve falters. The venture fails unless a character spends <energy><energy> or spends <lore> to attempt this test again.\\n\\n<bi>Within the crack, the walls grow slick as wet stone and sharp as volcanic glass. The descent becomes treacherous as each turn threatens to slice your skin to ribbons.</bi>\\n<b>Group, Hazard:</b> Everyone must test <dexterity> to climb safely. A character adds +2 if they have a <i>clothing</i> item, +2 for each <i>exploration</i> they have, and +2 if they are <i>wary</i>.\\n10+: You descend safely. If any character resolves this result, the venture continues.\\n1–9: You are sliced badly. Leave the venture unless you suffer <major_injury><minor_injury>. If all characters on the venture resolve this result, the venture fails.\\n\\n<bi>The sharp substance along the walls appears to be crystallized moonblood, bubbling up from a pit on the floor and spewing an acrid vapor into the air. At the bottom fo the crack, no sign of the coral can be found. The moonblood must be repelling it. There is not much here in liquid form, but you might be able to gather enough for a sample.</bi>\\n<b>Champion, Wonder:</b> Someone must test <awareness> to gather the moonblood safely. Add +2 if you have an item with a <fire> token on it, +2 if you have the moonblood mark, and +2 if you are <i>resourceful</i>. You may discard 1 water to add +4.\\n13+: The sample is substantial. Gain 3 moonblood. Complete this venture and the associated goal.\\n9–12: The sample is minuscule, but usable. Gain 1 moonblood. Complete this venture and the associated goal.\\n1–8: The thick vapors overcome you. The venture fails unless a character suffers <major_disease> or spends <lore> to attempt this test again.\\"","ru":"<p><i><b>Ваши поиски начались в огромной пещере. Кораллы заполнили часть полости, но даже они держались подальше от шипящей трещины, рассекающей пол…</b></i></p><p>Отправьтесь в поход (см. раздел «Походы» в правилах игры на с. 60).</p><p><i><b>Вы стояли на краю шипящей трещины. Кто‑то должен был спуститься вниз.</b></i></p><p><b>Защитник, чудо.</b> Один из персонажей в походе должен провести проверку <conviction>, чтобы забраться внутрь трещины. +2, если у персонажа есть предмет с <fire>, +2, если он <i>отважный</i>, и +1 за каждый его предмет для <i>исследования</i>.<br><b>≥11:</b>  Вы с уверенностью залезли в трещину. Продолжите поход.<br><b>1-10:</b>  У вас сдали нервы. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy> или <lore>, чтобы провести проверку ещё раз.</p><p><b><i>Стены внутри трещины были скользкими, как мокрый камень, и острыми, как вулканическое стекло. Спуск становился опасным: на каждом выступе можно было сильно порезаться.</i></b></p><p><b>Группа, угроза.</b> Все персонажи в походе должны провести проверку <dexterity>, чтобы безопасно спуститься. +2, если у персонажа есть <i>одежда</i>, +2 за каждый его предмет для <i>исследования </i>и +2, если он <i>осторожный</i>.<br><b>≥10:</b>  Вы спустились без происшествий. Если хотя бы один персонаж получил этот результат, продолжите поход.<br><b>1-9:</b>  Вы сильно поцарапались. Покиньте поход или получите <major_injury> и <minor_injury>. Если все персонажи получили этот результат, поход окончился неудачно.</p><p><i><b>Острые выступы на стенах, похоже, были кристаллизованной лунной кровью, что пузырилась в яме на дне и выбрасывала едкий пар в воздух. На дне трещины не было следов кораллов. Видимо, лунная кровь их отпугивала. В жидкой форме её здесь было немного, но возможно, вы могли бы собрать хотя бы небольшой образец.</b></i></p><p><b>Защитник, чудо. </b>Один из персонажей в походе должен провести проверку <awareness>, чтобы безопасно собрать лунную кровь. +2, если у персонажа есть предмет с <fire>, +2, если у него есть отметка лунной крови, и +2, если он изобретательный. Также +4, если персонаж сбросит 1 воду.<br><b>≥13:</b>  Вы собрали хороший образец. Получите 3 лунные крови. Завершите этот поход и достигните соответствующей цели.<br><b>9-12:</b>  Вам не удалось собрать много жидкости, но этого было вполне достаточно. Получите 1 лунную кровь. Завершите этот поход и достигните соответствующей цели.<br><b>1-8:</b>  Едкие пары не дали вам сосредоточиться. Поход окончился неудачно, если только любой персонаж в походе не получит <major_disease> или не потратит <lore>, чтобы провести проверку ещё раз.</p>"},"repeatable":false,"marks":[{"label":"","image":"<moonblood>"}]},{"id":"outcomes-593","code":"593","description":{"en":"<p>\\"You pore over the stars and learn their patterns, and even the behemoth's movements seem to fall into place with a grand, cosmic pattern.\\"</p>\\n<p>Your society gains the Behemoth-Speaker (MA18) mantle power.</p>","ru":"<p><i><b>Вы внимательно изучили звёзды и разгадали их узоры. Даже передвижения чудища оказались вписанными в великий космический замысел.</b></i></p><p>Ваша община получает силу мантии «Говорящий с чудищами» (MA18).</p>"},"repeatable":false},{"id":"outcomes-594","code":"594","description":{"en":"<p>\\"Within your mind's eye, you see a spreading canopy of trees from above. Are you atop a vast mountain? The world lurches forward, and the thunder of your footfall shakes the canopy. You have taken the form of a beast of unthinkable scale, striding across the landscape in pursuit of primordial instincts.The trees scatter like leaves as you stomp through the forest. You awaken covered in sweat, a dreadful certainty lingering in your mind. Somewhere, at some great distance, this beast treads forward with purpose...\\"</p>\\n\\"Choose one and resolve it:\\n\\n<b>A) Reach out for the unfamiliar mind:</b> If there is at least 1 behemoth without its mark on the primal cave wall, randomly select one of those behemoths. Illustrate the saga of the primal mind on the primal cave wall, including that behemoth's mark and the mystery mark. Add <activity><activity><activity> and gain <major_boost> to <might>.\\n\\n<b>B) Seek knowledge of this behemoth:</b> You may spend <lore><lore><lore> or add <activity><activity> to choose a behemoth with an active lair in the valley. Shuffle its Secret cards that you have not yet revealed, then draw one and reveal it (see Secrets on Rulebook p.81).\\"","ru":"<p><i><b>Перед вашим внутренним взором предстал раскинувшийся под вами полог леса. Неужели вы стояли на вершине огромной горы? Мир рванулся вперёд, и гром ваших шагов сотряс полог. Вы приняли облик существа немыслимых размеров, ведомого первобытными инстинктами. Деревья разлетались, словно листья, когда вы ступали по лесу. Миг спустя вы очнулись в холодном поту, с мрачной, тревожащей душу уверенностью: где‑то очень далеко это чудище целеустремлённо продолжало свой путь…</b></i></p><p>Выберите и разыграйте одно:<br><b>А. Свяжитесь с незнакомым разумом.</b> Выберите случайное чудище, отметки которого нет на стене первобытной пещеры. На стене первобытной пещеры изобразите историю о древнейшем разуме, включив в неё отметку этого чудища и отметку тайны. Добавьте <activity><activity><activity> и получите <major_boost> к <might>.<br><b>Б. Найдите информацию об этом чудище.</b> Потратьте <lore><lore><lore> или добавьте <activity><activity>, чтобы выбрать чудище с активным логовом в долине. Перемешайте его неоткрытые карты секретов, затем откройте одну из них (см. раздел «Секреты» в правилах игры на с. 81).</p>"},"repeatable":false,"marks":[{"label":"","image":"<mystery>"}]},{"id":"outcomes-595","code":"595","description":{"en":"<p>As you vault up the spines, you whisper to yourself. The behemoth stops, craning its neck as if to listen. With its movement stilled, you are able to ascend easily.</p>\\n<p>\\"You may discard a Legend card to placate the behemoth's demeanor by 1. Then, continue the encounter.\\"</p>","ru":"<p><i><b>Вскарабкавшись на острые шипы, вы прошептали что‑то себе под нос. Чудище замерло, вытянув шею, будто прислушиваясь. Когда оно перестало двигаться, вы легко смогли подняться выше.</b></i></p><p>Можете сбросить карту легенды, чтобы успокоить чудище на 1. Затем продолжите эту встречу.</p>"},"repeatable":false},{"id":"outcomes-596","code":"596","description":{"en":"<p>\\"Your quest to find the omens brings you answers. Your search for each omen has taken you all over the volcanic wastes, and in the process, you have witnessed the signs. Clouds of steam sear from cracks in the ground. Blazing magma burns like the sun. Sparks spit from the top of the burning mountain like chaotic stars. The mountain's ire is building to some yet-unknown crescendo. Stranger still, the aloof, amber-touched behemoth that makes its home in this region seems also to sense a disturbance, and paces at the mountain's feet...\\"</p>\\n\\"At the end of any day, you may end this challenge. Then, add Eruption (CY04) to your looming challenges. Illustrate the saga of the mountain's ire on the primal cave wall, including the blaze mark (ii) and the blackened sky mark (i). Finally, resolve the first you are able:\\n\\n<b>A) The ashen behemoth makes its way to the volcanic wastes:</b> If the BH4 mark (iii) was already on the primal cave wall, move its lair to a randomly selected hex in the Volcanic Wastes. Roll <1d6> and place it in the corresponding zone: (1–2): A, (3–4), B, (5–6) C. \\n\\n<b>B) The ashen behemoth arrives in the valley:</b> Set up BH4 as described in Behemoth Arrival on Rulebook p.74. Place its lair in a randomly selected hex in the Volcanic Wastes. Roll <1d6> and place it in the corresponding zone: (1–2): A, (3–4), B, (5–6) C.\\"","ru":"<p><i><b>Вы обошли все Вулканические пустоши в поисках каждого знамения и по пути увидели знаки. Облака пара вырывались из трещин в земле, обжигая всё вокруг. Магма пылала, словно солнце. Искры разлетались с вершины горящей горы, как хаотичные звёзды. Гнев горы нарастал, подбираясь к какому‑то, пока неведомому пиковому моменту. Даже равнодушное пепельное чудище, обитавшее в этом регионе, казалось, тоже чувствовало надвигающееся бедствие и мерило шагами подножие горы…</b></i></p><p>В конце любого дня можете завершить текущее испытание.</p><p>Затем добавьте карту «Извержение» (ИЕ04) к грядущим испытаниям. На стене первобытной пещеры изобразите историю о гневе горы, включив в неё отметку пламени [ii] и отметку почерневшего неба [i]. Наконец, разыграйте первое, что можете:<br><b>А. Пепельное чудище направилось к Вулканическим пустошам. </b>Если на стене первобытной пещеры есть отметка ЧД4 [iii], переместите его логово на случайный участок Вулканических пустошей. Бросьте <1d6>, чтобы поместить логово в соответствующий район: [1-2] А, [3-4] Б, [5-6] В.<br><b>Б. Пепельное чудище прибыло в долину. </b>Подготовьте ЧД4 (см. раздел «Появление чудища» в правилах игры на с. 74). Поместите его логово на случайный участок Вулканических пустошей. Бросьте <1d6>, чтобы поместить логово в соответствующий район: [1-2] А, [3-4] Б, [5-6] В.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<blackenedsky>"},{"label":"ii","image":"<blaze>"},{"label":"iii","image":"<bh4>"}]},{"id":"outcomes-597","code":"597","description":{"en":"<p>As you round a shadowy bend, you see several figures. Their mood is ominous, and you can barely overhear their mutterings of doom and destruction. You fear this encounter may turn hostile.</p>\\n\\"Test <might> or <dexterity> to <i>fight</i>. Add +2 if you are <i>vengeful</i> and +4 if you have the battle mark.\\n10+: As the hostile group descends upon you, you disperse them with well-placed blows. They slink off into the shadows. Remove the mystery token and place it on Rising Chaos, then add <lore>.\\n7-9: They rush you, but you manage to fend them off with some cuts and bruises. Suffer <minor_injury>, then move the mystery token to another hex, choosing the nearest hex without a character, if able.\\n1-6: Foes descends upon you, raining blows and curses. Suffer <major_injury><major_injury>. Move the mystery token to another hex, choosing a hex with no character and adjacent to a hex with an outpost, if able.\\"","ru":"<p><i><b>За тёмным поворотом показалось несколько фигур. Их угрожающий вид стал ещё мрачнее, когда вы услышали их бормотание о гибели и разрушении. Вы испугались, что эта встреча может перерасти в столкновение. </b></i></p><p>Проведите проверку <might> или <dexterity>, чтобы сразиться. +2, если вы <i>мстительный</i>, и +4, если у вас есть отметка битвы.<br><b>≥10:</b>  Когда враждебная группа набросилась на вас, вы разогнали их хорошо поставленными ударами. Они скрылись во мраке. Уберите жетон тайны, поместив его на карту «Выживите в растущем хаосе», затем добавьте <lore>.<br><b>7-9:</b>  Чужаки набросились на вас, но вам удалось отбиться, хоть вы и получили несколько порезов и ушибов. Получите <minor_injury>. Переместите жетон тайны на другой участок местности, выбрав ближайший участок без персонажа, если возможно.<br><b>1-6:</b>  Противники атаковали вас, осыпая ударами и проклятиями. Получите <major_injury><major_injury>. Переместите жетон тайны на другой участок местности, выбрав соседний с поселением участок без персонажа, если возможно.</p>"},"repeatable":false,"marks":[{"label":"","image":"<battle>"}]},{"id":"outcomes-599","code":"599","description":{"en":"<p>With your courageous act, the great maw of flames is sealed. The smoke abates, and the magma cools. The violence of the earth fades to distant memory as your people flourish in the valley.</p>\\n\\"Illustrate the saga of the sealed gate on the primal cave wall, including the blaze mark and the Volcanic Wastes mark. Your society <b>persists.</b>\\n\\nCongratulations! You have completed Stonesaga's campaign! To immortalize a photo of your primal cave wall and see other people's works of art, we invite you to share your saga with our community!\\n\\n@[Insert Link]@\\n\\nTo continue playing Stonesaga, see Playing Endless Mode After a Campaign on Rulebook p.97, or Beginning Subsequent Campaigns on Rulebook p.97.\\"","ru":"<p><i><b>Набравшись смелости, вы запечатали пасть пламени. Дым рассеялся, а магма остыла. Ярость земли осталась лишь в памяти вашего народа, который отныне стал процветать в долине.</b></i></p><p>На стене первобытной пещеры изобразите историю о запечатанных вратах, включив в неё отметку пламени [i] и отметку Вулканических пустошей [ii]. Ваша община <b>выжила</b>.</p><p>Поздравляем! Вы завершили кампанию «Наскальной истории»! Чтобы увековечить фотографию своей стены первобытной пещеры и увидеть произведения искусства других игроков, мы приглашаем вас поделиться своей историей с нашим сообществом!</p><p>Чтобы продолжить играть в «Наскальную историю», см. в правилах игры раздел «Начало следующих кампаний» на с. 97 или раздел «Бесконечный режим» на с. 102.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<blaze>"},{"label":"ii","image":"<volcanic_wastes>"},{"label":"","image":"<qrcode>"}]},{"id":"outcomes-606","code":"606","description":{"en":"<p>\\"The glow of the behemoth's eyes locks in on the symbol you show...\\"</p>\\n\\"Choose one of the following and resolve it:\\n\\n<b>A) Trace the symbol upon the behemoth's brow:</b> End the encounter. Placate the behemoth's demeanor by 1. It flees. You may remove its aim and all its trace markers, then replace its current Instinct with Footsteps of Rebirth (BY05).\\n\\n<b>B) Erase the symbol:</b> End the encounter. Aggravate the behemoth's demeanor by 2. The behemoth flees.\\"","ru":"<p><i><b>Чудище пристально вгляделось в символ, который вы ему показали...</b></i></p><p>Выберите и разыграйте одно:<br><b>А. Начертите символ на лбу чудища. </b>Завершите встречу. Успокойте чудище на 1. Чудище сбегает. Можете убрать жетон направления и все жетоны следов этого чудища, а затем заменить его текущий инстинкт на «Нести возрождение» (ЧЕ05).<br><b>Б. Сотрите символ. </b>Завершите встречу. Разозлите чудище на 2. Чудище сбегает. </p>"},"repeatable":false},{"id":"outcomes-609","code":"609","description":{"en":"<p>By threat and persuasion, you intimidate the rogue group into backing down, and a tense stability settles over the valley. Though you no longer face the crisis of losing many of your people, some individuals still slip away in the night, and grumbling around the fire increases.</p>\\nAdd <unrest><unrest><unrest><unrest>. Illustrate the saga of the dispersal on the primal cave wall, including the schism mark. Add Fireside Grumbles (NN01) to the Night deck, if able.","ru":"<p><i><b>Угрозами и убеждениями вы заставили мятежную группу отступить, и в долине воцарился шаткий мир. Хоть вам больше и не грозила опасность, что могла унести множество жизней, некоторые ваши люди всё же исчезли в ночи, а посиделки у костра всё чаще наполнялись недовольными возгласами.</b></i></p><p>Добавьте <unrest><unrest><unrest><unrest>. На стене первобытной пещеры изобразите историю о расселении, включив в неё отметку раскола. Добавьте карту «Ворчание у костра» (НО01) в колоду ночи, если возможно.</p>"},"repeatable":false,"marks":[{"label":"","image":"<schism>"}]},{"id":"outcomes-612","code":"612","description":{"en":"<p>In the depths of the lair, you uncover a twisting stem of bone, atop it a flower with the pallor of a corpse. The flower opens, flickering with flame, and a vision cascades into your eyes. When you awaken, the room is filled with ash, the strange stem gone. Was the event you saw past? A possible future? Somehow, both past and prophecy?</p>\\n\\"Find goal card GY07. The player who completed the final <i>champion</i> test may look at that card for no more than 1 minute, then returns it to the game box and describes it to the other players for any amount of time. Then illustrate the saga of spreading change on the primal cave wall, including the BH4 mark (i) and the prophecy mark (ii) enclosing the <cloud> mark.\\n\\nAt the end of this challenge, end the current epoch. Refer to Codex p.196 to continue your campaign into Epoch 2.\\"","ru":"<p><i><b>В глубинах логова вы обнаружили скрученный костяной стебель, на вершине которого распустился мертвенно‑бледный цветок. Замерцавший пламенем бутон раскрылся и обрушил на вас видение. Когда вы пришли в себя, логово было заполнено пеплом, а странный стебель исчез. То, что вы увидели, уже давным‑давно свершилось? Или только грядёт? А может быть, видение было одновременно и воспоминанием, и пророчеством?</b></i></p><p>Найдите карту цели ЦЕ07. Игрок, прошедший последнюю проверку защитника, может изучать эту карту не более 1 минуты, после чего должен вернуть её в колоду целей и описать её другим игрокам. Затем на стене первобытной пещеры изобразите историю о волне перемен, включив в неё отметку ЧД4 [i] и отметку <cloud>, заключённую в отметку пророчества [ii].</p><p>В конце текущего испытания завершите эру. См. с. 196, чтобы начать эру 2.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<bh4>"},{"label":"ii","image":"<prophecy>"}]},{"id":"outcomes-614","code":"614","description":{"en":"<p>Your audience hangs on your every word as your tale stirs great heroes back to life, alongside the tests and crises they faced.</p>\\n\\"Subtract <unrest><unrest>, then choose one of the following and resolve it:\\n\\n<b>A) Praise a past hero's strength:</b> Choose a Legend card (assigned or unassigned) without the growth mark, then choose one of the Legend card's attributes. Permanently raise attribute by 2 (to a maximum of 8). Add the growth mark to the Legend side of that card.\\n\\n<b>B) Relate your circumstances to past's lessons:</b> Choose a Legend card (assigned or unassigned), then choose a trait your character has that the Legend card does not have. Add that trait to the Legend card.\\n\\n<b>C) Expand upon a hero's trials:</b> Choose a Legend card (assigned or unassigned), then choose a mark on the primal cave wall not on that card. Add it to that Legend card.\\n\\nThen return Fireside Grumbles (NN01) to the game box.\\"","ru":"<p><i><b>Ваши люди внимали каждому слову, пока ваш рассказ оживлял великих героев прошлого вместе с испытаниями и трудностями, через которые они прошли.</b></i></p><p>Уберите <unrest><unrest>, затем выберите и разыграйте одно:<br><b>А. Восславьте героя прошлого.</b> Выберите карту легенды без отметки становления, затем увеличьте любую её характеристику на 2 (не более чем до 8). Добавьте отметку становления на сторону легенды этой карты.<br><b>Б. Соотнесите всё происходящее с уроками прошлого. </b>Выберите карту легенды, затем выберите одну черту, которая есть у вашего персонажа, но отсутствует на этой карте. Добавьте эту черту на карту легенды.<br><b>В. В деталях поведайте историю об испытаниях героя. </b>Выберите карту легенды, затем на стене первобытной пещеры выберите отметку, которой ещё нет на этой карте. Добавьте эту отметку на эту карту легенды. </p><p>Затем верните в коробку карту «Ворчание у костра» (НО01).</p>"},"repeatable":false,"marks":[{"label":"","image":"<growth>"}]},{"id":"outcomes-618","code":"618","description":{"en":"<p>\\"Your mind touches the coral. You feel the water lap at your feet in the valley, far below. You feel the gentle light of distant stars, unfettered by sky. You feel the crawling of tiny feet across your skin in a dozen realms beyond. And you feel an intelligence brush up against your own, recognizing you as a creature of thought and emotion.\\n\\nWhen you return to the valley, you find the coral has withdrawn to a group of overgrowths surrounding the scar. While life in the valley is changed, the coral does not spread in the days and weeks to come. You teach your people how to commune with the coral, and wonders beyond the stars reveal themselves to you...\\"</p>\\n\\"Add <population><population><population> and subtract <unrest><unrest><unrest>. Remove each coral overgrowth overlay that is not adjacent to the impact crater hex, then flip each remaining coral overgrowth overlay to its inactive side.\\n\\nIllustrate the saga of the bond beyond time on the primal cave wall, including the Starlit Sea mark (i) and the conclusion mark enclosing the coral mark (ii). Your society <b>persists.</b> Gain the The Beyond (KN20) Knowledge card.\\n\\nCongratulations! You have completed <i>Stonesaga</i>'s campaign! To immortalize a photo of your primal cave wall and see other people's works of art, we invite you to share your saga with our community!\\n\\n@[Insert Link]@\\n\\nTo continue playing <i>Stonesaga</i>, see Playing Endless Mode After a Campaign on Rulebook p.97, or Beginning Subsequent Campaigns on Rulebook p.97.\\"","ru":"<p><i><b>Ваш разум запел в унисон с кораллом. Вы ощутили, как вода плескалась у ваших ног в долине далеко внизу. Вы ощутили мягкий свет далёких звёзд, не скрытых облаками. Вы ощутили ползущие по коже крошечные ножки из дюжины иных миров. И вы ощутили, как коралл признал в вас существо, способное мыслить и чувствовать.<br>Когда вы вернулись в долину, вы увидели, что коралл отступил к зарослям вокруг кратера. Хоть жизнь в долине и изменилась, одно вы могли сказать точно — коралл больше не будет разрастаться. Вы научили свой народ общаться с кораллом — и чудеса за пределами звёзд открылись вам…</b></i></p><p>Добавьте <population><population><population> и уберите <unrest><unrest><unrest>. Уберите все накладки коралловых зарослей, не соседствующие с местом падения, затем переверните оставшиеся в долине накладки коралловых зарослей неактивной стороной вверх.</p><p>На стене первобытной пещеры изобразите историю о связи вне времени, включив в неё отметку Звёздного моря [i] и отметку коралла, заключённую в отметку окончания [ii]. Ваша община <b>выжила</b>. Получите карту знаний «Вовне» (ЗБ20).</p><p>Поздравляем! Вы завершили кампанию «Наскальной истории»! Чтобы увековечить фотографию своей стены первобытной пещеры и увидеть произведения искусства других игроков, мы приглашаем вас поделиться своей историей с нашим сообществом!</p><p>Чтобы продолжить играть в «Наскальную историю», см. в правилах игры раздел «Начало следующих кампаний» на с. 97 или раздел «Бесконечный режим» на с. 102.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<starlitsea>"},{"label":"ii","image":"<conclusion>EncCoral"},{"label":"","image":"<qrcode>"}]},{"id":"outcomes-622","code":"622","description":{"en":"<p>You make your way toward the scar...</p>\\n\\"Proceed to the venture below (see Ventures on Rulebook p.60).\\n\\n<bi>The lip of the scar creeps into your vision. It is jagged, the surrounding stone turned to glass by the force of the impact. Descending will require great care.</bi>\\n<b>Group:</b> Everyone must test <awareness> to descend safely. Add +1 for each <i>exploration</i> item you have and +2 if you are <i>intrepid</i>.\\n11+: You safely descend. The venture continues.\\n1–10: You tumble down the slope, and are cut badly on the jagged glass in the process. Suffer <major_injury><minor_injury>. The venture continues.\\n\\n<bi>Within the pit at the center of the scar, you approach the monumental stone that smashed the valley's surface. Fronds of coral gently wave around it, moving in tune to an inaudible rhythm. A crack extends up one side of the great stone. It seems the best place to hide, but what lies within?</bi>\\n<b>Coral, Group:</b> Everyone must test <might> to push within. A character adds +2 if they have the coral mark.\\n11+: You push within the crevice. Inside, you find the stone hollow, a shell surrounding a suspended coral heart that beats above you. The venture continues.\\n1–10: You cough and choke as the coral spores fill your lungs. If all characters resolve this result, the venture fails unless a character suffers <minor_disease> or spends <lore> to attempt this test again.\\n\\n<bi>The great beating of the heart beckons you into the darkness. Someone must approach...</bi>\\nSomeone must commune with the heart. Choose a character on the venture. Add the coral mark to the Legend side of their Character card, then check the Legend box on that card.\\"","ru":"<p><i><b>Вы направились к кратеру…</b></i></p><p>Отправьтесь в поход (см. раздел «Походы» в правилах игры на с. 60).</p><p><i><b>Вы увидели край кратера. Он был зазубренным, а окружающие его камни превратились в стекло от силы удара. Спускаться предстояло с большой осторожностью.</b></i></p><p>Группа. Все персонажи в походе должны провести проверку <awareness>, чтобы безопасно спуститься. +1 за каждый предмет для <i>исследования</i>, который есть у персонажа, и +2, если персонаж <i>отважный</i>.<br><b>≥11:</b>  Вы благополучно спустились. Продолжите поход.<br><b>1-10:</b>  Вы скатились по склону, сильно порезавшись о зазубренное стекло. Получите <major_injury> и <minor_injury>. Продолжите поход.</p><p><i><b>Вы подошли к лежащему посередине кратера огромному камню, который упал в долину. Около камня мягко покачивались коралловые отростки, двигаясь в ритме неслышной вам мелодии. А по самому камню змеилась вверх глубокая трещина. Вам показалось, что внутри камня было что‑то спрятано. Но что именно?</b></i></p><p><b>Коралл, группа.</b> Все персонажи в походе должны провести проверку <might>, чтобы протиснуться внутрь. +2, если у персонажа есть отметка коралла.<br><b>≥11:</b>  Вы протиснулись в расщелину. Внутри вы обнаружили, что камень полый — он был оболочкой, которая окружала подвешенное коралловое сердце, бившееся у вас над головой. Продолжите поход.<br><b>1-10:</b>  Вы начали кашлять и задыхаться, когда коралловые споры заполнили ваши лёгкие. Если все персонажи получили этот результат, поход окончился неудачно, если только любой персонаж в походе не получит <major_disease> или не потратит <lore>, чтобы провести проверку ещё раз.</p><p><b><i>Гул великого сердца звал вас из темноты. Кто‑то должен был подойти к сердцу и поговорить с ним… </i></b></p><p>Выберите персонажа в этом походе. Добавьте отметку коралла на сторону легенды карты этого персонажа, затем этот персонаж становится легендой.<br>Завершите этот поход и достигните соответствующей цели.</p>"},"repeatable":false,"marks":[{"label":"","image":"<coral>"}]},{"id":"outcomes-624","code":"624","description":{"en":"<p>You stumble into the heart of the coral overgrowth, the chiming fraying at your mind and twisting the world into knots. At the center is a glowing tendril of coral.</p>\\n\\"Choose one of the following and resolve it:\\n\\n<b>A) Harvest the glowing bulb:</b> Gain 3 living coral. Then choose an inactive coral overgrowth in the valley and flip it to its active side, if able.\\n\\n<b>B) Commune with the coral:</b> Your mind's eye flashes to a location connected to this place by the coral. Place a mystery token in another hex of your choice, choosing a hex with a coral overgrowth, if able.\\n\\n<b>C) Put the coral in a dormant state:</b> Discard 1 moonblood to flip an active coral overgrowth of your choice to its inactive side.\\"","ru":"<p><i><b>Вы заплутали в самом сердце коралловых зарослей. Звон разрывал ваш рассудок и скручивал мир в узлы. Вы наткнулись на светящийся коралловый отросток.</b></i></p><p>Выберите и разыграйте одно:<br><b>А. Возьмите светящийся шар.</b> Получите 3 живых коралла. Затем, если в долине есть хотя бы 1 накладка неактивных коралловых зарослей, переверните любую из них.<br><b>Б. Свяжитесь с кораллом. </b>Перед вашим внутренним взором мелькнуло место, связанное с этими зарослями. Поместите жетон тайны на другой участок местности, выбрав участок с коралловыми зарослями, если возможно.<br><b>В. Усыпите коралл. </b>Сбросьте 1 лунную кровь, чтобы перевернуть любые активные коралловые заросли.</p>"},"repeatable":false},{"id":"outcomes-625","code":"625","description":{"en":"<p>\\"The behemoth's blistered tracks fan out in a leaflike pattern. Is this great creature... making art for the joy of it? Was it dancing?\\"</p>\\n\\"Choose one of the following and resolve it:\\n\\n<b>A) Study the pattern's details:</b> If the behemoth has an unrevealed Secret card assigned to it, reveal this behemoth's currently assigned Secret card, then record under the Secrets for that behemoth in the Journal.\\n\\n<b>B) Behold the whole pattern from afar to see a message:</b> If you have a Legend card with two or more marks, you may discard it to add 1 of those marks to the Legend side of your Character card.\\"","ru":"<p><i><b>Пузырчатые следы чудища разветвлялись и складывались в узор, напоминающий лист. Неужели это великое создание творило искусство ради удовольствия?.. Неужели оно танцевало?</b></i></p><p>Выберите и разыграйте одно:<br><b>А. Изучите детали узора. </b>Если у чудища есть неоткрытая назначенная карта секрета, откройте её. Затем запишите её в раздел секретов этого чудища в журнале.<br><b>Б. Осмотрите узор издалека. </b>Если у вас есть карта легенды хотя бы с 2 отметками, можете сбросить эту карту, чтобы добавить одну из этих отметок на сторону легенды карты своего персонажа.</p>"},"repeatable":false},{"id":"outcomes-635","code":"635","description":{"en":"<p>With might and fury you drive back the coral predators. With these harbingers of the coral thinned, some of the overgrowths go dormant.</p>\\n<p>Choose up to two active coral overgrowth overlays and flip them to their inactive sides.</p>","ru":"<p><i><b>Собравшись с силами, вы отогнали коралловых хищников. Когда этих вестников коралла стало меньше, часть зарослей затихла и замерла.</b></i></p><p>Выберите не более 2 накладок активных коралловых зарослей и переверните их.</p>"},"repeatable":false},{"id":"outcomes-640","code":"640","description":{"en":"<p>You surmount the great, withering sheets of ice. As you stand astride the sky, staring into the eyes of the massive cadaver, you...</p>\\n\\"Illustrate the saga of the icy climb on the primal cave wall, including the mark of your starting region, the glacier mark (i), and the discovery mark (ii). Then, resolve the first you are able:\\n\\n<b>A) ...see a land touched by clouds reflecting on the skull's sheer surface:</b> If your starting region is the Verdant Vale, <outcome> 984.:\\n\\n<b>B) ...hear the whisper of the wind through trees just past the glacier:</b> If your starting region is the Skyreach Plateau, <outcome> 423.\\n\\n<b>C) ...notice something truly unexpected:</b> <outcome> 928.\\"","ru":"<p><i><b>Вы взобрались на огромные иссохшие ледяные пласты. Стоя под самым небом, глядя в глазницы гигантского черепа, вы… </b></i></p><p>Получите карту знаний «Переход через ледники» (ЗБ14). На стене первобытной пещеры изобразите историю о ледяном восхождении, включив в неё отметку своего начального региона, отметку ледника [i] и отметку открытия [ii]. Затем разыграйте первое, что можете:<br><b>А. …увидели землю, тронутую облаками, отражающимися на гладкой поверхности черепа. </b>Если ваш начальный регион — Дивная долина, то <outcome> 984.<br><b>Б. …услышали шёпот ветра в деревьях сразу за ледником.</b> Если ваш начальный регион — Поднебесная равнина, то <outcome> 423.<br><b>В. …заметили нечто поистине неожиданное. </b><outcome> 928.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<glacier>"},{"label":"ii","image":"<discovery>"}]},{"id":"outcomes-642","code":"642","description":{"en":"<p>The behemoth completes its furtive search. What could it have been seeking?</p>\\n<p>\\"Place a mystery token in each hex with a trace token.\\n\\nThen, remove all of this behemoth's trace markers from the valley. Assign the Return to Slumber (BT20) instinct to this behemoth (replacing its previous instinct).\\"</p>","ru":"<p><i><b>Чудище завершило свои таинственные поиски. Что же оно пыталось найти?</b></i></p><p>Поместите жетон тайны на каждый участок местности с жетоном следов.</p><p>Затем уберите жетон направления и все жетоны следов этого чудища. Замените его текущий инстинкт на «Вернуться в забытьё» (ЧК20).</p>"},"repeatable":false},{"id":"outcomes-644","code":"644","description":{"en":"<p>\\"The light illuminates an animal carcass. It looks like it hasn't been here too long, so it should be safe to eat.\\"</p>\\n\\"Test <might> to pull the carcass free. Add +2 if you are <i>resourceful</i> and +2 if you have <cut>.\\n13+: You wrench the carcass from the recent rockslide. Gain 2 game, 1 bone, and 1 hide.\\n9–12: You manage to free a chunk of the creature. Gain 1 game and 1 hide.\\n1–8: Your efforts destabilize the moraine, and rocks tumble around you. Suffer <minor_injury>.\\"","ru":"<p><i><b>Свет выхватил из темноты тушу животного. Казалось, она пролежала здесь недолго, так что, вероятно, вы могли бы разделать её.</b></i></p><p>Проведите проверку <might>, чтобы вытащить тушу. +2, если вы <i>изобретательный</i>, и +2, если у вас есть <cut>.<br><b>≥13:</b>  Вы вытянули тушу из-под недавнего каменного обвала. Получите 2 дичи, 1 кость и 1 шкуру.<br><b>9-12:</b>  Вам удалось оторвать кусок туши. Получите 1 дичь и 1 шкуру.<br><b>1-8:</b>  Вы расшатали морену, и вокруг посыпались камни. Получите <minor_injury>. </p>"},"repeatable":false},{"id":"outcomes-652","code":"652","description":{"en":"<p>A rainstorm descends, and water begins spilling over the side of the chasm, threatening to turn it into an unexpected river!</p>\\n\\"Test to <dexterity> to scramble up the side. Add +2 if you are <i>intrepid</i> and +2 if you have a Piton.\\n12+: You vault desperately up the chasm wall to safety. Gain 1 water.\\n8–11: The torrent strikes you, but you manage to catch a dangling shrub and pull yourself from the rushing water. Suffer <minor_injury>.\\n1–7: You are swept away by the current. Suffer <major_injury>, lose one randomly selected item, and flee to a randomly selected adjacent hex.\\"","ru":"<p><i><b>На долину обрушился ливень такой силы, что скапливающаяся вода начала переливаться через край пропасти, грозя превратить её в реку!</b></i></p><p>Проведите проверку <dexterity>, чтобы взобраться на край. +2, если вы <i>отважный</i>, и +2, если у вас есть «Скальный крюк».<br><b>≥12:</b>  Вы отчаянно взобрались по стене пропасти в безопасное место. Получите 1 воду.<br><b>8-11:</b>  Поток сбил вас с ног, но вам удалось ухватиться за свисающий куст и убраться подальше от стремительно прибывающей воды. Получите <minor_injury>.<br><b>1-7:</b>  Течение унесло вас. Получите <major_injury>, потеряйте 1 случайный предмет и сбегите на случайный соседний участок местности.</p>"},"repeatable":false},{"id":"outcomes-654","code":"654","description":{"en":"<p>You reach out toward the water when suddenly a hand emerges from the depths. It grasps at you, attempting to pull to the surface and dragging you under in the process.</p>\\n\\"Choose a Character card in the game box with the moonblood mark (ii) who is Young or Old (they can't be a Legend). Illustrate the saga of the frozen one on the primal cave wall, including the moonblood mark (ii) and the mystery mark (i). Return Face in the Deep (JQ02) to the game box. Then resolve the first you are able:\\n\\n<b>A) Fight off the ancient:</b> If your <might> and your <conviction> are both higher than those of the chosen character, you break away. Suffer <major_injury> and add <lore><lore>. Return the chosen character to the game box.\\n\\n<b>B) Slip beneath the surface:</b> Exchange that Character card with your current Character card. Add the moonblood mark (ii) to the Legend side of your previous character, then place that card in the game box. At the end of the challenge, your newly acquired character remains an available character and your previous character remains in the game box.\\"","ru":"<p><i><b>Когда вы потянулись к воде, из глубины вдруг показалась рука. Кто‑то пытался выбраться на поверхность и вместе с этим утянуть вас на дно.</b></i></p><p>Найдите в коробке карту молодого или пожилого персонажа (но не легенду) с отметкой лунной крови [ii], если возможно. На стене первобытной пещеры изобразите историю о замёрзшем, включив в неё отметку лунной крови [ii] и отметку тайны [i].</p><p>Верните в коробку карту «Облик на глубине» (ПЗ02). Затем разыграйте первое, что можете:<br><b>А. Отбейтесь от древнего создания. </b>Если и ваша <might>, и ваша <conviction> больше, чем у выбранного персонажа, вам удалось вырваться. Получите <major_injury> и добавьте <lore><lore>. Верните в коробку карту выбранного персонажа.<br><b>Б. Уйдите под поверхность. </b>Замените карту своего текущего персонажа этой картой персонажа. Добавьте отметку лунной крови [ii] на сторону легенды карты своего предыдущего персонажа, затем верните её в коробку. В конце испытания ваш новый персонаж станет доступным, а предыдущий останется в коробке.<br><b>В. Вы потрясли головой, пытаясь отбросить наваждение, и поняли, что вам всё это лишь показалось. </b>Без эффекта</p>"},"repeatable":false,"marks":[{"label":"i","image":"<mystery>"},{"label":"ii","image":"<moonblood>"}]},{"id":"outcomes-658","code":"658","description":{"en":"<p>\\"You have almost finished etching the mark on the behemoth's shell. With a great, mighty stroke, you complete the symbol. The behemoth goes stock still. Then, the shell bursts like a wave crashing upon the ocean, the whole creature seeming to turn to liquid. The behemoth's blood spills forth, blue and crystalline as the remnants of the shell melt away like a spring frost. The great gouts of icy liquid flow past you, seeping across the landscape and trickling back into the behemoth's lair. Where the blood flows, the land freezes hard as deep winter.\\"</p>\\n\\"End this challenge.\\n\\nIllustrate the saga of the felled ancient on the primal cave wall, including the battle mark (i) and the alert behemoth's mark adorned by the behemoth's blood mark (ii). Add the behemoth's blood mark to the Legend side of the card of each character who participated in the venture. One character who participated in the venture must discard a <i>weapon</i> item, if able.\\n\\nPlace the alert behemoth's lair in its current hex in its inactive state. Then, if there are any unplaced icy wake overlays, place them in randomly selected hexes adjacent to the behemoth's inactive lair. For each wake placed this way, roll <1d6> and place it in the corresponding zone: 1–2: A, 3–4: B, 5–6: C. If a wake would be placed in a hex with an overlay this way, remove the overlay and replace it with the icy wake. \\n\\nThen end the Epoch. See Codex p.204 to begin Epoch 3.\\"","ru":"<p><i><b>Вы почти закончили выцарапывать отметку на панцире чудища. Могучим последним взмахом вы завершили символ. Чудище застыло, словно окаменев. Затем панцирь взорвался, будто волна, разбившаяся о берег, — всё тело существа, казалось, обратилось в жидкость. Кровь чудища хлынула наружу — синяя и кристальная, а остатки панциря растаяли, как весенняя изморозь. Потоки ледяной жидкости пронеслись мимо вас, просочились по земле и потекли обратно в логово чудища. Там, где пролилась эта кровь, земля замёрзла, словно в разгар суровой зимы.</b></i></p><p>Завершите текущее испытание.</p><p>На стене первобытной пещеры изобразите историю о поверженном древнем существе, включив в неё отметку битвы [i] и отметку бодрствующего чудища, украшенную отметкой крови чудища [ii]. Добавьте отметку крови чудища [ii] на сторону легенды карт персонажей, участвовавших в этом походе. Один из этих персонажей должен сбросить оружие, если возможно.</p><p>Поместите логово бодрствующего чудища неактивной стороной вверх на участок местности с чудищем. Затем, если остались неразмещённые накладки ледяных отпечатков, поместите их на случайные участки местности, соседние с неактивным логовом чудища. Для каждого отпечатка бросьте <1d6>, чтобы поместить отпечаток в соответствующий район: [1-2] А, [3-4] Б, [5-6] В. Если при этом вы должны поместить отпечаток в район с другой накладкой, замените её на ледяной отпечаток.</p><p>Затем завершите текущую эру. См. с. 204, чтобы начать эру 3.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<battle>"},{"label":"ii","image":"<behemothsblood>"}]},{"id":"outcomes-667","code":"667","description":{"en":"<p>Choking ash spreads over the skies. In the days to come, the air grows bitter and the land sours. Only two options exist for your people: escape or perseverance. Either will be a bitter battle for life itself.</p>\\n\\"Lose <1d6><population>. Then, if <population> is 0, <outcome> 966. Otherwise, as a group, the players must choose one of the following paths for your society:\\n\\n<b>A) Persist to the bitter end:</b> Add Ashfall (CY05) to your looming challenge.\\n\\n<b>B) Desperately seek an exit to the valley:</b> Add Exodus (CZ09) to your looming challenges.\\"","ru":"<p><i><b>Удушающий дым распространился по всему небу. В последующие дни воздух стал горьким, а земля — мёртвой. Для вашего народа оставалось лишь два пути: бежать из этих мест или держаться до последнего.</b></i></p><p>Завершите текущее испытание.</p><p>Бросьте <1d6> и уберите столько <population>, сколько выпало на <1d6>. Затем, если значение <population> равно 0, то <outcome> 966. В противном случае совместно выберите один из следующих путей развития общины:<br><b>А. Держитесь до последнего. </b>Добавьте к грядущим испытаниям карту «Пеплопад» (ИЕ05).<br><b>Б. Найдите выход из долины. </b>Добавьте к грядущим испытаниям карту «Исход» (ИЯ09).</p>"},"repeatable":false},{"id":"outcomes-671","code":"671","description":{"en":"<p>Using your supplies to buy loyalty, you keep the people under control. The food may keep them in line, but without stockpiles you suffer greatly in the winter.</p>\\n\\"End this challenge.\\n\\nSubtract <population><population><population><population><population>. Illustrate the saga of dominance on the primal cave wall, including the caution mark (i) and harrowing mark (ii). Then, as a group, the players must choose one of the following paths for your society:\\n\\n<b>A) Seek the coral's origins in a strange and icy land:</b> If the Starli Sea mark (iii) is on the primal cave wall, add To Speak Beyond the Sky (CC07) to your looming challenges.\\n\\n<b>B) Face a champion of old who now serves the coral:</b> If the coral mark is enclosed in the conclusion mark (iv) on the primal cave wall, add The Comet's Chosen (CC08) to your looming challenges.\\n\\n<b>C) Seek out the lair of your ancient nemesis:</b> If the behemoth's blood mark (v) adorns the mark of a behemoth with an inactive lair on the primal cave wall, add Behemoth of the Comet (CC09) to your looming challenges.\\n\\n<b>D) Turn to a behemoth's bond of ancient days:</b> If a behemoth's mark is enclosed in the bond mark (vi) on the primal cave wall and that behemoth has an active lair in the valley, add Bond of the Behemoth (CC10) to your looming challenges.\\n\\n<b>E) Flee the valley once and for all:</b> Remove all other looming challenges and add Exodus (CZ09) to your looming challenges.\\"","ru":"<p><i><b>Раздав свои припасы, вы добились преданности людей и успокоили их. Хоть некоторые соплеменники, понадеявшиеся на сытые годы, и решили после этого остаться в общине, зимой им пришлось затянуть пояса.</b></i></p><p>Завершите текущее испытание.</p><p>Уберите 5<population>. На стене первобытной пещеры изобразите историю о влиянии, включив в неё отметку осторожности [i] и отметку ужаса [ii].</p><p>Затем совместно выберите один из следующих путей развития общины:<br><b>A. Отыщите истоки коралла в незнакомой ледяной земле. </b>Если на стене первобытной пещеры есть отметка Звёздного моря [iii], добавьте карту «Разговор со звёздами» (ИВ07) к грядущим испытаниям.<br><b>Б. Сразитесь с защитником древности, который ныне служит кораллу. </b>Если на стене первобытной пещеры есть отметка коралла, заключённая в отметку окончания [iv], добавьте карту «Избранник кометы» (ИВ08) к грядущим испытаниям.<br><b>В. Отправьтесь на поиски логова своего древнего врага. </b>Если на стене первобытной пещеры есть отметка чудища с неактивным логовом, украшенная отметкой крови чудища [v], добавьте карту «Чудище кометы» (ИВ09) к грядущим испытаниям.<br><b>Г. Вспомните о связи чудища с прошлым. </b>Если на стене первобытной пещеры есть отметка чудища с активным логовом в долине, заключённая в отметку связи [vi], добавьте карту «Узы чудища» (ИВ10) к грядущим испытаниям.<br><b>Д. Покиньте долину раз и навсегда. </b>Добавьте к грядущим испытаниям карту «Исход» (ИЯ09).</p>"},"repeatable":false,"marks":[{"label":"i","image":"<caution>"},{"label":"ii","image":"<harrowing>"},{"label":"iii","image":"<starlitsea>"},{"label":"iv","image":"<conclusion>"},{"label":"v","image":"<behemothsblood>"},{"label":"vi","image":"<bond>"}]},{"id":"outcomes-675","code":"675","description":{"en":"<p>Sickness descends across your villages. Without a means to fight this invisible death, your people struggle ot survive. It is not the strong nor the young that survive, merely the lucky.</p>\\n\\"End this challenge. \\n\\nSubtract 6 <population>. Illustrate the saga of the spreading death on the primal cave wall, including the harrowing mark (i) and the plague mark (ii). Roll <1d6> for each character and resolve the corresponding result: (1–2) The character perishes, (3–6) No effect.\\"","ru":"<p><i><b>Хворь обрушилась на ваши поселения. Не зная, как бороться с этой бестелесной смертью, ваши люди изо всех сил пытались выжить. Это удавалось не сильнейшим и не молодым — а тем, кому повезло.</b></i></p><p>Завершите текущее испытание.</p><p>Уберите 6 <population>. На стене первобытной пещеры изобразите историю о распространяющейся смерти, включив в неё отметку ужаса [i] и отметку чумы [ii]. Бросьте <1d6> за каждого персонажа и разыграйте эффект по результату броска: [1-2] этот персонаж умирает, [3-6] без эффекта.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<harrowing>"},{"label":"ii","image":"<plague>"}]},{"id":"outcomes-676","code":"676","description":{"en":"<p>\\"With a mighty crash, one behemoth topples the other, and bellows as if to challenge the sky's vaunted heights next...\\"</p>\\n\\"Resolve a <might> contest between the two alert behemoths, adding +2 to each behemoth's result for each of its trace markers on Colossal Brawl. For each of the losing behemoth's trace markers on Colossal Brawl, subtract <population><population> unless that behemoth's mark is enclosed in the bond mark (i) on the primal cave wall.\\n\\nThen, end this challenge. Illustrate the saga of the giant's clash, including the mark of each alert behemoth and the broken earth mark (ii). Flip the losing behemoth's lair to its inactive side.\\"","ru":"<p><i><b>С оглушительным грохотом один исполин поверг другого наземь и издал такой рёв, словно был намерен бросить вызов недосягаемым высотам неба...</b></i></p><p>Разыграйте состязание между <might> двух бодрствующих чудищ. +2 к результату чудища за каждый его жетон следов на карте «Узрите великую битву». Затем, если на стене первобытной пещеры нет отметки проигравшего чудища, заключённой в отметку связи [i], уберите <population><population> за каждый жетон следов этого чудища на карте «Узрите великую битву».</p><p>Завершите текущее испытание. На стене первобытной пещеры изобразите историю о схватке гигантов, включив в неё отметки каждого бодрствующего чудища и отметку расколотой земли [ii]. Переверните логово проигравшего чудища неактивной стороной вверх.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<bond>"},{"label":"ii","image":"<brokenearth>"}]},{"id":"outcomes-677","code":"677","description":{"en":"<p>You reach out your hand to touch the strange liquid.</p>\\n\\"Test <conviction> to grasp the liquid. Add +2 if you are <i>attuned</i> and +4 you have the moonblood mark.\\n10+: Gain 1 moonblood\\n7–9: The icy substance slips through your fingers. Lose <energy>.\\n1–6: <outcome> 899.\\"","ru":"<p><i><b>Вы протянули руку, чтобы коснуться странной жидкости.</b></i></p><p>Проведите проверку <conviction>, чтобы зачерпнуть жидкость. +2, если вы <i>сосредоточенный</i>, и +4, если у вас есть отметка лунной крови.<br><b>≥10:</b>  Получите 1 лунную кровь.<br><b>7-9:</b>  Холодное вещество выскользнуло сквозь пальцы. Потеряйте <energy>. <br><b>1-6:</b> <outcome>899.</p>"},"repeatable":false,"marks":[{"label":"","image":"<moonblood>"}]},{"id":"outcomes-682","code":"682","description":{"en":"<p>\\"Within what you now recognize as ancient behemoth's broken body, you find a strange treasure. Lifting it up, you feel a surge of dreadful power rush through your body.\\"</p>\\n\\"Based on the behemoth whose inactive lair you explored, set aside the corresponding Item cards from the Item deck (without looking at their fronts). If any character, animal companion, or storage structure currently has any of the <i>trophy</i> items that share a name with them (e.g. Symbiotic or Ruinous), exclude those cards from the cards you set aside.\\n\\n<BH1>: IT85, IT86\\n<BH2>: IT87, IT88\\n<BH3>: IT92, IT93\\n<BH4>: IT99, IT100\\n\\nShuffle the items you set aside, then gain one of them at random and return the other to the supply.\\n\\nIllustrate the saga of the ancient trophy on the primal cave wall, including the mark of the behemoth whose inactive lair you explored and the relic mark (i).\\"","ru":"<p><i><b>Внутри останков древнего чудища вы нашли странное сокровище. Вы взяли его в руки и ощутили, как через всё тело волной пронеслась ужасающая сила.</b></i></p><p>В зависимости от чудища, неактивное логово которого вы исследовали, отложите соответствующие карты предметов из колоды предметов (не рассматривая их лицевые стороны). Затем, если у персонажа, животного-компаньона или в сооружении-<i>хранилище</i> есть <i>трофейные </i>предметы с такими же словами в названиях (например, «симбиотический» или «разрушительный»), верните в колоду такие отложенные карты.</p><p><bh1>: ВЩ85, ВЩ86<br><bh2>: ВЩ87, ВЩ88<br><bh3>: ВЩ92, ВЩ93<br><bh4>: ВЩ99, ВЩ100</p><p>Перемешайте отложенные карты, возьмите из них одну случайную, а остальные верните в колоду.<br>На стене первобытной пещеры изобразите историю о древнем трофее, включив в неё отметку чудища, логово которого вы исследовали, и отметку реликвии.</p>"},"repeatable":false,"marks":[{"label":"","image":"<bh1>"},{"label":"","image":"<bh2>"},{"label":"","image":"<bh3>"},{"label":"","image":"<bh4>"},{"label":"i","image":"<relic>"}]},{"id":"outcomes-686","code":"686","description":{"en":"<p>\\"Under sunlight's caress, the seedling has begun to sprout, gentle green tendrils seeking nourishment in its environment. If it is not fed and watered, it will wither as surely as the rest of the Tangle.\\"</p>\\n\\"Embark on the venture below (see Ventures on Rulebook p.60).\\n\\n<bi>The great seed from the root-tunnels is not merely large, it also seems to have unusual properties and needs. To understand it, you must leverage all your knowledge of the Tangle.</bi>\\n<b>Champion:</b> Someone must test <awareness> to observe the seed. Add +2 if you are <i>attuned</i> and +4 if you have the Tangle mark. You may spend 1 <lore>; if you do, add +4 to the result.\\n12+: Studying the seed, you see that its tendrils grow toward the earth. You suspect it will be healthiest if buried, as it would be in the natural order of things. The venture continues.\\n1–11: You're stumped. The venture fails unless a character spends <energy><energy> or <lore> to attempt this test again.\\n\\n<bi>You set about burying the seed in nourishing nest of soil.</bi>\\n<b>Group:</b> Everyone must test <might> to pile soil. A character adds +2 if they have <chop>, +2 if they have <dig>, and +2 if they are <i>resourceful</i>. A character may discard 1 plant material; if they do, add +4 to their result.\\n11+: You bury the seed in loamy earth. If any character resolves this result, the venture continues.\\n1–10: The soil you have gathered doesn't seem quite right. If all characters on the venture resolve this result, the venture fails unless a character spends <energy><energy> or <lore><lore> to attempt this test again.\\n\\n<bi>With the seed ensconced in a protective mound of dirt and vegetation, you water it to encourage its growth.</bi>\\n<b>Champion:</b> Someone must test <dexterity> to irrigate the seed. Add +2 if you have <dig> and +2 if you are <i>wise</i>. You may discard 1 water; if you do, add +2 to the result. If you have <grind>, you may discard 1 bone, hide, or guts to add +6 to the result.\\n15+: You nourish the seedling successfully. Complete this venture and the associated goal.\\n1–14: Your efforts do not seem to be effective. The venture fails unless a character spends <energy><energy> or <lore> to attempt this test again.\\"","ru":"<p><i><b>Под лаской солнечных лучей пробудился к жизни росток, потянувшись нежными зелёными побегами к окружающему миру в поисках живительной силы. Если его не подкармливать и не поливать, он зачахнет, как и другие растения Сплетения.</b></i></p><p>Отправьтесь в поход (см. раздел «Походы» в правилах игры на с. 60).</p><p><b><i>Великое семя из корневых туннелей оказалось не просто огромным — оно, похоже, обладало необычными свойствами и нуждалось в особом уходе. Чтобы понять, как с ним обойтись, вам пришлось вспомнить всё, что вы знаете о Сплетении.</i></b></p><p><b>Защитник. </b>Один из персонажей в походе должен провести проверку <awareness>, чтобы изучить семя. +2, если этот персонаж <i>сосредоточенный</i>, и +4, если у него есть отметка Сплетения. Также +4, если персонаж потратит <lore>.<br><b>≥12:</b>  Изучив семя, вы увидели, что его побеги тянутся к земле. Вероятно, лучше всего было бы его закопать, как того требовал естественный порядок вещей. Продолжите поход.<br><b>1-11:</b>  Вы зашли в тупик. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy> или <lore>, чтобы провести проверку ещё раз.</p><p><b><i>Вы принялись закапывать семя в питательную почву.</i></b></p><p><b>Группа. </b>Все персонажи в походе должны провести проверку <might>, чтобы вспахать землю. +2, если у персонажа есть <chop>, +2, если у него есть <dig> и он <i>изобретательный</i>. Также +4, если персонаж сбросит 1 растительный материал.<br><b>≥11:</b>  Вы закопали семя в рыхлую землю. Если хотя бы один персонаж получил этот результат, продолжите поход.<br><b>1-10:</b>  Работа с землёй — не конёк вашей общины. Если все персонажи получили этот результат, поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy> или <lore><lore>, чтобы провести проверку ещё раз.</p><p><b><i>Поместив семя в насыпь из земли и растительности, вы полили его, чтобы оно быстрее росло.</i></b></p><p><b>Защитник.</b> Один из персонажей в походе должен провести проверку <dexterity>, чтобы полить семя. +2, если у этого персонажа есть <dig>, и +2, если он <i>мудрый</i>. Также +2, если он сбросит 1 воду. Если у этого персонажа есть <grind>, он может сбросить 1 кость, шкуру или жилы, чтобы добавить 6 к результату.<br><b>≥15:</b>  Вы напоили росток. Завершите этот поход и достигните соответствующей цели.<br>1-14  Ваши усилия не принесли результата. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy> или <lore>, чтобы провести проверку ещё раз.</p>"},"repeatable":false},{"id":"outcomes-688","code":"688","description":{"en":"<p>The grumbles become shouts, then ignite into bellows of rage. Soon, blows may be thrown and blood may be shed.</p>\\nAdd Open Hostilities (NN02) to the Night deck, if able. Otherwise, subtract <population>.","ru":"<p><i><b>Ропот перерос в крики, а затем вспыхнул рёвом ярости. В любой момент могла начаться кровавая потасовка.</b></i></p><p>Добавьте карту «Открытая враждебность» (НО02) в колоду ночи, если возможно. В противном случае уберите <population>.</p>"},"repeatable":false},{"id":"outcomes-690","code":"690","description":{"en":"<p>\\"You trace the pattern on the behemoth's back, and it grows still...\\"</p>\\n\\"Choose one of the following and resolve it:\\n\\n<b>A) Try to guide the behemoth:</b> End the encounter. The behemoth flees twice. Place your character in the final hex it reaches this way.\\n\\n<b>B) Send the behemoth away:</b> End the encounter. Aggravate the behemoth's demeanor by 1. The behemoth flees three times.\\"","ru":"<p><i><b>Вы прошлись по узору на спине чудища, и оно замерло…</b></i></p><p>Выберите и разыграйте одно:<br><b>А. Попробуйте направить чудище. </b>Завершите встречу. Чудище сбегает 2 раза. Переместите своего персонажа на участок местности, куда оно сбежало.<br><b>Б. Прогоните чудище. </b>Завершите встречу. Разозлите чудище на 1. Чудище сбегает 3 раза.</p>"},"repeatable":false},{"id":"outcomes-691","code":"691","description":{"en":"<p>Your desperate experiment is promising. Frost spreads across the seed, and it begins to go dormant at its touch. Perhaps the Tangle need not die after all!</p>\\n\\"At the end of any day, you may end this challenge.\\n\\nIllustrate the saga of the icy salvation on the primal cave wall, including the conclusion mark enclosing the <moon> mark. Add A New Flourishing (CN05) to your looming challenges.\\"","ru":"<p><i><b>Ваши отчаянные попытки принесли плоды. Мороз объял семя, и оно начало погружаться в спячку от ледяного прикосновения. Возможно, Сплетение всё же не было обречено на погибель!</b></i></p><p>В конце любого дня можете завершить текущее испытание.</p><p>На стене первобытной пещеры изобразите историю о ледяном спасении, включив в неё отметку <moon>, заключённую в отметку окончания.</p><p>Добавьте карту «Новый расцвет» (ИЖ05) к грядущим испытаниям.</p>"},"repeatable":false,"marks":[{"label":"","image":"<conclusion>"}]},{"id":"outcomes-692","code":"692","description":{"en":"<p>You push past the creeping vines to discover...</p>\\n\\"Embark on the venture below (see Ventures on Rulebook p.60).\\n\\n<bi>A strange furrow in the earth. A snarl of stony tendrils left behind by the behemoth form a seal, preventing you from reaching whatever lies within.</bi>\\n<b>Champion, Wonder:</b> Someone must test <might> to break the snarled seal. Add +2 if you have <stoneworking> and +2 for each <i>exploration</i> item you have.\\n11+: You break through the seal. Then continue the venture.\\n1–10: Your digging tools bounce off the stony vines. The venture fails unless a character spends <energy> or <lore> to attempt this test again.\\n\\n<bi>As soon as you crack the seal, a potent miasma leaks out. The behemoth clearly sought to contain this substance that bubbles up from the pits of the earth.</bi>\\n<b>Group, Hazard:</b> Everyone must test <awareness> to remain alert. Add +2 if you have an item with a <fire> token on it.\\n10+: You step back, and the cloud of built-up miasma slowly passes, withering leaves as it goes. Then continue the venture.\\n1–9: Suffer <major_disease>. If all characters on the venture resolve this result, the venture fails.\\n\\n<bi>You approach the murky, sputtering pool. What unearthly poison is this, expelled up from the earth's deepest bowels?</bi>\\n<b>Champion, Hazard:</b> Someone must test <conviction> to anoint their weapon in the bubbling goo. Add +4 if one or more Secrets have been recorded in the Journal for this behemoth.\\n12+: You dip your weapon into the liquid, and it hisses with audible vileness as it twists the weapon into an implement to fell the great beast. Complete this venture and the associated goal.\\n1–11: Your nerve breaks, and you back away from the pool. The venture fails unless a character spends <energy><energy> to attempt this test again.\\"","ru":"<p><i><b>Вы раздвинули вьющиеся лианы и обнаружили нечто интересное…</b></i></p><p>Отправьтесь в поход (см. раздел «Походы» в правилах игры на с. 60).</p><p><b><i>По земле тянулась странная борозда. Клубок каменных щупалец, оставленных чудищем, запечатывал проход. Что же скрывалось за ним?</i></b></p><p><b>Защитник, чудо. </b>Один из персонажей в походе должен провести проверку <might>, чтобы разрушить каменную печать. +2, если у этого персонажа есть <stoneworking>, и +2 за каждый его предмет для <i>исследования</i>.<br><b>≥11:</b>  Вы прорвались сквозь печать. Продолжите поход.<br>1-10  Ваши инструменты лишь отскакивали от каменных лоз. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy> или <lore>, чтобы провести проверку ещё раз.</p><p><b><i>Как только вы разрушили печать, наружу просочились едкие испарения. Видимо, чудище пыталось сдержать вещество, что поднималось из глубин земли.</i></b></p><p><b>Группа, угроза.</b> Все персонажи в походе должны провести проверку <awareness>, чтобы оставаться настороже. +2, если у персонажа есть предмет с <fire>.<br><b>≥10:</b>  Вы сделали шаг назад, когда плотное облако ядовитого пара медленно рассеялось, иссушая листья на своём пути. Продолжите поход.<br><b>1-9:</b>  Получите <major_disease>. Если все персонажи получили этот результат, поход окончился неудачно.</p><p><b><i>Вы подошли к мутной булькающей луже. Вам казалось, будто в ней был яд, что извергся из самых недр земли. </i></b></p><p><b>Защитник, угроза. </b>Один из персонажей в походе должен провести проверку <conviction>, чтобы окунуть оружие в бурлящую жижу. +4, если в журнале записан хотя бы 1 секрет этого чудища.<br><b>≥12:</b>  Вы опустили оружие в жидкость, и оно зашипело, исказилось и превратилось в орудие, способное повергнуть великого зверя. Завершите этот поход и достигните соответствующей цели.<br><b>1-11:</b>  У вас не хватило духу подойти к луже, и вы отступили прочь. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy>, чтобы провести проверку ещё раз.</p>"},"repeatable":false},{"id":"outcomes-693","code":"693","description":{"en":"<p>You pursue the trail of vines, and as you travel, the growth becomes thicker and more dense. Eventually, you reach a veritable wall of plants, seemingly impenetrable to human passage. Surely, there must be a way in...</p>\\n\\"Embark on the venture below (see Ventures on Rulebook p.60).\\n\\n<bi>The wall of vines may seem impenetrable, but surely you can hack your way in...</bi>\\n<b>Group:</b> Everyone must test <might> to cut a path. A character adds +2 if they have <cut>, +4 if they have <chop>, and +2 if they are <i>vengeful</i>.\\n13+: You slash your way through the verdant barricaded and create an opening. If any character resolves this result, the venture continues.\\n1–12: For each vine you slash, it almost seems as if another two take their place. Are they multiplying? If all characters on the venture resolve this result, the venture fails unless a character spends <energy><energy> or <lore><lore> to attempt this test again.\\n\\n<bi>As soon as you break through the outer wall, you find yourself in a bog. Trudging into the swamp amidst the roots of the great plant, you realize with sudden urgency that you are sinking!</bi>\\n<b>Group, Hazard:</b> Each character must test <awareness> to avoid sinking into the murky swamp. A character adds +2 if they have Rope or a Walking Stick and +2 if they are <i>wary</i>.\\n11+: You find a solid patch of roots and pull yourself from the mire. If any character resolves this result, the venture continues.\\n1–10: You struggle as you the mud rises around you. Suffer <major_injury><major_injury>. If all characters on the venture resolve this result, the venture fails unless a character spends <energy><energy> or <lore> to attempt this test again.\\n\\n<bi>Finally on solid ground, you marvel at the soft light that penetrates the dense canopy above. Your reverie is disrupted by a hungry growl: you have stumbled into a nest of predators!</bi>\\n<b>Group, Hazard:</b> Each character must encounter a predator (see Wildlife Encounters on Rulebook p.48), using the results below to <i>fight</i> instead of the standard results, adding an additional +2 if you have an item with a <fire> token on it or there is a <fire> token in your hex. If a character chooses to <i>flee</i>, they resolve the standard results, then leave the venture; if all characters <i>flee</i>, the venture fails.\\n12+: You drive the creatures off. If any character resolves this result, complete this venture and the associated goal.\\n1–11: You are gored badly by the predators' attack. Suffer <major_injury><minor_injury>. If all characters on the venture resolve this result, the venture fails unless a character spends <energy> or <lore> to attempt this test again.\\"","ru":"<p><i><b>Вы решили пройтись вдоль лиан. Чем дальше вы забредали, тем гуще и плотнее становились заросли. В конце концов вы добрались до настоящей стены из растений, через которую, казалось, невозможно было пробраться. Вы задались вопросом, действительно ли она неприступна, как кажется.</b></i></p><p>Отправьтесь в поход (см. раздел «Походы» в правилах игры на с. 60). </p><p><i><b>Стена из лиан казалась непроходимой, но вы решили прорубить себе путь…</b></i></p><p><b>Группа.</b> Все персонажи в походе должны провести проверку <might>, чтобы прорубить проход. +2, если у персонажа есть <cut>, +4, если у него есть <chop>, и +2, если он <i>мстительный</i>.<br><b>≥13:</b>  Вы прорубили себе путь сквозь зелёные баррикады и открыли проход. Если хотя бы один персонаж получил этот результат, продолжите поход.<br><b>1-12:</b>  На месте каждой лианы, которую вы срубали, словно вырастали две новые. Неужели их становилось больше? Если все персонажи получили этот результат, поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy> или <lore><lore>, чтобы провести проверку ещё раз.</p><p><i><b>Вы прорвались сквозь стену лиан и тут же оказались в болоте. Пробираясь по топям среди корней огромного растения, вы с ужасом осознали, что начали тонуть!</b></i></p><p><b>Группа, угроза. </b>Все персонажи в походе должны провести проверку <awareness>, чтобы не утонуть в мутном болоте. +2, если у персонажа есть «Верёвка» или «Трость», и +2, если он <i>осторожный</i>.<br><b>≥11:</b>  Вы нашли твёрдое место среди корней и выбрались из трясины. Если хотя бы один персонаж получил этот результат, продолжите поход.<br><b>1-10:</b>  Вы барахтались, пока грязь поднималась всё выше. Получите <major_injury><major_injury>. Если все персонажи получили этот результат, поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy> или <lore><lore>, чтобы провести проверку ещё раз.</p><p><i><b>Поняв, что почва больше не уходит из‑под ног, вы посмотрели наверх и увидели восхитительный мягкий свет, пробивающийся сквозь густой полог. Не успели вы насладиться картиной, как из грёз вас вырвал низкий рык: вы наткнулись на логово голодных хищников!</b></i></p><p><b>Группа, угроза. </b>Каждый персонаж в походе должен провести встречу с хищником (см. раздел «Встреча с хищником» в правилах игры на с. 48), используя приведённые ниже результаты проверки вместо обычных. +2, если у персонажа есть предмет с <fire> или если на его участке местности есть <fire>. Если персонаж решил отступить, он разыгрывает стандартные результаты, а затем покидает поход. Если все персонажи покинули поход, он окончился неудачно.<br><b>≥12:</b>  Вы заставили существ отступить. Если хотя бы один персонаж получил этот результат, завершите этот поход и достигните соответствующей цели.<br><b>1-11:</b>  Хищники нанесли вам тяжёлые раны. Получите <major_injury> и <minor_injury>. Если все персонажи получили этот результат, поход окончился неудачно, если только любой персонаж в походе не потратит <energy> или <lore>, чтобы провести проверку ещё раз.</p>"},"repeatable":false},{"id":"outcomes-694","code":"694","description":{"en":"<p>You manage to survive the hard season, finding ways to survive despite deprivation.</p>\\nAt the end of any day, you may end this challenge. Then, add <population><population><population>. Illustrate the saga of the hardwon bounty, including the plenty mark.","ru":"<p><i><b>Вы смогли выстоять в суровую пору, отыскивая любые возможности для выживания, вопреки всем невзгодам.</b></i></p><p>В конце любого дня можете завершить текущее испытание.</p><p>Затем добавьте <population><population><population>. На стене первобытной пещеры изобразите историю о нелегко доставшейся награде, включив в неё отметку изобилия.</p>"},"repeatable":false,"marks":[{"label":"","image":"<plenty>"}]},{"id":"outcomes-697","code":"697","description":{"en":"<p>In the vision, you feel yourself crawling on your belly through a vast, milky expanse. Below you, clouds and water swirl gently.</p>\\n\\"Embark on the venture below (see Ventures on Rulebook p.60).\\n\\n<bi>Eddies of consciousness swirl around you. Each time you reach your hand into a current, you see a different vision, a different place.<bi>\\n<b>Champion, Dream:</b> Someone must test <conviction> to see through the coral's eyes. Add +2 if you have a <i>coral</i> item and +2 if you are <i>inquisitive</i>. You may discard any number of living coral to add +2 per token discarded this way.\\n11+: Your mind expands as you perceive lands beyond your own. A red windswept plain. Spiraling ebony pools specked with stars. The venture continues.\\n1–10: You cannot comprehend what fills your senses. The venture fails unless a character spends <energy> or <lore> to attempt this test again.\\n\\n<bi>The churn of the coral's mind is overwhelming. But its memories swirl with familiar thoughts. Perhaps you can grab hold of one and ride it to safety like driftwood in a great storm.<bi>\\n<b>Champion, Dream:</b> Someone must test <awareness> to find a common thread of understanding. Add +2 if you have <music>, +4 if you have the mark of the song-weavers, and +2 if you are <i>lucky</i>. You may discard any number of living coral to add +2 per token discarded this way.\\n12+: You find a common thread which you can pull, and the mind of the coral seems to respond. Perhaps you can weave an understanding upon this idea.The venture continues.\\n1–11: You struggle to find anything you might share with an existence so vast and strange. The venture fails unless a character spends <energy> or <lore> to attempt this test again.\\n\\n<bi>Your raft of understanding is tenuous and fragile. It floats atop the surface of a vast consciousness that threatens to swallow you.</bi>\\n<b>Champion, Dream:</b> Someone must test <conviction> to express a message of coexistence. Add +4 if you have the coral mark, +2 if you have an <i>instrument</i> item, and +2 if you are <i>attuned</i>. You may discard any number of living coral to add +2 per token discarded this way.\\n13+: The coral fronds weave together, forming a face like your own. You feel its understanding grow in your shared perception, and you see yourself through its eyes, small and strange and frail. Complete this venture and the associated goal.\\n1–12: The coral responds, the fronds twitching wildly. But you sense confusion at your message. The venture fails unless a character spends <energy><energy> or <lore> to attempt this test again.\\n\\"","ru":"<p><i><b>Вы ползли на животе через огромное молочно‑белое пространство. А облака и вода медленно кружились под вами.</b></i></p><p>Отправьтесь в поход (см. раздел «Походы» в правилах игры на с. 60).</p><p><i><b>Вихри сознания потоком кружились вокруг вас. Каждый раз, когда вы протягивали руку к этому потоку, вам являлись новое видение и новое место.</b></i></p><p><b>Защитник, сон. </b>Один из персонажей в походе должен провести проверку <conviction>, чтобы посмотреть на мир глазами коралла. +2, если у этого персонажа есть предмет <i>коралла</i>, и +2, если этот персонаж <i>любознательный</i>. Также +2 за каждый <i>живой коралл</i>, который сбросит этот персонаж.<br><b>≥11:</b>  Ваш разум расширился, когда вы увидели неведомые места. Красная, продуваемая ветрами равнина… Спиральные чёрные водоёмы, усеянные звёздами… Продолжите поход.<br><b>1-10:</b>  Вы не смогли познать то, что наполнило ваш разум. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy> или <lore>, чтобы провести проверку ещё раз.</p><p><i><b>Водоворот разума коралла казался непреодолимым. Но в его недрах кружились знакомые мысли. Возможно, вы могли бы ухватиться за одну из них, как за корягу во время наводнения, чтобы выбраться.</b></i></p><p><b>Защитник, сон. </b>Один из персонажей в походе должен провести проверку <awareness>, чтобы найти связующую нить. +2, если у этого персонажа есть <music>, +4, если у него есть отметка песнопевца [i], и +2, если персонаж <i>удачливый</i>. Также +2 за каждый живой коралл, который сбросит этот персонаж.<br><b>≥12:</b>  Вы нашли связующую нить, за которую можно было потянуть, и разум коралла, похоже, откликнулся. Продолжите поход. <br><b>1-11:</b>  Вы безуспешно пытались найти хоть что-то, что могло бы вас сроднить с таким всеобъемлющим и странным существом. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy> или <lore>, чтобы провести проверку ещё раз.</p><p><b><i>Ваш островок разума колыхался на гребнях океана сознания, готовый в любой миг исчезнуть в его глубинах. </i></b></p><p><b>Защитник, сон. </b>Один из персонажей в походе должен провести проверку <conviction>, чтобы передать послание о мирном сосуществовании. +4, если у этого персонажа есть отметка коралла [ii], +2, если у персонажа есть <music>, и +2, если персонаж <i>сосредоточенный</i>. Также +2 за каждый живой коралл, который сбросит этот персонаж.<br><b>≥13:</b>  Коралловые усики скрутились, образовав лицо, похожее на ваше. Ваш разум словно стал общим, и вы увидели себя глазами коралла — маленьким, странным и хрупким существом. Завершите этот поход и достигните соответствующей цели. <br><b>1-12:</b>  Кораллы откликнулись, беспорядочно задёргав усиками. Но вы ощутили замешательство, увидев ответ на своё послание. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy> или <lore>, чтобы провести проверку ещё раз.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<songweaver>"},{"label":"ii","image":"<coral>"}]},{"id":"outcomes-699","code":"699","description":{"en":"<p>\\"You stand atop the chasm's edge, looking down. Within, you know there is a path to a strange and verdant realm. Reaching it could be a great achievement remembered for generations.\\"</p>\\n\\"Embark on the venture below (see Ventures on Rulebook p.60).\\n\\n<bi>The chasm's edge is treacherous, and even descending into the twisting passages is a worthy challenge.</bi>\\n<b>Champion, Wonder:</b> Someone must test <dexterity> to find a way into the chasm. Add +4 if you have the underworld mark (i) and +2 if you are <i>resourceful</i>.\\n10+: You descend with practiced grace. Continue the venture.\\n1–9: Your first foothold gives beneath you, and you scurry back up to the top. The venture fails unless a character spends <energy><energy> or <lore><lore> to attempt this test again.\\n\\n<bi>In the chasm's cool darkness, every sound frays at your nerves. Your group's resolve wavers.</bi>\\n<b>Group, Hazard:</b> Everyone must test <conviction> to brave the darkness. A character adds +2 if they have an item with a <fire> token on it, +2 if they are <i>inquisitive</i>, and +4 if they have the mystery mark (ii). \\n11+: You call out, and the familiar sound of your voice is a lifeline in the darkness. If any character resolves this result, the venture continues.\\n1–10: Your nerves hum as panic begins to overtake you. Lose <energy><energy>. If all characters on the venture resolve this result, the venture fails.\\n\\n<bi>The twisting corridors of the chasm create a tangle of paths in your mind. You must unwind this snarl and find a way through to reach the lands beyond.</bi>\\n<b>Champion, Hazard:</b> Someone must test <awareness> to navigate the passages. Add +2 if you have a Map, +2 if you are <i>patient</i>, and +4 if you have the arrival mark (iii).\\n10+: Complete this venture and the associated goal.\\n1–9: You become utterly lost and surface hours later, far away from your intended destination. Leave the venture and flee, then lose <energy><energy>. Another character on the venture must attempt this test. If all characters leave the venture, the venture fails.\\"","ru":"<p><i><b>Вы стояли на краю пропасти, внутри которой можно было отыскать путь в незнакомый зелёный мир. Если вы сможете попасть туда, то об этом наверняка будут складывать легенды ваши потомки.</b></i></p><p>Отправьтесь в поход (см. раздел «Походы» в правилах игры на с. 60).</p><p><b><i>Край пропасти был коварен, и даже спуск в его извилистые проходы стал достойным испытанием. </i></b></p><p>Защитник, чудо. Один из персонажей в походе должен провести проверку <dexterity>, чтобы найти путь в пропасть. +4, если у этого персонажа есть отметка подземного мира [i], и +2, если персонаж <i>изобретательный</i>.<br><b>≥10:</b>  Вы с лёгкостью спустились вниз. Продолжите поход.<br><b>1-9:</b>  Первая же платформа, на которую вы ступили, провалилась под вашим весом, и вы поспешно вернулись наверх. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy> или <lore><lore>, чтобы провести проверку ещё раз.</p><p><i><b>В прохладной тьме пропасти каждый звук действовал на нервы, из‑за чего вся группа чувствовала себя неуверенно. </b></i></p><p><b>Группа, угроза. </b>Все персонажи в походе должны провести проверку <conviction>, чтобы не побояться темноты. +2, если у персонажа есть предмет с <fire>, +2, если персонаж любознательный, и +4, если у него есть отметка тайны [ii].<br><b>≥11:</b>  Вы окликнули остальных, и знакомый звук вашего голоса стал для всех спасательным кругом в океане тьмы. Если хотя бы один персонаж получил этот результат, продолжите поход.<br><b>1-10:</b>  Ваши нервы дрогнули, и паника начала захлёстывать вас. Потеряйте <energy><energy>. Если все персонажи получили этот результат, поход окончился неудачно. </p><p><i><b>Извилистые коридоры ущелья переплелись у вас в голове. Вам нужно было распутать этот клубок и вновь найти дорогу,  чтобы достичь земель впереди.</b></i></p><p><b>Защитник, угроза. </b>Один из персонажей в походе должен провести проверку <awareness>, чтобы проложить путь через проходы. +2, если у этого персонажа есть «Карта», +2, если он <i>терпеливый</i>, и +4, если у него есть отметка прибытия [iii].<br><b>≥10:</b>  Вы нашли дорогу. Завершите этот поход и достигните соответствующей цели.<br><b>1-9:</b>  Заблудившись окончательно, вы вышли на поверхность только через несколько часов вдали от того места, куда направлялись. Покиньте поход и сбегите, затем потеряйте <energy><energy>. Другой персонаж в походе должен провести эту проверку. Если все персонажи получили этот результат, поход окончился неудачно.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<underworld>"},{"label":"ii","image":"<mystery>"},{"label":"iii","image":"<arrival>"}]},{"id":"outcomes-701","code":"701","description":{"en":"<p>You cannot help but shudder at the thought of what happened to one among your number in the depths of the scar, and what this may portend...</p>\\n\\"End this challenge.\\n\\nAdd <unrest><unrest>. Illustrate the saga of the vanished on the primal cave wall, including the mystery mark and the conclusion mark enclosing the coral mark. Add Scorn of the Earth (CC06) to your looming challenges.\\"","ru":"<p><i><b>Вы не могли не вздрогнуть от мысли о произошедшем с одним из вас в глубинах и о том, что это может предвещать…</b></i></p><p>Завершите текущее испытание.</p><p>Добавьте <unrest><unrest>. На стене первобытной пещеры изобразите историю о пропавшем, включив в неё отметку тайны [i] и отметку коралла [iii], заключённую в отметку окончания [ii]. Добавьте к грядущим испытаниям карту «Презрение земли» (ИВ06).</p>"},"repeatable":false,"marks":[{"label":"i","image":"<mystery>"},{"label":"ii","image":"<conclusion>"},{"label":"iii","image":"<coral>"}]},{"id":"outcomes-703","code":"703","description":{"en":"<p>\\"You can't escape or distract the subterranean creature, and now you must fight to survive.\\"</p>\\n\\"You must test <might> to <i>fight</i>. Add +2 if you are <i>vengeful</i>.\\n13+: Read outcome 210.\\n8–12: You drive the creature off, but are wounded in the process. Suffer <major_injury> and lose <energy><energy>.\\n1–7: In the scuffle, you are injured and drop what you have gathered while delving. Resolve 8–12, then lose all your rewards. Gain the <i>vengeful</i> trait.\\"","ru":"<p><i><b>Вам не удалось сбежать или отвлечь подземное существо, и теперь вам придётся сражаться, чтобы выжить.</b></i></p><p>Вы должны провести проверку <might>, чтобы сразиться. +2, если вы <i>мстительный</i>. <br><b>≥13:</b> <outcome> 210.<br><b>8-12:</b>  Вы отогнали существо, но оно успело вас ранить. Получите <major_injury> и потеряйте <energy><energy>.<br><b>1-7:</b>  В схватке вы получили рану и потеряли всё, что добыли во время спуска. Разыграйте исход как при [8-12], затем потеряйте все свои награды. Получите черту «мстительный».</p>"},"repeatable":false},{"id":"outcomes-704","code":"704","description":{"en":"<p>You set about restoring the ruin. Bringing human life back to this place will not be easy, but you believe it can be done.</p>\\n\\"Embark on the venture below (see Ventures on Rulebook p.60).\\n\\n<bi>Ruins often house dangerous creatures, and someone has to flush them out.</bi>\\n<b>Champion, Hazard:</b> Someone must test <awareness> to search the ruin for dangers. Add +2 if you are <i>wary</i> and +2 if you have an <i>exploration</i> item.\\n11+: You drive all dangerous animals from the ruins. The venture continues.\\n1–10: You are injured by a dangerous creature in the ruins. Suffer <major_injury>. Then, the venture fails unless a character spends <energy> or <lore> attempts this test again.\\n\\n<bi>The foundations of many structures are cracked, and will need careful repairs.</bi>\\n<b>Champion:</b> Someone must test <dexterity> to repair the foundations. Add +2 if you have <stoneworking>. You may discard up to 3 mineral materials. Add +3 for each clay you discard, +1 for each other mineral material discarded this way.\\n12+: You restore the foundations of the outpost. The venture continues.\\n1–11: The foundation is badly cracked. The venture fails unless a character spends <energy><energy> or <lore> to attempt this test again.\\n\\n<bi>Making the ruin suitable for living again takes more than simply solidifying the foundations. Various repairs and cleaning will be needed to make the place a home again.</bi>\\n<b>Champion:</b> Someone must test <conviction> to prepare a pleasant environment. Add +4 if you have a Broom and +4 if you have the hold mark. You may discard up to 4 wood. Add +2 for each wood discarded this way.\\n14+: You'll be happy to call this place home! Complete this venture and restore the ruin to an outpost. Make a new outpost card for it. Choose up to 2 structures recorded in the ruin and record them on the new card.\\n10–13: Your efforts are modestly successful, but the structures are beyond repair. Restore the ruin to an outpost. Make a new outpost card for it with no structures.\\n1–9: The outpost needs more work than you thought. The venture fails unless a character spends <energy><energy> or <lore> to attempt this test again.\\"","ru":"<p><i><b>Вы принялись восстанавливать руины. Заставить людей вновь здесь обустроиться казалось непосильной задачей, но вы верили, что это возможно.</b></i></p><p>Отправьтесь в поход (см. раздел «Походы» в правилах игры на с. 60).</p><p><b><i>В руинах часто скрывались опасные существа, и кто‑то должен был их выманить.</i></b></p><p><b>Защитник, угроза.</b> Один из персонажей в походе должен провести проверку <awareness>, чтобы обыскать руины в поисках угрозы. +2, если этот персонаж <i>осторожный</i>, и +2, если у него есть предмет для <i>исследования</i>. <br><b>≥11:</b>  Вы прогнали всех опасных животных из руин. Продолжите поход.<br><b>1-10:</b>  В руинах вас ранило опасное существо. Получите <major_injury>. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy> или <lore>, чтобы провести проверку ещё раз.</p><p><b><i>Фундаменты многих сооружений растрескались, их нужно было аккуратно восстановить.</i></b></p><p><b>Защитник. </b>Один из персонажей в походе должен провести проверку <dexterity>, чтобы восстановить фундаменты. +2, если у этого персонажа есть <stoneworking>. Также +3 за каждую глину и +1 за каждый другой минеральный материал, которые сбросит этот персонаж (можно сбросить не более 3 минеральных материалов, включая глину).<br><b>≥12:</b>  Вы восстановили фундаменты сооружений в поселении. Продолжите поход.<br><b>1-11:</b>  Ваших умений оказалось недостаточно, чтобы восстановить сильно повреждённый фундамент. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy> или <lore>, чтобы провести проверку ещё раз. </p><p><i><b>Чтобы сделать руины пригодными для жилья, нужно было не только укрепить фундаменты. Вам предстояло провести различные ремонтные работы и убраться, чтобы ваши люди вновь могли называть это место домом.</b></i></p><p><b>Защитник. </b>Один из персонажей в походе должен провести проверку <conviction>, чтобы создать подходящую обстановку. +4, если у этого персонажа есть «Метла», и +4, если у него есть отметка укрытия. Также +2 за каждое дерево, которое сбросит этот персонаж (не более +8).<br><b>≥14:</b>  Вы будете счастливы назвать это место домом! Переверните накладку руин. Создайте новую карту поселения. Выберите до 2 сооружений, записанных на карте руин, и запишите их на новой карте. Завершите этот поход.<br><b>10-13:</b>  Вам удалось восстановить поселение, но сооружения оказались непригодны для ремонта. Переверните накладку руин. Создайте новую карту поселения без сооружений. Завершите этот поход.<br><b>1-9:</b>  Восстановление поселения потребовало куда больших усилий, чем вы предполагали. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy> или <lore>, чтобы провести проверку ещё раз.</p>"},"repeatable":false,"marks":[{"label":"","image":"<hold>"}]},{"id":"outcomes-706","code":"706","description":{"en":"<p>\\"As you stand on its head, the behemoth's eyes cast up hungrily toward the flame you hold aloft...\\"</p>\\n\\"Choose one of the following and resolve it:\\n\\n<b>A) Offer the fire:</b> If you have an item with a <fire> token or there is <fire> in your hex, discard that <fire> token to end the encounter. Placate the behemoth's demeanor by 1. The behemoth flees. Then, if a character, animal companion, or storage structure has an item with Siphon in its name, gain 2 of the behemoth's curio; otherwise, gain the Siphon Stone (IT100) Item card.\\n\\n<b>B) Wave the flame about, driving the behemoth to a frenzy:</b> End the encounter. Aggravate the behemoth's demeanor by 1. The behemoth flees. Remove its aim and all its trace markers, then replace its current Instinct with Path of Ruin (BY04).\\"","ru":"<p><i><b>Когда вы стояли на голове чудища, оно с жадностью пыталось взглянуть на пламя, которое вы подняли над собой.</b></i></p><p>Выберите и разыграйте одно:<br><b>А. Преподнесите огонь. </b>Если у вас есть предмет с  <fire> или на вашем участке местности есть <fire>, сбросьте этот жетон, чтобы завершить встречу. Успокойте чудище на 1. Чудище сбегает. Затем, если у персонажа, животного- компаньона или в сооружении-<i>хранилище </i>есть предмет со словом «поглощающий» в названии, получите 2 сокровища чудища; в противном случае получите карту предмета «Поглощающий камень» (ВЩ100).<br><b>Б. Доведите чудище до неистовства, размахивая пламенем. </b>Завершите встречу. Разозлите чудище на 1. Чудище сбегает. Уберите жетон направления и все жетоны следов этого чудища, затем замените его текущий инстинкт на «Нести гибель» (ЧЕ04).</p>"},"repeatable":false},{"id":"outcomes-708","code":"708","description":{"en":"<p>\\"Feeding the behemoth has proven a successful strategy. While the creature's massive frame means that it cannot possibly be sustained by your paltry offerings alone, it seems to approve of your actions. As rays of light sliver the darkness, you awaken to find a bounty of strange treasures outside of your village: plants you have never seen, and glistening stones from some unknown depths. Future generations will benefit from this odd bounty, and perhaps seek to repay the behemoth's gifts with further tribute. In time, the behemoth might become an object of reverence to your people.\\"</p>\\n<p>\\"At the end of any day, you may end this challenge.\\n\\nIllustrate the saga of reverence on the primal cave wall, including the alert behemoth's mark and the feast mark.\\n\\nAdd Festival of Remembrance (CA07) and In Shadowed Vale (CA08) to your looming challenges.\\n\\"</p>","ru":"<p><i><b>Покормить чудище оказалось отличной идеей. Хоть его огромная туша никак не могла насытиться вашими жалкими подношениями, оно, похоже, было не прочь ими полакомиться. Поутру недалеко от деревни вы обнаружили странные сокровища: растения, которые вы никогда не видели, и сверкающие камни из неведомых глубин. Будущие поколения смогут воспользоваться этими необычайными дарами и, возможно, попытаются отблагодарить чудище новыми подношениями. Со временем чудище могло бы стать объектом поклонения для вашего народа.</b></i></p><p>В конце любого дня можете завершить текущее испытание.</p><p>На стене первобытной пещеры изобразите историю о почтении, включив в неё отметку бодрствующего чудища и отметку пира. Добавьте карты «Праздник памяти» (ИA07) и «Сумрак долины» (ИA08) к грядущим испытаниям.</p>"},"repeatable":false,"marks":[{"label":"","image":"<feast>"}]},{"id":"outcomes-709","code":"709","description":{"en":"<p>\\"The behemoth's roots swirl and churn the earth near you, and you dodge and roll to avoid them. High above, its head churns the clouds. You know that it is searching for water, and while you can never quench it, water has a noticeable impact. As the patch of roots near you converges to hungrily laps up the water, a strange bounty of foods bursts into existence amidst the many tangling vines.\\"</p>\\n<p>End the encounter. Gain any 3 vegetable foods of your choice.</p>","ru":"<p><i><b>Корни чудища вращались и вспахивали землю вокруг, а вы уворачивались от них. Голова чудища тянулась к облакам, словно оно искало воду. Утолить его жажду было невозможно, но вода явно действовала на него. Когда корни у ваших ног с жадностью потянулись к влаге, из переплетения лоз внезапно проросла диковинная пища.</b></i></p><p>Завершите встречу. Получите 3 любых овоща.</p>"},"repeatable":false},{"id":"outcomes-711","code":"711","description":{"en":"<p>The behemoth smashes into the center of the scar, and you race through its vast wake! You see the comet in the sky dipping low. Tendrils of spores spill from it, reaching down for the lost shard that fell to the valley. This reunion could devour the valley, unless you act now.</p>\\n\\"Embark on the venture below (see Ventures on Rulebook p.60).\\n\\n<bi>The shell of the comet is made of inert coral, tough and stony. You'll have to break a path. The behemoth roars and rushes forth.</bi>\\n<b>Behemoth, Champion, Coral:</b> Someone must test <conviction> to spur the behemoth on. Add +2 if you have a <i>talisman</i> item, +2 if you have a <i>trophy</i> item, and +2 if you are <i>wise</i>. Add your choice of the behemoth's <might> or <conviction> to the result.\\n20+: The behemoth shatters the shell with ease. The venture continues.\\n1–19: The shell cracks, but resists the impact. Degrade each of the behemoth's boosts once. Then the venture fails unless a character spends <energy> or <lore> to attempt this test again.\\n\\n<bi>Descending spores choke the air, clinging to the behemoth's flesh and burning where they touch.</bi>\\n<b>Behemoth, Coral, Group, Hazard:</b> Everyone must test <dexterity> to clear the behemoth. A character adds +2 if they have a Broom and +2 if they are <i>resourceful</i>. A character may discard up to 1 moonblood to add +4 to the result.\\n12+: You manage to clear enough of the behemoth's skin for it to surge forward to strike. The venture continues.\\n1–11: Suffer <major_disease>. Degrade all of the behemoth's boosts. Then the venture fails unless a character spends <energy> or <lore> to attempt this test again.\\n\\n<bi>The great heart of the coral beats within the shell, now exposed to the air. But spores grow ever thicker in the air, burning you and the behemoth alike.</bi>\\n<b>Behemoth, Champion, Coral, Hazard:</b> Someone must test <awareness> to guide the behemoth. Add +2 for each <i>moonblood</i> item a character on the venture has and +4 if you are <i>attuned</i>. Add your choice of the behemoth's <dexterity> or <awareness> to the result.\\n22+: The behemoth delivers the final blow. Complete this venture and the associated goal.\\n1–21: The behemoth's blow deflects off the remainder of the shell. Each character suffers <major_disease>. Then the venture fails unless a character spends <energy> or <lore> to attempt this test again.\\"","ru":"<p><i><b>Чудище устремилось к центру кратера, а вы пытались не отставать. В небесах нависала комета, исторгая струи спор, что тянулись к упавшему осколку. Их воссоединение грозило уничтожить долину, поэтому времени на размышления не было.</b></i></p><p>Отправьтесь в поход (см. раздел «Походы» в правилах игры на с. 60).</p><p><i><b>Оболочка осколка кометы состояла из мёртвого коралла — прочного, как камень. Нужно было её как‑то сломать. Чудище рычало и рвалось вперёд, готовое действовать.</b></i></p><p><b>Чудище, защитник, коралл. </b>Один из персонажей в походе должен провести проверку <conviction>, чтобы подстегнуть чудище. +2, если у этого персонажа есть <i>талисман</i>, +2, если у персонажа есть <i>трофей</i>, и +2, если персонаж <i>мудрый</i>. Добавьте значение <might> или <conviction> чудища к результату.<br><b>≥20:</b>  Чудище с лёгкостью разбило оболочку. Продолжите поход.<br><b>1-19:</b>  Оболочка треснула, но выдержала удар. Уменьшите все усиления чудища. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy> или <lore>, чтобы провести проверку ещё раз.</p><p><i><b>Споры опускались вниз, наполняя воздух удушающей завесой. Они липли к коже чудища, обжигая её в местах соприкосновения.</b></i></p><p><b>Чудище, коралл, группа, угроза. </b>Все персонажи в походе должны провести проверку <dexterity>, чтобы помочь чудищу. +2, если у персонажа есть «Метла», и +2, если он <i>изобретательный</i>. Также +4, если персонаж сбросит 1 лунную кровь.<br><b>≥12:</b>  Вам удалось стряхнуть споры с чудища, и оно с новыми силами бросилось в атаку. Продолжите поход.<br><b>1-11:</b>  Вы не смогли помочь чудищу. Получите <major_disease>. Уменьшите все усиления чудища. Если все персонажи получили этот результат, поход окончился неудачно, если только любой персонаж в походе не потратит <energy> или <lore>, чтобы провести проверку ещё раз.</p><p><i><b>Великое сердце коралла билось внутри оболочки, теперь открытой всем ветрам. Споры сгущались в воздухе, обжигая вас и чудище.</b></i></p><p><b>Чудище, защитник, коралл, угроза. </b>Один из персонажей в походе должен провести проверку <awareness>, чтобы направить чудище. +2 за каждый предмет <i>лунной крови</i> всех персонажей в походе и +4, если выбранный персонаж <i>сосредоточенный</i>. Добавьте значение <awareness> или <dexterity> чудища к результату.<br><b>≥22:</b>  Чудище нанесло последний удар. Завершите этот поход и достигните соответствующей цели.<br><b>1-21:</b>  Удар чудища был недостаточно силён. Каждый персонаж получает <major_disease>. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy> или <lore>, чтобы провести проверку ещё раз.</p>"},"repeatable":false},{"id":"outcomes-713","code":"713","description":{"en":"<p>\\"Despite the time you spend exploring it, the Tangle's mysteries continue to elude you. Your people grow to believe it to be a dangerous place, of flickering shadows and unpredictable beasts. Children are frightened with stories of the Tangle's horrors, should they wander within...\\"</p>\\n\\"Add <unrest><unrest><unrest>. Then, as a group, the players must choose one of the following paths for your society:\\n\\n<b>A) Remain wary of the shadow glades:</b> Add <unrest><unrest><unrest>. Illustrate the saga of the shadowed leaves, including the caution mark (i) and the Tangle mark (ii).\\n\\n<b>B) Prohibit lingering amid the fluttering leaves:</b> Subtract <unrest><unrest>. Add \\\\\\"Performing actions that place depletion tokens in the Tangle\\\\\\" to the Taboos section of the Culture page of the Journal. Gain the Taboos (KN19) Knowledge card. Illustrate the saga of the hungry forest on the primal cave wall, including the taboo mark (iii) and the Tangle mark (ii).\\"","ru":"<p><i><b>Несмотря на то что вы очень долго исследовали Сплетение, его тайны так и не открылись вам. Ваш народ начал считать это место — с его мерцающими тенями и непредсказуемыми зверями — опасным. Взрослые, чтобы отвадить детей от прогулок по Сплетению, пугали тех ужасными рассказами об этом месте.</b></i></p><p>Завершите текущее испытание.</p><p>Добавьте <unrest><unrest><unrest>. Затем совместно выберите один из следующих путей развития общины: <br><b>А. Остерегайтесь тенистых полян. </b>Добавьте <unrest><unrest><unrest>. На стене первобытной пещеры изобразите историю о скрытых во мраке листьях, включив в неё отметку осторожности [i] и отметку Сплетения [ii].<br><b>Б. Запретите прогулки среди шелестящих листьев. </b>Уберите <unrest><unrest>. Запишите «Совершать действия, добавляющие жетоны истощения в Сплетение» в раздел «Табу» на странице «Культура» в журнале. Получите карту знаний «Табу» (ЗБ18), если у вас её нет. На стене первобытной пещеры изобразите историю о хищном лесе, включив в неё отметку табу [iii] и отметку Сплетения [ii].</p>"},"repeatable":false,"marks":[{"label":"i","image":"<caution>"},{"label":"ii","image":"<tangle>"},{"label":"iii","image":"<taboo>"}]},{"id":"outcomes-716","code":"716","description":{"en":"<p>The behemoth has eaten a great clod of dirt, chewing with gusto.</p>\\n\\"Choose one of the following and resolve it:\\n\\n<b>A) Pick through the chewed rocks for information:</b> If the behemoth has an unrevealed Secret card assigned to it, reveal this behemoth's currently assigned Secret card, then record it under the Secrets for that behemoth in the Journal.\\n\\n<b>B) Leave a stone to entice the behemoth:</b> Discard 1 mineral material to gain <minor_boost> to <awareness>, the placate the behemoth's demeanor by 1.\\n\\n<b>C) Take a stone from the pile:</b> Gain a processed mineral material of your choice.\\"","ru":"<p><i><b>Чудище проглотило огромный ком земли, с наслаждением его перед этим прожевав.</b></i></p><p>Выберите и разыграйте одно:<br><b>А. Поройтесь в пережёванных камнях в поисках чего-нибудь важного. </b>Если у чудища есть неоткрытая назначенная карта секрета, откройте её. Затем запишите её в раздел секретов этого чудища в журнале.<br><b>Б. Оставьте камень, чтобы приманить чудище. </b>Сбросьте 1 минеральный материал, чтобы получить <minor_boost> к <awareness>, затем успокойте чудище на 1.<br><b>В. Возьмите камень из кучи. </b>Получите 1 любой обработанный минеральный материал.</p>"},"repeatable":false},{"id":"outcomes-717","code":"717","description":{"en":"<p>With a great, rocky fist, the behemoth plucks you from its soaring crown. You dangle above its vast, stone-churning maw. Reaching into your bag, you grasp for a stone that might be your salvation!</p>\\n\\"Choose one and resolve it:\\n\\n<b>A) Hurl the behemoth a stone:</b> If you have 1 or more mineral materials in your inventory, discard 1 or more mineral materials to end the encounter. Placate the behemoth's demeanor by 1 per material discarded this way.\\n\\n<b>B) Fall:</b> End the encounter. Suffer <major_injury><major_injury>.\\"","ru":"<p><i><b>Чудище схватило вас могучей лапой, когда вы забрались на самую вершину его парящего венца. Вы повисли над его огромной пастью, перемалывающей камни. В сумке вы нащупали камень, который, возможно, станет вашим спасением!</b></i></p><p>Выберите и разыграйте одно:<br><b>А. Швырните чудищу камень. </b>Если в вашем инвентаре есть минеральный материал, сбросьте хотя бы 1, чтобы завершить встречу. Успокойте чудище на 1 за каждый материал, который вы сбросите. <br><b>Б. Упадите.</b> Завершите встречу. Получите <major_injury><major_injury>.</p>"},"repeatable":false},{"id":"outcomes-719","code":"719","description":{"en":"<p>\\"Your hopes have come to fruition as the great citadel rises year by year. Your people flourish in the shadow of this colossus built by human hands, and the city's history becomes inextricably part of your people's saga.\\"</p>\\n\\"At the end of any day, you may end this challenge.\\n\\nSubtract <unrest><unrest><unrest><unrest><unrest>, add <population><population><population><population>. Illustrate the saga of the towering city on the primal cave wall, including the mark of the region where you constructed the city and the city mark.\\n\\nAt the end of this challenge, end the Epoch. See Codex p.204 to begin Epoch 3.\\"","ru":"<p><i><b>Ваши надежды оправдались: великая цитадель возвышалась над долиной многие годы. Ваша община процветала в тени этого изваяния, созданного человеческими руками, и история города неразрывно вплелась в историю вашего народа.</b></i></p><p>В конце любого дня можете завершить текущее испытание.</p><p>Уберите 5 <unrest>, добавьте <population><population><population><population>. На стене первобытной пещеры изобразите историю о возвышающемся городе, включив в неё отметку региона, где вы построили Город, и отметку Города.</p><p>В конце этого испытания завершите текущую эру. См. с. 204, чтобы начать эру 3.</p>"},"repeatable":false,"marks":[{"label":"","image":"<city>"}]},{"id":"outcomes-721","code":"721","description":{"en":"<p>Your footsteps kick up dust in an area that has been drained of all water. The silty ground crinkles beneath your feet.</p>\\n\\"Choose one of the following and resolve it:\\n\\n<b>A) Study the parched ground:</b> If the behemoth has an unrevealed Secret card assigned to it, reveal this behemoth's currently assigned Secret card, then record it under the Secrets for that behemoth in the Journal.\\n\\n<b>B) Water the dry dust, causing grasses to sprout with supernatural speed:</b> Gain 1 fiber. You may discard 1 water to gain 1 fiber and 2 roots, instead.\\"","ru":"<p><i><b>С каждым шагом поднимая всё больше и больше пыли, вы пришли туда, где не осталось ни капли влаги. Илистая земля трескалась под вашими ногами. </b></i></p><p>Выберите и разыграйте одно:<br><b>А. Изучите высохшую землю.</b> Если у чудища есть неоткрытая назначенная карта секрета, откройте её. Затем запишите её в раздел секретов этого чудища в журнале.<br><b>Б. Полейте пыль, заставив траву стремительно прорасти. </b>Получите 1 волокно. Можете сбросить 1 воду, чтобы дополнительно получить 2 коренья.</p>"},"repeatable":false},{"id":"outcomes-723","code":"723","description":{"en":"<p>\\"The songs you created spread across your people's culture, their melodies connecting present, past, and future.\\"</p>\\n<p>\\"At the end of any day, you may end this challenge. Then, illustrate the saga of the songweavers on the primal cave wall, including the songweaver mark. Your society can now access Legends. Gain the Legends (KN15) and Songs (KN16) Knowledge cards.\\n\\nYour society gains the Legend-Speaker (MA11) mantle power.\\"</p>","ru":"<p><i><b>Песни, созданные вами, стали частью культуры вашего народа — они объединили прошлое, настоящее и будущее.</b></i></p><p>В конце любого дня можете завершить текущее испытание.</p><p>Затем на стене первобытной пещеры изобразите историю о ткачах песен, включив в неё отметку песнопевца. Получите карты знаний «Легенды» (ЗБ15) и «Песни» (ЗБ16), если у вас их нет. Ваша община получает силу мантии «Глашатай легенд» (MA11).</p>"},"repeatable":false,"marks":[{"label":"","image":"<songweaver>"}]},{"id":"outcomes-724","code":"724","description":{"en":"<p>The behemoth absorbs water from the valley around it, and the life-giving substance grows harder and harder to find as it goes. The ground cracks, lips parch, and a drought descends in earnest.</p>\\n<p>\\"Until the end of this challenge, each character can gain a maximum of 1 water token each day.\\n\\nThen remove this behemoth's aim and all of its trace tokens. Assign it the Return to Slumber (BT20) instinct (replacing its previous instinct).\\"</p>","ru":"<p><i><b>Чудище поглощало всю воду в долине, и с каждым днём живительной влаги становилось всё меньше. Земля покрывалась трещинами, ваши губы сохли — на вас опустилась настоящая засуха.</b></i></p><p>До конца этого испытания каждый персонаж может получать не более 1 воды в день.<br>Уберите жетон направления и все жетоны следов этого чудища. Замените его текущий инстинкт на «Вернуться в забытьё» (ЧК20).</p>"},"repeatable":false},{"id":"outcomes-725","code":"725","description":{"en":"<p>Fine ashes line the tracks of the behemoth here. They still smoulder.</p>\\n\\"Choose one of the following and resolve it: \\n\\n<b>A) Study the horizon to see where the behemoth was headed, and perhaps why:</b> If the behemoth has an unrevealed Secret card assigned to it, reveal it and record it under the Secrets for that behemoth in the Journal.\\n\\n<b>B) Poke through the ashes:</b> If you have an item that can have a <fire> token placed on it, you may add a <fire> token to that item.\\"","ru":"<p><i><b>Тонкий слой пепла покрыл следы чудища. Они всё ещё тлели.</b></i></p><p>Выберите и разыграйте одно:<br><b>А. Вглядитесь в горизонт, чтобы понять, куда направлялось чудище, и, возможно, узнать его намерения. </b>Если у чудища есть неоткрытая назначенная карта секрета, откройте её. Затем запишите её в раздел секретов этого чудища в журнале.<br><b>Б. Используйте тлеющий пепел. </b>Если у вас есть предмет, на который можно поместить <fire>, можете добавить на него <fire>. <br><b>В. Молча уйдите прочь.</b> Завершите встречу.</p>"},"repeatable":false},{"id":"outcomes-726","code":"726","description":{"en":"<p>You have almost completed the mark, the scratches in the shell needing only one stroke to be complete. This, you are sure, would bring the behemoth to an end. But the desire to fight ebbs from you in this moment. This is no soaring victory, just the end of a life, somber as such a thing must be. You step back and let go of your weapon. The behemoth regards you, but the icy winds abate, and it makes no move to attack.</p>\\n\\"End this challenge.\\n\\nAdd <unrest><unrest><unrest><unrest>. Set the alert behemoth's demeanor to \\\\\\"2.\\\\\\" Illustrate the saga of the broken cycle on the primal cave wall, including the alert behemoth's mark, the caution mark (i), and the growth mark (ii). Permanently raise the <conviction> and <awareness> each character who was on the venture when it was completed by 1 (to a maximum of 7). Add the alert behemoth's mark and the growth mark (ii) to the Legend side of each of those Character cards.\\n\\nThen end the Epoch. See Codex p.204 to begin Epoch 3.\\"","ru":"<p><i><b>Вы почти закончили наносить отметку — в узоре царапин на панцире не хватало всего одного штриха. Вы знали: он положил бы конец чудищу. Но в этот миг желание сражаться покинуло вас. Это была бы не великая победа, а просто окончание жизни — и вы почувствовали всю тяжесть такого выбора. Вы отступили и выпустили оружие из рук. Чудище посмотрело на вас, но ледяные ветра стихли, и оно не сделало ни единого движения, чтобы атаковать.</b></i></p><p>Завершите текущее испытание.</p><p>Добавьте <unrest><unrest><unrest><unrest>. Установите значение нрава бодрствующего чудища на 2. На стене первобытной пещеры изобразите историю о разорванном круге, включив в неё отметку бодрствующего чудища, отметку осторожности [i] и отметку становления [ii]. Навсегда увеличьте <conviction> и <awareness> каждого персонажа, участвовавшего в этом походе на момент его завершения, на 1 (не более чем до 7). Добавьте отметку бодрствующего чудища и отметку становления [ii] на сторону легенды карт каждого из этих персонажей.</p><p>Затем завершите текущую эру. См. с. 204, чтобы начать эру 3.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<caution>"},{"label":"ii","image":"<growth>"}]},{"id":"outcomes-727","code":"727","description":{"en":"<p>\\"Your queries into the sickness of the Tangle neither sate your curiosity nor allay your people's fears. Whatever afflicts the floral jungle, it is beyond the things you know. In the years to come, the region slowly dies, revealing a different landscape underneath.\\"</p>\\n\\"Add <unrest><unrest>. Each outpost in the Tangle region becomes a ruin. Subtract <population><population> for each outpost that became a ruin this way. Then, as a group, the players must choose one of the following paths for your society:\\n\\n<b>A) Forbid lingering in the Tangle:</b> Add \\\\\\"Resting in a hex in the Tangle\\\\\\" to the Taboos section of the Culture page of the Journal. Gain the Taboos (KN18) Knowledge card. Add <unrest><unrest>. Illustrate the saga of the forbidden vale on the primal cave wall, including the Tangle mark (i) and the taboo mark (ii).\\n\\n<b>B) Risk the dangers of the spreading rot:</b> Lose <population><population><population>. Illustrate the saga of the spreading decay on the primal cave wall, including the harrowing mark (iii) and Tangle mark (i).\\"","ru":"<p><i><b>Ваши попытки понять природу заразы Сплетения не принесли плодов и не развеяли тревоги вашего народа. С годами это место медленно угасало: здешняя земля, покрываясь умирающей зеленью, принимала иной облик.</b></i></p><p>Завершите текущее испытание.</p><p>Добавьте <unrest><unrest>. Все поселения в регионе Сплетения становятся руинами. Уберите <population><population> за каждое поселение, ставшее руинами таким образом. Затем совместно выберите один из следующих путей развития общины:<br><b>А. Запретите надолго оставаться в Сплетении. </b>Запишите «Отдыхать на участке Сплетения» в раздел «Табу» на странице «Культура» в журнале. Получите карту знаний «Табу» (ЗБ18), если у вас её нет. Добавьте <unrest><unrest>. На стене первобытной пещеры изобразите историю о запретной долине, включив в неё отметку Сплетения [i] и отметку табу [ii].<br><b>Б. Рискните и дайте отпор расползающейся гнили. </b>Уберите <population><population><population>. На стене первобытной пещеры изобразите историю о распространяющемся гниении, включив в неё отметку ужаса [iii] и отметку Сплетения [i].</p>"},"repeatable":false,"marks":[{"label":"i","image":"<tangle>"},{"label":"ii","image":"<taboo>"},{"label":"iii","image":"<harrowing>"}]},{"id":"outcomes-728","code":"728","description":{"en":"<p>\\"You leap onto the behemoth's jaw and hang here. It does not see, but its posture shifts and you know it can perceive you there. By holding a stone aloft before it, you know that you can draw its attention.\\"</p>\\n\\"Choose one and resolve it:\\n\\n<b>A) Lead the behemoth to a stony feast:</b> If there is a feature in an adjacent hex where you could take the mine action, choose one of those features to end the encounter. Place your character and the behemoth in the hex with that feature (without drawing a Journey card). Then, if a character, animal companion, or storage structure has an item with Sundered in its name, gain 2 of the behemoth's curio; otherwise, gain the Sundered Stone (IT88) Item card.\\n\\n<b>B) Toss a stony morsel:</b> Discard a mineral material to end the encounter. The behemoth flees. Placate its demeanor by 1.\\n\\n<b>C) Tumble to the ground as the behemoth brushes you off:</b> End the encounter. Suffer <major_injury>.\\"","ru":"<p><i><b>Вы вскарабкались на челюсть чудища и повисли на ней. Вы поняли, что, хоть чудище и не видит вас, оно почуяло ваше присутствие, когда поменяло позу. Вы знали, что сможете привлечь внимание исполина, если используете камень, который всё это время был у вас с собой.</b></i></p><p>Выберите и разыграйте одно:<br><b>А. Отведите чудище на каменный пир.</b> Если на соседнем участке есть особенности местности, где можно добывать ископаемые, выберите одну из них, чтобы завершить встречу. Переместите своего персонажа и чудище на этот участок местности (не берите карту пути). Затем, если у персонажа, животного-компаньона или в сооружении-хранилище есть предмет со словом «расколотый» в названии, получите 2 сокровища чудища; в противном случае получите карту предмета «Расколотый камень» (ВЩ88).<br><b>Б. Бросьте каменное угощение. </b>Сбросьте 1 минерал, чтобы завершить встречу. Чудище сбегает. Успокойте чудище на 1.<br><b>В. Позвольте чудищу смахнуть вас. </b>Завершите встречу. Получите <major_injury>. </p>"},"repeatable":false},{"id":"outcomes-729","code":"729","description":{"en":"<p>Your people undertake a frenzy of activity, ranging far and wide for supplies. In their haste to complete the project, they disturb various flora and fauna of the vale.</p>\\n\\"Roll <1d6> and design the structure below that corresponds to the result (without spending <lore>):\\n1–2: Thatched Shelter (ST01)\\n3: Raincatchers (ST15)\\n4: Storage Containers (ST03)\\n5: Waste Pit (ST05)\\n6: Quern Stone (ST08)\\n\\nThen, built that structure in the outpost with the fewest structures (without spending <energy> or resources).\\"","ru":"<p><i><b>Ваш народ активно взялся за строительство сооружений.</b></i></p><p>Бросьте <1d6> и спроектируйте сооружение по результату броска, не тратя <lore>: [1-2] соломенная хижина (СР01), [3] дождесборник (СР15), [4] корзины для хранения (СР03), [5] мусорная яма (СР05), [6] жёрнов (СР08).</p><p>Затем постройте это сооружение в поселении, где меньше всего сооружений, не тратя <energy> и ресурсы.</p>"},"repeatable":false},{"id":"outcomes-731","code":"731","description":{"en":"<p>Your draconian control over foodstocks allows you to keep some people alive, but choosing who lives and who dies is a burden too great or any one person.</p>\\n\\"End this challenge.\\n\\nAdd <unrest><unrest>. Illustrate the saga of control on the primal cave wall, including the caution mark (i) and the misfortune mark (ii). Then, as a group, the players must choose one of the following paths for your society:\\n\\n<b>A) Seek the coral's origins in a distant, starlit land:</b> If the Starlit Sea mark (iii) is on the primal cave wall, add To Speak Beyond the Sky (CC07) to your looming challenges.\\n\\n<b>B) Face a champion of old who now serves the coral:</b> If the coral mark is enclosed in the conclusion mark (iv) on the primal cave wall, add The Comet's Chosen (CC08) to your looming challenges.\\n\\n<b>C) Seek out the lair of your ancient nemesis:</b> If the behemoth's blood mark (v) adorns the mark of a behemoth with an inactive lair on the primal cave wall, add Behemoth of the Comet (CC09) to your looming challenges.\\n\\n<b>D) Turn to a behemoth's bond of ancient days:</b> If a behemoth's mark is enclosed in the bond mark (vi) on the primal cave wall and that behemoth has an active lair in the valley, add Bond of the Behemoth (CC10) to your looming challenges.\\n\\n<b>E) Flee the valley once and for all:</b> Remove all other looming challenges and add Exodus (CZ09) to your looming challenges.\\"","ru":"<p><i><b>Жёсткий контроль за едой позволил сохранить жизни. Но бремя решений, кому жить, а кому умирать, оказалось слишком тяжёлым для одного человека.</b></i></p><p>Завершите текущее испытание.</p><p>Добавьте <unrest><unrest>. На стене первобытной пещеры изобразите историю о контроле, включив в неё отметку осторожности [i] и отметку несчастья [ii]. Затем совместно выберите один из следующих путей развития общины:<br><b>A. Отыщите истоки коралла в далёкой земле под звёздами.</b> Если на стене первобытной пещеры есть отметка Звёздного моря [iii], добавьте карту «Разговор со звёздами» (ИВ07) к грядущим испытаниям.<br><b>Б. Сразитесь с защитником древности, который ныне служит кораллу.</b> Если на стене первобытной пещеры есть отметка коралла [vii], заключённая в отметку окончания [iv], добавьте карту «Избранник кометы» (ИВ08) к грядущим испытаниям.<br><b>В. Отправьтесь на поиски логова своего древнего врага. </b>Если на стене первобытной пещеры есть отметка чудища с неактивным логовом, украшенная отметкой крови чудища [v], добавьте карту «Чудище кометы» (ИВ09) к грядущим испытаниям.<br><b>Г. Вспомните о связи чудища с прошлым.</b> Если на стене первобытной пещеры есть отметка чудища с активным логовом в долине, заключённая в отметку связи [vi], добавьте карту «Узы чудища» (ИВ10) к грядущим испытаниям.<br><b>Д. Покиньте долину раз и навсегда. </b>Добавьте к грядущим испытаниям карту «Исход» (ИЯ09).</p>"},"repeatable":false,"marks":[{"label":"i","image":"<caution>"},{"label":"ii","image":"<misfortune>"},{"label":"iii","image":"<starlitsea>"},{"label":"iv","image":"<conclusion>"},{"label":"v","image":"<behemothsblood>"},{"label":"vi","image":"<bond>"},{"label":"vii","image":"<coral>"}]},{"id":"outcomes-732","code":"732","description":{"en":"<p>\\"You lose your footing, and the channel's pull drags you beneath the surface. Jostled and dizzy in the torrent, you lose your sense of direction, fighting every second for air. When the light finally crosses your eyes, you find yourself in a stream elsewhere in the valley.\\"</p>\\nSuffer <major_injury><minor_disease>. End this delve action and lose all rewards you claimed. Place your character in a hex of your choice, choosing a hex with a lake, river, or wetland, if able.","ru":"<p><i><b>Вы не смогли удержаться на плаву, и течение утащило вас под воду. Вас мотало и кружило в бурлящем потоке, вы пере стали понимать, где вы, и каждую секунду боролись за глоток воздуха. Когда, наконец, вы пришли в себя, вы оказались в ручье где‑то в другой части долины. </b></i></p><p>Получите <major_injury> и <minor_disease>. Завершите действие спуска и потеряйте все награды, которые присвоили. Переместите своего персонажа на другой участок местности, выбрав участок с озером, рекой или болотом, если возможно.</p>"},"repeatable":false},{"id":"outcomes-733","code":"733","description":{"en":"<p>\\"As the echoes of devastation die down and dust drifts back to the ground, the behemoth's rampage comes to an end.\\"</p>\\n\\"For each hex with an outpost and a trace token, roll <1d6> and resolve the following, adding +1 if the behemoth's demeanor is 5 or lower:\\n\\n1-2: The behemoth leaves only a shattered crater. The outpost becomes a ruin. Subtract <1d6><population>.\\n3-4: The behemoth crashes through the edge of the outpost. Randomly select 2 structures in the outpost. They are destroyed. Subtract <population><population>\\n5-6: The behemoth damages the outpost and frightens the inhabitants. Randomly select 1 structure in the outpost. It is destroyed. Add <unrest>.\\n\\nThen, remove this behemoth's aim and all its trace markers. This card remains assigned to it.\\"","ru":"<p><i><b>Когда отзвуки разрушения стихли, а пыль опустилась обратно на землю, буйство чудища подошло к концу.</b></i></p><p>За каждый участок местности с поселением, где находится жетон следов, бросьте <1d6>. +1, если значение нрава чудища не более 5.</p><p>Затем разыграйте эффект в зависимости от результата:<br><b>1-2:</b>  Чудище сровняло поселение с землёй. Поселение становится руинами. Бросьте <1d6> и уберите столько <population>, сколько выпало на <1d6>.<br><b>3-4:</b>  Чудище проломило заграждения на окраине. Разрушьте 2 случайных сооружения в этом поселении. Уберите <population><population>. <br><b>5-6:</b>  Чудище повредило постройку и напугало жителей. Разрушьте 1 случайное сооружение в этом поселении. Добавьте <unrest>. </p><p>Затем уберите жетон направления и все жетоны следов этого чудища. Эта карта инстинкта остаётся назначенной этому чудищу.</p>"},"repeatable":false},{"id":"outcomes-736","code":"736","description":{"en":"<p>You know the behemoth leaves behind traces of the resource it values in places like this. You could gather this resource or supplement it to send a message back to the behemoth.</p>\\n\\"Choose one of the following and resolve it:\\n\\n<b>A) Give tribute to placate the behemoth:</b> Discard 1 of the behemoth's curio to placate its demeanor by 2.\\n\\n<b>B) Take the object for yourself:</b> Gain 1 of the behemoth's curio.\\"","ru":"<p><i><b>Вы знали, что чудище в этих местах оставляет на своём пути ценные для него ресурсы. Вы могли бы собрать эти ресурсы или оставить рядом с ними такой же, чтобы передать чудищу послание.</b></i></p><p>Выберите и разыграйте одно:<br><b>А. Принесите подношение, чтобы усмирить чудище.</b> Сбросьте 1 сокровище чудища, чтобы успокоить чудище на 2. <br><b>Б. Заберите ресурс. </b>Получите 1 сокровище чудища.</p>"},"repeatable":false},{"id":"outcomes-743","code":"743","description":{"en":"<p>\\"By striking out at it, your people have provoked the behemoth's wrath. Now it descends upon you with the indignation of a wounded god.\\"</p>\\n\\"When a behemoth activates during the next behemoth phase, instead of following its Instinct, it tests <dexterity> to tread toward the nearest hex occupied by a character. It adds +3 if its demeanor is 6 or higher.\\n\\n16+: The behemoth treads three times toward that hex.\\n12–15: The behemoth treads twice toward that hex.\\n1–11+: The behemoth treads once toward that hex, then gains <minor_boost> to each of its attributes.\\n\\nThen, if the behemoth entered a hex occupied by one or more characters, the players must choose one of those characters to encounter it. Additionally, if it entered a hex with an outpost, add <unrest><unrest>, then randomly select one structure in that outpost at random and destroy it.\\"","ru":"<p><i><b>Своим ударом ваш народ навлёк на себя гнев чудища. Теперь оно обрушилось на вас с яростью раненого божества. </b></i></p><p>Когда чудище активируется в следующую фазу чудищ, вместо того чтобы следовать своему инстинкту, оно проводит проверку <dexterity>, чтобы ступать к ближайшему участку местности с персонажем. +3, если значение нрава чудища равно хотя бы 6.<br><b>≥16:</b>  Чудище 3 раза ступает к тому участку. <br><b>12-15:</b>  Чудище 2 раза ступает к тому участку. <br><b>1-11:</b>  Чудище 1 раз ступает к тому участку, затем получает <minor_boost> ко всем характеристикам.</p><p>Затем, если чудище вошло на участок местности с одним или несколькими персонажами, выберите одного из этих персонажей — он должен провести встречу с чудищем. Кроме того, если оно вошло на участок местности с поселением, добавьте <unrest><unrest> и разрушьте 1 случайное сооружение в этом поселении.</p>"},"repeatable":false},{"id":"outcomes-744","code":"744","description":{"en":"<p>You see a faraway place, shrouded in mists of uncertainty. You shudder to wakefulness, and...</p>\\n\\"Resolve the first you are able.\\n\\n<b>A) The dream bursts from your mind and into the valley:</b> If there is at least 1 unplaced terrain tray and there are one or more regions with at least 1 placed hex and 3 or more unplaced hexes (other than the starting hex), select one of those regions at random and expand the valley by following the steps below:\\n\\n<b>Step 1:</b> Add a new tray to your valley. Place it adjacent to a hex of your choice. You must choose a hex matching the region you selected at random, if able. The tray must be placed such that its edges are adjacent to as many edges of placed trays as posslble. If multiple valid positions exist, choose one.\\n\\n<b>Step 2:</b> Place all of that region's unplaced hexes into the draw bag (except for the starting hex). Shuffle the hexes in the draw bag. Then, one at a time, draw three of those hexes. and place them unexplored in the slots of the tray you just placed, filling empty slots from north to south and east to west.\\n\\n<b>Step 3 (Epoch 1 and Endless Mode Only):</b> If it is Epoch 1 (or you are playing Endless Mode) and there are 1 or more unplaced glacier overlays, roll <1d6> and place glaciers as foillows:\\n1–2: 1 glacier in Zone \\\\\\"A\\\\\\" of one of the hexes without an overlay.\\n[diagram]\\n3–4: 1 glacier in Zone \\\\\\"B\\\\\\" of one of the hexes without an overlay.\\n[diagram]\\n5: Resolve both 1–2 and 3–4.\\n[diagram]\\n6: Roll <1d6> again and read the corresponding outcome instead.\\n1–2: <outcome> 846\\n3–5: <outcome> 134\\n6: <outcome> 446\\n\\nThen return Distant Dream (NU07) to the game box.\\n\\n<b>B) The dream fades like morning fog, leaving only dewy hints on the edges of your mind:</b> Add <lore><lore>.\\"","ru":"<p><i><b>Вы увидели далёкое место, окутанное вуалью неизвестности. Вы встрепенулись, чтобы очнуться, и…</b></i></p><p>Разыграйте первое, что можете:<br><b>А. ...сон вырвался из вашего разума, устремившись в долину. </b>Если у вас есть хотя бы 1 неразмещённая основа местности и в долине есть хотя бы 1 регион с хотя бы 1 размещённым участком местности и 3 или более неразмещёнными участками (кроме начального), случайным образом выберите 1 из таких регионов. Затем расширьте долину, пройдя описанные ниже этапы. <br><b>Этап 1. </b>Добавьте новую основу местности в долину. Поместите её по соседству со случайным участком региона, который был выбран ранее, если возможно. Границы основы должны соседствовать с как можно большим количеством границ уже помещённых основ. Если есть несколько возможных позиций, выберите одну случайным образом.<br><b>Этап 2. </b>Положите все неразмещённые участки местности выбранного региона в мешочек и перемешайте. Затем по одному вытащите 3 участка и поместите их неисследованной стороной вверх в ячейки новой основы по направлению с севера на юг и с востока на запад.<br><b>Этап 3 (только для эры 1 и бесконечного режима). </b>Если в запасе есть хотя бы 1 не помещённая накладка ледника, бросьте <1d6> и поместите ледники по результату броска: [1-2] один ледник в район А одного из участков местности без накладки, [3-4] один ледник в район Б одного из участков местности без накладки, [5] разыграйте результаты 1-2 и 3-4, [6] бросьте <1d6> ещё раз и прочитайте один из исходов ниже, соответствующий результату броска.<br>[1-2] <outcome> 846, [3-5] <outcome> 134, [6] <outcome>  446.<br>Затем верните в коробку карту «Недостижимая мечта» (НН07).<br><b>Б. ...сон рассеялся, как утренний туман, оставив лишь влажные отблески на краю вашего разума. </b>Добавьте <lore><lore>.</p>"},"repeatable":false},{"id":"outcomes-749","code":"749","description":{"en":"<p>\\"You splash water on the behemoth's massive face. As if in response, a massive torrent spills forth from the behemoth, carrying you away from it. When you finally manage to pull yourself from the torrent, you discover that you are holding an unusual object in hand.\\"</p>\\n<p>\\"End the encounter. Aggravate the behemoth's demeanor by 1. Place your character in an adjacent hex of your choice, choosing a hex with a lake, river, or wetland, if able (without drawing a Journey card).\\n\\nThen, if a character, animal companion, or storage structure has an item with Shimmering in its name, gain 2 fiber; otherwise, gain the Shimmering Moss (IT86) Item card.\\"</p>","ru":"<p><i><b>Вы плеснули водой в огромный лик чудища. И, словно в ответ, из него хлынул мощный поток, что унёс вас прочь. Когда вы пришли в себя, вы обнаружили, что сжимаете в руке странный предмет.</b></i></p><p>Завершите встречу. Разозлите чудище на 1. Переместите своего персонажа на соседний участок местности, выбрав участок с озером, рекой или болотом, если возможно (не берите карту пути).</p><p>Затем, если у персонажа, животного-компаньона или в сооружении-хранилище есть предмет со словом «мерцающий» в названии, получите 2 волокна; в противном случае получите карту предмета «Мерцающий мох» (ВЩ86).</p>"},"repeatable":false},{"id":"outcomes-754","code":"754","description":{"en":"<p>\\"In spite of your best efforts, the seed of the Tangle is unable to thrive. The seedling becomes dry and hard even as the blight devours what remains of its parent. Perhaps someday, in the wake of some great flood or fire, the Tangle's seed will reawaken, but for now, the majesty of the jungle of flowers remains only in your people's songs and stories. As generations pass, the valley grows dry and the soil brittle, and your people must seek new refuge, carrying with them forever the memory of the Tangle.\\"</p>\\n\\"Illustrate the saga of the brittle earth on the primal cave wall, including the exodus mark (i) and Tangle mark (ii). Your society <b>vanishes</b>. Replace the Tangle's starting hex with the starting hex of another region, if able, then replace as many other Tangle hexes as possible with randomly selected, unexplored hexes from that region.\\n\\nThis end may not be a happy one, but it can still be instructive to future peoples who inhabit the valley. To immortalize a photo of your primal cave wall and see other people's works of art, we invite you to share your saga with our community!\\n\\n@[Insert Link]@\\n\\nTo continue playing <i>Stonesaga</i>, see Beginning Subsequent Campaigns on Rulebook p.97. Or you could switch to Endless Mode, as described on Rulebook p.97.\\"","ru":"<p><i><b>Несмотря на все ваши усилия, семя Сплетения так и не смогло прижиться. Побег высох и затвердел, пока зараза пожирала остатки его родителя. Быть может, когда‑ нибудь, после великого наводнения или пожара, семя Сплетения пробудится вновь, но пока величие этих цветочных джунглей оставалось лишь в песнях и рассказах вашего народа. Поколения сменились, долина высохла, земля ещё сильнее покрылась трещинами, и ваш народ был вынужден искать новое убежище, оставив себе от Сплетения лишь воспоминания.</b></i></p><p>На стене первобытной пещеры изобразите историю о потрескавшейся земле, включив в неё отметку исхода [i] и отметку Сплетения [ii]. Замените начальный участок Сплетения на начальный участок местности другого региона, если возможно. Затем замените как можно больше других участков Сплетения на случайные участки этого региона, поместив их неисследованной стороной вверх. Ваша община <b>исчезла</b>.</p><p>Такой конец хоть и далёк от счастливого, но он всё же может послужить уроком для народов, которые заселят эту долину в будущем. Чтобы увековечить фотографию своей стены первобытной пещеры и увидеть произведения искусства других игроков, мы приглашаем вас поделиться своей историей с нашим сообществом!</p><p>Чтобы продолжить играть в «Наскальную историю», см. в правилах игры раздел «Начало следующих кампаний» на с. 97 или раздел «Бесконечный режим» на с. 102.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<exodus>"},{"label":"ii","image":"<tangle>"},{"label":"","image":"<qrcode>"}]},{"id":"outcomes-755","code":"755","description":{"en":"<p>Following rumors and wisps of an unusual cloud, you search for the land of searing mists and walking hills.</p>\\n\\"Embark on the venture below (see Ventures on Rulebook p.60).\\n\\n<bi>The cloud is a potent omen.</bi>\\n<b>Champion, Weather:</b> Someone must test <awareness> to interpret the sign. Add +2 if you have a <i>talisman</i> item and +2 if you are <i>attuned</i>.\\n10+: You discern the direction of the wisps. The venture continues.\\n1–9: You are unable to make much of this sign. The venture fails unless a character spends <energy><energy> or <lore> to attempt this test again.\\n\\n<bi>Journeying under the sign of the cloud, you approach an unusual pass in the valley. The plants are scored with strange pockmarks, and the dirt is dry and crumbly. As you enter the pass, you are beset by strange vapors that cling to you, searing your skin.</bi>\\n<b>Group, Weather:</b> Everyone must test <might> to avoid the mists. They add +2 if they have an <i>exploration</i> item and +2 if they are <i>wary</i>.\\n12+: You make your way through the vapors, suffering only minor discomfort. If any character resolves this result, the venture continues.\\n1–11: You leave the venture unless you suffer <major_disease><major_disease>. If all characters on the venture resolve this result, the venture fails.\\n\\n<bi>The vapors grow thicker. As you force your way through, you hear it first: a slow, grinding rumble. Then the fog parts slightly, and you see the hillside walking toward you. On vast legs, it stomps forward at a sedate, almost stately pace.</bi>\\n<b>Champion, Wonder:</b> Someone must test <conviction> to climb the ridgecrawler. Add +2 if you have a Rope, +2 if you have a Piton, +2 if you have <stoneworking>, and +2 if you are <i>intrepid</i>.\\n13+: You vault up the creature's back to find a little world nestled on its vast shoulders. Complete this venture and the associated goal.\\n1–12: You flinch. The venture fails unless a character spends <energy><energy> or <lore> to attempt this test again.\\"","ru":"<p><i><b>Поверив слухам, которые твердили, что путь вам укажут клочки необычного облака, вы отправились на поиски земли жгучих туманов и ходячих холмов.</b></i></p><p>Отправьтесь в поход (см. раздел «Походы» в правилах игры на с. 60).</p><p><i><b>Облако — это могущественное знамение.</b></i></p><p><b>Защитник, погода.</b> Один из персонажей в походе должен провести проверку <awareness>, чтобы истолковать знак. +2, если у этого персонажа есть <i>талисман</i>, и +2, если персонаж <i>сосредоточенный</i>.<br><b>≥10:</b>  Вы поняли, куда вас направляли облачные лоскуты. Продолжите поход.<br><b>1-9:</b>  Вы не смогли разобрать этот знак. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy> или <lore>, чтобы провести проверку ещё раз.</p><p><i><b>Путешествуя под знаком облака, вы добрались до необычного прохода в долине. Растения там были покрыты неестественными шероховатостями, а почва была сухой. Когда вы вошли в проход, вас окутали и обожгли странные испарения.</b></i></p><p><b>Группа, погода. </b>Все персонажи в походе должны провести проверку <might>, чтобы обойти туманные испарения стороной. +2, если у персонажа есть предмет для <i>исследования</i>, и +2, если персонаж <i>осторожный</i>.<br><b>≥12:</b>  Вы пробрались сквозь испарения, отделавшись лёгким испугом. Если хотя бы один персонаж получил этот результат, продолжите поход.<br><b>1-11:</b>  Покиньте поход или получите <major_disease><major_disease>. Если все персонажи получили этот результат, поход окончился неудачно.</p><p><i><b>Марево сгущалось. Пробираясь вперёд, вы сначала услышали затяжной грохочущий скрежет. Затем туман чуть рассеялся, и вы увидели, как склон холма медленной величавой поступью двигается в вашем направлении.</b></i></p><p><b>Защитник, чудо.</b> Один из персонажей в походе должен провести проверку <conviction>, чтобы взобраться на шагающий хребет. +2, если у этого персонажа есть «Верёвка», +2, если у него есть «Скальный крюк», +2, если у него есть <stoneworking>, и +2, если он <i>отважный</i>. <br><b>≥13:</b>  Вы взобрались на спину создания и обнаружили там маленький мир, укрывшийся на его огромных плечах. Завершите этот поход и достигните соответствующей цели.<br><b>1-12:</b>  Вы дрогнули. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy> или <lore>, чтобы провести проверку ещё раз.</p>"},"repeatable":false},{"id":"outcomes-761","code":"761","description":{"en":"<p>\\"From atop the behemoth's horn, you can see...\\"</p>\\n\\"Choose one and resolve it:\\n\\n<b>A) A rich vein of stone where the behemoth can feast:</b> If there is a feature where you could mine in your hex, choose one to end the encounter. Perform a mine action at that feature (without spending <energy> as normal). Placate the behemoth's demeanor by 2. \\n\\n<b>B) Nothing of interest, your seemingly pointless antics frustrating the behemoth:</b> End the encounter. Aggravate the behemoth's demeanor by 1.\\n\\n<b>C) A place to safely leap off:</b> End the encounter. Spend <lore> to gain <minor_boost> to <conviction>.\\"","ru":"<p><i><b>С вершины рога чудища вы увидели…</b></i></p><p>Выберите и разыграйте одно:<br><b>А. …большие залежи камня, которым чудище могло полакомиться. </b>Если на вашем участке есть особенности местности, где можно добывать ископаемые, выберите одну из них, чтобы завершить встречу. Выполните действие добычи ископаемых на этой особенности местности, не тратя <energy>. Успокойте чудище на 2.<br><b>Б. …лишь привычный пейзаж: ваши попытки что-то обнаружить, похоже, были бессмысленными и лишь разозлили чудище.</b> Завершите встречу. Разозлите чудище на 1.<br><b>В. …место, куда можно было безопасно спрыгнуть. </b>Завершите встречу. Потратьте <lore>, чтобы получить <minor_boost> к <conviction>.</p>"},"repeatable":false},{"id":"outcomes-764","code":"764","description":{"en":"<p>Your burgeoning population puts significant pressure on the valley, and the land can barely sustain your people. Empty beds are scarce, even in your largest outposts, and refuse begins to pile up, threatening to spread disease.</p>\\n\\"Add <activity><activity>. If there are fewer than 4 outposts, add <unrest><unrest><unrest>. Each character in a hex with an outpost without a Waste Pit suffers <major_disease>, then if the plague mark is on the primal cave wall, add <lore>; otherwise, add Pestilence (CZ03) to your looming challenges.\\n\\nAt the end of the night, place a depletion token in each hex with an outpost.\\"","ru":"<p><i><b>Людей в вашей общине стало так много, что земля уже не могла их выдержать. Даже в самых крупных поселениях не хватало свободных жилищ. Мусор стал скапливаться так быстро, что это грозило распространением болезней. </b></i></p><p>Добавьте <activity><activity>. Если в долине не более 3 поселений, добавьте <unrest><unrest><unrest>. Каждый персонаж на участке местности с поселением, в котором нет мусорной ямы, получает <major_disease>. Затем, если на стене первобытной пещеры есть отметка чумы, добавьте <lore>. В противном случае добавьте карту «Мор» (ИЯ03) к грядущим испытаниям.</p><p>В конце ночи положите жетон истощения на каждый участок местности с поселением.</p>"},"repeatable":false,"marks":[{"label":"","image":"<plague>"}]},{"id":"outcomes-765","code":"765","description":{"en":"<p>You are pulled into the torrent. Dark water fills your senses and your lungs. You awaken to the water lapping at your feet, the sun hanging low in the sky.</p>\\nSuffer <major_injury> and lose <energy>. Then <exit>, placing your character in a hex of your choice, choose a hex with a lake, river, or wetland, if able. If you are <i>intrepid</i> or <i>lucky</i> add <lore><lore>.","ru":"<p><i><b>Вас затянуло в бурный поток. Тёмная вода захватила ваш разум и заполнила лёгкие. Очнувшись, вы почувствовали, как вода омывает ваши ноги. Солнце уже клонилось к горизонту.</b></i></p><p>Получите <major_injury> и потеряйте <energy>. Затем <exit>, переместив своего персонажа на другой участок местности, выбрав участок с озером, рекой или болотом, если возможно. Если персонаж <i>отважный </i>или <i>удачливый</i>, добавьте <lore><lore>.</p>"},"repeatable":false},{"id":"outcomes-766","code":"766","description":{"en":"<p>Deep in a chunk of frozen moonblood, you see what looks like a human form, trapped for who knows how long in the mystic rime. While you cannot reach them through the veil of frosts, you see a bag poking out of the hardened chunk of luminescent stone.</p>\\nYou may perform a scavenge action without spending <energy>. If you do, add 1 additional moonblood to the draw bag.","ru":"<p><i><b>Глубоко внутри глыбы замёрзшей лунной крови вы увидели силуэт, похожий на человеческий, — неведомо когда он был пленён таинственным инеем. Вы заметили, что из затвердевшего светящегося камня торчала сумка, явно принадлежащая этому существу.</b></i></p><p>Можете провести раскопки, не тратя <energy> и добавив 1 дополнительную лунную кровь в мешочек.</p>"},"repeatable":false},{"id":"outcomes-772","code":"772","description":{"en":"<p>\\"Several different signs are spotted during the year, but none become linked to your people's identity as a society.\\"</p>\\n\\"Add <unrest><unrest>. Illustrate the saga of the many signs on the primal cave wall, including the schism mark.\\n\\nThen end this challenge and end the Epoch. See Codex p.204 to begin Epoch 3.\\"","ru":"<p><i><b>В течение года вы заприметили несколько разных знаков, но ни один из них так и не стал символом вашей общины.</b></i></p><p>Добавьте <unrest><unrest>. На стене первобытной пещеры изобразите историю о множестве знаков, включив в неё отметку раскола.</p><p>Затем завершите текущее испытание и текущую эру. См. с. 204, чтобы начать эру 3.</p>"},"repeatable":false,"marks":[{"label":"","image":"<schism>"}]},{"id":"outcomes-773","code":"773","description":{"en":"<p>\\"You sprinkle water along the behemoth's back, and plant life pushes up through the opalescent stone of its neck. You pluck a sprout of brilliant green, and the behemoth skids to a halt. You tumble down the mountain of its side, your senses scattering before you hit the ground. When you awaken, the behemoth is long gone, but the sprout rests in your hand.\\"</p>\\n\\"End the encounter. Placate the behemoth's demeanor by 1. Suffer <major_injury>.\\n\\nThen, if a character, animal companion, or storage structure has an item with Vivacious in its name, gain 2 fiber; otherwise, gain the Vivacious Sprout (IT90) Item card.\\"","ru":"<p><i><b>Вы брызнули водой на спину чудища, и из опалового камня на его шее начали пробиваться ростки. Вы сорвали один ярко‑зелёный побег, из‑за чего чудище резко остановилось. Вы скатились с его бока, как с горы, и рухнули оземь. Когда вы пришли в себя, то обнаружили, что чудище давно ушло, но сорванный росток всё ещё был у вас в руке.</b></i></p><p>Завершите встречу. Успокойте чудище на 1. Получите <major_injury>. Затем, если у персонажа, животного-компаньона или в сооружении-<i>хранилище </i>есть предмет со словом «живой» в названии, получите 2 волокна; в противном случае получите карту предмета «Живой росток» (ВЩ90).</p>"},"repeatable":false},{"id":"outcomes-774","code":"774","description":{"en":"<p>As your people spread across the valley, cultural cohesion becomes increasingly important. You seek ways to build bridges and strengthen bonds.</p>\\n\\"As a group, the players must choose one of the following paths for your society:\\n\\n<b>A) Address old scars and grievances:</b> Add Quell the Embers (GZ21) to your goals.\\n\\n<b>B) Hunt fabled prey:</b> Add Hunt an Omen-Beast (GA17) to your goals.\\n\\n<b>C) Sing your sagas proudly:</b> Add Song and Story (GA21) to your goals.\\n\\n<b>D) Engrave icons of culture for future generations:</b> Add Carved in Stone (GA20) to your goals.\\n\\n<b>E) Cultivate shared beliefs:</b> If the songweaver mark (i) or scribe mark (ii) is on the primal cave wall, add the goal Seek a Symbol (GB09) to your goals.\\n\\nThen, you may spend 6<lore> to choose another effect from this list and resolve it. You may do this any number of times.\\"","ru":"<p><i><b>Когда ваш народ расселился по долине, культурное единство стало особенно важным. Вы стали искать способы построить мосты доверия и укрепить духовные связи между людьми. </b></i></p><p>Совместно выберите один из следующих путей развития общины:<br><b>А. Разберитесь со старыми ранами и обидами.</b> Добавьте карту «Погасите искры» (ЦЯ21) к целям.<br><b>Б. Объявите охоту на легендарную добычу. </b>Добавьте карту «Выйдите на охоту под светом знамения» (ЦA17) к целям. <br><b>В. Гордо поведайте свою историю. </b>Добавьте карту «Сложите песни и сказания» (ЦA21) к целям.<br><b>Г. Начертите знаки культуры для будущих поколений. </b>Добавьте карту «Увековечьте в камне» (ЦA20) к целям.<br><b>Д. Начните развивать общие верования. </b>Если на стене первобытной пещеры есть отметка песнопевца [i] или отметка летописца [ii], добавьте карту «Отыщите символ» (ЦБ09) к целям.</p><p>Затем можете потратить 6 <lore>, чтобы выбрать другой эффект из этого списка и разыграть его. Повторите это сколько угодно раз.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<songweaver>"},{"label":"ii","image":"<scribe>"}]},{"id":"outcomes-776","code":"776","description":{"en":"<p>To understand the disease that afflicts the Tangle, you must observe the blighted areas firsthand. Within a withering glade, you begin your search.</p>\\n\\"Embark on the venture below (see Ventures on Rulebook p.60).\\n\\n<bi>The vines within the glade are limp and their bark is taught. You might gain some insight by cutting into them for more samples.</bi>\\n<b>Champion:</b> Someone must test <dexterity> to sample the vines. Add +2 if you have <cut> and +2 if you are <i>inquisitive</i>. Add +1 for each token on Sample Foliage or +6 if that goal is completed.\\n14+: You notice that the condition of the vines seems to worsen as they approach the roots. The venture continues.\\n1–13: You are unable to find much of interest. The venture fails unless a character spends <energy><energy> or <lore> to attempt this test again.\\n\\n<bi>You search for the root system of the great plants of the Tangle, digging into the soil to find an underground nexus.</bi>\\n<b>Group:</b> Everyone must test <might> to dig. A character adds +2 if they have <dig> and +2 if they are <i>resourceful</i>.\\n10+: You unearth a twist of roots. If any character resolves this result, the venture continues.\\n1–9: You root around in the loamy soil but find nothing. If all characters on the venture resolve this result, the venture fails unless a character spends <energy><energy> or <lore> to attempt this test again.\\n\\n<bi>Having found the roots, you need to examine them closely, but getting through their tough skin will be a challenge.</bi>\\n<b>Champion:</b> Someone must test <awareness> to examine the roots. Add +2 if you have <chop> and +2 if you are <i>attuned</i>. Add +1 for each token on Sample Foliage or +6 if this goal is completed.\\n15+: You chop into the roots to see a mass of noxious, oozing nodules. This must be a symptom fo the blight - does that mean its source comes from deeper under the earth? Complete this venture and the associated goal.\\n1–14: You are stymied by this problem before you. The venture fails unless a character spends <energy><energy> or <lore> to attempt this test again.\\"","ru":"<p><i><b>Чтобы разузнать об истоках болезни, распространившейся в Сплетении, вы должны были самостоятельно изучить поражённые участки. Вы начали свои поиски на увядающей поляне. </b></i></p><p>Отправьтесь в поход (см. раздел «Походы» в правилах игры на с. 60).</p><p><i><b>Лианы на поляне безжизненно повисли, а их кора была туго натянута. Возможно, вы могли бы получить новые сведения, срезав больше образцов.</b></i></p><p><b>Защитник.</b> Один из персонажей в походе должен провести проверку <dexterity>, чтобы взять образцы лиан. +2, если у этого персонажа есть <cut>, и +2, если он <i>любознательный</i>. Также +1 за каждый жетон на карте цели «Соберите образцы листвы» или +6, если эта цель выполнена.<br><b>≥14:</b>  Вы заметили, как лианы чахли у корней. Продолжите поход.<br><b>1-13:</b>  Вам не удалось найти ничего интересного. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy> или <lore>, чтобы провести проверку ещё раз.</p><p><i><b>Вы начали изучать корневую систему больших растений Сплетения, раскапывая землю в поисках подземного узла. </b></i></p><p><b>Группа.</b> Все персонажи в походе должны провести проверку <might>, чтобы откопать корни. +2, если у персонажа есть <dig>, и +2, если он <i>изобретательный</i>.<br><b>≥10:</b>  Вы откопали скрученные корни. Если хотя бы один персонаж получил этот результат, продолжите поход.<br><b>1-9:</b>  Вы вскопали рыхлую почву, но ничего не нашли. Если все персонажи получили этот результат, поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy> или <lore>, чтобы провести проверку ещё раз.</p><p><i><b>Вам нужно было внимательно изучить корни изнутри, но пробиться сквозь их плотную оболочку оказалось непросто. </b></i></p><p><b>Защитник.</b> Один из персонажей в походе должен провести проверку <awareness>, чтобы изучить корни. +2, если у этого персонажа есть <chop>, и +2, если он <i>сосредоточенный</i>. Также +1 за каждый жетон на карте цели «Соберите образцы листвы» или +6, если эта цель выполнена. <br><b>≥15:</b>  Вы прорубили корни и увидели скопление сочащихся ядом наростов. Они наверняка были симптомом порчи — неужели её источник находился ещё глубже под землёй? Завершите этот поход и достигните соответствующей цели.<br><b>1-14:</b>  Эта задача оказалась для вас нерешаемой. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy> или <lore>, чтобы провести проверку ещё раз.</p>"},"repeatable":false},{"id":"outcomes-777","code":"777","description":{"en":"<p>As dawn breaks, you see that which you feared most. The behemoth trudges toward your village. Whether in scorn or ignorance, it smashes part your structures and drives your people into flight.</p>\\nSubtract 6<population>. Illustrate the saga of the dire day on the primal cave wall, including the mark of the alert behemoth adorned with the wrath mark (see Adorning Marks on Rulebook p.70). Add In Shadowed Vale (CA08) to your looming challenges.","ru":"<p><i><b>С рассветом вы увидели то, чего больше всего опасались: чудище брело к вашей деревне. То ли в гневе, то ли по неведению оно разрушило часть ваших сооружений и обратило ваш народ в бегство.</b></i></p><p>Завершите текущее испытание.</p><p>Уберите 6 <population>. На стене первобытной пещеры изобразите историю о страшном часе, включив в неё отметку бодрствующего чудища, украшенную отметкой гнева. Добавьте карту «Сумрак долины» (ИА08) к грядущим испытаниям.</p>"},"repeatable":false,"marks":[{"label":"","image":"<wrath>"}]},{"id":"outcomes-783","code":"783","description":{"en":"<p>You discover that a faction among your people believes you should hunt the behemoth, ending the threat once and for all.</p>\\n\\"As a group, the players must choose one of the following paths for your society:\\n\\n<b>A) Accept the plan to hunt the behemoth:</b> Subtract <unrest><unrest><unrest>. Choose a behemoth with the highest demeanor and aggravate its demeanor by 3. Add Night of Storms (CA09) to your looming challenges.\\n\\n<b>B) Set a taboo against approaching behemoths entirely:</b> Subtract <unrest><unrest><unrest>. Placate each behemoth's demeanor by 3. Add \\\\\\"Moving into an alert behemoth's hex\\\\\\" to the Taboos section of the Culture page of the Journal. Gain the Taboos (KN18) Knowledge card.\\n\\n<b>C) Persuade them that coexistence is possible:</b> One character must test <conviction> to deescalate the situation. Add +2 if you are <i>wise</i>. Add +2 if you have the mediator mark and +4 if you have the mark of a behemoth with the highest demeanor.\\n11+: You make clear the consequences of such a plan. Subtract <unrest><unrest><unrest>. Placate each behemoth's demeanor by 1.\\n9–10: Your people are disgruntled, but are ultimately persuaded. Add <unrest><unrest><unrest>.\\n1–8: A group of people depart to strike at the behemoth. Add <unrest><unrest><unrest>. Aggravate each behemoth's demeanor by 3. Add Night of Storms (CA09) to your looming challenges.\\"","ru":"<p><i><b>Вы узнали, что часть вашего народа считает, что чудище нужно обязательно выследить и покончить с ним навсегда.</b></i></p><p>Совместно выберите один из следующих путей развития общины:<br><b>А. Согласитесь охотиться на чудище. </b>Уберите <unrest><unrest><unrest>. Выберите чудище с самым высоким значением нрава и разозлите его на 3. Добавьте карту «Ночь бурь» (ИA09) к грядущим испытаниям.<br><b>Б. Запретите приближаться к чудищам.</b> Уберите <unrest><unrest><unrest>. Успокойте каждое чудище на 3. Запишите «Перемещаться на участок с бодрствующим чудищем» в раздел «Табу» на странице «Культура» в журнале. Получите карту знаний «Табу» (ЗБ18), если у вас её нет.<br><b>В. Убедите свой народ, что мирное сосуществование возможно.</b> Один из персонажей должен провести проверку <conviction>, чтобы разрядить обстановку. +2, если этот персонаж <i>мудрый</i>, +2, если у него есть отметка посредника, и +4, если у него есть отметка чудища с самым высоким значением нрава.<br><b>≥11:</b>  Вы ясно дали понять, к чему приведёт план охоты. Уберите <unrest><unrest><unrest>. Успокойте каждое чудище на 1.<br><b>9-10:</b>  Хоть вам и удалось убедить свой народ, кто-то остался недоволен. Добавьте <unrest><unrest><unrest>.<br><b>1-8:</b>  Группа людей не послушала вас и отправилась на битву с чудищем. Добавьте <unrest><unrest><unrest>. Разозлите каждое чудище на 3. Добавьте карту «Ночь бурь» (ИA09) к грядущим испытаниям.</p>"},"repeatable":false,"marks":[{"label":"","image":"<mediator>"}]},{"id":"outcomes-784","code":"784","description":{"en":"<p>You know that the behemoth feeds upon choice stones. Rummaging in your bag, you look for something to sate its hunger.</p>\\n\\"Choose one and resolve it:\\n\\n<b>A) Feed the behemoth a choice morsel:</b> If you have a material token in your inventory, discard 1 material token to end the encounter. Placate the behemoth's demeanor by 1. Then, if a character, animal companion, or storage structure has an item with Seeping in its name, gain 2 of the behemoth's curio; otherwise, gain the Stone of Seeping (IT91) Item card. \\n\\n<b>B) Disappoint the great rock-gorger:</b> Aggravate the behemoth's demeanor by 1, then end the encounter.\\"","ru":"<p><i><b>Вы знали, что чудище питается отборными камнями. Порывшись в своей сумке, вы попытались найти что‑то, что утолит его голод.</b></i></p><p>Разыграйте первое, что можете:<br><b>А. Накормите чудище отборным каменным лакомством.</b> Сбросьте 1 минерал, чтобы завершить встречу. Успокойте чудище на 1. Затем, если у персонажа, животного-компаньона или в сооружении-хранилище есть предмет со словом «сочащийся» в названии, получите 2 сокровища чудища; в противном случае получите карту предмета «Сочащийся камень» (ВЩ91).<br><b>Б. Разочаруйте великого пожирателя камней.</b> Разозлите чудище на 1, затем завершите встречу.</p>"},"repeatable":false},{"id":"outcomes-785","code":"785","description":{"en":"<p>The desolate behemoth stands before you, its great crown of antlers challenging the sky? Who are you to face a creature whose very tread heralds fiery doom and rebirth from the ashes alike?</p>\\n\\"Embark on the venture below (see Ventures on Rulebook p.60).\\n\\n<bi>As you approach, the amber light that spills from the beast saps you of the strength to charge....</bi>\\n<b>Behemoth, Group, Hazard:</b> Everyone must contest <awareness> versus the behemoth's <conviction> to see the path through the withering light. A character adds +2 if they have a <i>coral</i> or <i>moonblood</i> item and +2 if they are <i>patient</i>.\\nWin (Equal or higher): You find a path through without being sapped. The venture continues.\\nLose (Lower): The light drains your strength. Degrade all of your boosts twice. The venture continues.\\n\\n<bi>The behemoth breaks off as you reach it, circling your group swiftly and leaving searing footprints as it passes. You must nimbly avoid the flames to catch it!</bi>\\n<b>Behemoth, Group, Hazard:</b> Everyone must contest <dexterity> versus the behemoth's <might> to dodge through the fire unharmed. A character adds +2 if they have a <i>cloak</i> item and +2 if they are <i>cunning</i>.\\nWin (Equal or higher): You burst through the fiery trail unharmed. If any character resolves this result, continue the venture.\\nLose (Lower): You must leave the venture unless you suffer <major_injury> to attempt this test again. If all characters leave the venture, the venture fails.\\n\\n<bi>Having reached the behemoth, you must grapple your way up the bone-thorned flanks. The spurs provides some protection from the drain of vitality, but the effort is still superhuman.</bi>\\n<b>Behemoth, Champion:</b> Someone must test <might> versus the behemoth's <awareness> to clamber up. Add +2 if you have a Rope, +2 if you have a Piton, +2 if you have <stoneworking>, and +2 if you are <i>vengeful</i>.\\nWin (Equal or higher): You drag yourself up the side, the strength trickling from you with every handhold. You must leave the venture unless you reduce your <conviction> or <awareness> attribute by 1. If all characters leave the venture, the venture fails. Otherwise, continue the venture.\\nLose (Lower): You are thrown from the beast's side. Suffer <major_injury><major_injury>, then leave the venture. Another character on the venture must attempt this test. If all characters on the venture leave, the venture fails.\\n\\n<bi>Atop the behemoth, you clench the bead of amber. The air itself screams and the skin peels from your hand as you push the gemstone into the mighty ribcage.</bi>\\n<b>Behemoth, Champion:</b> Someone must contest <conviction> versus the behemoth's <dexterity> to withstand the pain. Add +2 if you have a <i>talisman</i> item, +4 if you have a <i>trophy</i> item, and +2 if you are <i>indomitable</i>.\\nWin (Equal or higher): You plunge the bead deep into the amber light at the core of the behemoth. Reduce your <might> or <dexterity> attribute by 1. Complete this venture and the associated goal.\\nLose (Lower): Mark one Age box on your character. If you check the Legend box this way, your character perishes immediately. The venture fails unless a character spends <energy><energy> or <lore> to attempt this test again.\\"","ru":"<p><i><b>Перед вами стояло безмолвное чудище — его огромная корона бросала вызов небу. Кто вы, чтобы противостоять созданию, чей каждый шаг возвещал огненную гибель и возрождение из пепла?</b></i></p><p>Отправьтесь в поход (см. раздел «Походы» в правилах игры на с. 60).</p><p><i><b>Приблизившись, вы почувствовали, как янтарный свет, льющийся от чудища, лишает вас сил для решительного рывка… </b></i></p><p><b>Чудище, группа, угроза. </b>Все персонажи в походе должны провести состязание, чтобы увидеть путь сквозь губительный свет: <awareness> против <conviction> чудища. +2, если у персонажа есть предмет коралла или предмет <i>лунной крови</i>, и +2, если персонаж <i>терпеливый</i>.<br><b>Успех.</b> Вы нашли путь сквозь свет. Продолжите поход.<br><b>Провал.</b> Свет истощил вас. Уменьшите все свои усиления дважды. Продолжите поход.</p><p><i><b>Чудище отступило, как только вы его настигли, быстро окружив вашу группу раскалёнными следами. Теперь вам нужно было ловко уклониться от огня, чтобы поймать чудище.</b></i></p><p><b>Чудище, группа, угроза. </b>Все персонажи в походе должны провести состязание, чтобы уклониться от огня: <dexterity> против <might> чудища. +2, если у персонажа есть <i>накидка</i>, и +2, если персонаж <i>хитрый</i>.<br><b>Успех. </b>Вы прорвались сквозь огненную завесу невредимыми. Если хотя бы один персонаж получил этот результат, продолжите поход. <br><b>Провал.</b> Получите <major_injury>, чтобы провести проверку ещё раз, или покиньте поход. Если все персонажи покинули поход, он окончился неудачно.</p><p><i><b>Вы добрались до чудища и стали взбираться на его покрытые шипами бока, что требовало нечеловеческих усилий.</b></i></p><p><b>Чудище, защитник. </b>Один из персонажей в походе должен провести состязание, чтобы взобраться: его <might> против <awareness> чудища. +2, если у этого персонажа есть «Верёвка», +2, если у него есть «Трость», +2, если у него есть <stoneworking>, и +2, если он <i>мстительный</i>.<br><b>Успех.</b> Вы цеплялись за уступы, с каждым движением теряя последние силы. Вы должны покинуть поход или навсегда уменьшить значение своей <conviction> либо <awareness> на 1. Другой персонаж в походе должен провести эту проверку. Если все персонажи покинули поход, он окончился неудачно. В противном случае продолжите поход.<br><b>Провал. </b>Вы не смогли удержаться на чудище. Получите <major_injury><major_injury> и покиньте поход. Если все персонажи получили этот результат, поход окончился неудачно.</p><p><i><b>Оказавшись на чудище, вы сжали в кулаке бусину из янтаря. Сам воздух взвыл, а кожа начала слезать с вашей руки, когда вы вонзили камень в могучую грудь чудища.</b></i></p><p><b>Чудище, защитник. </b>Один из персонажей в походе должен провести состязание, чтобы выдержать боль: его <conviction> против <dexterity> чудища. +2, если у этого персонажа есть <i>талисман</i>, +4, если у него есть <i>трофей</i>, и +2, если персонаж <i>неукротимый</i>.<br><b>Успех. </b>Вы вонзили бусину глубоко в светящееся янтарём сердце чудища. Навсегда уменьшите значение своей <might> или <dexterity> на 1. Завершите этот поход и достигните соответствующей цели.<br><b>Провал.</b> Отметьте одну клетку возраста на карте персонажа. Если таким образом будет отмечена клетка легенды, персонаж немедленно умирает. Затем поход заканчивается неудачно, если только любой живой персонаж в походе не потратит <energy><energy> или <lore>, чтобы провести проверку ещё раз.</p>"},"repeatable":false},{"id":"outcomes-790","code":"790","description":{"en":"<p>The behemoth turns its massive head to look at you as you stand atop its spine. Its gaze does not waver from the fire.</p>\\n\\"Choose one of the following and resolve it:\\n\\n<b>A) Feed the flames to the behemoth:</b> End the encounter. The behemoth flees twice. Remove a depletion token from each hex it enters this way.\\n\\n<b>B) Douse the flame:</b> End the encounter. Aggravate the behemoth's demeanor by 2. Then, if a character, animal companion, or storage structure has an item with Siphon in its name, gain 2 of the behemoth's curio; otherwise, gain the Siphon Stone (IT100) Item card.\\"","ru":"<p><i><b>Чудище повернуло свою массивную голову, чтобы взглянуть на вас, пока вы стояли на его спине. Оно не отводило глаз от пламени.</b></i></p><p>Выберите и разыграйте одно:<br><b>А. Скормите пламя чудищу. Завершите встречу.</b> Чудище сбегает дважды. Уберите по одному жетону истощения с каждого участка местности, на который оно переместилось во время бегства.<br><b>Б. Потушите пламя. Завершите встречу. </b>Разозлите чудище на 2. Затем, если у персонажа, животного-компаньона или в сооружении-хранилище есть предмет со словом «поглощающий» в названии, получите 2 сокровища чудища; в противном случае получите карту предмета «Поглощающий камень» (ВЩ100).</p>"},"repeatable":false},{"id":"outcomes-797","code":"797","description":{"en":"<p>You skirmish with the behemoth, eventually driving it back to its lair. The creature retreats within, and is not seen for many seasons to come...</p>\\n\\"At the end of any day, you may end this challenge. Then as a group, the players must choose one of the following paths for your society:\\n\\n<b>A) Revel in your victory over the behemoth:</b> Subtract <unrest><unrest>. Illustrate the saga of the storm's end on the primal cave wall, including the alert behemoth's mark adorned with the wrath mark (i) (see Adorning Marks on Rulebook p.70).\\n\\n<b>B) Keep the fires of vigilance burning in case of the behemoth's return:</b> If the blaze mark is on the primal cave wall, add <population><population>. Illustrate the saga of the fire-sworn watchers on the primal cave wall, including the bond mark enclosing the blaze mark (ii).\\n\\nEnd the current epoch. Refer to Codex p.196 for rules on how to continue the current campaign into Epoch 2.\\"","ru":"<p><i><b>Вы сразились с чудищем и в конце концов оттеснили его обратно в логово. Существо скрылось внутри — и его не видели многие сезоны…</b></i></p><p>В конце любого дня можете завершить текущее испытание.</p><p>Затем совместно выберите один из следующих путей развития общины:<br><b>А. Возрадуйтесь победе над чудищем.</b> Уберите <unrest><unrest>. На стене первобытной пещеры изобразите историю о конце бури, включив в неё отметку бодрствующего чудища, украшенную отметкой гнева [i].<br><b>Б. Сохраните огонь на случай, если чудище вернётся.</b> Если на стене первобытной пещеры есть отметка пламени, добавьте <population><population>. На стене первобытной пещеры изобразите историю о присягнувших огню стражах, включив в неё отметку пламени [iii], заключённую в отметку связи [ii].</p><p>Завершите текущую эру. См. с. 196, чтобы начать эру 2.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<wrath>"},{"label":"ii","image":"<bond>"},{"label":"iii","image":"<blaze>"}]},{"id":"outcomes-801","code":"801","description":{"en":"<p>Your feast will be remembered for years to come.</p>\\n\\"At the end of any day, you may end this challenge. Then, subtract <unrest><unrest><unrest><unrest> and add <population><population>. Illustrate the saga of autumn's bounty on the primal cave wall, including the feast mark and the plenty mark.\\"","ru":"<p><i><b>Ваш пир запомнится на долгие годы.</b></i></p><p>В конце любого дня можете завершить текущее испытание.</p><p>Затем уберите <unrest><unrest><unrest><unrest> и добавьте <population><population>. На стене первобытной пещеры изобразите историю об осеннем изобилии, включив в неё отметку пира [i] и отметку изобилия [ii].</p>"},"repeatable":false,"marks":[{"label":"i","image":"<feast>"},{"label":"ii","image":"<plenty>"}]},{"id":"outcomes-811","code":"811","description":{"en":"<p>\\"Within a deep groove cut by the behemoth's passing, you notice chunks of coral that it carefully avoided.\\"</p>\\n\\"Choose one of the following and resolve it:\\n\\n<b>A) Observe the path's deviation:</b> If the behemoth has an unrevealed Secret card assigned to it, reveal this behemoth's currently assigned Secret card, then record it under the Secrets for that behemoth in the Journal.\\n\\n<b>B) Gather the coral shards:</b> Gain 1 dead coral. If you have living coral or a <i>coral</i> item, gain 1 living coral instead.\\"","ru":"<p><i><b>Рядом с глубокой бороздой, оставленной чудищем, вы заметили куски коралла, которые оно аккуратно обошло стороной.</b></i></p><p>Выберите и разыграйте одно:<br><b>А. Проследите, как изменился путь. </b>Если у чудища есть неоткрытая назначенная карта секрета, откройте её. Затем запишите её в раздел секретов этого чудища в журнале.<br><b>Б. Соберите коралловые осколки. </b>Получите 1 мёртвый коралл. Если у вас есть хотя бы 1 живой коралл или предмет <i>коралла</i>, вместо этого получите 1 живой коралл.</p>"},"repeatable":false},{"id":"outcomes-813","code":"813","description":{"en":"<p>You have studied the behemoth and found that, while powerful, it is a living being like you. It moves across the valley with purpose, seeking the resources vital to its existence. Learning about it, your people come to view it as a potent force of nature to be respected. It also creates useful opportunities within the valley as its titanic movements reveal unseen, rare resources from deep within the earth.</p>\\n\\"At the end of any day, you may end this challenge.\\n\\nThen, as a group, the players must choose one of the following paths for your society:\\n\\n<b>A) Advise your people to avoid the behemoth's passage:</b> Subtract <unrest>. Placate the alert behemoth's demeanor by 2. Illustrate the saga of the mighty neighbor on the primal cave wall, including the alert behemoths' mark, the caution mark (i), and the taboo mark (iv). Add \\\\\\"Resting in a hex with a behemoth's wake overlay\\\\\\" to the Taboos section of the Culture page of the Journal. Gain the Taboos (KN18) Knowledge card.\\n\\n<b>B) Use the behemoth's cataclysmic movements to secure more of the precious silver liquid:</b> If the moonblood mark is on the primal cave wall, add <population><population><population>. Aggravate the alert behemoth's demeanor by 3. Illustrate the saga of the moonblood bounty on the primal cave wall, including the alert behemoths' mark, the mystery mark (v), and the bond mark enclosing the moonblood mark (ii).\\n\\n<b>C) Take advantage of the behemoth's destructive wake to further explore the mysteries hidden beneath the valley:</b> If the underworld mark is on the primal cave wall, add <population><population><population>. Aggravate the alert behemoth's demeanor by 3. Illustrate the saga of the depths revealed on the primal cave wall, including the alert behemoth's mark, the mystery mark (v), and the bond mark enclosing the underworld mark (iii).\\n\\nAt the end of this challenge, end the current epoch. Refer to Codex p.196 to continue your campaign into Epoch 2.\\"","ru":"<p><i><b>Вы изучили чудище и поняли, что, несмотря на свою силу, оно — живое существо, как и вы. Оно сновало по долине не просто так, а разыскивало ресурсы, необходимые для выживания. Познав его, ваш народ стал видеть в нём могущественную силу природы, достойную уважения. К тому же оно подняло наверх из глубин земли скрытые редкие ресурсы, которые вы могли использовать себе во благо.</b></i></p><p>Завершите текущее испытание.</p><p>Затем совместно выберите один из следующих путей развития общины:<br><b>А. Посоветуйте людям своей общины избегать путей чудища. </b>Уберите <unrest>. Успокойте бодрствующее чудище на 2. На стене первобытной пещеры изобразите историю о могучем соседе, включив в неё отметку бодрствующего чудища, отметку осторожности [i] и отметку табу [iii]. Запишите «Отдыхать на участке с отпечатком чудища» в раздел «Табу» на странице «Культура» в журнале. Получите карту знаний «Табу» (ЗБ18), если у вас её нет.<br><b>Б. Воспользуйтесь разрушающими движениями чудища, чтобы добыть больше драгоценной серебристой жидкости. </b>Если на стене первобытной пещеры есть отметка лунной крови, добавьте <population><population><population>. Разозлите бодрствующее чудище на 3. На стене первобытной пещеры изобразите историю о даре лунной крови, включив в неё отметку бодрствующего чудища, отметку тайны [iv] и отметку лунной крови [v], заключённую в отметку связи [ii].<br><b>В. Воспользуйтесь разрушительным отпечатком чудища, чтобы лучше исследовать тайны, скрытые под долиной. </b>Если на стене первобытной пещеры есть отметка подземного мира, добавьте <population><population><population>. Разозлите бодрствующее чудище на 3. На стене первобытной пещеры изобразите историю о раскрытых глубинах, включив в неё отметку бодрствующего чудища, отметку тайны [iv] и отметку подземного мира [vi], заключённую в отметку связи [iii].</p><p>Затем завершите текущую эру. См. с. 196, чтобы начать эру 2.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<caution>"},{"label":"ii","image":"<bond>"},{"label":"iii","image":"<taboo>"},{"label":"iv","image":"<mystery>"},{"label":"v","image":"<moonblood>"},{"label":"vi","image":"<underworld>"}]},{"id":"outcomes-814","code":"814","description":{"en":"<p>The raiders might have grown emboldened by their success, but you have met them with determination and force. Too much blood has been spilled, but the time of turmoil is over.</p>\\nSubtract <population><population><population>, subtract 6<unrest>. Illustrate the saga of the silenced ones on the primal cave wall, including the battle mark (i) and the harrowing mark (ii).","ru":"<p><i><b>Налётчики, уверовавшие в свою неуязвимость, бросились в бой, но ваши отвага и мощь сломили их. Много крови было пролито впустую, однако время смуты миновало.</b></i></p><p>Уберите <population><population><population> и уберите 6 <unrest>. На стене первобытной пещеры изобразите историю о затихших, включив в неё отметку битвы [i] и отметку ужаса [ii].</p>"},"repeatable":false,"marks":[{"label":"i","image":"<battle>"},{"label":"ii","image":"<harrowing>"}]},{"id":"outcomes-815","code":"815","description":{"en":"<p>The behemoth regards you with expectant interest. You know it has no love of the coral, yet you wonder what would happen if you offered it...</p>\\n\\"Choose one and resolve it:\\n\\n<b>A) Offer a coral trinket:</b> If you have a living coral material or a <i>coral</i> item in your inventory, discard a living coral or a <i>coral</i> item to end the encounter. Aggravate the behemoth's demeanor by 3. The behemoth flees. Then, if a character, animal companion, or storage structure has an item with Sundered in its name, gain 2 of the behemoth's curio; otherwise, gain the, gain the Sundered Stone (IT88) Item card.\\n\\n<b>B) Think better of it and offer a safer token:</b> If you have a processed material or an item in your inventory, discard a processed material or an item to end the encounter. Placate the behemoth's demeanor by 1. Gain 1 of this behemoth's curio.\\n\\n<b>C) Swiftly retreat without an offering:</b> End the encounter. Aggravate the behemoth's demeanor by 2.\\"","ru":"<p><i><b>Чудище с интересом глядело на вас, явно чего‑то выжидая. Вы знали, что оно не выносит коралл, но вам было любопытно, что произойдёт, если вы всё же предложите его чудищу…</b></i></p><p>Выберите и разыграйте одно:<br><b>А. Предложите коралловую безделушку. </b>Если в вашем инвентаре есть живой коралл или предмет коралла, сбросьте 1 такой материал или предмет, чтобы завершить встречу. Разозлите чудище на 3. Чудище сбегает. Затем, если у персонажа, животного-компаньона или в сооружении-<i>хранилище </i>есть предмет со словом «расколотый» в названии, получите 2 сокровища чудища; в противном случае получите карту предмета «Расколотый камень» (ВЩ88).<br><b>Б. Предложите более безопасный дар.</b> Если в вашем инвентаре есть обработанный материал или предмет, сбросьте 1 обработанный материал или предмет, чтобы завершить встречу. Успокойте чудище на 1. Получите 1 сокровище этого чудища. <br><b>В. Быстро отступите, ничего не предложив.</b> Завершите встречу. Разозлите чудище на 2.</p>"},"repeatable":false},{"id":"outcomes-816","code":"816","description":{"en":"<p>The sky screams, and you look up to see a great rent above you. At the leading edge of this tear, you see the wanderer. A chunk of stone splits from it, and it descends. The shriek ends in a moment of silence. And then you are thrown from your feet by a rush of noise and chaos.</p>\\n\\"<i>The unfathomable impact alters the valley forever.</i> Follow the steps below to resolve it:\\n\\n<b>Step 1: <i>Everything at the impact site is instantly vaporized.</i></b> Choose a hex in the valley. You must choose a hex with a coral overgrowth, if able. Remove all overlays from that hex. Place the impact site overlay (HX01b) on top of that hex. Each character in the chosen hex becomes a Legend; their player creates a new character.\\n\\n<b>Step 2: <i>The blast wave shatters the surrounding area.</i></b> For each hex adjacent to the impact site, remove each overlay from that hex. If a behemoth's lair would be removed this way, it becomes inactive instead (a behemoth with an inactive lair can't become alert). Each character in a hex affected this way suffers <major_injury><major_injury><major_injury>.\\n\\n<b>Step 3: <i>The devastation spreads further still.</i></b> For each hex adjacent to a hex adjacent to the impact site, each overlay in that hex becomes inactive. If a behemoth's lair would become inactive this way, aggravate that behemoth's demeanor by <1d6> instead. Each character in a hex affected this way suffers <major_injury><minor_injury> .\\n\\n<b>Step 4: <i>Lashing winds and falling debris could threaten the entire valley.</i></b> For each other hex in the region with the impact site and each region adjacent to that region, each character in that hex suffers <major_injury><minor_injury> unless their hex has <shelter>. Then, if the hex contains an outpost, 2 randomly selected structures in that outpost are destroyed.\\n\\n<b>Step 5: <i>Coral overgrowths rapidly spread from the impact site.</i></b> One at a time, place an unplaced coral overgrowth overlay in a hex adjacent to the impact site without an overlay, if able. To determine the zone, roll <1d6> and resolve the following: (1–2) A, (3–4) B, (5–6) C.\\n\\n<b>Step 6: <i>Twisting transformations begin to affect the valley's flora and fauna.</i></b> Resolve as many of the following as you are able:\\n<b>A) The forests begin to change in odd ways:</b> If there is at least one Verdant Vale hex in the valley, add CF02 to the Forest Foraging deck.\\n\\n<b>B) Odd stalks sprout amidst the familiar grasses of the prairies:</b> If there is at least one Skyreach Plateau hex in the valley, add CP02 to the Prairie Foraging deck.\\n\\n<b>C) Even within the strangeness of the Tangle, an unusual presence is clear:</b> If there is at least one Tangle hex in the valley, add CT02 to the Glade Foraging deck (if available).\\n\\n<b>Step 7: <i>As the chaos spreads, your people become panicked and desperate.</i></b> As a group, the players must choose one of the following paths for your society:\\n\\n<b>A) Despite your best effort, widespread panic takes hold:</b> Add <unrest><unrest> and subtract <population><population><population>. Add Rising Chaos (GC01) to your goals.\\n\\n<b>B) Warn your people to avoid the impact site:</b> If the caution mark (i) is on the primal cave wall, add \\\\\\"moving into the impact site\\\\\\" to the Taboos section of the Culture page of the Journal. Gain the Taboos (KN18) Knowledge card.\\n\\n<b>C) Seek refuge in the depths:</b> If the mystery mark (ii) and the underworld mark (iii) are both on the primal cave wall, add Flee Underground (GC10) to your goals.\\"","ru":"<p><i><b>Небо раскололось с пронзительным рёвом. Вы посмотрели наверх и увидели в образовавшемся там зияющем разрыве Скитальца. Кусок камня оторвался от него и устремился вниз, в долину. Внезапная тишина ненадолго оборвала рёв, а затем вас швырнуло наземь громогласной волной вселенского разрушения.</b></i></p><p><b>Это невообразимое столкновение навсегда изменило долину. </b>Пройдите описанные ниже этапы в указанном порядке.<br><b>Этап 1. Всё в месте падения мгновенно испарилось. </b>Уберите все накладки с любого участка в долине, выбрав участок с коралловыми зарослями, если возможно, и поместите поверх него накладку места падения (ОБ01б). Каждый персонаж на этом участке местности становится легендой — создайте новых персонажей им на замену.<br><b>Этап 2. Ударная волна разрушила окрестности. </b>Уберите все накладки с каждого участка местности, соседнего с местом падения. Если таким образом должно быть убрано логово чудища, вместо этого переверните его неактивной стороной вверх (чудище с неактивным логовом не может стать бодрствующим). Каждый персонаж на этих участках получает <major_injury><major_injury><major_injury>.<br><b>Этап 3. Разрушение распространилось ещё дальше. </b>Переверните все накладки неактивной стороной вверх на каждом участке местности, соседнем с хотя бы одним участком, который соседствует с местом падения. Если логово чудища должно стать неактивным таким образом, вместо этого разозлите это чудище на результат броска <1d6>. Каждый персонаж на этих участках получает <major_injury> и  <minor_injury>.<br><b>Этап 4. Ветер и падающие обломки могли угрожать всей долине.</b> Персонажи на каждом другом участке местности в регионе с местом падения и в каждом соседнем регионе получают <major_injury> и <minor_injury>, если на их участке нет <shelter>. Затем, если на затронутом участке местности есть поселение, разрушьте в нём 2 случайных сооружения.<br><b>Этап 5. Коралловые заросли начали стремительно распространяться от места падения. </b>Если возможно, поочерёдно поместите неразмещённые накладки коралловых зарослей на соседние с местом падения участки местности, на которых нет ни одной накладки. Бросьте <1d6>, чтобы поместить накладку в соответствующий район: [1-2] А, [3-4] Б, [5-6] В.<br><b>Этап 6. Неожиданные превращения изменили саму природу долины.</b> Разыграйте как можно больше из следующего:<br><b>А. Леса начали меняться странным образом. </b>Если в долине есть хотя бы 1 участок Дивной долины, добавьте карту КЛ02 в колоду добычи припасов в лесу.<br><b>Б. В степной траве начали попадаться загадочные стебли.</b> Если в долине есть хотя бы 1 участок Поднебесной равнины, добавьте карту КС02 в колоду добычи припасов в степи.<br><b>В. Даже в необычном Сплетении появилось нечто чуждое. </b>Если в долине есть хотя бы 1 участок Сплетения, добавьте карту КП02 в колоду добычи припасов на полянах.<br><b>Этап 7. Чем больше распространялся хаос, тем больше паниковал и впадал в отчаяние ваш народ.</b>Совместно выберите один из следующих путей развития общины:<br><b>А. Свыкнитесь с обстоятельствами. </b>Добавьте <unrest><unrest> и уберите <population><population><population>. Добавьте карту «Выживите в растущем хаосе» (ЦВ01) к целям.<br><b>Б. Заставьте людей избегать места падения.</b> Если на стене первобытной пещеры есть отметка осторожности [i], запишите «Перемещаться в место падения» в раздел «Табу» на странице «Культура» в журнале. Получите карту знаний «Табу» (ЗБ18), если у вас её нет.<br><b>В. Найдите убежище в глубинах.</b> Если на стене первобытной пещеры есть отметка тайны [ii] и отметка подземного мира [iii], добавьте карту «Укройтесь под землёй» (ЦВ10) к целям.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<caution>"},{"label":"ii","image":"<mystery>"},{"label":"iii","image":"<underworld>"}]},{"id":"outcomes-817","code":"817","description":{"en":"<p>\\"As you approach the behemoth's lair, you find it overrun with tendrils of the coral. The great beast is trapped within, and your hopes rest with it.\\"</p>\\n\\"Embark on the venture below (see Ventures on Rulebook p.60).\\n\\n<bi>The coral surrounding the lair has shifted into its dormant state, turning it into a rocky barrier. You'll have to smash through!</bi>\\n<b>Coral, Group:</b> Everyone must test <might> to break the barrier. Add +2 if you have <strike>, +4 if you have <stoneworking>, and +2 if you are <i>resourceful</i>.\\n12+: You crack the coral, and it falls away to reveal a passage large enough to enter. Continue the venture.\\n1–11: You only exhaust yourself. If all characters on the venture resolve this result, the venture fails unless a character spends <energy><energy> to attempt this test again.\\n\\n<bi>Within the heart of the lair you find the behemoth, entangled in more of the coral. The living tendrils are thick as vines and tough as sinew.</bi>\\n<b>Behemoth, Coral, Group:</b> Everyone must test <dexterity> to cut the behemoth free. A character adds +2 if they have <cut>, +4 if they have a <i>moonblood</i> item with <cut>, and +2 if they are <i>wise</i>.\\n13+: You slash loose enough tendrils to free one of the behemoth's limbs, and the great beast pushes itself to its feet, snapping the rest as it goes. Continue the venture.\\n1–12: Despite your effort, the coral strands hold fast, regrowing nearly as swiftly as you can slice them. If all characters on the venture resolve this result, the venture fails unless a character suffers <major_injury> or spends <lore><lore> to attempt this test again.\\n\\n<bi>The behemoth may be free, but it filled with the fury of desperation. You'll need to direct that anger, lest it crush you in its panicked anger.</bi>\\n<b>Behemoth, Champion, Coral:</b> Someone must test <conviction> to soothe the behemoth. Add +4 if one or more Secrets have been recorded in the Journal for this behemoth and +2 if you are <i>attuned</i>. Add +4 if the behemoth's demeanor is 5 or lower. You may discard up to 3 of the behemoth's curio to add +2 per token discarded this way.\\n14+: The behemoth looks deep into your eyes and grows calm. Complete this venture and the associated goal..\\n9–13: The venture fails unless a character spends <energy><energy> or <lore> to attempt this test again.\\n1–8: Suffer <major_injury><major_injury> as the behemoth's struggles topple debris from its lair onto you. Then resolve 9–13.\\"","ru":"<p><i><b>Когда вы приблизились к логову чудища, то обнаружили, что вход в логово опутан щупальцами коралла. Великое создание оказалось в ловушке внутри, а ведь на него вы возлагали свои надежды.</b></i></p><p>Отправьтесь в поход (см. раздел «Походы» в правилах игры на с. 60).</p><p><b><i>Коралл вокруг логова, казалось, заснул и стал подобен каменной преграде. Придётся её пробить!</i></b></p><p>Коралл, группа. Все персонажи в походе должны провести проверку <might>, чтобы проломить барьер. +2, если у персонажа есть <strike>, +4, если у него есть <stoneworking>, и +2, если он <i>изобретательный</i>.<br><b>≥12:</b>  Вы раскололи коралл, и он обрушился, открыв проход — достаточно широкий, чтобы вы смогли попасть внутрь логова. Продолжите поход.<br><b>1-11:</b>  Вы выбились из сил. Если все персонажи получили этот результат, поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy>, чтобы провести проверку ещё раз.</p><p><i><b>В самом сердце логова вы нашли чудище, опутанное живыми коралловыми щупальцами — толстыми, как лианы, и прочными, как жилы.</b></i></p><p><b>Чудище, коралл, группа.</b> Все персонажи в походе должны провести проверку <dexterity>, чтобы освободить чудище. +2, если у персонажа есть <cut>, +4, если у него есть предмет лунной крови с <cut>, и +2, если он <i>мудрый</i>.<br><b>≥13:</b>  Вы перерезали достаточно щупалец, чтобы освободить одну из конечностей чудища, и оно поднялось на ноги, разрывая оставшиеся путы. Продолжите поход.<br>1-12  Несмотря на ваши усилия, прочные коралловые щупальца отрастали почти с той же скоростью, с какой вы их срезали. Если все персонажи получили этот результат, поход окончился неудачно, если только любой персонаж в походе не получит <major_injury> или не потратит <lore><lore>, чтобы провести проверку ещё раз.</p><p><i><b>Чудище освободилось от пут, и тут же его охватила слепая ярость. Вам нужно было направить гнев чудища в нужное русло, пока оно не выбрало вас своей целью.</b></i></p><p><b>Чудище, защитник, коралл. </b>Один из персонажей в походе должен провести проверку <conviction>, чтобы успокоить чудище. +4, если в журнале записан хотя бы один секрет этого чудища, +2, если этот персонаж <i>сосредоточенный</i>, +4, если значение нрава чудища не более 5. Также +2 за каждое сброшенное выбранным персонажем сокровище чудища (не более +6).<br><b>≥14:</b>  Чудище посмотрело вам в глаза и успокоилось. Завершите этот поход и достигните соответствующей цели.<br><b>9-13:</b>  Поход окончился неудачно, если только любой персонаж в походе не потратит или , чтобы провести проверку ещё раз.<br><b>1-8:</b>  Чудище в агонии обрушило на вас обломки логова. Получите <major_injury><major_injury>, затем разыграйте исход как при [9-13].</p>"},"repeatable":false},{"id":"outcomes-818","code":"818","description":{"en":"<p>\\"Your people establish a tradition of moving from season to season, allowing you to hunt and fish without depleting the land's natural resources.\\"</p>\\n<p>\\"At the end of any day, you may end this challenge. Add A Peaceful Season (CZ01) to looming challenges (even if previously completed).\\n\\nThen, illustrate the saga of the seasonal migration on the primal cave wall, including the caravan mark (i), the hunter mark (ii), and the plenty mark (iii).\\"</p>","ru":"<p><i><b>Ваш народ привык каждый сезон переезжать с места на место, что позволяло ему охотиться и рыбачить, не истощая природные ресурсы.</b></i></p><p>В конце любого дня можете завершить текущее испытание.</p><p>Добавьте карту «Период затишья» (ИЯ01) к грядущим испытаниям (даже если вы завершали ранее это испытание).</p><p>Затем на стене первобытной пещеры изобразите историю о сезонном переселении, включив в неё отметку каравана [i], отметку охотника [ii] и отметку изобилия [iii].</p>"},"repeatable":false,"marks":[{"label":"i","image":"<caravan>"},{"label":"ii","image":"<hunter>"},{"label":"iii","image":"<plenty>"}]},{"id":"outcomes-821","code":"821","description":{"en":"<p>Under the symbol you have chosen, your people rally as one. As the ages pass, this symbol becomes synonymous with your unique culture.</p>\\n\\"At the end of any day, you may end this challenge.\\n\\nThen, subtract <unrest><unrest><unrest><unrest>. Illustrate the saga of the unifying sign on the primal cave wall, including the mediator mark (i) and the bond mark (ii) enclosing the omen mark matching the faceup token on Spinner of Myth. Add that omen mark to the Legend side of each of your character character cards. Then, resolve one of the following based on that omen:\\n\\n<b>A) The thundercloud becomes a symbol of power in your culture:</b> If the omen was <cloud>, each of your characters gains the <i>indomitable</i> trait. For each character without the growth mark (iv) on the Legend side of their character card, permanently raise that character's <might> by 1 (to a maximum of 7), then add the growth mark (iv) to the Legend side of their character card.\\n\\n<b>B) The wanderer becomes your people's symbol, representing your tenacity and adaptability:</b> If the omen was <comet>, each of your characters gains the <i>resourceful</i> trait. For each character without the growth mark (iv) on the Legend side of their character card, permanently raise one of that character's lowest attributes by 3 (to a maximum of 8), then add the coral mark (iii) and the growth mark (iv) to the Legend side of their character card.\\n\\n<b>C) The moon's shrouded mystery takes on a prominent role in your culture:</b> If the omen was <moon>, each of your characters gains the <i>wise</i> trait. For each character without the growth mark (iv) on the Legend side of their character card, permanently raise that character's <awareness> by 1 (to a maximum of 7), then add the growth mark (iv) to the Legend side of their character card.\\n\\n<b>D) The life-giving sun becomes the symbol of your people:</b> If the omen was <sun>, each of your characters gains the <i>intrepid</i> trait. For each character without the growth mark (iv) on the Legend side of their character card, permanently raise that character's <conviction> by 1 (to a maximum of 7), then add the growth mark (iv) to the Legend side of their character card.\\n\\n<b>E) The cold and glittering stars come to represent the distant aspirations your people seek:</b> If the omen was <star>, each of your characters gains the <i>cunning</i> trait. For each character without the growth mark (iv) on the Legend side of their character card, permanently raise that character's <dexterity> by 1 (to a maximum of 7), then add the growth mark (iv) to the Legend side of their character card.\\n\\nThen end this challenge and end the Epoch. See Codex p.204 to begin Epoch 3.\\"","ru":"<p><i><b>Выбранный вами символ сплотил людей. Спустя много лет он стал олицетворением неповторимости вашей культуры.</b></i></p><p>В конце любого дня можете завершить текущее испытание. </p><p>Затем уберите <unrest><unrest><unrest><unrest>. На стене первобытной пещеры изобразите историю об объединяющем знаке, включив в неё отметку посредника [i] и отметку знамения с открытого жетона на карте цели «Сотворите миф», заключённую в отметку связи [ii]. Также добавьте отметку этого знамения на сторону легенды карт персонажей. После чего разыграйте эффект в зависимости от знамения:<br><b>А. Грозовая туча стала символом силы вашей культуры.</b> Если знамение — <cloud>, каждый персонаж получает черту «неукротимый». Каждый персонаж, на стороне легенды карты которого нет отметки становления [iv], навсегда увеличивает <might> на 1 (не более чем до 7), а затем получает отметку становления.<br><b>Б. Скиталец стал символом несгибаемости и приспособляемости вашего народа. </b>Если знамение — <comet>, каждый персонаж получает черту «изобретательный». Каждый персонаж, на стороне легенды карты которого нет отметки становления [iv], навсегда увеличивает одну из своих самых низких характеристик на 3 (не более чем до 8), а затем получает отметки коралла [iii] и становления.<br><b>В. Таинственная луна заняла видное место в культуре вашего народа. </b>Если знамение — <moon>, каждый персонаж получает черту «мудрый». Каждый персонаж, на стороне легенды карты которого нет отметки становления [iv], навсегда увеличивает <awareness> на 1 (не более чем до 7), а затем получает отметку становления.<br><b>Г. Животворящее солнце стало символом вашего народа. </b>Если знамение — <sun>, каждый персонаж получает черту «отважный». Каждый персонаж, на стороне легенды карты которого нет отметки становления (iv), навсегда увеличивает <conviction> на 1 (не более чем до 7), а затем получает отметку становления.<br><b>Д. Холодные мерцающие звёзды стали символом стремлений вашего народа к недосягаемым высотам.</b> Если знамение — <star>, каждый персонаж получает черту «хитрый». Каждый персонаж, на стороне легенды карты которого нет отметки становления [iv], навсегда увеличивает <dexterity> на 1 (не более чем до 7), а затем получает отметку становления.</p><p>Затем завершите текущее испытание и текущую эру. См. с. 204, чтобы начать эру 3.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<mediator>"},{"label":"ii","image":"<bond>"},{"label":"iii","image":"<coral>"},{"label":"iv","image":"<growth>"}]},{"id":"outcomes-823","code":"823","description":{"en":"<p>Winter comes, and your plants wither in your would-be fields. Perhaps this endeavor was doomed from the start. With a great deal of time lost, your people must scramble to gather the supplies needed for a harsh winter.</p>\\n\\"End this challenge. \\n\\nThen subtract <population><population><population> and add <unrest><unrest>. Illustrate the saga of the parched fields on the primal cave wall, including the broken earth mark and the <sun> mark.\\"","ru":"<p><i><b>Зима вступила в свои права, не дав посевам на ваших полях взойти. Похоже, эта затея была обречена на провал с самого начала. Вашему народу теперь нужно было срочно найти припасы на зиму, чтобы выжить.</b></i></p><p>Завершите текущее испытание.</p><p>Затем уберите <population><population><population> и добавьте <unrest><unrest>. На стене первобытной пещеры изобразите историю о пересохших полях, включив в неё отметку расколотой земли и отметку <sun>.</p>"},"repeatable":false,"marks":[{"label":"","image":"<brokenearth>"}]},{"id":"outcomes-824","code":"824","description":{"en":"<p>Your people have created a vital foothold in the valley. In generations to come, it will give your descendents a chance to flourish.</p>\\n\\"At the end of any day, you may end this challenge. Add Buried Coals May Yet Burn (CZ05) to looming challenges (even if previously completed)\\n\\nWhen you end this challenge this way, add <population><population><population><population>. Add A Peaceful Season (CZ01) to your looming challenges and A Trail of Mysteries (GA11) to your goals.\\"","ru":"<p><i><b>Ваш народ создал жизненно важную опорную точку в долине. Через много лет она может дать вашим потомкам шанс на процветание.</b></i></p><p>В конце любого дня можете завершить текущее испытание.</p><p>Затем добавьте <population><population><population><population>. Добавьте карты «Период затишья» (ИЯ01) и «Тлеющие угли» (ИЯ05) к грядущим испытаниям (даже если вы завершали ранее испытание «Тлеющие угли»). Добавьте к целям карту «Пройдите по следам тайн» (ЦA11).</p>"},"repeatable":false},{"id":"outcomes-830","code":"830","description":{"en":"<p>The two behemoths regard each other with animosity, and the valley becomes their battleground.</p>\\n<p>Randomly select two behemoths with active lairs in the valley. Each one becomes alert. Add Colossal Brawl (GZ16) and Tip the Scales (GZ17) to your goals.</p>","ru":"<p><i><b>Два чудища, исполненные ненависти, сверлили друг друга взглядами, готовясь превратить долину в поле для сражения. </b></i></p><p>Выберите 2 случайных чудищ с активными логовами в долине. Оба становятся бодрствующими. Добавьте к целям карты «Узрите великую битву» (ЦЯ16) и «Склоните чашу весов» (ЦЯ17).</p>"},"repeatable":false},{"id":"outcomes-831","code":"831","description":{"en":"<p>\\"Under the wanderer's glow, the behemoth sits torpid. You approach without difficulty.\\"</p>\\nGain <minor_boost> to <conviction>. Continue the encounter.","ru":"<p><i><b>Под светом Скитальца чудище впало в оцепенение. Вы легко смогли подойти к нему.</b></i></p><p>Получите <minor_boost> к <conviction>. Продолжите встречу.</p>"},"repeatable":false},{"id":"outcomes-832","code":"832","description":{"en":"<p>High above in the sky, the moon keeps its secrets. Rumors swirl that the moonblood you have unearthed in your search may carry some curse beyond mortal ken.</p>\\n\\"End this challenge. \\n\\nAdd <unrest><unrest><unrest><unrest>. Illustrate the saga of the moon's veil on the primal cave wall, including the <moon> mark and the mystery mark.\\"","ru":"<p><i><b>Далёкая луна хранила свои секреты. Ходили слухи, что обнаруженная вами лунная кровь несла в себе проклятие, неподвластное разумению смертных.</b></i></p><p>Завершите текущее испытание.</p><p>Добавьте <unrest><unrest><unrest><unrest>. На стене первобытной пещеры изобразите историю о лунной завесе, включив в неё отметку <moon> и отметку тайны.</p>"},"repeatable":false,"marks":[{"label":"","image":"<mystery>"}]},{"id":"outcomes-833","code":"833","description":{"en":"<p>In the long days between epochs, the ancient quarrels spill over into brutal conflict.</p>\\n\\"Subtract <population><population>. Then, as a group, the players must choose one of the following paths for your society:\\n\\n<b>A) Drive off those who refuse to let old matters rest:</b> Subtract <population>. Illustrate the saga of the red days on the primal cave wall, including the battle mark (i) and the schism mark (iii).\\n\\n<b>B) Bring grievances to the surface in hopes of reconciliation:</b> Add <unrest><unrest><unrest>. Illustrate the saga of the hard truths on the primal cave wall, including the mediator mark (ii).\\"","ru":"<p><i><b>Время шло, и древние распри переросли в жестокий конфликт.</b></i></p><p>Уберите <population><population>. Затем совместно выберите один из следующих путей развития общины:<br><b>А. Изгоните тех, кто отказывается забыть прошлые обиды. </b>Уберите <population>. На стене первобытной пещеры изобразите историю о кровавых днях, включив в неё отметку битвы [i] и отметку раскола [iii].<br><b>Б. Попытайтесь примирить конфликтующие стороны. </b>Добавьте <unrest><unrest><unrest>. На стене первобытной пещеры изобразите историю о непростых истинах, включив в неё отметку посредника [ii].</p>"},"repeatable":false,"marks":[{"label":"i","image":"<battle>"},{"label":"ii","image":"<mediator>"},{"label":"iii","image":"<schism>"}]},{"id":"outcomes-838","code":"838","description":{"en":"<p>Whispers around your outposts say that the prophet has foreseen a catastrophe without equal: a beast of rot that chews at the roots of the Tangle, turning it to sand. The great floral jungle sustains your people, and its destruction would mean the end of your way of life. The prophet claims that the Tangle must be given its due, refreshed with sacrifice as it gives to your people.</p>\\n<p>Add Scout the Underground (GN06) and Root of the Problem (GN07) to your goals.</p>","ru":"<p><i><b>По поселениям поползли слухи: пророк предсказал ужасную катастрофу — нашествие чудовищной гнили, прогрызающей корни Сплетения и превращающей их в песок. Великие заросли поддерживали ваш народ, поэтому их гибель должна была стать концом привычного уклада жизни. Пророк утверждал, что Сплетение должно получить причитающуюся ему жертву, чтобы, как и прежде, давать ресурсы вашему народу.</b></i></p><p>Если на стене первобытной пещеры есть отметка Сплетения [ii], заключённая в отметку погибели [i], добавьте 4 <lore>. В противном случае добавьте карты «Соберите образцы листвы» (ЦЖ04) и «Изучите природу заражения» (ЦЖ05) к целям.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<doom>"},{"label":"ii","image":"<tangle>"}]},{"id":"outcomes-839","code":"839","description":{"en":"<p>Revenge is a bitter poison, and yet your people have grown all too accustomed to its taste. In the shadows of your outposts, belligerent groups often pursue vendettas against one another.</p>\\nAdd Cycle of Violence (JE06) to the Journey deck, if able. Otherwise, subtract <population>.","ru":"<p><i><b>Отмщение — это яд с горьким привкусом, однако ваши люди слишком хорошо изучили его вкус. В тени поселений враждебные группы неустанно сводили друг с другом счёты.</b></i></p><p>Добавьте карту «Беспрестанное насилие» (ПР06) в колоду пути, если возможно. В противном случае уберите <population>.</p>"},"repeatable":false},{"id":"outcomes-841","code":"841","description":{"en":"<p>From atop a jagged tooth of a mountain, you look down upon a land of fire and ash. Smoke uncoils from a great shuddering mountain, an inky serpent that swallows the sky. What could thrive in a land of such desolation?</p>\\n\\"Resolve the first you are able:\\n\\n<b>A) Venture into a familiar land of flame and shadowglass:</b> If the Volcanic Wastes mark (ii) is on the primal cave wall, place your character in any Volcanic Wastes hex, then add <lore><lore><lore>. \\n\\n<b>B) Explore this land of fire:</b> If you have 1 or more available terrain trays, illustrate the saga of the flame-touched lands on the primal cave wall, including the following marks: discovery (i), <sun>, Volcanic Wastes (ii). Add An Ominous Start (GY03) to your goals. Then expand your valley by following the steps below:\\n\\n<b>Step 1:</b> Add a new tray to your valley. Place it adjacent to your hex, if able. The tray must be placed such that its edges are adjacent to as many edges of placed trays as posslble. If multiple valid positions exist, select one at random.\\n\\n<b>Step 2:</b> Place all Volcanic Wastes hexes into the draw bag (except for the starting hex). Shuffle the hexes in the draw bag. Then, one at a time, draw three of those hexes. and place them unexplored in the slots of the tray you just placed, filling empty slots from north to south and east to west.\\n\\n<b>Step 3:</b> If there are 1 or more unplaced geothermal vents overlays, select a Volcanic Wastes hex at random and place an active geothermal vents overlay in that hex. Roll <1d6> and place it in the corresponding zone: (1–2): A, (3–4), B, (5–6) C.\\n\\n<b>Step 4:</b> If the mark of <BH4> (iii) is on the primal cave wall, move its lair to a randomly selected hex in the Volcanic Wastes without an overlay. Otherwise, it arrives in the valley; place its lair in a randomly selected hex in the Volcanic Wastes without an overlay. \\n\\n<b>C) A lava flow has temporarily covered another region in ash:</b> If you have no available terrain trays, randomly select a hex from the Volcanic Wastes region and place it adjacent to your current hex, not in a terrain tray. Place your character in that hex. Until the end of the challenge, treat that hex as the Volcanic Wastes region (see Meals & Myths Rulebook p.8). At the end of the challenge, return that hex to the game box; any tokens or overlays on that hex at that time are returned to the game box, and any characters in that hex perish.\\n\\nAt the end of any day, you may end this challenge.\\"","ru":"<p><i><b>С вершины зубчатого склона вы смотрели вниз на землю огня и пепла. Из глубин дрожащей горы поднимался дым — словно чёрный змей, пожирающий небо. Что же могло выжить в этой пустоши?</b></i></p><p>Разыграйте первое, что можете:<br><b>А. Отправьтесь в знакомую землю огня и пепла. </b>Если на стене первобытной пещеры есть отметка Вулканических пустошей [ii], переместите своего персонажа на любой участок Вулканических пустошей, затем добавьте <lore><lore><lore>.<br><b>Б. Исследуйте огненную землю.</b> Если у вас есть хотя бы одна неразмещённая основа местности, на стене первобытной пещеры изобразите историю о затронутых пламенем землях, включив в неё отметку открытия [i], отметку <sun> и отметку Вулканических пустошей [ii]. Добавьте карту «Изучите зловещее предзнаменование» (ЦЕ03) к целям. Затем расширьте долину, пройдя описанные ниже этапы.<br><b>Этап 1. </b>Добавьте новую основу местности в долину. Поместите её по соседству с участком местности со своим персонажем, если возможно. Границы основы должны соседствовать с как можно большим количеством границ уже размещённых основ. Если есть несколько возможных позиций, выберите одну случайным образом.<br><b>Этап 2. </b>Положите все неразмещённые участки Вулканических пустошей, кроме начального, в мешочек и перемешайте. Затем по одному вытащите 3 участка и поместите их неисследованной стороной вверх в ячейки новой основы по направлению с севера на юг и с востока на запад.<br><b>Этап 3.</b> Если есть хотя бы 1 неиспользованная накладка геотермальных источников, выберите случайный участок Вулканических пустошей и поместите туда накладку геотермальных источников активной стороной вверх. Бросьте <1d6>, чтобы поместить накладку в соответствующий район: [1-2] А, [3-4] Б, [5-6] В.<br><b>Этап 4.</b> Если на стене первобытной пещеры есть отметка ЧД4 [iii], переместите логово этого чудища на случайный участок Вулканических пустошей без накладки. В противном случае это чудище появляется в долине: поместите его логово на случайный участок Вулканических пустошей без накладки.<br><b>Этап 5.</b> Добавьте карты ПВ01–ПВ03 в колоду пути, если возможно.<br><b>В. Проследите за тем, как поток лавы покрывает пеплом другой регион.</b> Если у вас нет неразмещённых основ местности, поместите случайный участок Вулканических пустошей рядом со своим участком (не в ячейку основы местности), а затем поместите своего персонажа на него. До конца текущего испытания считайте, что этот участок относится к региону Вулканических пустошей (см. правила дополнения «Пища и притчи», с. 8). Завершив испытание, верните в коробку этот участок местности вместе с жетонами и накладками на нём. Персонажи, которые находились на убранном участке, умирают.</p><p>В конце любого дня можете завершить текущее испытание.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<discovery>"},{"label":"ii","image":"<volcanic_wastes>"},{"label":"iii","image":"<bh4>"}]},{"id":"outcomes-843","code":"843","description":{"en":"<p>You approach the eerie, blazing tree to discover...</p>\\n\\"Embark on the venture below (see Ventures on Rulebook p.60).\\n\\n<bi>A wall of smoke rises around the tree, obscuring your senses as you approach.</bi>\\n<b>Champion:</b> Someone must test <awareness> to find the way forward. Add +2 for each <i>exploration</i> item you have and +2 if you are <i>attuned</i>.\\n10+: You find your way through the billowing shadows. The venture continues.\\n1–9: You become lost and stumble out, choking. Suffer <major_disease>. The venture fails unless a character spends <energy><energy> or <lore> to attempt this test again.\\n\\n<bi>Out of the smoke, the tree suddenly rises, its fiery foliage lighting up the sky above you. Blazing leaves drop around you, and you must dodge through them to avoid being burned.</bi>\\n<b>Group:</b> Everyone must test <dexterity> to approach the tree. Add +2 if you are <i>lucky</i> and +4 if one or more Secrets have been recorded in the Journal for this behemoth.\\n11+: You dance through the blistering leaves to safety at the base of the tree. The venture continues.\\n1–10: Suffer <major_injury><minor_injury> unless you leave the venture. If all characters on the venture resolve this result, the venture fails.\\n\\n<bi>Within a high hollow on the tree, something glistens in the flickering light of the falling leaves. It must be important to the behemoth somehow...</bi>\\n<b>Champion:</b> Someone must test <conviction> to reach inside. Add +2 if you have an item with a <fire> token on it, +2 if you have <stoneworking>, and +2 if you are <i>resourceful</i>.\\n12+: You reach inside and pull out a marvel you never expected: a bead of pulsing amber that burns hot to the touch. You quickly wrap it and tuck it into your bag. Complete this venture and the associated goal.\\n1–11: Your nerve breaks, and you step back. Degrade all of your boosts twice. The venture fails unless a character spends <energy><energy> or <lore> to attempt this test again.\\"","ru":"<p><i><b>Вы приблизились к зловещему пылающему дереву.</b></i></p><p>Отправьтесь в поход (см. раздел «Походы» в правилах игры на с. 60).</p><p><i><b>Вокруг дерева поднялась стена дыма. Чем ближе вы подходили, тем сильнее она затмевала ваши чувства.</b></i></p><p><b>Защитник. </b>Один из персонажей в походе должен провести проверку <awareness>, чтобы проложить путь вперёд. +2 за каждый предмет для <i>исследования </i>у этого персонажа и +2, если он <i>сосредоточенный</i>.<br><b>≥10:</b>  Вы нашли путь сквозь клубящиеся тени. Продолжите поход.<br><b>1-9:</b>  Вы сбились с пути и, едва не задохнувшись, выбрались наружу. Получите <major_disease>. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy> или <lore>, чтобы провести проверку ещё раз.</p><p><i><b>Из завесы дыма внезапно поднялось дерево, и его пылающая листва озарила небо над вами. Вокруг посыпались горящие листья, и вам пришлось уклоняться от них, чтобы не обжечься.</b></i></p><p><b>Группа.</b> Все персонажи в походе должны провести проверку <dexterity>, чтобы подойти к дереву. +2, если персонаж <i>удачливый</i>, и +4, если в журнале записан хотя бы 1 секрет этого чудища.<br><b>≥11:</b>  Вы прорвались сквозь обжигающие листья и добрались до подножия дерева. Продолжите поход.<br><b>1-10:</b>  Вы сильно обожглись. Покиньте поход или получите <major_injury> и <minor_injury>. Если все персонажи получили этот результат, поход окончился неудачно.</p><p><i><b>В дупле высоко на дереве что‑то поблёскивало в отсветах падающих листьев. Видимо, это было что‑то важное для чудища… </b></i></p><p><b>Защитник. </b>Один из персонажей в походе должен провести проверку <conviction>, чтобы дотянуться. +2, если у этого персонажа есть предмет с <fire>, +2, если у персонажа есть <stoneworking>, и +2, если он <i>изобретательный</i>.<br><b>≥12:</b>  Вы сунули руку в дупло и извлекли невообразимое сокровище — янтарную бусину, пульсирующую жаром. Вы быстро завернули её и спрятали в сумку. Завершите этот поход и достигните соответствующей цели.<br><b>1-11:</b>  Вас охватил страх, и вы отступили. Уменьшите все свои усиления дважды. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy> или <lore>, чтобы провести проверку ещё раз.</p>"},"repeatable":false},{"id":"outcomes-845","code":"845","description":{"en":"<p>Your words fall like rain upon searing embers, cooling the tempers that have ignited. You have a chance to get people to move past the old disputes if you choose to ask the hard questions and face the difficult truths now.</p>\\n\\"Choose one of the following and resolve it:\\n\\n<b>A) Smooth over the clash with gentle words:</b> Subtract <unrest><unrest><unrest>.\\n\\n<b>B) Ask others to face their own part in the conflict:</b> Add <unrest>. Return Open Hostilities (NN02) to the game box.\\"","ru":"<p><i><b>Подобно дождю, падающему на раскалённые угли, ваши слова готовы были погасить разгоревшиеся страсти.</b></i></p><p>Выберите и разыграйте одно:<br><b>А. Уладьте разногласие уважительной речью. </b>Уберите <unrest><unrest><unrest>.<br><b>Б. Попросите других взглянуть на свою роль в этом конфликте. </b>Добавьте <unrest>. Верните в коробку карту «Открытая враждебность» (НО02).</p>"},"repeatable":false},{"id":"outcomes-846","code":"846","description":{"en":"<p>You find tracks from some massive creatures that migrated across this region, seemingly in a vast swarm.</p>\\n<p>Place 1 mystery token in each unexplored hex in the tray.</p>","ru":"<p><i><b>Вы нашли следы гигантских существ, которые, вероятно, огромным стадом проходили через этот регион.</b></i></p><p>Поместите по 1 жетону тайны на каждый неисследованный участок в основе местности.</p>"},"repeatable":false},{"id":"outcomes-848","code":"848","description":{"en":"<p>As it ambles from the rocks and shakes itself, the shelled predator eyes you with wary curiosity.</p>\\n<p>Add A Friend with Big Teeth (GN16) to your goals.</p>","ru":"<p><i><b>Выбравшись из завалов и отряхнувшись, хищник в панцире посмотрел на вас с настороженным любопытством.</b></i></p><p>Добавьте карту «Подружитесь с зубастиком» (ЦЖ16) к целям.</p>"},"repeatable":false},{"id":"outcomes-849","code":"849","description":{"en":"<p>Various competing interpretations of recent events create division among your people. The fireside chatter grows tense...</p>\\nAdd Fireside Grumbles (NN01) to the Night deck, if able. Otherwise, add <unrest>.","ru":"<p><i><b>Разные, порой противоречивые трактовки недавних событий вызвали разногласия среди вашего народа. Разговоры у костра становились всё напряжённее…</b></i></p><p>Добавьте карту «Ворчание у костра» (НО01) в колоду ночи, если возможно. В противном случае добавьте <unrest>.</p>"},"repeatable":false},{"id":"outcomes-852","code":"852","description":{"en":"<p>\\"Again, the comet's champion draws near a place of habitation, and again you rush to stop them. This time, however, a recognition flashes in their eyes, and their stride quickens toward you. Dormant coral coalesces around their body, creating a shell you will struggle to crack.\\"</p>\\n\\"Resolve a contest of your <might> versus the coral champion's <conviction> to fight. Add +2 to your result if you have a <i>moonblood</i> item. Add +3 to the coral champion's result for each adjacent hex with an active coral overgrowth.\\n<b>Success:</b> You drive the coral champion back with your ferocity, cracking their shell. As you bring down the final blow, the armor disintegrates, leaving behind only a cloud of scintillating spores. The coral champion has evaded you somehow. Add <major_boost> to <conviction>\\n<b>Failure:</b> Your blows rain down, but fail to crack the shell. Then the coral champion strikes back, and you feel bones splinter under the weight of the blow. Suffer <major_injury><minor_injury>.\\"","ru":"<p><i><b>Защитник кометы снова приближался к поселению, и вы снова бросились ему наперерез. Однако на этот раз, похоже, он узнал вас и не стал мешкать, быстро направившись вам навстречу. Вокруг его тела сомкнулась коралловая броня, которую будет непросто пробить.</b></i></p><p>Проведите состязание, чтобы сразиться: ваша <might> против <conviction> кораллового защитника. +2 к вашему результату, если у вас есть предмет <i>лунной крови</i>. +3 к результату кораллового защитника за каждый соседний участок местности с активными коралловыми зарослями. <br><b>Успех. </b>Вы яростно оттеснили кораллового защитника, пробив его броню. Когда вы нанесли последний удар, доспехи рассыпались, оставив после себя лишь облако мерцающих спор. Но каким-то образом противнику удалось ускользнуть. Добавьте <major_boost> к <conviction>.<br><b>Провал.</b> Вы обрушили на кораллового защитника град ударов, но так и не смогли пробить его броню. Он ударил вас в ответ, и вы почувствовали, как у вас хрустнули кости. Получите <major_injury> и <minor_injury>.</p>"},"repeatable":false},{"id":"outcomes-857","code":"857","description":{"en":"<p>The unusual coral activity passes as the wanderer vanishes from the sky for some months; whatever the connection might be, it eludes your people for now.</p>\\nAdd <lore><lore>.","ru":"<p><i><b>Необычная коралловая активность сошла на нет, когда Скиталец исчез с небосвода на несколько месяцев. Какова бы ни была связь между ними, ваши люди не могли её осознать.</b></i></p><p>Завершите текущее испытание. </p><p>Добавьте <lore><lore>.</p>"},"repeatable":false},{"id":"outcomes-870","code":"870","description":{"en":"<p>\\"Your search for the omens seems futile amidst the blistering ash and choking clouds. What fragmentary message can you construe from this incomplete message? You cannot help but feel unprepared for some coming crisis. What's more, a behemoth has become increasingly active as the smoke grows thicker...\\"</p>\\n\\"Add Eruption (CY04) to your looming challenges. Illustrate the saga of blistered hopes on the primal cave wall, including the BH4's mark (i) and blaze mark (ii). Then, resolve the first you are able:\\n\\n<b>A) The ashen behemoth makes its way to the volcanic wastes:</b> If BH4's mark (i) was already on the primal cave wall, move its lair to a randomly selected hex in the Volcanic Wastes. Roll <1d6> and place it in the corresponding zone: (1–2): A, (3–4), B, (5–6) C. \\n\\n<b>B) The ashen behemoth arrives in the valley:</b> Set up BH4 as described in Behemoth Arrival on Rulebook p.74. Place its lair in a randomly selected hex in the Volcanic Wastes. Roll <1d6> and place it in the corresponding zone: (1–2): A, (3–4), B, (5–6) C.\\"","ru":"<p><i><b>Поиски знамений среди обжигающего пепла и удушающего дыма оказались тщетными. Вы чувствовали себя неподготовленными к грядущему. Тем временем чудище становилось всё активнее по мере того, как дым сгущался…</b></i></p><p>Завершите текущее испытание.</p><p>Добавьте карту «Извержение» (ИЕ04) к грядущим испытаниям. На стене первобытной пещеры изобразите историю об опалённых надеждах, включив в неё отметку ЧД4 [i] и отметку пламени [ii].</p><p>Затем разыграйте первое, что можете:<br><b>А. Пепельное чудище направилось к Вулканическим пустошам. </b>Если на стене первобытной пещеры есть отметка ЧД4 [i], переместите его логово на случайный участок Вулканических пустошей. Бросьте <1d6>, что бы поместить логово в соответствующий район: [1-2] А, [3-4] Б, [5-6] В.<br><b>Б. Пепельное чудище появилось в долине. </b>Подготовьте ЧД4, как описано в разделе «Появление чудища» в правилах игры на с. 74. Поместите его логово на случайный участок Вулканических пустошей. Бросьте <1d6>, чтобы поместить логово в соответствующий район: [1-2] А, [3-4] Б, [5-6] В.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<bh4>"},{"label":"ii","image":"<blaze>"}]},{"id":"outcomes-871","code":"871","description":{"en":"<p>In your dream, your vision ascends to the clouds. From the perspective of a star, you see a slumbering behemoth in its lair. The ages sweep past, covering the lair with the sediment of epochs.</p>\\n\\"Randomly select an unplaced behemoth's lair and place a it in a hex of your choice, choosing a hex without an overlay and with a feature that matches its behemoth's affinity, if able. Roll <1d6> and place it in the corresponding zone: (1–2): A, (3–4), B, (5–6) C. Illustrate the saga of the primordial cradle on the primal cave wall, including the mark of the behemoth whose lair you placed this way and the discovery mark.\\n\\nRules for behemoth lairs are found in the Overlay Reference section beginning on Codex p.210.\\n\\nThen return Fathomless Dreams (NZ02) to the game box.\\"","ru":"<p><i><b>Во сне ваш взор воспарил к небесам. Словно звезда, вы смотрели вниз и видели спящее чудище в его убежище. Тысячелетия проносились мимо, засыпая логово пылью веков.</b></i></p><p>Выберите случайное неразмещённое логово чудища и поместите его на любой участок местности, выбрав участок без накладки и с особенностью местности, соответствующей склонности этого чудища, если возможно. Бросьте <1d6>, чтобы поместить логово в соответствующий район: [1-2] А, [3-4] Б, [5-6] В. На стене первобытной пещеры изобразите историю о первозданной колыбели, включив в неё отметку чудища, чьё логово вы поместили, и отметку открытия. </p><p>Правила логов чудищ см. на с. 211–212. Затем верните в коробку карту «Безграничные сны» (НЯ02).</p>"},"repeatable":false,"marks":[{"label":"","image":"<discovery>"}]},{"id":"outcomes-875","code":"875","description":{"en":"<p>Suddenly, the behemoth shakes free of its trance-like wandering. Following some ineffable urge, it vaults across the landscape, and the earth breaks in its wake.</p>\\n<p>\\"Place an active shattered wake overlay in each hex with a trace marker. For each overlay you place this way, choose a zone without an overlay and with a water feature (lake, wetland, or river), if able. See Codex p.211 for the shattered wake rules.\\n\\nThen, remove all of this behemoth's trace markers from the valley. Assign the Return to Slumber (BT20) instinct to this behemoth (replacing its previous instinct).\\"</p>","ru":"<p><i><b>Внезапно чудище стряхнуло с себя глубокое оцепенение. Повинуясь неведомому зову, существо понеслось вперёд, раскалывая землю на своём пути.</b></i></p><p>Поместите накладку расколотого отпечатка активной стороной вверх на каждый участок местности с жетоном следов. Для каждой помещённой накладки выбирайте район без накладки и с озером, болотом или рекой, если возможно. Правила расколотого отпечатка см. на с. 211.</p><p>Затем уберите жетон направления и все жетоны следов этого чудища. Замените его текущий инстинкт на «Вернуться в забытьё» (ЧК20).</p>"},"repeatable":false},{"id":"outcomes-878","code":"878","description":{"en":"<p>Without supplies and new hunting grounds, your people are caught in deadly straits between hunger and the coming frosts. You must hunt as the snows begin to fall, consigning some among your people to vanish into the frigid winter lands.</p>\\nSubtract <population><population><population>. Add <unrest><unrest>. Illustrate the saga of the bitter winter on the primal cave wall, including the ice mark (i) and the harrowing mark (ii). Add Buried Coals May Yet Burn (CZ05) to looming challenges (even if previously completed).","ru":"<p><i><b>Лишённый припасов и новых охотничьих угодий, ваш народ оказался в смертельной западне между голодом и надвигающимися холодами. Вам приходилось охотиться под падающим снегом, посылая некоторых людей своей общины на верную гибель в ледяных землях.</b></i></p><p>Завершите текущее испытание.</p><p>Уберите <population><population><population>. Добавьте <unrest><unrest>. На стене первобытной пещеры изобразите историю о лютой зиме, включив в неё отметку льда [i] и отметку ужаса [ii]. Добавьте карту «Тлеющие угли» (ИЯ05) к грядущим испытаниям (даже если вы завершали ранее это испытание).</p>"},"repeatable":false,"marks":[{"label":"i","image":"<ice>"},{"label":"ii","image":"<harrowing>"}]},{"id":"outcomes-881","code":"881","description":{"en":"<p>A vision of a vast, shimmering sea fills your mind. The silvery waters shineand swirl with starlight. Jagged teeth of icy crystal emerge from the sea.</p>\\nAdd <lore><lore>. Randomly select two hexes from the Starlit Sea region. You may look at their explored sides for up to 1 minute (without showing other players). Then return them to the game box and you may tell the other players about them for any amount of time. Illustrate the saga of the shimmering sea on the primal cave wall, including the moonblood mark (ii) and the mystery mark (i).","ru":"<p><i><b>В вашем разуме возникла картина необъятного мерцающего моря. Серебристые воды сверкали и закручивались в звёздном свете. Из моря поднимались зазубренные клыки ледяного кристалла.</b></i></p><p>Добавьте <lore><lore>. Возьмите 2 случайных участка Звёздного моря и посмотрите на их исследованные стороны в течение 1 минуты, не показывая другим игрокам. Затем верните их в коробку. Можете рассказать остальным игрокам о том, что увидели. На стене первобытной пещеры изобразите историю о мерцающем море, включив в неё отметку лунной крови [ii] и отметку тайны [i].</p>"},"repeatable":false,"marks":[{"label":"i","image":"<mystery>"},{"label":"ii","image":"<moonblood>"}]},{"id":"outcomes-882","code":"882","description":{"en":"<p>Time unwinds itself around the behemoth. Sinew and skin stretch around ancient bone, and the giant rises, made new by your offering. In wonder and dread, you stare up as the massive creature steps forth from its ancient lair...</p>\\n\\"Add <unrest><unrest><unrest>. Flip the inactive behemoth's lair to its active side. Illustrate the saga of the ancient returned on the primal cave wall, including the mark of this behemoth and the mark of broken earth. That behemoth arrives in the valley (see Behemoth Arrival on Rulebook p.74). Then, if there are two or more active behemoth lairs in the valley, add Clash of Titans (CZ08) to your looming challenges.\\"","ru":"<p><i><b>Словно само время обернулось вспять вокруг чудища. Жилы и кожа натянулись на древние кости, и исполин восстал, обновлённый вашей жертвой. С изумлением и страхом вы взирали, как гигантское существо вышло из своего логова…</b></i></p><p>Добавьте <unrest><unrest><unrest>. Переверните неактивное логово чудища. На стене первобытной пещеры изобразите историю о возвращении древнего существа, включив в неё отметку этого чудища и отметку расколотой земли. Это чудище появляется в долине (см. раздел «Появление чудища» в правилах игры на с. 74). Затем, если в долине есть хотя бы 2 активных логова, добавьте карту «Битва титанов» (ИЯ08) к грядущим испытаниям.</p>"},"repeatable":false,"marks":[{"label":"","image":"<brokenearth>"}]},{"id":"outcomes-883","code":"883","description":{"en":"<p>\\"The behemoth's fury is dire, battering down all obstacles that stand in the way of its wrath and mercilessly crushing anyone unfortunate enough to fall beneath its tread.\\"</p>\\n\\"For each hex with an outpost and a trace token, roll <1d6> and resolve the following, adding +1 if the behemoth's demeanor is 5 or lower:\\n1-4: The behemoth leaves only a shattered crater. The outpost becomes a ruin. Subtract <1d6><population>.\\n5: The behemoth crashes through the edge of the outpost. Randomly select 2 structures in the outpost. They are destroyed. Subtract <population><population>\\n6: The behemoth damages the outpost and frightens the inhabitants. Randomly select 1 structure in the outpost. It is destroyed. Add <unrest>.\\nThen remove all trace tokens and assign the behemoth the Obliteration (BT18) instinct.\\"","ru":"<p><i><b>Ярость чудища была страшна: оно сокрушало все преграды на своём пути и безжалостно давило каждого, кому не повезло оказаться у него под ногами.</b></i></p><p>За каждый участок местности с поселением, где есть жетон следов, бросьте <1d6>.+1, если значение нрава чудища не более 5. Разыграйте эффект по результату броска:<br><b>1-4:</b>  Чудище оставило после себя лишь разбитый кратер. Поселение становится руинами. Уберите <1d6><population>.<br><b>5:</b>  Чудище проломило заграждения на окраине поселения. Разрушьте 2 случайных сооружения в этом поселении. Уберите <population><population>.<br><b>6:</b>  Чудище снесло постройку и напугало жителей. Разрушьте 1 случайное сооружение в этом поселении. Добавьте <unrest>. </p><p>Затем уберите все жетоны следов этого чудища и назначьте ему инстинкт «Истребить» (ЧК18).</p>"},"repeatable":false},{"id":"outcomes-885","code":"885","description":{"en":"<p>\\"The behemoth shambles toward the seed, its tendrils intertwining with the seed's own green growths. The behemoth seems to be feeding the other organism, helping it to grow!\\"</p>\\n\\"Resolve the first you are able:\\n\\n<b>A) Let the seed flourish:</b> If the goal Nurture the Seedling is in play and is incomplete, complete it immediately.\\n\\n<b>B) Watch in frustration as the seed thaws:</b> If the goal Halt the Cycle is in play and is incomplete, remove all moonblood from it.\\n\\n<b>C) Take heart in the behemoth's boon:</b> Each character gains <minor_boost> to <awareness>.\\n\\nThen, remove this behemoth's aim and all of its trace tokens. Assign it the Return to Slumber (BT20) instinct (replacing its previous instinct).\\"","ru":"<p><i><b>Чудище подобралось к семени и переплело свои щупальца с зелёными побегами. Казалось, чудище кормило другой организм, помогая ему расти! </b></i></p><p>Разыграйте первое, что можете:<br><b>А. Позвольте семени расцвести.</b> Если цель «Взрастите саженец» в игре и ещё не достигнута, достигните её немедленно.<br><b>Б. Беспомощно наблюдайте, как семя оттаивает. </b>Если цель «Разомкните круг» в игре и ещё не достигнута, уберите с неё все жетоны лунной крови.<br><b>В. Воодушевитесь дарами чудища. </b>Каждый персонаж получает <minor_boost> к <awareness>.</p><p>Затем уберите жетон направления и все жетоны следов этого чудища. Замените его текущий инстинкт на «Вернуться в забытьё» (ЧК20)</p>"},"repeatable":false},{"id":"outcomes-886","code":"886","description":{"en":"<p>\\"You know the behemoth's fear of the coral can be used to drive it off. Wherever it is exposed to the fronds of the coral, and whenever these fronds bloom under the comet's light, the beast takes flight. Now, you use them to drive it away from an area.\\"</p>\\n<p>End the encounter. Aggravate the behemoth’s demeanor by 1. The behemoth flees.</p>","ru":"<p><i><b>Вы знали, что можете прогнать чудище, используя его страх перед кораллом. Чудище обращалось в бегство всякий раз, когда сталкивалось с коралловыми побегами или когда те расцветали под светом кометы.</b></i></p><p>Завершите встречу. Разозлите чудище на 1. Чудище сбегает.</p>"},"repeatable":false},{"id":"outcomes-887","code":"887","description":{"en":"<p>\\"You thrust your weapon into the pulsing heart of the coral behemoth. It shudders as death slowly reclaims the great beast. A great chiming peals out, and the coral across the valley turns ashen and dead.\\n\\nThe valley is still be scarred by the impact and your great clash with the beast. Still, in the years to come, your people thrive. Your children play in the shadow of the felled beast, and their children know no fear of the creature or the coral that once threatened to engulf the valley.\\"</p>\\n\\"Add <population><population><population> and subtract <unrest><unrest><unrest>. Flip all coral overgrowth overlays and the coral behemoth's lair to their inactive sides.\\n\\nIllustrate the saga of coral vengeance on the primal cave wall, including both that behemoth's mark and the battle mark and the conclusion mark enclosing the coral mark. Your society <b>persists.</b>\\n\\nCongratulations! You have completed <i>Stonesaga</i>'s campaign! To immortalize a photo of your primal cave wall and see other people's works of art, we invite you to share your saga with our community!\\n\\n@[Insert Link]@\\n\\nTo continue playing <i>Stonesaga</i>, see Playing Endless Mode After a Campaign on Rulebook p.97, or Beginning Subsequent Campaigns on Rulebook p.97.\\"","ru":"<p><i><b>Вы вонзили оружие в пульсирующее сердце кораллового чудища. Существо содрогалось, пока смерть не поглотила его. Раздался мощный перезвон, и коралл по всей долине поблёк и умер.</b></i></p><p>Добавьте <population><population><population> и уберите <unrest><unrest><unrest>. Переверните коралловые заросли и логово кораллового чудища неактивной стороной вверх.</p><p>На стене первобытной пещеры изобразите историю о коралловом возмездии, включив в неё отметку этого чудища, отметку битвы [i], а также отметку коралла [iii], заключённую в отметку окончания [ii]. Ваша община <b>выжила</b>.</p><p>Поздравляем! Вы завершили кампанию «Наскальной истории»! Чтобы увековечить фотографию своей стены первобытной пещеры и увидеть произведения искусства других игроков, мы приглашаем вас поделиться своей историей с нашим сообществом!</p><p>Чтобы продолжить играть в «Наскальную историю», см. в правилах игры раздел «Начало следующих кампаний» на с. 97 или раздел «Бесконечный режим» на с. 102.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<battle>"},{"label":"ii","image":"<conclusion>"},{"label":"iii","image":"<coral>"},{"label":"","image":"<qrcode>"}]},{"id":"outcomes-888","code":"888","description":{"en":"<p>You have quashed the rebellion, but not solved the underlying issue.</p>\\nSet <unrest> to 4. Subtract <population><population><population>. Illustrate the saga of the scattered ash on the primal cave wall, including the battle mark. Then add Fireside Grumbles (NN01) to the Night deck, if able.","ru":"<p><i><b>Вы подавили бунт, но так и не устранили его первопричину.</b></i></p><p>Завершите текущее испытание.</p><p>Установите значение <unrest> на 4. Уберите <population><population><population>. На стене первобытной пещеры изобразите историю о рассыпанном пепле, включив в неё отметку битвы. Затем добавьте карту «Ворчание у костра» (НО01) в колоду ночи, если возможно.</p>"},"repeatable":false,"marks":[{"label":"","image":"<battle>"}]},{"id":"outcomes-889","code":"889","description":{"en":"<p>Over the intervening years, your people have discovered paths deeper into the valley, and many strange wonders reveal themselves...</p>\\n\\"<i>Many strange happenings occur in the valley as you explore it more deeply.</i> Resolve as many of the following as you are able:\\n\\nA) Add JE01-04 and JU01-11 to the Journey deck.\\nB) If there is at least 1 Verdant Vale hex in the valley, add JV01-06 to the Journey deck.\\nC) If there is at least 1 Skyreach Plateau hex in the valley, add JS01-06 to the Journey deck.\\nD) If there is at least 1 Maelstrom Hills hex in the valley, add JM01-05 to the Journey deck.\\nE) If there is at least 1 Starlit Sea hex in the valley, add JQ01-03 to the Journey deck.\\n\\n<i>The longer you remain in the valley, the more you begin to see the wonders and horrors of its nights.</i> Resolve as many of the following as you are able:\\nA) Add NU01–16 to the Night deck.\\nB) If there is at least 1 Verdant Vale hex in the valley, add NV01–03 to the Night deck.\\nC) If there is at least 1 Skyreach Plateau hex in the valley, add NP01–03 to the Night deck.\\n\\n<i>Then, your people explore find the last great bastion of the mighty glaciers.</i> Follow the steps below: \\nStep 1: Add a new terrain tray to the valley. This terrain tray must be placed adjacent to the north-most hex and touch as many edges of the first terrain tray as possible. \\n[diagram]\\nStep 2: Put all unplaced hexes for your starting region into the draw bag.\\nStep 3: One at a time, draw 3 hexes from the draw bag. From north to south and east to west, fill the empty slots of the tray with 3 hexes you drew. Place these hexes with their unexplored side faceup.\\n[diagram]\\nStep 4: Place the glacier cap overlay (HX01a) on top of a hex in the newly placed tray. Place it over a northernmost hex. \\n[diagram]\\nStep 5: Roll 1d6 and place glaciers in the newly placed hexes as foillows:\\n1–2: 1 glacier in Zone \\\\\\"A\\\\\\" of either hex without an overlay.\\n[diagram]\\n3–4: 1 glacier in Zone \\\\\\"B\\\\\\" of either hex without an overlay.\\n[diagram]\\n5: Resolve both 1–2 and 3–4.\\n[diagram]\\n6: 1 glacier in Zone \\\\\\"B\\\\\\" and 1 glacier in zone \\\\\\"C\\\\\\" of either hex without the glacier cap.\\n\\nNature of the Beast Additions\\nIf you are playing with the Nature of the Beast expansion, resolve as many of the following as you are able:\\nA) Add JN01-07 to the Journey deck.\\nB) If there is at least 1 Tangle hex in the valley, add JT01-06 to the Journey deck. Otherwise, add Seek the Tangle (GN01) to your goals.\\nC) Add NX01-07 to the Night deck.\\nD) If there is at least 1 Tangle hex in the valley, add NT01–03 to the Night deck.\\nE) Add FF15 to the Forest Foraging deck.\\nF) Add FP15 to the Prairie Foraging deck.\\nG) Add DN01 to the Delving deck (even if you haven't yet unlocked it).\\nH) If there is at least 1 Tangle hex in the valley, add Beneath the Canopy (CN01) to your looming challenges.\\n\\nMeals & Myths Additions\\nIf you are playing with the Meals & Myths expansion, resolve as many of the following as you are able:\\nA) Add JY01-07 to the Journey deck.\\nB) If there is at least 1 Volcanic Wastes hex in the valley, add JW01-03 to the Journey deck.\\nC) Add NM01-10 to the Night deck.\\nD) Add Feast for the Ages (CY01) to your looming challenges.\\"","ru":"<p><i><b>С годами ваши люди обнаружили пути, ведущие вглубь долины, и невероятные чудеса открылись перед ними...</b></i></p><p>Разыграйте как можно больше из следующего:<br><b>А.</b> Добавьте карты ПР01–ПР04 и ПН01–ПН11 в колоду пути.<br><b>Б.</b> Если в долине есть хотя бы 1 участок Дивной долины, добавьте карты ПД01–ПД06 в колоду пути.<br><b>В.</b> Если в долине есть хотя бы 1 участок Поднебесной равнины, добавьте карты ПП01–ПП06 в колоду пути.<br><b>Г.</b> Если в долине есть хотя бы 1 участок Ураганных холмов, добавьте карты ПУ01–ПУ05 в колоду пути. <br><b>Д.</b> Если в долине есть хотя бы 1 участок Звёздного моря, добавьте карты ПЗ01–ПЗ03 в колоду пути.<br><b>Е.</b> Получите силы мантий МА01–МА04, если ещё этого не сделали (см. раздел «Силы мантий» на с. 65 правил). </p><p><i><b>Чем дольше вы находились в долине, тем больше чудес и ужасов её ночей вы начинали видеть. </b></i></p><p>Разыграйте как можно больше из следующего:<br><b>А.</b> Добавьте карты НН01–НН16 в колоду ночи.<br><b>Б.</b> Если в долине есть хотя бы 1 участок Дивной долины, добавьте карты НД01–НД03 в колоду ночи.<br><b>В. </b>Если в долине есть хотя бы 1 участок Поднебесной равнины, добавьте карты НП01–НП03 в колоду ночи. </p><p><i><b>Затем ваши люди нашли последний оплот могущественных ледников.</b></i></p><p>Пройдите описанные ниже этапы.<br><b>Этап 1. </b>Добавьте новую основу местности в долину. Эта основа должна быть помещена по соседству с самым северным участком местности и касаться как можно большего числа границ первой основы. <br><b>Этап 2. </b>Положите все неразмещённые участки местности начального региона в мешочек. По одному вытащите 3 участка и поместите их неисследованной стороной вверх в ячейки новой основы по направлению с севера на юг и с востока на запад.<br><b>Этап 3.</b> Поместите накладку ледникового купола (ОБ01a) на самый северный участок в только что помещённой основе местности.<br><b>Этап 4.</b> Бросьте <1d6> и поместите ледники на только что помещённых участках местности по результату броска: [1-2] один ледник в район А любого из участков местности без накладки, [3-4] один ледник в район Б любого из участков местности без накладки, [5] разыграйте результаты 1-2 и 3-4, [6] один ледник в район Б и один ледник в район В любого из участков местности без ледникового купола.</p><p><i><b>Дополнение «Природа зверя»</b></i></p><p>Если вы используете дополнение «Природа зверя», разыграйте как можно больше из следующего:<br><b>А. </b>Добавьте карты ПЖ01–ПЖ04 в колоду пути.<br><b>Б.</b> Если в долине есть хотя бы 1 участок Сплетения, добавьте карты ПС01–ПС06 в колоду пути. В противном случае добавьте карту «Найдите Сплетение» (ЦЖ01) к целям.<br><b>В.</b> Добавьте карты НЖ01–НЖ07 в колоду ночи.<br><b>Г. </b>Если в долине есть хотя бы 1 участок Сплетения, добавьте карты НС01–НС03 в колоду ночи.<br><b>Д.</b> Добавьте карту ДЛ15 в колоду добычи припасов в лесу.<br><b>Е.</b> Добавьте карту ДС15 в колоду добычи припасов в степи.<br><b>Ж. </b>Добавьте карту ГЖ01 в колоду спуска (даже если действие спуска ещё не доступно).<br><b>З.</b> Добавьте карту РД11 в колоду рыбалки.<br><b>И.</b> Если в долине есть хотя бы 1 участок Сплетения, добавьте карту «Под навесом» (ИЖ01) к грядущим испытаниям. </p><p><i><b>Дополнение «Пища и притчи»</b></i></p><p>Если вы используете дополнение «Пища и притчи», разыграйте как можно больше из следующего:<br><b>А. </b>Добавьте карты ПЕ01–ПЕ07 в колоду пути.<br><b>Б.</b> Если в долине есть хотя бы 1 участок Вулканических пустошей, добавьте карты ПВ01–ПВ03 в колоду пути.<br><b>В.</b> Добавьте карты НЕ01–НЕ10 в колоду ночи.<br><b>Г.</b> Добавьте карту «Пир на весь мир» (ИЕ01) к грядущим испытаниям.</p>"},"repeatable":false},{"id":"outcomes-890","code":"890","description":{"en":"<p>\\"Through your thorough searches, you find that the would-be prophet's message is twisted, but contains a seed of the truth. A great danger does loom before the valley, and you must rise to face it. Not with the wild, conspiratorial whispers you have faced, but with the clear-eyed certainty of hard-won knowledge.\\"</p>\\n\\"At the end of any day, you may end this challenge. Then, resolve the first you are able: \\n\\n<b>A) The leader mutters about a great cosmic unity coming to the valley:</b> If the coral mark (i) is enclosed in the doom mark (ii) on the primal cave wall, add A Time to Prepare (CC03) to your looming challenges and Seek the Comet's Sign (GC03) to your goals.\\n\\n<b>B) The message speaks of a rot beneath your very feet:</b> If the broken earth mark (iii) is enclosed in the doom mark (ii) on the primal cave wall, add The Deep Rot (CN03) to your looming challenges.\\n\\n<b>C) The devout claim the world will end soon, choked in deathly white ash:</b> If the blaze mark (iv) is enclosed in the doom mark (ii) on the primal cave wall, add Searing Ash, Glinting Secrets (CY03) to your looming challenges.\\"","ru":"<p><i><b>Ваши усердные поиски раскрыли удивительную правду: послание предполагаемого пророка было искажено, но в нём содержалось зерно истины. Над долиной и правда нависало древнее зло, и вам предстояло встретиться с ним. Не с помощью пустых домыслов и тайных заговоров, что будоражили умы прежде, а с твёрдой уверенностью человека, прошедшего тяжкие испытания и познавшего истину.</b></i></p><p>В конце любого дня можете завершить текущее испытание. Затем разыграйте первое, что можете:<br><b>А. Послание говорило о гниении под самими вашими ногами.</b> Если на стене первобытной пещеры есть отметка расколотой земли [iii], заключённая в отметку погибели [ii], добавьте карту «Подземная зараза» (ИЖ03) к грядущим испытаниям.<br><b>Б. Сторонники пророка утверждали, что мир скоро навеки задохнётся в мертвенно-белом пепле. </b>Если на стене первобытной пещеры есть отметка пламени [iv] заключённая в отметку погибели [ii], добавьте карту «Жгучий пепел, сверкающие тайны» (ИЕ03) к грядущим испытаниям.<br><b>В. Пророк бормотал о всеобъемлющем единстве, которое должно было прийти в долину. </b>Добавьте к грядущим испытаниям карту «Час приготовлений» (ИВ03).</p>"},"repeatable":false,"marks":[{"label":"i","image":"<coral>"},{"label":"ii","image":"<doom>"},{"label":"iii","image":"<brokenearth>"},{"label":"iv","image":"<blaze>"}]},{"id":"outcomes-891","code":"891","description":{"en":"<p>You successfully relocate your outpost to new grounds with rich game.</p>\\n<p>Until the end of the challenge, do not place depletion tokens when you perform a forage or fish action.</p>","ru":"<p><i><b>Вы успешно перенесли своё поселение в новые земли, богатые дичью.</b></i></p><p>До конца текущего испытания не помещайте жетоны истощения при выполнении действий добычи припасов или рыбалки.</p>"},"repeatable":false},{"id":"outcomes-893","code":"893","description":{"en":"<p>Your efforts to drive back the coral have shown some success, but the dust above cannot be driven back with axe or flame. Plants wither and die, and food grows scarce.</p>\\nSubtract <population><population>. Add Scorn of the Earth (CC06) to your looming challenges.","ru":"<p><i><b>Хотя вам удалось немного сдержать натиск коралловых зарослей, но поднявшуюся при этом пыльную завесу невозможно было разогнать ни оружием, ни огнём. Из‑за неё растения вяли и умирали, а еда становилась всё более скудной.</b></i></p><p>Уберите <population><population>. Добавьте к грядущим испытаниям карту «Презрение земли» (ИВ06).</p>"},"repeatable":false},{"id":"outcomes-895","code":"895","description":{"en":"<p>The behemoth moves slowly amidst the spores of coral that fill the air around you, allowing you to climb with ease. As you do, in a ridge on its back, you discover a strange object. You could use coral to irritate the area around it to get the item free, but it the behemoth might notice...</p>\\n\\"Choose one and resolve it:\\n\\n<b>A) Use coral to loosen the object:</b> Discard a living coral from your inventory or a <i>coral</i> item to end the encounter. Aggravate the behemoth's demeanor by 3. The behemoth flees. Then, if a character, animal companion, or storage structure has an item with Symbiotic in its name, gain 2 of the behemoth's curio; otherwise, gain the Symbiotic Egg (IT93) Item card.\\n\\n<b>B) Decide not to poke the behemoth:</b> Continue the encounter.\\"","ru":"<p><i><b>Через коралловые споры, наполнявшие воздух вокруг вас, чудище двигалось медленно, что позволяло вам с лёгкостью на него взбираться. В гребне на его спине вы обнаружили странный предмет. Вы могли бы достать его, использовав коралл, но чудище могло это заметить…</b></i></p><p>Выберите и разыграйте одно:<br><b>А. Используйте коралл, чтобы достать предмет. </b>Сбросьте живой коралл из своего инвентаря или предмет коралла, чтобы завершить встречу. Разозлите чудище на 3. Чудище сбегает. Затем, если у персонажа, животного-компаньона или в сооружении-<i>хранилище </i>есть предмет со словом «симбиотический» в названии, получите 2 сокровища чудища; в противном случае получите карту предмета «Симбиотическое яйцо» (ВЩ93).<br><b>Б. Не тревожьте чудище. </b>Продолжите встречу.</p>"},"repeatable":false},{"id":"outcomes-899","code":"899","description":{"en":"<p>\\"You tumble into the strange pool, and the substance clings to your flesh even as you begin to sink. A cold spreads throughout your body, like standing outside on a moonless winter's night. Tiny points of light fill your vision, blurring like stars. You tumble through the substance, for how long you cannot say. Then cold and darkness overtake you.\\"</p>\\n<p>Add the moonblood mark to the legend side of your Character card, then return your Character card to the game box. Create a new character as if your character had perished. Add Face in the Deep (JQ02) to the Journey deck.</p>","ru":"<p><i><b>Вы скатились в странный омут, и вещество прилипло к вашей коже, когда вы начали тонуть. Холод распространился по всему телу — такой, будто вы стояли на улице в безлунную зимнюю ночь. Перед глазами поплыли маленькие размытые огоньки, похожие на звёзды. Вас швыряло в этом веществе неизвестно как долго. Затем холод и тьма охватили вас.</b></i></p><p>Добавьте отметку лунной крови на сторону легенды карты своего персонажа, затем верните в коробку эту карту. Создайте нового персонажа, как если бы ваш предыдущий персонаж умер. Добавьте карту «Облик на глубине» (ПЗ02) в колоду пути.</p>"},"repeatable":false,"marks":[{"label":"","image":"<moonblood>"}]},{"id":"outcomes-903","code":"903","description":{"en":"<p>Discussions become arguments, and arguments become quarrels. As tensions rise, you fear it may drive some in your society to extreme acts.</p>\\nAdd Warning Sign (JE03) to the Journey deck, if able. Otherwise, add <unrest>.","ru":"<p><i><b>Разговоры переросли в ссоры, а те, в свою очередь, — в стычки. Чем больше нарастало напряжение, тем больше вы начинали бояться, что это может подтолкнуть некоторых людей вашей общины на крайние меры. </b></i></p><p>Добавьте карту «Знак опасности» (ПР03) в колоду пути, если возможно. В противном случае добавьте <unrest>.</p>"},"repeatable":false},{"id":"outcomes-907","code":"907","description":{"en":"<p>As waves lap at the shore of the quicksilver ocean, you see a face within the water. At first you think it is a reflection, but slowly it breaks the surface. It is a human form, still encrusted in solidified moonblood. You drag the body onto the shore, breaking away the strange stone from their body. As you do, the form stirs slightly, coughs, and looks up at you with eyes lost in the eons.</p>\\n\\"Choose a Character card in the game box with the moonblood mark (i) who is Young or Old (they can't be a Legend). Illustrate the saga of the frozen one on the primal cave wall, including the moonblood mark (i) and the mystery mark (ii). Return Face in the Deep (JQ02) to the game box. Then choose one for your character:\\n\\n<b>A) Beseech the ancient's wisdom:</b> Choose <conviction> or <awareness>. You may replace your attribute value with that of the character from the game box. If you do, add the growth mark (iii) to the legend side of your Character card.\\n\\n<b>B) Ask the ancient to take up your task:</b> Exchange the chosen Character card with your current Character card. Your previous character is an unused character for the remainder of this challenge. At the end of the challenge, return the chosen character with the moonbloon mark (i) to the game box.\\"","ru":"<p><i><b>Среди переливов ртутного моря вы заметили странное лицо на глубине. Сперва вы подумали, что это ваше отражение, но постепенно лик всплыл на поверхность. Это была человеческая фигура, покрытая затвердевшей лунной кровью. Вы вытащили тело на берег и освободили от оболочки. Фигура пошевелилась, закашлялась и смерила вас взглядом, в котором отражалась бесконечность ушедших эпох.</b></i></p><p>Возьмите из коробки карту молодого или пожилого персонажа (он не может быть легендой) с отметкой лунной крови [i]. На стене первобытной пещеры изобразите историю о замёрзшем, включив в неё отметку лунной крови [i] и отметку тайны [ii]. Верните в коробку карту «Облик на глубине» (ПЗ02). Затем выберите одно:<br><b>А. Взовите к мудрости древнего. </b>Выберите <conviction> или <awareness>. Можете заменить значение выбранной характеристики с карты своего персонажа на значение этой же характеристики с карты персонажа из коробки. Если сделали это, добавьте отметку становления [iii] на сторону легенды карты своего персонажа.<br><b>Б. Попросите древнего взять на себя вашу ношу.</b> Замените карту своего персонажа картой персонажа из коробки. Ваш предыдущий персонаж не будет использоваться до конца этого испытания. В конце испытания верните в коробку выбранную карту персонажа.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<moonblood>"},{"label":"ii","image":"<mystery>"},{"label":"iii","image":"<growth>"}]},{"id":"outcomes-908","code":"908","description":{"en":"<p>A land emerges from the low-hanging mists of the chasms...</p>\\n\\"Resolve the first you are able:\\n\\n<b>A) You gaze upon a familiar biome from a new perspective:</b> If the Verdant Vale mark (i) is on the primal cave wall or you have 0 unplaced terrain trays, add <lore><lore><lore>.\\n\\n<b>B) You arrive in a land of wonders:</b> If the Verdant Vale mark (i) is not on the primal cave wall and you have 1 or more unplaced terrain trays, you discover this region. Illustrate the saga of the lowlands green on the primal cave wall, including the Verdant Vale mark (i) and the discovery mark (ii). Then expand your valley by following the steps below:\\n\\n<b>Step 1:</b> Add a new tray to your valley. Place it adjacent to your hex, if able. The tray must be placed such that its edges are adjacent to as many edges of placed trays as posslble. If multiple valid positions exist, select one at random.\\n\\n<b>Step 2:</b> Place all Verdant Vale hexes into the draw bag (except for the starting hex). Shuffle the hexes in the draw bag. Then, one at a time, draw three of those hexes and place them unexplored in the slots of the tray you just placed, filling empty slots from north to south and east to west.\\n\\n<b>Step 3 (Epoch 1 and Endless Mode Only):</b> If it is Epoch 1 (or you are playing Endless Mode) and there are 1 or more unplaced glacier overlays, roll <1d6> and place glaciers as foillows:\\n1–2: 1 glacier in Zone \\\\\\"A\\\\\\" of one of the hexes without an overlay.\\n[diagram]\\n3–4: 1 glacier in Zone \\\\\\"B\\\\\\" of one of the hexes without an overlay.\\n[diagram]\\n5: Resolve both 1–2 and 3–4.\\n[diagram]\\n6: Roll <1d6> again and read the corresponding outcome instead.\\n1–2: <outcome> 846\\n3–5: <outcome> 134\\n6: <outcome> 446\\"","ru":"<p><i><b>Из‑за низко нависших над пропастями туманов показалась земля…</b></i></p><p>Разыграйте первое, что можете:<br><b>А. Посмотрите на окружающую вас знакомую местность с новой точки зрения.</b> Если на стене первобытной пещеры есть отметка Дивной долины [i] или у вас нет непомещённых основ местности, добавьте <lore><lore><lore>. <br><b>Б. Попадите на землю чудес. </b>Если на стене первобытной пещеры нет отметки Дивной долины [i] и у вас есть хотя бы 1 неразмещённая основа местности, откройте новый регион. На стене первобытной пещеры изобразите историю о зелёной низине, включив в неё отметку Дивной долины [i] и отметку открытия [ii]. Затем расширьте долину, пройдя описанные ниже этапы.<br><b>Этап 1. </b>Добавьте новую основу местности в долину. Поместите её по соседству с участком местности со своим персонажем, если возможно. Границы основы должны соседствовать с как можно большим количеством границ уже размещённых основ. Если есть несколько возможных позиций, выберите одну случайным образом.<br><b>Этап 2. </b>Положите все неразмещённые участки Дивной долины, кроме начального, в мешочек и перемешайте. Затем по одному вытащите 3 участка и поместите их неисследованной стороной вверх в ячейки новой основы по направлению с севера на юг и с востока на запад.<br><b>Этап 3 (только для эры 1 и бесконечного режима).</b> Если в запасе есть хотя бы 1 непомещённая накладка ледника, бросьте <1d6> и поместите ледники по результату броска: [1-2] один ледник в район А одного из участков местности без накладки, [3-4] один ледник в район Б одного из участков местности без накладки, [5] разыграйте результаты 1-2 и 3-4, [6] бросьте <1d6> ещё раз и прочитайте один из исходов ниже, соответствующий результату броска.<br>[1-2] <outcome> 846, [3-5] <outcome> 134, [6] <outcome> 446.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<verdantvale>"},{"label":"ii","image":"<discovery>"}]},{"id":"outcomes-913","code":"913","description":{"en":"<p>Pushing your way sluggishly through freezing liquid, the world seems to invert. Following bubbles to the surface, you gasp for air. You shake the chill from your bones as the liquid runs off you and struggle to your feet on a distant shore. A sea of glistening silver laps at your feet, cold stars glimmering above. Yet their pattern is familiar to you. Strangest still, a blue-green moon rises in the distance, filling the sky.</p>\\n\\"Resolve the first you are able:\\n\\n<b>A) You know this place, but it is still wondrous to experience with your own senses:</b> If the Starlit Sea mark (i) is on the primal cave wall, end this delve action. Gain all rewards you claimed. Place your character in any hex in the Starlit Sea region, choosing a hex with a cave, if able. Then add <lore><lore><lore>.\\n\\n<b>B) What a wondrous place to explore:</b> If you have 1 or more available terrain trays, end this delve action. Gain all rewards you claimed. Then illustrate the saga of the cold footfalls on the primal cave wall, including the discovery mark (ii), the Starlit Sea mark (i), and the underworld mark (iii). Finally set up the Starlit Sea as described on Codex p.216\\n\\n<b>C) You explore furtively, dread’s frosty breath upon your neck:</b> If you have no available terrain trays, randomly select a hex from the Starlit Sea region and place it adjacent to but not touching your valley. Place your character in that hex. Until the end of the challenge, treat that hex as part of the Starlit Sea region (see Codex p.216), and treat that hex as having a cave for the purposes of performing a delve action. At the end of the challenge, return that hex to the game box; any tokens or overlays on that hex at that time are returned to the game box, and each character in that hex perishes.\\"","ru":"<p><i><b>Пока вы медленно плыли в ледяной жидкости, вам казалось, что весь мир перевернулся. Проследовав за пузырьками до поверхности, вы с жадностью глотнули воздух. Сотрясаясь от холода, пока жидкость стекала с тела, вы с трудом поднялись на ноги, когда добрались до берега. Море сверкающего серебра омывало ваши ступни. Над головой мерцали холодные звёзды — их рисунок показался вам знакомым. И, что удивительнее всего, вдалеке восходила голубовато‑зелёная луна, заполняя собой небо.</b></i></p><p>Разыграйте первое, что можете:<br><b>А. Поймите, что вы знаете это место, пусть оно и показалось необычным, когда вы его увидели воочию. </b>Если на стене первобытной пещеры есть отметка Звёздного моря [i], завершите это действие спуска. Получите все награды, которые вы присвоили. Переместите своего персонажа на любой участок Звёздного моря, выбрав участок с пещерой, если возможно. Затем добавьте <lore><lore><lore>.<br><b>Б. Осознайте, что это отличное место для исследования.</b> Если у вас есть хотя бы 1 неразмещённая основа местности, завершите это действие спуска. Получите все награды, которые вы присвоили. На стене первобытной пещеры изобразите историю о холодных следах, включив в неё отметку открытия [iii], отметку Звёздного моря [i] и отметку подземного мира [ii]. Наконец, подготовьте Звёздное море, как описано на с. 216.<br><b>В. Затаившись, словно ощутили ледяное дыхание ужаса за спиной, исследуйте местность.</b> Если у вас нет неразмещённых основ местности, поместите случайный участок Звёздного моря рядом с долиной, но без соприкосновения с ней. Переместите своего персонажа на этот участок. До конца текущего испытания считайте, что этот участок местности относится к региону Звёздного моря (см. с. 216) и что на нём есть пещера для спуска. В конце испытания верните в коробку этот участок местности вместе с жетонами и накладками этого участка. Персонажи, которые находились на убранном участке, умирают.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<starlitsea>"},{"label":"ii","image":"<underworld>"},{"label":"iii","image":"<discovery>"}]},{"id":"outcomes-914","code":"914","description":{"en":"<p>\\"Your tunnels weave through the valley's underworld. Yet in darkness, you have opened the door the hunters in shadow. The massive arthropods that prowl the tenebrous depths burst up into one of your villages, shattering buildings and dragging unfortunate villagers below. When the nearby village's scouts arrive to investigate, only a vast crater remains.\\"</p>\\n\\"End this challenge.\\n\\nEach of your outposts with an entrance is swallowed by the earth. All outposts in these hexes become ruins. Subtract <population><population> per swallowed outpost. Then, as a group, the players must choose one of the following paths for your society:\\n\\n<b>Abandon those lost to the underworld:</b> Illustrate the saga of the swallowed realm, including the broken earth mark (i), the harrowing mark (ii), and the taboo mark (iii). Remove all ruin of outposts that were swallowed during this challenge from the valley. Add \\\\\\"Performing a delve action\\\\\\" to the Taboos section of the Culture page of the Journal. Gain the Taboos (KN18) Knowledge card. \\n\\n<b>Stubbornly fight to reclaim your cities:</b> If the both the beastslayer mark and the hunter mark are on the primal cave wall, add <unrest><unrest><unrest><unrest> and subtract <population><population>. Illustrate the saga of the dark-sought beasts on the primal cave wall, including the underworld mark (vi), the harrowing mark (ii), and the taboo mark (iii). Add \\\\\\"Performing a delve action without a <i>weapon</i> item\\\\\\" to the Taboos section of the Culture page of the Journal. Gain the Taboos (KN18) Knowledge card. \\n\\n<b>Mount a daring rescue effort beneath the earth:</b> If both the discovery mark and the mystery mark are on the primal cave wall, add <population><population><population>. Illustrate the saga of shrouded lorekeepers on the primal cave wall, including the underworld mark (vi), the mystery mark (viii), and the taboo mark (iii). Add \\\\\\"Performing a delve action without a Map item\\\\\\" to the Taboos section of the Culture page of the Journal. Gain the Taboos (KN18) Knowledge card. \\n\\nThen end the Epoch. See page Codex p.204 to begin Epoch 3.\\"","ru":"<p><i><b>Сеть ваших туннелей раскинулась под долиной. Путешествуя по ним, вы ненароком открыли дверь охотникам из теней. Жуткие членистоногие монстры, бродившие по мрачным глубинам, вырвались на поверхность в ваших поселениях, разрушая сооружения и утаскивая несчастных жителей под землю. Когда разведчики из ближайшего поселения прибыли, чтобы расследовать случившееся, они обнаружили лишь огромную воронку на месте поселения.</b></i></p><p>Завершите текущее испытание.</p><p>Каждое из ваших поселений со входом было поглощено землёй. Эти поселения становятся руинами. Уберите <population><population> за каждое поглощённое поселение. Затем совместно выберите один из следующих путей развития общины:<br><b>А. Оставьте позади тех, кто ушёл в подземелья.</b> На стене первобытной пещеры изобразите историю о поглощённом царстве, включив в неё отметку расколотой земли [i], отметку ужаса [ii] и отметку табу [iii]. Уберите из долины все руины поселений, которые были поглощены в конце этого испытания. Запишите «Выполнять действие спуска» в раздел «Табу» на странице «Культура» в журнале. Получите карту знаний «Табу» (ЗБ18), если у вас её нет.<br><b>Б. Верните себе потерянные города.</b> Если на стене первобытной пещеры есть отметки зверобоя [iv] и охотника [v], добавьте <unrest><unrest><unrest><unrest> и уберите <population><population>. На стене первобытной пещеры изобразите историю о чудищах из тьмы, включив в неё отметку подземного мира [vi], отметку ужаса [ii] и отметку табу [iii]. Запишите «Выполнять действие спуска без предмета оружия» в раздел «Табу» на странице «Культура» в журнале. Получите карту знаний «Табу» (ЗБ18), если у вас её нет.<br><b>В. Совершите дерзкую спасательную вылазку под землю. </b>Если на стене первобытной пещеры есть отметки открытия [vii] и тайны [viii], добавьте <population><population><population>. На стене первобытной пещеры изобразите историю о хранителях сокровенных знаний, включив в неё отметку подземного мира [vi], отметку тайны [viii] и отметку табу [iii]. Запишите «Выполнять действие спуска без „Карты“» в раздел «Табу» на странице «Культура» в журнале. Получите карту знаний «Табу» (ЗБ18), если у вас её нет.</p><p>Затем завершите текущую эру. См. с. 204, чтобы начать эру 3.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<brokenearth>"},{"label":"ii","image":"<harrowing>"},{"label":"iii","image":"<taboo>"},{"label":"iv","image":"<beastslayer>"},{"label":"v","image":"<hunter>"},{"label":"vi","image":"<underworld>"},{"label":"vi","image":"<discovery>"},{"label":"viii","image":"<mystery>"}]},{"id":"outcomes-915","code":"915","description":{"en":"<p>The harsh gale pulls you off-balance and you tumble into the shrouded world below. As you fall through the fog, you see a source of possible salvation: a single gossamer strand swinging free in the wind. You reach out to grab it, and it wraps around your hand. Then something begins to pull you skyward, out of the burning mists. When you finally make your way onto the back of the ridgecrawler, your savior is nowhere to be seen, but a coil of gossamer remains.</p>\\nGain 1 silk. Add <lore><lore>. Add Mistwalkers (GZ25) to your goals.","ru":"<p><i><b>Мощный порыв ветра сбил вас с ног, и вы рухнули в затянутый туманом мир внизу. Падая сквозь пелену, вы заметили возможное спасение — тончайшую нить, свободно качающуюся на ветру. Вы потянулись к ней — и она обвилась вокруг вашей руки. Затем нечто начало тянуть вас вверх, прочь из горящих туманов. Когда вы наконец оказались на спине шагающего хребта, вашего спасителя нигде не было видно, но виток нити остался.</b></i></p><p>Получите 1 шёлк. Добавьте <lore><lore>. Добавьте к целям карту «Пройдите сквозь туман» (ЦЯ25).</p>"},"repeatable":false},{"id":"outcomes-916","code":"916","description":{"en":"<p>You approach the towering mountains, having glimpsed the lands beyond. If you can surmount the great stony barrier, you wiill find a new region to explore.</p>\\n\\"Embark on venture below (see Ventures on Rulebook p.60).\\n\\n<bi>The mountains are hard to ascend at the best of times, and someone must scout the path for the group.</bi>\\n<b>Champion, Hazard:</b> Someone must test <might> to scale the mountain. Add +2 if you have a Piton, +2 if you have Rope, and +4 if you have the glacier mark.\\n9+: You scale the sheer cliff with expert ease. The venture continues.\\n1–8: You get off to a poor start, the rough stones threatening to slice your hands as you climb. The venture fails unless a characters suffers <major_injury> or spends <lore> to attempt this test again.\\n\\n<bi>With a solid path, the group makes good progress. Your mood sours as a storm gathers on the horizon, battering against the mountainside.</bi>\\n<b>Group, Weather:</b> Everyone must test <awareness> to find shelter from a storm. A character adds +2 for each <i>clothing</i> item they have, +2 if they have a <i>clothing</i> item, and +2 if they have an item with a <fire> token on it, and +4 if they have the ice mark.\\n11+: You find a shelter and cut a path toward it. If any character resolves this result, the venture continues.\\n1–10: The battering storm catches you on the cliffside, buffeting you against the sharp stones. Suffer <major_injury>. If all characters on the venture resolve this result, the venture fails.\\n\\n<bi>The storm passes, but the mountainside is slick and dangerous. Descending is a deadly prospect, and finding a safe route will be challenging.</bi>\\n<b>Champion, Hazard:</b> Someone must test <dexterity> to find a safe path down. Add +2 if you have an <i>exploration</i> item and +4 if you have the arrival mark,.\\n10+: You nimbly vault up a safe path. Complete this venture and the associated goal.\\n1–9: You slip and begin to tumble. Suffer <major_injury><major_injury>. The venture fails unless a character spends <energy><energy> or discards a Rope or Piton item to attempt this test again.\\"","ru":"<p><i><b>Вы приблизились к высоким горам, заметив земли по ту сторону. Если вам удастся преодолеть это громадное каменное препятствие, вам откроется новый регион для исследования. </b></i></p><p>Отправьтесь в поход (см. раздел «Походы» в правилах игры на с. 60).</p><p><b><i>Подниматься в горы было трудно даже в лучшие времена. Одному из вас пришлось разведать путь для всей группы. </i></b></p><p><b>Защитник, угроза. </b>Один из персонажей в походе должен провести проверку <might>, чтобы взобраться на гору. +2, если у него есть «Скальный крюк», +2, если у него есть «Верёвка», и +4, если у него есть отметка ледника [i].<br><b>≥9:</b>  Вы без труда вскарабкались по отвесной скале. Продолжите поход.<br><b>1-8:</b>  Начало выдалось тяжёлым — острые камни грозили изрезать вам руки. Поход окончился неудачно, если только любой персонаж в походе не получит <major_injury> или не потратит <lore>, чтобы провести проверку ещё раз.</p><p><i><b>Ваша группа уверенно продвигалась вперёд по надёжной тропе. Но ваше настроение резко упало, когда на горизонте показалась буря, грозящая яростно обрушиться на склон горы.</b></i></p><p><b>Группа, погода. </b>Все персонажи в походе должны провести проверку <awareness>, чтобы найти укрытие. +2, если у персонажа есть <i>одежда</i>, +2, если у него есть <i>накидка</i>, +2, если у него есть предмет с <fire>, и +4, если у него есть отметка льда [ii]. <br><b>≥11:</b>  Вам удалось вовремя укрыться. Если хотя бы один персонаж получил этот результат, продолжите поход.<br><b>1-10:</b>  Яростная буря обрушилась на склон и начала швырять вас о каменные выступы. Получите <major_injury>. Если все персонажи получили этот результат, поход окончился неудачно.</p><p><i><b>Буря утихла, но склон горы оставался скользким и опасным.</b></i></p><p><b>Защитник, угроза.</b> Один из персонажей в походе должен провести проверку <dexterity>, чтобы найти безопасный путь вниз. +2, если у него есть предмет для <i>исследования</i>, и +4, если у него есть отметка прибытия [iii].<br><b>≥10:</b>  Вы ловко выбрались по безопасному маршруту. Завершите этот поход и достигните соответствующей цели.<br><b>1-9:</b>  Вы поскользнулись и начали падать. Получите <major_injury><major_injury>. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy> или не сбросит «Верёвку» либо «Скальный крюк», чтобы провести проверку ещё раз.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<glacier>"},{"label":"ii","image":"<ice>"},{"label":"iii","image":"<arrival>"}]},{"id":"outcomes-917","code":"917","description":{"en":"<p>\\"In the past, the behemoth has been your people's protector in the valley. Now, you approach the great beast to ask one final boon: survival for your people.\\"</p>\\n\\"Embark on the venture below (see Ventures on Rulebook p.60).\\n\\n<bi>You approach the behemoth's lair, offerings in hand. If this bond means anything, may it mean something now!</bi>\\n<b>Behemoth, Champion:</b> Someone must test <awareness> and discard a material or an item to present a gift. Add +2 if the material is the behemoth's curio, +2 if it is a rare material, +2 if it is an item, and +6 if it is a <i>trophy</i> item. Add +2 for each Secret that has been recorded in the Journal for this behemoth.\\n12+: The behemoth slowly turns to face you. The venture continues.\\n1–11: The behemoth seems not to notice you. The venture fails unless a character spends <lore> to attempt this test again.\\n\\n<bi>The behemoth's great head bends toward you. Your soul shudders under its regard.</bi>\\n<b>Behemoth, Group:</b> Everyone must test <conviction> to stand firm. A character adds +2 for each Secret that has been recorded in the Journal for this behemoth.\\n13+: You stand firm. If any character resolves this result, the venture continues.\\n1–12: Leave the venture and flee. If all characters leave the venture, the venture fails.\\n\\n<bi>The behemoth makes no reaction. How can you explain yourself to this creature? You reach out a hand to its great head and begin to speak, hoping desperately that it might understand.</bi>\\n<b>Behemoth, Champion:</b> Someone must test <awareness> to communicate. Add +2 for each Secret that has been recorded in the Journal for this behemoth.\\n14+: The behemoth turns away from you, moving to some unknown end. Were your fervent requests understood by the creature? Complete this venture and the associated goal.\\n1–13: The behemoth seems not to understand. The venture fails unless a character spends <energy> or <lore> to attempt this test again.\\"","ru":"<p><i><b>В прошлом чудище было защитником ваших людей в долине. Теперь вы пришли к великому зверю с последней просьбой: даровать выживание вашему народу.</b></i></p><p>Отправьтесь в поход (см. раздел «Походы» в правилах игры на с. 60).</p><p><b><i>Вы подошли к логову чудища с дарами в руках. Если ваша с ним связь что‑то значила, это должно помочь.</i></b></p><p><b>Чудище, защитник. </b>Один из персонажей в походе должен провести проверку <awareness> и сбросить материал или предмет, чтобы сделать подношение. +2, если сброшенный материал — сокровище чудища, +2, если это редкий материал, +2, если это предмет, и +6, если это трофей. Также +2 за каждый секрет этого чудища, записанный в журнал.<br><b>≥12:</b>  Чудище медленно повернулось к вам. Продолжите поход.<br><b>1-11:</b>  Чудище, похоже, вас не заметило. Поход окончился неудачно, если только любой персонаж в походе не потратит <lore>, чтобы провести проверку ещё раз.</p><p><i><b>Громадная голова чудища склонилась к вам. Вы содрогнулись пред его взором.</b></i></p><p><b>Чудище, группа. </b>Все персонажи в походе должны провести проверку <conviction>, чтобы выстоять. +2, если персонаж <i>неукротимый</i>, и +2 за каждый секрет этого чудища, записанный в журнал.<br><b>≥13:</b>  Вы держались стойко. Если хотя бы один персонаж получил этот результат, продолжите поход.<br><b>1-12:</b>  Вы не выдержали взгляда чудища. Покиньте поход и сбегите. Если все персонажи получили этот результат, поход окончился неудачно.</p><p><i><b>Чудище не реагировало. Как вы могли объясниться с этим существом? Вы протянули руку к его громадной голове и начали говорить, отчаянно надеясь, что оно поймёт вас.</b></i></p><p><b>Чудище, защитник. </b>Один из персонажей в походе должен провести проверку <awareness>, чтобы поговорить с чудищем. +2 за каждый секрет этого чудища, записанный в журнал.<br><b>≥14:</b>  Чудище отвернулось от вас и ушло в неизвестном направлении. Были ли ваши просьбы поняты этим существом? Завершите этот поход и достигните соответствующей цели.<br><b>1-13:</b>  Чудище, похоже, не поняло вас. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy> или <lore>, чтобы провести проверку ещё раз.</p>"},"repeatable":false},{"id":"outcomes-918","code":"918","description":{"en":"<p>The behemoth dominates the skyline before you, the beast of ancient myth revived by the power of the coral. Tendrils of pulsing coral envelope the ancient bones, and it rumbles toward you with a wrath that death itself cannot quench.</p>\\n\\"Embark on the venture below (see Ventures on Rulebook p.60).\\n\\n<bi>A shell of dormant coral has formed around the behemoth, while living tendrils animate its body within. You'll need to crack the shell to reach its vulnerable interior.</bi>\\n<b>Behemoth, Champion, Coral:</b> Someone must contest <might> versus the coral behemoth's <dexterity> to fight. Add +2 if you have <strike> or <stoneworking> or +4 if you have a <i>moonblood</i> item with <strike> or <stonework>, and +2 if you are <i>cunning</i>.\\nWin (Equal or higher): With great effort, you break open the shell, exposing the beating coral heart in the behemoth's chest. The venture continues.\\nLose (Lower): Tendrils of living coral snake out, to repair the damage you cause, and you choke on the spores that flit out where they arise. Suffer <minor_disease>. The venture fails unless a character spends <energy><energy> to attempt this test again.\\n\\n<bi>Further enraged by your attack, the behemoth strikes back. Its thunderous blow shatters the ground around you!</bi>\\n<b>Behemoth, Coral, Group:</b> Everyone must contest <dexterity> or <awareness> versus the coral behemoth's <might> to avoid harm. Add +2 if you have a <i>clothing</i> item, +2 if you have a Moonblood Talisman, and +2 if you are <i>lucky</i>.\\nWin (Equal or higher): You duck under the flying debris. If any character resolves this result, the venture continues.\\nLose (Lower): A stone catches you full in the chest, throwing you from your feet. Suffer <major_injury><minor_injury>. If all characters on the venture resolve this result, the venture fails unless a character spends <energy><energy> or <lore><lore> to attempt this test again.\\n\\n<bi>As your ears ring and the dust clears, you see your moment. Someone can race up the behemoth's extended limb, then strike through a crack in its shell to stab at the coral's beating heart!</bi>\\n<b>Behemoth, Champion, Coral:</b> Someone must contest <dexterity> versus the behemoth's <conviction>. Add +2 if you have a <i>moonblood weapon</i> item, +4 if you have a <i>trophy weapon</i> item, and +2 if you are <i>vengeful</i>.\\nWin (Equal or higher): You stab down at the coral heart, and your weapon pierces it! Complete this venture and the associated goal.\\nLose (Lower): The behemoth hurls you into the air, and you land with a crunch. Discard any <i>weapon</i> item you used for the test. Suffer <major_injury><major_injury>. You must return to the previous step of the venture unless you spend <energy><energy> or <lore> to attempt this contest again.\\"","ru":"<p><i><b>Чудище возвышалось над горизонтом — то был зверь из старинных мифов, воскрешённый силой коралла. Пульсирующие коралловые щупальца оплетали его древние кости, и оно двигалось к вам с яростью, которую не усмирила бы и смерть.</b></i></p><p>Отправьтесь в поход (см. раздел «Походы» в правилах игры на с. 60).</p><p><i><b>Вокруг чудища образовалась оболочка из спящего коралла, а под ней его тело приводили в движение живые щупальца. Вам предстояло расколоть эту оболочку, чтобы добраться до уязвимого нутра.</b></i></p><p><b>Чудище, защитник, коралл.</b> Один из персонажей в походе должен провести состязание, чтобы сразиться: его <might> против <dexterity> кораллового чудища. +2, если у этого персонажа есть <strike> или <stoneworking> (или +4, если у него есть предмет лунной крови с <strike> или <stoneworking>), и +2, если персонаж <i>хитрый</i>.<br><b>Успех. </b>С большим трудом, но вы вскрыли оболочку, обнажив бьющееся коралловое сердце в груди чудища. Продолжите поход. <br><b>Провал.</b> Живые коралловые щупальца выползали наружу и залечивали раны, а вы задыхались от спор, вырывающихся из трещин. Получите <minor_disease>. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy>, чтобы провести проверку ещё раз.</p><p><b><i>Разъярённое вашей атакой, чудище нанесло ответный удар. Земля вокруг вас содрогнулась и раскололась!</i></b></p><p><b>Чудище, коралл, группа. </b>Все персонажи в походе должны провести состязание, чтобы избежать урона: <dexterity> или <awareness> против <might> кораллового чудища. +2, если у персонажа есть <i>одежда</i>, +2, если у него есть «Талисман из лунной крови», и +2, если он <i>удачливый</i>.<br><b>Успех. </b>Вы успели укрыться от летящих обломков. Если хотя бы один персонаж получил этот результат, продолжите поход.<br><b>Провал. </b>Камень ударил вас прямо в грудь и сбил с ног. Получите <major_injury> и <minor_injury>. Если все персонажи получили этот результат, поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy> или <lore><lore>, чтобы провести проверку ещё раз.</p><p><i><b>Когда звон в ушах стих, а пыль осела, судьба преподнесла вам ещё один шанс. Кто‑то из вас мог взбежать по вытянутой конечности чудища и ударить в трещину его панциря, чтобы пронзить бьющееся коралловое сердце!</b></i></p><p><b>Чудище, защитник, коралл.</b> Один из персонажей в походе должен провести состязание, чтобы пронзить сердце: его <dexterity> против <conviction> чудища. +2, если у этого персонажа есть <i>оружие лунной крови</i>, +4, если у персонажа есть <i>оружие-трофей</i>, и +2, если персонаж <i>мстительный</i>.<br><b>Успех.</b> Вы вонзили оружие в коралловое сердце и пронзили его! Завершите этот поход и достигните соответствующей цели.<br><b>Провал. </b>Чудище подкинуло вас в воздух, и вы упали с глухим треском. Сбросьте оружие, использованное в проверке. Получите <major_injury><major_injury>. Вернитесь к предыдущей вылазке, если только не потратите <energy><energy> или <lore>, чтобы провести проверку ещё раз.</p>"},"repeatable":false},{"id":"outcomes-919","code":"919","description":{"en":"<p>The peaceful days draw to a close uneventfully, but uncertainty looms on the horizon...</p>\\nEnd this challenge, then add <population><population>.","ru":"<p><b><i>Спокойные дни подошли к концу, на горизонте нависла неопределённость…</i></b></p><p>Завершите текущее испытание, затем добавьте  <population><population>.</p>"},"repeatable":false},{"id":"outcomes-924","code":"924","description":{"en":"<p>You rush toward the behemoth...</p>\\n\\"Embark on the venture below (see Ventures on Rulebook p.60).\\n<bi>...and the realization of what you are doing suddenly assails you as the creature's stony visage looms overhead. The behemoth is so massive, so ancient. How can you possibly hope to face it?</bi>\\n<b>Behemoth, Champion:</b> Someone must contest <conviction> versus the behemoth's <awareness> to lead the charge. Add +2 if you are <i>indomitable</i>.\\nWin (Equal or higher): You rally, and the others fall in behind you. The venture continues.\\nLose (Lower): Your will waivers. The venture fails unless a character spends <energy><energy> or <lore> to attempt this test again.\\n\\n<bi>As you approach the base of the behemoth, a forest springs to life around you, tendrils twisting out of the soil to impede your progress. You must avoid being impaled!</bi>\\n<b>Behemoth, Group, Hazard:</b> Everyone must contest <dexterity> or <awareness> versus the behemoth's <dexterity> to avoid harm. A character adds +2 if they have a <i>weapon</i> item and +2 if they are <i>wary</i>.\\nWin (Equal or higher): You smash your way through the thorns. If any character resolves this result, the venture continues.\\nLose (Lower): You are impaled on the warding thorns. Leave the venture unless you suffer <major_injury><major_injury><minor_injury>. If all characters on the venture resolve this result, the venture fails.\\n\\n<bi>You race toward the behemoth, and its massive head descends to meet you. It smashes a furrow in the ground, casting a wave of dirt up into your face. You vault and land, then strike down upon its great head.</bi>\\n<b>Behemoth, Champion:</b> Someone must contest <dexterity> or <might> versus the behemoth's <might> to fight. Add +2 if you have a <i>weapon</i> item and +4 if you have a <i>trophy</i> item.\\nWin (Equal or higher): You bring down your weapon in a fell blow that will be heard across ages. Complete this venture and the associated goal.\\nLose (Lower): You are rebuffed, hurled back by the force of your foe. The venture fails unless a character suffers <major_injury> to attempt this test again.\\"","ru":"<p><i><b>Вы бросились к чудищу…</b></i></p><p>Отправьтесь в поход (см. раздел «Походы» в правилах игры на с. 60).</p><p><i><b>…и осознание содеянного внезапно нахлынуло на вас, когда над головой навис каменный лик чудища. Существо оказалось таким громадным, таким древним… Как вы вообще могли надеяться противостоять ему?</b></i></p><p><b>Чудище, защитник. </b>Один из персонажей в походе должен провести состязание, чтобы вести остальных за собой: его <conviction> против <awareness> чудища. +2, если этот персонаж <i>неукротимый</i>.<br><b>Успех.</b> Вы собрались с духом, и остальные двинулись за вами. Продолжите поход.<br><b>Провал. </b>Ваша решимость дала трещину. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy> или <lore>, чтобы провести проверку ещё раз.</p><p><i><b>Когда вы приблизились к чудищу, вокруг вас внезапно появился лес щупалец, мешающих двигаться вперёд. Вы должны были не дать им добраться до вас!</b></i></p><p><b>Чудище, группа, угроза. </b>Все персонажи в походе должны провести состязание, чтобы избежать урона: <dexterity> или <awareness> против <dexterity> чудища. +2, если у персонажа есть оружие, и +2, если он <i>осторожный</i>.<br><b>Успех.</b> Вы прорвались сквозь колючие заросли. Если хотя бы один персонаж получил этот результат, продолжите поход.<br><b>Провал.</b> Вас изранили колючие побеги. Покиньте поход или получите <major_injury><major_injury> и <minor_injury>. Если все персонажи получили этот результат, поход окончился неудачно.</p><p><i><b>Вы снова бросились к чудищу, и его массивная голова опустилась навстречу вам. Чудище вгрызлось в землю, и вас накрыло волной грязи. Вы прыгнули и обрушили удар на гигантскую голову.</b></i></p><p><b>Чудище, защитник.</b> Один из персонажей в походе должен провести состязание, чтобы сразиться с чудищем: его <dexterity> или <might> против <might> чудища. +2, если у этого персонажа есть <i>оружие</i>, и +4, если у персонажа есть <i>трофей</i>.<br><b>Успех.</b> Вы обрушили оружие с сокрушительным ударом, который ещё долго будут помнить. Завершите этот поход и достигните соответствующей цели.<br><b>Провал.</b> Ответный удар противника отбросил вас. Поход окончился неудачно, если только любой персонаж в походе не получит <major_injury>, чтобы провести проверку ещё раз.</p>"},"repeatable":false},{"id":"outcomes-928","code":"928","description":{"en":"<p>The realm you find is strange and wondrous in ways very different from the place you first entered the valley...</p>\\nAdd <lore><lore><lore>. Roll <1d6> and add the corresponding result to your goals: 1–3: Beyond the Jagged Rim (GZ04), 4–6: A World Below (GZ05).","ru":"<p><i><b>Место, в которое вы попали, оказалось странным и удивительным — оно было совсем не похоже на тот мир, что вы видели раньше…</b></i></p><p>Добавьте <lore><lore><lore>. Бросьте <1d6> и добавьте соответствующую цель: [1-3] «Отправьтесь за зубчатый край» (ЦЯ04), [4-6] «Отправьтесь в подземный мир» (ЦЯ05).</p>"},"repeatable":false},{"id":"outcomes-929","code":"929","description":{"en":"<p>In the dark of the deep root-tunnels, you do not find the answers you need to save the Tangle. Some among your people believe that the Tangle is lost and the only answer is to depart, but others believe it can still be saved.</p>\\n\\"Add <unrest><unrest>. Each outpost in the Tangle region becomes a ruin. Subtract <population><population> for each outpost that became a ruin this way. Then, as a group, the players must choose one of the following paths for your society:\\n\\n<b>A) Seek new lands, beyond the blight:</b> Illustrate the saga of the lost haven on the primal cave wall, including the exodus mark (i) and the Tangle mark (ii). Add Exodus (CZ09) to your looming challenges.\\n\\n<b>B) Redouble your efforts to save the diminished Tangle at great cost to your people:</b> Illustrate the saga of the rot's toll on the primal cave wall, including the harrowing mark (iii) and the Tangle mark (ii). Subtract <1d6><population> and add <unrest><unrest>, then add Hope Buried Deep (CN04) to your looming challenges.\\"","ru":"<p><i><b>Во тьме глубинных корневых тоннелей вы не нашли ответа на вопрос, как спасти Сплетение. Среди вашего народа ходили верования, что Сплетение обречено и единственный выход — покинуть это место. Но кто‑то верил и в другой путь.</b></i></p><p>Завершите текущее испытание.</p><p>Добавьте <unrest><unrest>. Все поселения в регионе Сплетения становятся руинами. За каждое такое поселение уберите <population><population>. Затем совместно выберите один из следующих путей развития общины:<br><b>А. Найдите земли без заражения. </b>На стене первобытной пещеры изобразите историю о потерянном рае, включив в неё отметку исхода [i] и отметку Сплетения [ii]. Добавьте к грядущим испытаниям карту «Исход» (ИЯ09).<br><b>Б. Спасите умирающее Сплетение, чего бы это ни стоило вашему народу. </b>На стене первобытной пещеры изобразите историю о цене гнили, включив в неё отметку ужаса [iii] и отметку Сплетения [ii]. Уберите <1d6><population> и добавьте <unrest><unrest>. Затем добавьте карту «Глубоко захороненная надежда» (ИЖ04) к грядущим испытаниям.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<exodus>"},{"label":"ii","image":"<tangle>"},{"label":"iii","image":"<harrowing>"}]},{"id":"outcomes-931","code":"931","description":{"en":"<p>\\"Your people watch the wanderer's path with trepidation in their hearts. As if in response, the earth buckles and cracks like mud shaken from the back of some great beast. People panic, and fires spread out of control in your outposts.\\"</p>\\n<p>Flip each inactive coral overgrowth overlay to its active side. For each outpost, randomly select 1 structure in that outpost. That structure is destroyed unless one or more characters in that hex discard a total of 2 water.</p>","ru":"<p><i><b>Ваш народ с тревогой наблюдал за передвижением Скитальца. И словно в ответ на это земля выгнулась и треснула, точно грязь, которую некий громадный зверь стряхнул со своего хребта. По поселениям стремительно разнеслись пожары. </b></i></p><p>Переверните все неактивные коралловые заросли. В каждом поселении разрушьте 1 случайное сооружение, если персонажи (один или несколько) на участке местности с этим поселением не сбросят 2 воды.</p>"},"repeatable":false},{"id":"outcomes-932","code":"932","description":{"en":"<p>Your greetings and offerings are accepted, and your new friends lead you to their home. There, you find many familiar artifacts and structures. As you sit around their fires and celebrate, you are certain these people are your ancient kin, long-lost but now reunited.</p>\\nAdd 6<population>. Build a new outpost into the farthest hex from an outpost without an overlay (without spending <energy>). Roll <1d6> 3 times and add the following structures to the outpost (rerolling duplicates): (1-2) fire pit (ST02), (3) healing house (ST10), (4) watchtower (ST19), (5) garden (ST20), (6) monument of the sky (ST13). Illustrate the saga of the reunion on the primal cave wall, including the mark of the mediator.","ru":"<p><i><b>Ваши дары и приветствия были приняты, и новые друзья повели вас в своё поселение. Там вы обнаружили множество знакомых артефактов и сооружений. Сидя у костра, вы поняли: вы наконец‑то нашли своих давних сородичей. </b></i></p><p>Добавьте 6 <population>. Постройте новое поселение на самом удалённом от других поселений участке местности, на котором нет накладки, не тратя <energy>. Бросьте <1d6> три раза и постройте в этом поселении следующие сооружения по результатам бросков (повторяющиеся результаты перебрасывайте): [1-2] костровая яма (СР02), [3] дом исцеления (СР10), [4] сторожевая башня (СР19), [5] сад (СР20), [6] памятник небу (СР13).</p><p>На стене первобытной пещеры изобразите историю о воссоединении, включив в неё отметку посредника.</p>"},"repeatable":false,"marks":[{"label":"","image":"<mediator>"}]},{"id":"outcomes-934","code":"934","description":{"en":"<p>You can do nothing but watch as the two titans batter each other, flattening forests and shattering mountainsides in their epic struggle. Eventually, one proves victorious, and casts down the broken body of the loser. For a moment, the valley falls silent under the gaze of its new sovreign.</p>\\n\\"Resolve a <might> contest between the two behemoths. Subtract 6<population> unless the winning behemoth's mark is enclosed in the bond mark (i) on the primal cave wall.\\n\\nThen illustrate the saga of the cataclysmic duel on the primal cave wall, including the mark of each alert behemoth and the broken earth mark (ii).\\n\\nThen, end this challenge. Flip the losing behemoth's lair to its inactive side.\\"","ru":"<p><i><b>Вы могли лишь наблюдать, как два титана сражались друг с другом, как они сминали леса и разбивали склоны гор в своей легендарной битве. В конце концов один одержал верх и низринул изломанное тело поверженного. На мгновение долина затихла, узрев нового владыку.</b></i></p><p>Проведите состязание <might> между двумя чудищами. Уберите 6 <population>, если отметка победившего чудища не заключена в отметку связи [i] на стене первобытной пещеры.</p><p>Затем на стене первобытной пещеры изобразите историю о разрушительной дуэли, включив в неё отметки обоих бодрствующих чудищ и отметку расколотой земли [ii].</p><p>Затем завершите текущее испытание. Переверните логово проигравшего чудища.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<bond>"},{"label":"ii","image":"<brokenearth>"}]},{"id":"outcomes-939","code":"939","description":{"en":"<p>As your band of explorers works to cross the glacial expanse, you are faced by a sheer cliff, buffeting winds, and icy cold. To survive, you will need grit, ingenuity, and the right tools.</p>\\n\\"Embark on the venture below (see Ventures on Rulebook p.60).\\n\\n<bi>You approach the massive wall of the glacier. Despite the cold, you feel sweat prick the back of your neck in the face of such enormity.</bi>\\n<b>Group, Hazard:</b> Everyone must test <dexterity> to scale the face. A character adds +2 if they have a Piton, +2 if they have a Rope, and +4 if they have <stoneworking>.\\n9+: You manage to clamber up the cliff face and find an icy plain. If any character resolves this result, continue the venture.\\n1–8: The ice and dirt gives way beneath you, and you slide painfully down the cliff face. You suffer <major_injury> and leave the venture unless you spend <energy><energy> or <lore><lore> to attempt this test again. If all characters leave the venture, the venture fails.\\n\\n<bi>Atop the glacier, you see a vast plane of frozen earth cut by jagged teeth of ice. As you begin to trudge across the expanse, clouds gather overhead and snowflakes dance menacingly on the breeze.</bi>\\n<b>Group, Weather:</b> Everyone must test <might> to endure the cold. A character adds +2 if they have a <i>clothing</i> item and +2 if they are <i>indomitable</i>.\\n9+: You shrug off the biting winds. If any character resolves this result, continue the venture.\\n1–8: Your limbs grow terribly numb, and you feel the strength leaving your body. To press on would be folly! You leave the venture unless you suffer <major_disease> or spend <lore><lore> to attempt this test again. If all characters leave the venture, the venture fails.\\n\\n<bi>The clouds clear, but the bright white of the glacier top dazzles the senses and leaves you disoriented. Surrounded by unyielding glare, you must find your route without becoming lost.</bi>\\n<b>Champion, Hazard:</b> Someone must test <awareness> to chart a course across the plain of ice. A character adds +2 for each <i>exploration</i> item they have and +2 if they are <i>attuned</i>.\\n10+: Complete this venture and the associated goal.\\n1–9: Your group becomes terribly lost amidst the desolate white sameness of the glacier. The venture fails unless a character spends <energy><energy> to attempt this test again.\\"","ru":"<p><i><b>Когда ваша группа исследователей попыталась пересечь ледники, на вашем пути встали отвесные утёсы, ревущие ветра и леденящий холод. Чтобы выжить, вам понадобились выдержка, находчивость и подходящее снаряжение.</b></i></p><p>Отправьтесь в поход (см. раздел «Походы» в правилах игры на с. 60).</p><p><b><i>Вы подошли к огромной ледяной стене. Несмотря на холод, от одного её вида пот выступил у вас на затылке.</i></b></p><p><b>Группа, угроза.</b> Все персонажи в походе должны провести проверку <dexterity>, чтобы взобраться на стену. +2, если у персонажа есть «Скальный крюк», +2, если у персонажа есть «Верёвка», и +4, если у него есть <stoneworking>.<br><b>≥9:</b>  Вам удалось взобраться по ледяной стене, и вы оказались на замёрзшем плато. Если хотя бы один персонаж получил этот результат, продолжите поход.<br><b>1-8:</b>  Лёд и земля под вами обрушились, и вы соскользнули вниз по стене, почувствовав боль. Получите <major_injury> и покиньте поход либо потратьте <energy><energy> или <lore><lore>, чтобы провести проверку ещё раз. Если все персонажи покинули поход, он окончился неудачно.</p><p><b><i>На вершине ледника вы увидели бескрайнюю равнину мёрзлой земли, испещрённой ледяными зубцами. Когда вы начали пробираться вперёд, над вами сгустились тучи и в воздухе зловеще закружились снежинки.</i></b></p><p><b>Группа, погода. </b>Все персонажи в походе должны провести проверку <might>, чтобы выдержать холод. +2, если у персонажа есть <i>одежда</i>, и +2, если он <i>неукротимый</i>.<br><b>≥9:</b>  Вы устояли перед пронизывающим ветром. Если хотя бы один персонаж получил этот результат, продолжите поход.<br><b>1-8:</b>  Ваши конечности начали страшно неметь, и вы почувствовали, как силы покидают тело. Продолжать путь было безумием. Покиньте поход либо получите <major_disease> или потратьте <lore><lore>, чтобы провести проверку ещё раз. Если все персонажи покинули поход, он окончился неудачно.</p><p><b><i>Тучи рассеялись, но белизна ледника ослепила вас и лишила ориентира. Вы должны были найти путь и не сбиться с него. </i></b></p><p><b>Защитник, угроза.</b> Один из персонажей в походе должен провести проверку <awareness>, чтобы проложить маршрут через ледяное плато. +2 за каждый предмет для <i>исследования </i>у этого персонажа и +2, если он <i>сосредоточенный</i>.<br><b>≥10:</b>  Вам удалось пройти по леднику. Завершите этот поход и достигните соответствующей цели.<br><b>1-9:</b>  Ваша группа окончательно заблудилась среди однообразной безжизненной белизны. Поход окончился неудачно, если только любой персонаж в походе не потратит <energy><energy>, чтобы провести проверку ещё раз.</p>"},"repeatable":false},{"id":"outcomes-940","code":"940","description":{"en":"<p>Your efforts to create a grand citadel for your people has fallen short of aspirations. As the seasons and years wear on, your people become convinced that the work will never end. The unfinished portions of the city are eventually inhabited as they are, and construction becomes impossible. Finally, the great boundary walls you drew out ages ago vanish into the resurgent wilds, and many of your people scatter. Your descendents who remain live amidst the folly of ages past.</p>\\n\\"End this challenge.\\n\\nSubtract <population><population>. Then, as a group, the players must choose one of the following paths for your society:\\n\\n<b>A) Cling to phantom glories that could have been:</b> Add <unrest><unrest><unrest>. Illustrate the saga of the work abandoned on the primal cave wall, including the broken earth mark (i) and the misfortune mark (ii). For each character, permanently lower their <awareness> by 1 (to a minimum of 1) and raise their <conviction> by 2 (to a maximum of 7). Then add the growth mark (iii) and the misfortune mark (ii) to the Legend side of their Character cards.\\n\\n<b>B) Let ambitions and failure vanish from memory:</b> Illustrate the saga of the forgotten path on the primal cave wall, including the broken earth mark (i) and mystery mark (iv). When your current characters become Legends at the end of the Epoch, randomly select half of them. These Legend cards are forgotten; place them in the game box, and they cannot be used by your society.\\n\\nThen end the Epoch. See Codex p.204 to begin Epoch 3.\\"","ru":"<p><i><b>Ваши усилия по созданию великой цитадели не увенчались успехом. С годами ваши соплеменники окончательно уверовали в то, что стройке не будет конца. Незавершённые части города в итоге были заселены как есть, и продолжать строительство стало невозможно. Наконец, границы, которые вы наметили много лет назад, исчезли в буйных зарослях, и многие люди вашей общины разбрелись. Потомки, что остались здесь, жили среди руин былых мечтаний.</b></i></p><p>Завершите текущее испытание.</p><p>Уберите <population><population>. Затем совместно выберите один из следующих путей развития общины:<br><b>А. Зацепитесь за призрачную славу несбывшегося. </b>Добавьте <unrest><unrest><unrest>. На стене первобытной пещеры изобразите историю о брошенной работе, включив в неё отметку расколотой земли [i] и отметку несчастья [ii]. Навсегда уменьшите <awareness> каждого персонажа на 1 (не может быть меньше 1) и увеличьте <conviction> на 2 (не более чем до 7). Затем добавьте отметку становления [iii] и отметку несчастья [ii] на сторону легенды карт всех персонажей.<br><b>Б. Позвольте честолюбию и неудачам исчезнуть из памяти.</b> На стене первобытной пещеры изобразите историю о забытом пути, включив в неё отметку расколотой земли [i] и отметку тайны [iv]. Когда ваши текущие персонажи станут легендами в конце эры, случайным образом выберите половину из них (округляя в меньшую сторону). Эти карты легенд становятся забытыми: верните их в коробку.</p><p>Затем завершите текущую эру. См. с. 204, чтобы начать эру 3.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<brokenearth>"},{"label":"ii","image":"<misfortune>"},{"label":"iii","image":"<growth>"},{"label":"iv","image":"<mystery>"}]},{"id":"outcomes-948","code":"948","description":{"en":"<p>\\"The rumors that swirl around the prophet say this individual have witnessed a great beast of fire spewing flames across the land, burning your civilization to the ground for its sin of hubris. The prophet's warning to your people is simple: the great fire must be fed before it takes what it desires.\\"</p>\\n<p>Add Mark the Omens (GY04) to your goals.</p>","ru":"<p><i><b>Ходили слухи, что пророку довелось увидеть великое огненное чудище, извергающее пламя по всей земле и сжигающее вашу цивилизацию дотла за грех гордыни. Предупреждение пророка вашему народу было простым: великий огонь нужно насытить, пока он сам не возымел желаемое.</b></i></p><p>Добавьте карту «Запечатлейте знамения» (ЦЕ04) к целям.</p>"},"repeatable":false},{"id":"outcomes-966","code":"966","description":{"en":"<p>Spreading death covers the valley as a winter without spring begins. The bones of our people vanish beneath the ashfall, preserved for some unseen age yet to dawn. Your sagas are sung no more.</p>\\n\\"Illustrate the saga of the ash-flecked conclusion on the primal cave wall, including the blackened sky mark and the harrowing mark. Your society <b>vanishes</b>.\\n\\nThis end may not be a happy one, but it can still be instructive to future peoples who inhabit the valley. To immortalize a photo of your primal cave wall and see other people's works of art, we invite you to share your saga with our community!\\n\\n@[Insert Link]@\\n\\nTo continue playing <i>Stonesaga</i>, see Beginning Subsequent Campaigns on Rulebook p.97. Or you could switch to Endless Mode, as described on Rulebook p.97.\\"","ru":"<p><i><b>Смерть, расползшаяся по долине, возвещала вечную зиму. Кости вашего народа, засыпанные пеплом, сохранились для тех веков, которым ещё предстояло наступить. Но вашу историю пересказать было более некому.</b></i></p><p>На стене первобытной пещеры изобразите историю о покрытом пеплом исходе, включив в неё отметку почерневшего неба [ii] и отметку ужаса [i]. Ваша община <b>исчезла</b>.</p><p>Такой конец хоть и далёк от счастливого, но он всё же может послужить уроком для народов, которые заселят эту долину в будущем. Чтобы увековечить фотографию своей стены первобытной пещеры и увидеть произведения искусства других игроков, мы приглашаем вас поделиться своей историей с нашим сообществом!</p><p>Чтобы продолжить играть в «Наскальную историю», см. в правилах игры раздел «Начало следующих кампаний» на с. 97 или раздел «Бесконечный режим» на с. 102.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<blackenedsky>"},{"label":"ii","image":"<harrowing>"},{"label":"","image":"<qrcode>"}]},{"id":"outcomes-973","code":"973","description":{"en":"<p>Your exploration uncovers a massive and strange mound. Could it be an edifice? The den of some ancient creature? A grave?</p>\\n<p>\\"Randomly select an unplaced behemoth lair and place it in a hex in the terrain tray you just placed. The lair overlay must be placed in an unexplored hex without an overlay, if able. Illustrate the saga of the ancient tomb on the primal cave wall, including the mark of the behemoth whose lair you placed this way and the discovery mark.\\n\\nRules for behemoth lairs are found in the Overlay Reference section beginning on Codex p.210.\\"</p>","ru":"<p><b><i>Вы заприметили странный огромный курган. Что это могло быть? Здание? Логово древнего существа? Могила?</i></b></p><p>Выберите случайное непомещённое логово чудища и поместите его на участок местности в своей основе местности или в соседней. Выбирайте неисследованный участок местности без накладок, если возможно. На стене первобытной пещеры изобразите историю о древней гробнице, включив в неё отметку чудища, чьё логово вы поместили, и отметку открытия. Правила логов чудищ см. на с. 211–212.</p>"},"repeatable":false,"marks":[{"label":"","image":"<discovery>"}]},{"id":"outcomes-975","code":"975","description":{"en":"<p>The fury of the sky crashes down, setting nearby foliage ablaze!</p>\\n\\"Choose one and resolve it:\\n\\nA) Perhaps the your people could harness the power of fire?...: Add Stoke the Flame (GA08) to your goals.\\n\\nB) Uncontrolled flames are dangerous, but you know how to quickly douse them: If blaze mark is on the primal cave wall, degrade the <fire> in your hex twice. Then add <lore>.\\"","ru":"<p><i><b>Ярость небес обрушилась вниз, поджигая листву вокруг!</b></i></p><p>Выберите и разыграйте одно:<br><b>А. Обуздайте силу огня.</b> Добавьте карту «Разведите огонь» (ЦA08) к целям.<br><b>Б. Потушите неконтролируемое пламя.</b> Если на стене первобытной пещеры есть отметка пламени, дважды уменьшите <fire> на своём участке местности. Затем добавьте <lore>.</p>"},"repeatable":false,"marks":[{"label":"","image":"<blaze>"}]},{"id":"outcomes-977","code":"977","description":{"en":"<p>The noxious mists around you suddenly ignite in a plume of fire.</p>\\n\\"Test <dexterity> to leap back. Add +2 if you are <i>wary</i> and +4 if you have the blaze mark.\\n12+: You avoid the brunt of the explosion, and emerge slightly singed. Suffer <minor_injury>.\\n6–11: The blast knocks you flat. Suffer <major_injury>.\\n1–5: You are badly burned by the flames. Suffer <major_injury><major_injury>. Discard each of your items with a <fire> token on it.\\"","ru":"<p><i><b>Ядовитый туман вокруг вас внезапно вспыхнул огненным столбом.</b></i></p><p>Проведите проверку <dexterity>, чтобы отскочить назад. +2, если вы <i>осторожный</i>, и +4, если у вас есть отметка пламени.<br><b>≥12:</b>  Вам удалось уклониться от сокрушительной мощи взрыва и выбраться лишь слегка обожжённым. Получите <minor_injury>.<br><b>6-11:</b>  Взрыв сбил вас с ног. Получите <major_injury>.<br><b>1-5:</b>  Вы получили сильные ожоги. Получите <major_injury><major_injury>. Сбросьте все свои предметы с <fire>.</p>"},"repeatable":false,"marks":[{"label":"","image":"<blaze>"}]},{"id":"outcomes-978","code":"978","description":{"en":"<p>You have resolved the problem that split your people, but chaos has consumed the valley in the process. While the belligerent factions agree to set down their arms, blood has already been shed and true peace seems distant.</p>\\nSet <unrest> to 3. Subtract <population>. Illustrate the saga of uneasy compromise on the primal cave wall, including the caution mark (i) and mediator mark (ii).","ru":"<p><i><b>Вы устранили проблему, что расколола ваш народ, но в долине воцарился хаос. Хоть враждующие группы и согласились сложить оружие, кровь уже была пролита и мира добиться было сложно.</b></i></p><p>Завершите текущее испытание.</p><p>Установите значение <unrest> на 3. Уберите <population>. На стене первобытной пещеры изобразите историю о хрупком перемирии, включив в неё отметку осторожности [i] и отметку посредника [ii].</p>"},"repeatable":false,"marks":[{"label":"i","image":"<caution>"},{"label":"ii","image":"<mediator>"}]},{"id":"outcomes-981","code":"981","description":{"en":"<p>From the quicksilver sea, you pull up a chunk of something unexpected: a petrified chunk of coral. Strangely, you have not seen this material elsewhere in the region.</p>\\nGain 1 dead coral. Add <lore><lore>.","ru":"<p><i><b>Из ртутного моря вы вытащили окаменевший кусок коралла, который явно не ожидали здесь выловить. Странно, но в этом регионе он вам нигде больше не встречался.</b></i></p><p>Получите 1 мёртвый коралл. Добавьте <lore><lore>.</p>"},"repeatable":false},{"id":"outcomes-982","code":"982","description":{"en":"<p>\\"There's a blinding flash of light and you look away. Opening your eyes, you discover you are no longer in the cave. You feel dazed but oddly empowered.\\"</p>\\n\\"Suffer <minor_injury> and gain <major_boost> to each ability. Choose another explored hex in the valley and move your character there, if able. Then resolve the first you are able:\\n\\n<b>A: You find yourself restored to youthful vigor:</b> If you are old, erase or cross out the mark on the \\\\\\"Old\\\\\\" box on your Character card. Your character is now \\\\\\"Young\\\\\\" again.\\n\\n<b>B: This strange occurance has given you a perspective beyond your years:</b> If you are young, choose one of the following traits and add a new trait to your Character card: <i>inquisitive</i>, <i>lucky</i>, or <i>wise</i>.\\n\\nThen illustrate the saga of the odd finding on the primal cave wall, including the mystery mark. Finally, return The Unknown (JU07) to the game box.\\"","ru":"<p><i><b>Ослепительный свет заставил зажмуриться. Открыв глаза, вы обнаружили, что вы больше не в пещере. Ошеломление от происходящего переплеталось с необъяснимым чувством радости и воодушевления.</b></i></p><p>Получите <minor_injury>. Получите <major_boost> к каждой характеристике. Выберите другой участок местности в долине и переместите туда своего персонажа, если возможно. Затем разыграйте первое, что можете:<br><b>А. Почувствуйте, как к вам возвращается юношеская энергия. </b>Если ваш персонаж пожилой, сотрите или зачеркните отметку в клетке «Пожилой» на карте персонажа. Теперь ваш персонаж снова считается молодым.<br><b>Б. Приобретите мудрость, несвойственную возрасту. </b>Если ваш персонаж молодой, выберите одну из следующих черт и добавьте её на карту персонажа: «любознательный», «удачливый» или «мудрый».</p><p>Затем на стене первобытной пещеры изобразите историю о странной находке, включив в неё отметку тайны.</p><p>Наконец, верните в коробку карту «Загадка» (ПН07).</p>"},"repeatable":false,"marks":[{"label":"","image":"<mystery>"}]},{"id":"outcomes-983","code":"983","description":{"en":"<p>A great behemoth has arrived in the valley alongside you, and the evidence of its presence is now undeniable. Trees broken like twigs, footprints deep as dried lakes. Yet you still have not encountered the beast yourself. What sort of creature could change the world this way with its very tread?</p>\\n\\"Add Arrival (CA04) to your looming challenges. Then, as a group, the players must choose one of the following paths for your society:\\n\\n<b>A) Ruminate on what creature could have been responsible:</b> If there is at least 1 behemoth without its mark on the primal cave wall, randomly select one of those behemoths. Illustrate the saga of the unseen giant on the primal cave wall, including the mark of the selected behemoth and the mystery mark. \\n\\n<b>B) Recall that you have observed signs of a creature that fits such a description:</b> Add <lore><lore><lore>.\\"","ru":"<p><i><b>В долине появилось огромное чудище, и теперь его присутствие невозможно было отрицать. Существо было настолько громадным, что ломало деревья, словно это были ветки, и оставляло отпечатки следов таких размеров, что их легко было спутать с высохшими озёрами. Однако воочию вы его не лицезрели. Что же это за существо, способное одной только поступью изменить мир вокруг?</b></i></p><p>Добавьте карту «Вторжение» (ИА04) к грядущим испытаниям. Затем совместно выберите один из следующих путей развития общины: <br><b>А. Поразмышляйте о природе загадочного существа.</b> Если есть чудище, чья отметка не запечатлена на стене первобытной пещеры, выберите одно из таких чудищ случайным образом. На стене первобытной пещеры изобразите историю о незримом гиганте, включив в неё отметку выбранного чудища и отметку тайны.<br><b>Б. Вспомните, что вы уже видели признаки существа, подходящего под это описание. </b>Добавьте <lore><lore><lore>.</p>"},"repeatable":false,"marks":[{"label":"","image":"<mystery>"}]},{"id":"outcomes-984","code":"984","description":{"en":"<p>You peer into arid land of high plateaus and sweeping vistas. Here, the earth swells up toward the sky and plunges into deep crevasses of eternal gloom.</p>\\nAdd <lore><lore><lore>. Add Beyond the Jagged Rim (GZ04) to your goals.","ru":"<p><i><b>Вы вгляделись в засушливую землю высокой равнины. Здесь земля вздымалась к небу и обрушивалась в глубокие расселины вечного мрака.</b></i></p><p>Добавьте <lore><lore><lore>. Добавьте к целям карту «Отправьтесь за зубчатый край» (ЦЯ04).</p>"},"repeatable":false},{"id":"outcomes-986","code":"986","description":{"en":"<p>\\"Within the lair, you discover a massive wall of ice wrought with the behemoth's strange markings. As you stare at the wall, the images come alive, playing out many scenes that wrestle for dominance in your mind. One becomes clear for a moment, one future in a tumult of possibility.\\"</p>\\n\\"Resolve the first you are able:\\n\\n<b>A) The pigment on the wall swirls into a vast, choking cloud, and you reel under its enormity:</b> If <comet> or <sun> is a current omen, find Goal card GC10. The player who completed the final <i>champion</i> test may look at that card for no more than 1 minute, then returns it to the Goal deck and describes it to the other players for any amount of time. Then illustrate the saga of the neverdawn on the primal cave wall, including the BH3's mark (i), the underworld mark (ii), and the prophecy mark (iii) enclosing the <comet> mark.\\n\\n<b>B) As the vision fades, your ears ring with shouts of anger and your nostrils fill with the scent of blood:</b> If <star> or <cloud> is a current omen, find Goal card GZ06. TThe player who completed the final <i>champion</i> test may look at that card for no more than 1 minute, then returns it to the Goal deck and describes it to the other players for any amount of time. Then illustrate the saga of the foretold split on the primal cave wall, including the BH3's mark (i) and the prophecy mark (iii) enclosing the <star> mark.\\n\\n<b>C) You stumble back from the twisting markings, one lair blending into another:</b> If <moon> is a current omen, find Goal card GZ15. The player who completed the final <i>champion</i> test may look at that card for no more than 1 minute, then returns it to the Goal deck and describes it to the other players for any amount of time. Then illustrate the saga of the ageless vault on the primal cave wall, including the BH3's mark (i) and the prophecy mark (iii) enclosing the <moon> mark.\\n\\nAt the end of this challenge, end the current epoch. Refer to Codex p.196 to continue your campaign into Epoch 2.\\"","ru":"<p><i><b>В логове вы обнаружили массивную ледяную стену, испещрённую странными метками чудища. Вы пристально всмотрелись в них — и изображения ожили, разыгрывая перед вами множество сцен, борющихся за господство в вашем сознании. На миг одна из них прояснилась, открыв вам вариант будущего в водовороте возможностей.</b></i></p><p>Разыграйте первое, что можете:<br><b>А. Пигмент на стене перекрутился в гигантское облако, и вы отшатнулись. </b>Если <comet> или <sun>— текущее знамение, найдите карту цели ЦВ10. Игрок, прошедший последнюю проверку защитника, может изучать эту карту не более 1 минуты, после чего должен вернуть её в колоду целей и описать её другим игрокам. Затем на стене первобытной пещеры изобразите историю о ненаступающем рассвете, включив в неё отметку ЧД3 [i], отметку подземного мира [ii] и отметку <comet>, заключённую в отметку пророчества [iii].<br><b>Б. Когда видение исчезло, в ушах у вас звенело от криков ярости, а ноздри наполнились запахом крови.</b> Если <star> или <cloud> — текущее знамение, найдите карту цели ЦЯ06. Игрок, прошедший последнюю проверку защитника, может изучать эту карту не более 1 минуты, после чего должен вернуть её в колоду целей и описать её другим игрокам. Затем на стене первобытной пещеры изобразите историю о предсказанном расколе, включив в неё отметку ЧД3 [i] и отметку <star>, заключённую в отметку пророчества [iii].<br><b>В. Вас отбросило назад от извивающихся узоров — одно логово перетекало в другое.</b> Если <moon> — текущее знамение, найдите карту цели ЦЯ15. Игрок, прошедший последнюю проверку защитника, может изучать эту карту не более 1 минуты, после чего должен вернуть её в колоду целей и описать её другим игрокам. Затем на стене первобытной пещеры изобразите историю о вековом хранилище, включив в неё отметку ЧД3 [i] и отметку <moon>, заключённую в отметку пророчества [iii].</p><p>В конце текущего испытания завершите текущую эру. См. с. 196, чтобы начать эру 2.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<bh2>"},{"label":"ii","image":"<underworld>"},{"label":"iii","image":"<prophecy>"}]},{"id":"outcomes-988","code":"988","description":{"en":"<p>Overharvesting of plants disrupts the cycles of growth, making vital staple foods harder and harder to find as the generations pass. Now, your people face a difficult decision...</p>\\n\\"As a group, the players must choose one of the following paths for your society: \\n\\n<b>A) Allow the overharvesting to continue:</b> Subtract <population><population><population>. For each of the following regions, remove the cards below from the Foraging decks, if able:\\n\\n1) If there is at least 1 Verdant Vale hex in the valley, remove FF09 from the Forest Foraging deck.\\n2) If there is at least 1 Skyreach Plateau hex in the valley, remove FP07 from the Prairie Foraging deck.\\n3) If there is at least 1 Maelstrom Hills hex in the valley, remove FM04 from the Jungle Foraging deck.\\n4) If there is at least 1 Tangle hex in the valley (and this region is available), remove FT03 from the Glade Foraging deck.\\n\\n<b>B) Restrict harvesting plants:</b> Add \\\\\\"harvesting 3 or more vegetables in a single day\\\\\\" to the Taboos section of the Culture page of the Journal. Gain the Taboos (KN18) Knowledge card. Add <unrest><unrest>. Illustrate the saga of the cautious harvest on the primal cave wall, including the following marks: caution (i), herbalism (ii), taboo (iii).\\n\\n<b>C) Reevaluate old taboos about diet:</b> If you have a taboo against eating meat (fish or game), remove that taboo and add <unrest><unrest><unrest>.\\"","ru":"<p><i><b>Чрезмерное собирательство нарушило циклы роста, и с каждым поколением вам становилось всё труднее добывать пропитание. Теперь ваш народ встал перед трудным выбором... </b></i></p><p>Совместно выберите один из следующих путей развития общины:<br><b>А. Продолжите добывать припасы, как и прежде. </b>Уберите <population><population><population>. Для каждого из следующих регионов уберите следующие карты из соответствующих колод добычи припасов, если возможно:<br>1. Если в долине есть хотя бы 1 участок Дивной долины, уберите карту ДЛ09 из колоды добычи припасов в лесу.<br>2. Если в долине есть хотя бы 1 участок Поднебесной равнины, уберите карту ДС07 из колоды добычи припасов в степи.<br>3. Если в долине есть хотя бы 1 участок Ураганных холмов, уберите карту ДД04 из колоды добычи припасов в джунглях.<br>4. Если в долине есть хотя бы 1 участок Сплетения (и этот регион доступен), уберите карту ДП03 из колоды добычи припасов на полянах.<br><br><b>Б. Ограничьте сбор растений. </b>Запишите «Собирать 3 или более овоща в день» в раздел «Табу» на странице «Культура» в журнале. Получите карту знаний «Табу» (ЗБ18), если у вас её нет. Добавьте <unrest><unrest>. На стене первобытной пещеры изобразите историю об осторожном сборе, включив в неё отметку осторожности [i], отметку травничества [ii] и отметку табу [iii].<br><b>В. Переосмыслите старые запреты, касающиеся питания. </b>Если у вас есть табу на потребление мяса (рыбы или дичи), удалите это табу и добавьте <unrest><unrest><unrest>.</p>"},"repeatable":false,"marks":[{"label":"i","image":"<caution>"},{"label":"ii","image":"<herbalism>"},{"label":"iii","image":"<taboo>"}]},{"id":"outcomes-990","code":"990","description":{"en":"<p>A black cloud in the distance catches your attention. It roils on the horizon, just beyond reach.</p>\\nIf the Volcanic Wastes mark is on the primal cave wall, add <lore>. Otherwise, add Seek the Shadow Column (GY02) to your goals.","ru":"<p><i><b>Ваше внимание привлекло чёрное облако вдалеке. Оно клубилось на горизонте, за пределами досягаемости.</b></i></p><p>Если на стене первобытной пещеры есть отметка Вулканических пустошей, добавьте <lore>. В противном случае добавьте карту «Найдите луч света» (ЦЕ02) к целям.</p>"},"repeatable":false},{"id":"outcomes-992","code":"992","description":{"en":"<p>As day is inverted to night, the certainty of the waking world is upended. Seething tensions burst to the surface, and chaos reigns beneath the vanished sun.</p>\\nSubtract <1d6> <population>. Each character in a hex with an outpost suffers <major_injury><major_injury> unless they are <i>cunning</i> or <i>wise</i>.","ru":"<p><i><b>Когда день обернулся ночью, казалось, что мир не проснулся. Всколыхнувшееся напряжение вырвалось наружу, и под исчезнувшим солнцем воцарился хаос.</b></i></p><p>Уберите <1d6> <population>. Каждый персонаж на участке местности с поселением получает <major_injury><major_injury>, если только он не <i>хитрый </i>или <i>мудрый</i>.</p>"},"repeatable":false},{"id":"outcomes-993","code":"993","description":{"en":"<p>You grow dreadfully ill. In the morning, you hear others coughing...</p>\\nIf the plague mark is on the primal cave wall, add <lore>. Otherwise, add Pestilence (CZ03) to your looming challenges.","ru":"<p><i><b>Вы сильно заболели. Утром вы услышали, как кашляют и другие...</b></i></p><p>Если на стене первобытной пещеры есть отметка чумы, добавьте <lore>. В противном случае добавьте карту «Мор» (ИЯ03) к грядущим испытаниям.</p>"},"repeatable":false,"marks":[{"label":"","image":"<plague>"}]},{"id":"outcomes-994","code":"994","description":{"en":"<p>In memorializing the deeds of your ancestors through song, your characters have earned their own place as legends.</p>\\nSubtract <unrest><unrest>. Illustrate the saga of the songweavers on the primal cave wall, including the songweaver mark. Gain the Legends (KN15) Knowledge card.","ru":"<p><i><b>Воспевая деяния предков, ваши люди заслужили своё место среди легенд.</b></i></p><p>Уберите <unrest><unrest>. На стене первобытной пещеры изобразите историю о ткачах песен, включив в неё отметку песнопевца. Получите карту знаний «Легенды» (ЗБ15), если у вас её нет.</p>"},"repeatable":false,"marks":[{"label":"","image":"<songweaver>"}]},{"id":"outcomes-995","code":"995","description":{"en":"<p>The behemoth has gorged itself upon the fruits of the valley, leaving little for anyone else...</p>\\n<p>\\"Until the end of this challenge (or the end of the current event, in Endless Mode), each character can gain a maximum of 1 vegetable food per day from the forage action.\\n \\nThen, remove this behemoth's aim and all of its trace tokens. Assign the Return to Slumber (BT20) instinct to this behemoth (replacing its previous instinct).\\"</p>","ru":"<p><i><b>Чудище насытилось плодами долины, мало что оставив после себя...</b></i></p><p>До конца текущего испытания (или до конца события в бесконечном режиме) каждый персонаж может получать не более 1 овоща в день при выполнении действия добычи припасов.</p><p>Уберите жетон направления и все жетоны следов этого чудища. Замените его текущий инстинкт на «Вернуться в забытьё» (ЧК20).</p>"},"repeatable":false},{"id":"outcomes-996","code":"996","description":{"en":"<p>You are caught in a rockslide!</p>\\n\\"Test <dexterity> to wriggle from the pile. Add +2 if you are <i>cunning</i> and +2 if you have <strike>.\\n11+: You slip free of the rocky teeth without incident. No effect.\\n8–10: You must twist your arm to free yourself. Suffer <minor_injury>.\\n1–7: Getting free is a laborious and painful process. Suffer <minor_injury> and lose <energy><energy>.\\"","ru":"<p><i><b>Вы застряли в каменной лавине!</b></i></p><p>Проведите проверку <dexterity>, чтобы вырваться из груды камней. +2, если вы <i>хитрый</i>, и +2, если у вас есть <strike>.<br><b>≥11:</b>  Вы легко выскользнули из каменных зубьев. Без эффекта.<br><b>8-10:</b>  Вам пришлось вывихнуть себе руку, чтобы освободиться. Получите <minor_injury>.<br><b>1-7:</b>  Освобождение было утомительным и болезненным. Получите <minor_injury> и потеряйте <energy><energy>.</p>"},"repeatable":false},{"id":"outcomes-997","code":"997","description":{"en":"<p>As you wake to the darkened dawn, the ashen behemoth stands before your village as if beckoning you. You can sense that your ancient bond with the behemoth is now of the utmost importance.</p>\\nAdd <lore><lore>. Place the BH4 in a hex adjacent to a hex with an outpost. Place <minor_boost> on the Study the Ashen Behemoth Goal card.","ru":"<p><i><b>Когда вы проснулись на рассвете, пепельное чудище стояло перед вашим поселением, словно подзывая вас. Вы ощутили, как древняя связь с этим существом стала теперь важнее всего на свете.</b></i></p><p>Добавьте <lore><lore>. Поместите ЧД4 на соседний с поселением участок местности. Поместите <minor_boost> на карту цели «Изучите пепельное чудище».</p>"},"repeatable":false},{"id":"outcomes-998","code":"998","description":{"en":"<p>\\"The comet's champion approaches a village. Already, you can see the coral spreading, spores thick in the air and threatening to overtake this place. You steel yourself to face the one given over to the wanderer's power. They raise a hand, and tendrils of live coral lash from the ground, slicing at your flesh!\\"</p>\\n\\"Resolve a contest of your <dexterity> versus the coral champion's <awareness> to fight. Add +2 to your result if you have a <i>moonblood</i> item. Add +2 to the coral champion's result for each adjacent hex with an active coral overgrowth.\\n<b>Success:</b> You race up to the coral champion, avoiding the lashing tendrils. Your blow strikes true, and the coral champion staggers back, vanishing into the seething mist of spores. Add <major_boost> to <might>.\\n<b>Failure:</b> The coral champion moves swiftly, evading your strikes and delivering a devastating counterattack. Suffer <major_injury>.\\"","ru":"<p><i><b>Коралловый защитник приближался к поселению. Он будто вёл за собой коралл, споры которого густо висели в воздухе, угрожая поглотить это место. Вы собрались с духом, готовясь встретиться с тем, кто оказался во власти Скитальца. Защитник поднял руку — и щупальца живого коралла вырвались из земли, разрезая вашу плоть!</b></i></p><p>Проведите состязание: <dexterity> своего персонажа против <awareness> кораллового защитника. +2 к вашему результату, если у вас есть предмет <i>лунной крови</i>. +2 к результату кораллового защитника за каждый соседний с ним участок местности с активными коралловыми зарослями. <br><b>Успех.</b> Вы стремительно бросились к коралловому защитнику, избегая его хлестающих щупалец. Ваш удар оказался точным — коралловый защитник пошатнулся и исчез в густом тумане из спор. Добавьте <major_boost> к <might>.<br><b>Провал. </b>Коралловый защитник двигался быстро, избегая ваших ударов и нанося урон в ответ. Получите <major_injury>.</p>"},"repeatable":false},{"id":"outcomes-999","code":"999","description":{"en":"<p>\\"The behemoth's fury subsides and it begins to plod toward its lair, its need to assert its dominance satisfied for now.\\"</p>\\n\\"For each hex with an outpost and a trace token, subtract <population><population> and add <unrest><unrest>. Each character in a hex with a trace token suffers <minor_injury>. \\n\\nThen, remove this behemoth's aim and all of its trace tokens. Assign the Return to Slumber (BT20) instinct to this behemoth (replacing its previous instinct).\\"","ru":"<p><i><b>Свирепость чудища стихла, и оно тяжёлой поступью начало путь к своему логову, довольное тем, что показало свою мощь. </b></i></p><p>За каждый участок местности с поселением и жетоном следов уберите <population><population> и добавьте <unrest><unrest>. Каждый персонаж на участке местности с жетоном следов получает <minor_injury>.</p><p>Затем уберите жетон направления и все жетоны следов этого чудища. Замените его текущий инстинкт на «Вернуться в забытьё» (ЧК20).</p>"},"repeatable":false}]`),G={version:B,lastUpdated:_,outcomes:R},n={en:{title:"OUTCOMES",searchButton:"Seek Outcome",enterNumber:"Enter code",noOutcome:"Outcome Unfound",repeatableTrue:"Repeatable",repeatableFalse:"Unique",thisOutcome:"This outcome is"},ru:{title:"Исходы",searchButton:"Проверить исход",enterNumber:"Введите код",noOutcome:"Исход не найден",repeatableTrue:"Повторяемый",repeatableFalse:"Уникальный",thisOutcome:"Этот исход"}};function z(){const{language:r}=A(),i=x(),b=S(),[f,m]=o.useState(!1),[s,p]=o.useState(null),[h,c]=o.useState(""),[l,v]=o.useState([]),w=async()=>G;o.useEffect(()=>{w().then(a=>{v(a.outcomes)})},[]),o.useEffect(()=>{const u=new URLSearchParams(i.search).get("code");if(u){const t=u.trim();c(t),l.length&&g(t)}},[i.search,l.length]);const g=o.useCallback(async(a=h,{replaceHistory:u=!0}={})=>{const t=a?.trim();if(t){m(!0);try{const d=l.find(T=>T.code===t);p(d||{isNotFound:!0,title:{en:n.en.noOutcome,ru:n.ru.noOutcome},description:{en:`<p class="not-found-message">No outcome found with code: <strong>${t}</strong></p>`,ru:`<p class="not-found-message">Исход с кодом <strong>${t}</strong> не найден</p>`}}),c(t);const k=i.search||"",y=`?code=${encodeURIComponent(t)}`;k!==y&&b({pathname:"/OUTCOMES",search:y},{replace:u})}catch(d){console.error("Error fetching outcomes:",d),p({isNotFound:!0,title:{en:"Error",ru:"Ошибка"},description:{en:'<p class="error-message">An error occurred while searching for the outcome.</p>',ru:'<p class="error-message">Произошла ошибка при поиске исхода.</p>'}})}finally{m(!1)}}},[h,l,i.search,b]);return e.jsxs(e.Fragment,{children:[e.jsx(I,{}),e.jsx(Y,{title:n[r].title,children:e.jsxs("div",{className:"recipes-content",children:[e.jsxs("div",{className:"input-row",children:[e.jsx("input",{type:"number",className:"number-input",value:h,onChange:a=>c(a.target.value.trim()),placeholder:n[r].enterNumber}),e.jsx("button",{className:"craft-button",onClick:()=>g(h),disabled:f,children:n[r].searchButton})]}),s&&e.jsxs(C,{children:[s.title?e.jsx("h3",{children:n[r].noOutcome}):e.jsx(e.Fragment,{}),e.jsx(j,{text:s.description[r]}),e.jsx(E,{marks:s.marks})]})]})})]})}export{z as default};
